window.EXPL={"세무사2016_53-41-1":{"f":"발기설립의 경우 이사는 변태설립사항에 관한 조사를 하게 하기 위하여 검사인의 선임을 법원에 청구하여야 한다.","w":"발기설립에서 검사인 선임을 법원에 청구하는 사람은 발기인이 아니라 이사다(상법 제298조 제4항). 발기인이 청구하는 것은 모집설립이다(제310조).","c":"상","v":1},"세무사2016_53-41-2":{"f":"모집설립의 경우 발기인은 변태설립사항에 관한 조사를 하게 하기 위하여 검사인의 선임을 법원에 청구하여야 한다.","w":"모집설립에서는 이사와 감사가 아니라 발기인이 검사인 선임을 법원에 청구한다(상법 제310조 제1항). 이사 청구는 발기설립이다.","c":"상","v":1},"세무사2016_53-41-4":{"f":"회사가 부담할 설립비용과 발기인이 받을 보수액에 대해서는 공증인의 조사ㆍ보고로 법원이 선임한 검사인의 조사에 갈음할 수 있다.","w":"설립비용과 발기인 보수액, 특별이익은 공증인의 조사ㆍ보고로 검사인 조사를 갈음한다. 공인된 감정인의 감정으로 갈음하는 것은 현물출자와 재산인수다(상법 제299조의2).","c":"상","v":1},"세무사2016_53-41-5":{"f":"모집설립의 경우 검사인의 변태설립사항의 조사에 대하여 창립총회가 한 변경에 불복한 주식인수인은 그 주식의 인수를 취소할 수 있다.","w":"모집설립에서 변태설립사항을 변경하는 것은 법원이 아니라 창립총회이고, 불복하는 사람도 발기인이 아니라 주식인수인이다(상법 제314조). 법원의 변경처분에 불복한 발기인의 취소권은 발기설립에만 있다(제300조 제2항).","c":"중","v":1},"세무사2016_53-43-5":{"f":"모집설립의 경우 주식인수인이 인수한 주금의 납입을 하지 아니한 때에는 발기인은 일정한 기일을 정하여 그 기일내에 납입을 하지 아니하면 그 권리를 잃는다는 뜻을 기일의 2주간전에 그 주식인수인에게 통지하여야 한다.","w":"실권예고 통지는 모집설립에서 발기인이 납입하지 않은 주식인수인에게 하는 절차다(상법 제307조). 발기설립에서 발기인끼리 서로 통지하는 절차는 없다.","c":"중","v":1},"세무사2016_53-44-5":{"f":"","w":"정관변경 특별결의는 출석한 주주 의결권의 3분의 2 이상과 발행주식총수의 3분의 1 이상으로 하고(상법 제434조), 의결권 없는 주식은 발행주식총수에 넣지 않는다(제371조 제1항). 문장이 조문과 같은데 공식 정답은 이 선지를 옳지 않은 것으로 처리했다. 출제에서 뺀다.","c":"의심","v":1,"old":1,"ow":"O·X 표시 오류로 출제에서 뺌: 문장이 상법 제434조·제371조 제1항과 같은데 공식 정답이 옳지 않은 것으로 처리했다. 틀린 문장으로 내면 안 되어 출제에서 뺀다."},"세무사2016_53-46-3":{"f":"이사가 2명인 경우에는 각자 회사를 대표한다.","w":"자본금 10억원 미만 회사는 이사를 1인 또는 2인으로 할 수 있고 이사회가 없다. 이 경우 각 이사가 회사를 대표하고, 주주총회가 대표이사를 정한 때에는 그 이사만 대표한다(상법 제383조).","c":"상","v":1},"세무사2016_53-79-2":{"f":"설립취소의 소는 본점소재지의 지방법원의 관할에 전속한다.","w":"회사 설립의 무효ㆍ취소의 소는 본점소재지 지방법원의 전속관할이다(상법 제186조). 지점소재지가 아니다.","c":"상","v":1},"세무사2017_54-42-2":{"f":"합자회사의 청산인은 무한책임사원 과반수의 의결로 선임하여야 한다.","w":"합자회사의 청산인은 무한책임사원 과반수의 의결로 선임하고, 선임하지 않으면 업무집행사원이 청산인이 된다(상법 제287조). 유한책임사원 전원의 의결로 정하지 않는다.","c":"상","v":1},"세무사2017_54-46-1":{"f":"모집설립의 경우 발기인은 법원의 허가를 받아 납입금의 보관자를 변경할 수 있다.","w":"납입금 보관자나 납입장소를 변경하려면 법원의 허가가 있어야 한다(상법 제306조).","c":"상","v":1},"세무사2017_54-47-4":{"f":"회사가 성립하지 못한 경우 발기인은 그 설립에 관하여 지급한 비용을 부담한다.","w":"회사가 성립하지 못하면 발기인이 설립에 관한 행위의 책임을 지고 지급한 비용도 부담한다(상법 제326조).","c":"상","v":1},"세무사2017_54-48-1":{"f":"발기인이 받을 특별이익을 정관에 기재하지 아니하면 그 효력이 없다.","w":"특별이익은 정관에 적어야 효력이 있고, 적지 않으면 그 약정만 무효다. 정관 전체가 무효가 되지는 않는다(상법 제290조).","c":"상","v":1},"세무사2017_54-48-2":{"f":"발기설립에서 법원은 변태설립사항이 부당하다고 인정한 때에는 이를 변경하여 각 발기인에게 통고할 수 있는데, 그 변경에 불복하는 발기인은 그 주식의 인수를 취소할 수 있다.","w":"법원의 변경에 불복하는 발기인은 주식의 인수를 취소할 수 있다(상법 제300조 제2항).","c":"상","v":1},"세무사2017_54-48-4":{"f":"회사 성립후에 양수할 것을 약정한 재산이 있는 경우 그 재산의 종류, 수량, 가격과 양도인의 성명을 정관에 기재하여야 그 효력이 있다.","w":"재산인수는 재산의 종류ㆍ수량ㆍ가격과 양도인의 성명이 모두 정관에 적혀 있어야 효력이 있다(상법 제290조 제3호).","c":"상","v":1},"세무사2017_54-48-5":{"f":"발기인이 받을 보수액은 정관에 기재하지 않으면 그 효력이 없다.","w":"발기인이 받을 보수액과 회사가 부담할 설립비용은 정관에 적어야 효력이 있다(상법 제290조 제4호).","c":"상","v":1},"세무사2017_54-49-2":{"f":"합명회사의 사원은 다른 사원 과반수의 승인이 있어야만 자기 또는 제3자의 계산으로 회사와 거래를 할 수 있다.","w":"사원의 자기거래에는 다른 사원 과반수의 승인이 필요하다. 전원의 동의까지는 필요하지 않다(상법 제199조).","c":"상","v":1},"세무사2021_58-41-4":{"f":"해산후의 회사가 합병하는 경우, 존립중의 회사를 존속하는 회사로 할 수 있다.","w":"해산후의 회사는 존립중의 회사를 존속회사로 하는 경우에만 합병할 수 있다. 해산후의 회사가 존속회사가 되는 합병은 허용되지 않는다(상법 제174조 제3항).","c":"상","v":1},"세무사2021_58-42-1":{"f":"각 발기인은 서면에 의하여 주식을 인수하여야 한다.","w":"발기인의 주식인수는 서면으로 한다(상법 제293조). 주식청약서는 모집설립에서 주식인수인이 쓰는 서면이다.","c":"상","v":1},"세무사2021_58-42-2":{"f":"발기인이 이사와 감사를 선임하는 경우, 각 발기인은 인수한 주식 1주에 대하여 1개의 의결권을 가진다.","w":"발기설립에서 이사ㆍ감사 선임은 발기인의 의결권 과반수로 하고, 의결권은 인수한 주식 1주에 1개다(상법 제296조 제2항). 발기인 1인당 1표가 아니다.","c":"상","v":1},"세무사2021_58-42-3":{"f":"법원이 부당한 변태설립사항을 변경하여 각 발기인에게 통고한 경우, 발기인은 그 변경에 불복하여 그 주식의 인수를 취소할 수 있다.","w":"법원의 변경에 불복하는 발기인은 그 주식의 인수를 취소할 수 있다(상법 제300조 제2항).","c":"상","v":1},"세무사2021_58-42-4":{"f":"변태설립사항의 조사를 위하여 선임된 공증인 또는 감정인은 조사 또는 감정결과를 법원에 보고하여야 한다.","w":"공증인과 감정인은 조사ㆍ감정 결과를 발기인이 아니라 법원에 보고한다(상법 제299조의2).","c":"상","v":1},"세무사2021_58-43-1":{"f":"회사설립시에 발행한 주식으로서 회사성립후에 주식인수의 청약이 취소된 때에는 발기인이 이를 공동으로 인수한 것으로 본다.","w":"회사 성립 후 주식인수의 청약이 취소되면 그 주식은 발기인이 공동으로 인수한 것으로 본다. 다시 주주를 모집하지 않는다(상법 제321조 제1항).","c":"상","v":1},"세무사2021_58-44-3":{"f":"창립총회에서의 정관변경 결의는 소집통지서에 그 뜻의 기재가 없는 경우에도 이를 할 수 있다.","w":"창립총회는 소집통지서에 적지 않았더라도 정관의 변경이나 설립폐지를 결의할 수 있다(상법 제316조 제2항 취지).","c":"중","v":1},"세무사2021_58-45-1":{"f":"회사가 집행임원을 둔 경우, 집행임원의 성명ㆍ주민등록번호 및 주소는 등기사항이다.","w":"집행임원의 성명ㆍ주민등록번호ㆍ주소는 등기사항이고 정관의 절대적 기재사항이 아니다. 정관의 절대적 기재사항은 상법 제289조 제1항에 열거된 것뿐이다.","c":"중","v":1},"세무사2021_58-45-2":{"f":"회사설립의 경우, 발기인 전원의 동의로 정관을 작성하고 발기인 전원이 기명날인 또는 서명하여야 한다.","w":"정관에는 발기인 전원이 기명날인 또는 서명해야 한다(상법 제289조 제1항). 대표발기인만 서명하면 되는 것이 아니다.","c":"상","v":1},"세무사2021_58-45-3":{"f":"자본금 총액이 10억원 미만인 회사를 발기설립하는 경우, 회사의 정관은 공증인의 인증을 받지 않아도 효력이 생긴다.","w":"주식회사 정관은 공증인의 인증으로 효력이 생기지만, 자본금 10억원 미만 회사를 발기설립할 때는 인증이 필요 없다(상법 제292조 단서).","c":"상","v":1},"세무사2021_58-45-5":{"f":"회사가 무액면주식을 발행하는 경우, 주식의 발행가액과 자본금으로 계상하는 금액은 정관의 절대적 기재사항이 아니다.","w":"설립 때 무액면주식의 발행가액과 그중 자본금으로 계상할 금액은 정관에 달리 정하지 않으면 발기인 전원의 동의로 정한다(상법 제291조 제3호). 정관의 절대적 기재사항(제289조 제1항)에는 들어 있지 않다.","c":"상","v":1},"세무사2021_58-46-2":{"f":"발기인이 회사설립에 관한 임무해태로 인하여 회사에 대하여 부담하는 손해배상책임은 총주주의 동의로 면제할 수 있다.","w":"발기인의 회사에 대한 임무해태 책임은 총주주의 동의로 면제할 수 있다(상법 제324조, 제400조).","c":"상","v":1},"세무사2022_59-42-1":{"f":"회사는 자연인과 달리 성질ㆍ법령ㆍ정관상 목적에 의한 제한을 받는 범위에서 권리능력이 인정된다.","w":"회사는 법인이어서 권리능력이 있지만, 친권ㆍ상속처럼 자연인에게만 인정되는 권리는 가질 수 없고 법령이나 정관의 목적에 따른 제한도 받는다.","c":"중","v":1},"세무사2022_59-42-2":{"f":"합명회사는 유한책임회사의 업무집행자가 될 수 있다.","w":"법인도 유한책임회사의 업무집행자가 될 수 있고, 이때 그 법인은 직무를 행할 자를 선임해 그 성명과 주소를 다른 사원에게 통지한다(상법 제287조의15 제1항).","c":"상","v":1},"세무사2022_59-42-4":{"f":"회사에는 친권과 상속을 받을 권리가 인정되지 않으나 유증을 받을 권리는 인정된다.","w":"회사는 자연인이 아니므로 친권과 상속은 없지만, 유증은 받을 수 있다.","c":"상","v":1},"세무사2022_59-42-5":{"f":"합명회사가 총사원의 동의로 해산한 경우 청산의 목적범위 내에서 권리능력이 존속한다.","w":"해산한 회사는 곧바로 소멸하지 않고 청산이 끝날 때까지 청산의 목적 범위 안에서 권리능력을 가진다(상법 제245조).","c":"상","v":1},"세무사2022_59-43-2":{"f":"합명회사 및 합자회사의 경우 사원의 성명·주민등록번호 및 주소는 정관의 절대적 기재사항이고, 유한회사의 경우에도 그러하다.","w":"유한회사 정관에도 사원의 성명ㆍ주민등록번호ㆍ주소를 적어야 한다(상법 제543조 제2항). 주식회사는 주주를 정관에 적지 않는다.","c":"상","v":1},"세무사2022_59-43-3":{"f":"회사의 설립등기사항은 회사의 종류에 따라 다르다.","w":"설립등기사항은 합명회사(제180조), 합자회사(제271조), 유한책임회사(제287조의5), 유한회사(제549조), 주식회사(제317조)마다 따로 정해져 있다.","c":"상","v":1},"세무사2022_59-43-4":{"f":"주식회사의 설립과정에서 발기인이나 주식인수인이 주식을 인수하지만 회사는 설립등기 이후에 주권을 발행할 수 있다.","w":"주권은 회사 성립 후가 아니면 발행하지 못하고, 이를 어기고 발행한 주권은 무효다(상법 제355조 제2항).","c":"상","v":1},"세무사2022_59-43-5":{"f":"","w":"회사는 본점소재지에서 설립등기를 함으로써 성립한다(상법 제172조). 주식회사와 유한회사의 설립등기 기간은 3주가 아니라 2주간이다(제317조 제1항, 제549조 제1항).","c":"상","v":1},"세무사2022_59-44-4":{"f":"유한책임회사의 설립무효의 소의 경우 그 소를 제기할 수 있는 자는 사원 및 업무집행자에 한정된다.","w":"유한책임회사 설립무효의 소는 사원뿐 아니라 업무집행자도 제기할 수 있다(상법 제287조의6이 제184조의 \"사원\"을 \"사원 및 업무집행자\"로 읽도록 준용).","c":"상","v":1},"세무사2023_60-41-1":{"f":"회사는 상행위 기타 영리를 목적으로 하는 사단법인이지만 설립시 사원이 반드시 2인 이상이어야 하는 것은 아니다.","w":"주식회사ㆍ유한회사ㆍ유한책임회사는 사원 1인으로도 설립할 수 있다. 합명회사와 합자회사만 2인 이상이 필요하다.","c":"상","v":1},"세무사2023_60-41-3":{"f":"회사는 주식회사의 주주가 될 수 있다.","w":"회사는 다른 회사의 주주가 될 수 있다. 제한되는 것은 무한책임사원이 되는 경우(제173조)와 자기주식ㆍ상호주 취득이다.","c":"상","v":1},"세무사2023_60-41-4":{"f":"회사는 해산등기를 한 때에도 청산의 목적범위 내에서 권리능력이 존속한다.","w":"해산한 회사도 청산의 목적범위 안에서 존속한다(상법 제245조). 청산종결등기를 했더라도 청산사무가 남아 있으면 그 범위에서 권리능력이 남는다는 것이 판례다.","c":"상","v":1},"세무사2023_60-41-5":{"f":"회사의 권리능력은 제한될 수 있다.","w":"회사의 권리능력은 성질, 법령(제173조 등), 정관상 목적에 따라 제한된다.","c":"상","v":1},"세무사2023_60-42-4":{"f":"주식회사와 유한회사에서 정관은 정관에 일정한 사항을 기재하고 사원 또는 발기인이 기명날인 또는 서명한 후 공증인의 인증을 받아야 효력이 발생한다.","w":"공증인의 인증이 필요한 것은 주식회사(제292조)와 유한회사(제543조 제3항)이고, 합명ㆍ합자ㆍ유한책임회사의 정관은 인증이 필요 없다.","c":"상","v":1},"세무사2023_60-43-1":{"f":"설립 시에 발행하는 주식의 종류와 수에 관한 사항은 정관으로 달리 정하지 아니하면 발기인 전원의 동의로 이를 정한다.","w":"정관에 정하지 않은 설립 시 발행 주식의 종류와 수는 발기인 전원의 동의로 정한다(상법 제291조). 과반수가 아니다.","c":"상","v":1},"세무사2023_60-43-2":{"f":"자본금 총액이 10억원 미만인 회사의 정관은 발기설립의 경우 공증인의 인증을 받지 않아도 효력이 생긴다.","w":"자본금 10억원 미만 회사를 발기설립할 때는 공증인 인증이 필요 없다(상법 제292조 단서). 모집설립이면 인증이 필요하다.","c":"상","v":1},"세무사2023_60-43-3":{"f":"각 발기인은 서면에 의하여 주식을 인수하여야 한다.","w":"발기인의 주식 인수는 서면으로만 하고 구두로는 하지 못한다(상법 제293조).","c":"상","v":1},"세무사2023_60-43-5":{"f":"설립의 하자는 회사성립의 날로부터 2년내에 설립무효의 소로써 이를 주장할 수 있다.","w":"주식회사는 설립취소의 소가 없고 설립무효의 소만 있다(상법 제328조).","c":"상","v":1},"세무사2023_60-44-1":{"f":"정관에 출자자의 성명과 출자의 목적인 부동산의 종류, 수량, 가격 및 이에 대하여 부여할 주식의 종류와 수가 기재되어 있어야 그 부동산을 유효하게 현물출자할 수 있다.","w":"현물출자는 출자자의 성명, 재산의 종류ㆍ수량ㆍ가격, 부여하는 주식의 종류와 수를 모두 정관에 적어야 효력이 있다(상법 제290조 제2호). 종류와 가격만으로는 부족하다.","c":"상","v":1},"세무사2023_60-44-2":{"f":"현물출자자인 이사는 회사의 설립에 관한 모든 사항이 법령 또는 정관의 규정에 위반되지 아니하는지 여부의 조사에 참여할 수 없다.","w":"변태설립사항에 이해관계가 있는 이사는 설립에 관한 조사에 참여하지 못한다(상법 제298조 제2항).","c":"상","v":1},"세무사2023_60-44-3":{"f":"현물출자 및 재산인수의 재산의 총액이 자본금의 5분의 1을 초과하지 않고 5천만원을 초과하지 않는 경우에는 법원이 선임한 검사인의 조사를 받지 않아도 된다.","w":"소액 현물출자는 검사인 조사 대상에서 제외된다. 총액과 관계없이 모두 조사받는 것이 아니다(상법 제299조 제2항 참조).","c":"중","v":1},"세무사2023_60-44-4":{"f":"모집설립에서 현물출자가 부당한 경우 그 변경은 창립총회가 할 수 있다.","w":"모집설립에서는 법원이 아니라 창립총회가 부당한 변태설립사항을 변경한다(상법 제314조 제1항).","c":"상","v":1},"세무사2023_60-77-4":{"f":"신설합병의 창립총회에서는 합병계약의 취지에 반하는 정관변경을 결의할 수 없다.","w":"신설합병의 창립총회에서는 정관변경을 결의할 수 있지만 합병계약의 취지에 위반하는 결의는 하지 못한다(상법 제527조 제2항 단서).","c":"중","v":1},"세무사2024_61-41-1":{"f":"회사란 상행위나 그 밖의 영리를 목적으로 하여 설립된 법인을 말한다.","w":"회사는 상행위나 그 밖의 영리를 목적으로 하여 설립한 법인이다(상법 제169조). 기본적 상행위만으로 한정되지 않는다.","c":"상","v":1},"세무사2024_61-41-2":{"f":"해산후의 회사는 존립중의 회사를 존속하는 회사로 하여 합병할 수 있다.","w":"해산후의 회사는 존립중의 회사를 존속회사로 하는 경우에만 합병할 수 있다. 해산후의 회사끼리 합병해 어느 한쪽을 존속시키는 것은 허용되지 않는다(상법 제174조 제3항).","c":"상","v":1},"세무사2024_61-41-3":{"f":"회사는 다른 회사의 무한책임사원이 될 수 없다.","w":"회사는 다른 회사의 무한책임사원이 되지 못한다(상법 제173조). 주식회사의 주주나 유한책임사원은 될 수 있다.","c":"상","v":1},"세무사2024_61-41-4":{"f":"회사의 종류는 합명회사, 합자회사, 유한책임회사, 유한회사, 주식회사의 5종류로 한다.","w":"상법상 회사는 합명회사, 합자회사, 유한책임회사, 주식회사, 유한회사 다섯 종류다(상법 제170조). 상호회사는 포함되지 않는다.","c":"상","v":1},"세무사2024_61-42-1":{"f":"발기인이 악의 또는 중대한 과실로 인하여 그 임무를 해태한 때에는 그 발기인은 제3자에 대하여 연대하여 손해를 배상할 책임이 있다.","w":"발기인은 임무를 게을리한 데 악의 또는 중대한 과실이 있을 때에만 제3자에 대해 연대하여 배상책임을 진다(상법 제322조 제2항). 경과실이면 책임이 없다.","c":"상","v":1},"세무사2024_61-42-2":{"f":"회사설립의 무효는 주주ㆍ이사 또는 감사에 한하여 회사성립의 날로부터 2년 내에 소만으로 이를 주장할 수 있다.","w":"주식회사는 설립취소의 소가 없고 설립무효의 소만 있다(상법 제328조 제1항).","c":"상","v":1},"세무사2024_61-42-4":{"f":"발기인의 인수담보책임과 납입담보책임은 총주주의 동의로도 면제할 수 없다.","w":"인수담보책임과 납입담보책임은 자본충실을 위한 책임이어서 총주주의 동의로도 면제되지 않는다(상법 제321조). 총주주의 동의로 면제되는 것은 임무해태로 인한 손해배상책임이다(제324조).","c":"상","v":1},"세무사2024_61-42-5":{"f":"회사설립시에 발행하는 주식의 총수가 인수된 때에는 발기인은 지체없이 주식인수인에 대하여 각 주식에 대한 인수가액의 전액을 납입시켜야 한다.","w":"모집설립에서 주식 총수가 인수되면 납입을 시키는 사람은 이사가 아니라 발기인이다(상법 제305조 제1항).","c":"상","v":1},"세무사2024_61-43-1":{"f":"모집설립시 주식인수인이 납입기일 내에 주금을 납입하지 않으면 발기인의 실권예고 통지에서 정한 기일까지 납입하지 않을 때 권리를 상실한다.","w":"납입기일을 넘겼다고 바로 권리를 잃는 것이 아니다. 발기인이 실권예고 기일 2주 전에 통지하고, 그 기일까지 납입하지 않아야 권리를 잃는다(상법 제307조).","c":"상","v":1},"세무사2024_61-75-2":{"f":"정관변경의 총회결의는 출석한 주주의 의결권의 3분의 2 이상의 수와 발행주식총수의 3분의 1 이상의 수로 하여야 한다.","w":"정관변경은 특별결의로 하고, 출석 의결권의 3분의 2 이상과 발행주식총수의 3분의 1 이상이 필요하다(상법 제434조). 발행주식총수의 과반수가 아니다.","c":"상","v":1},"세무사2025_62-42-3":{"f":"무액면주식을 발행하는 경우에도 주식의 발행가액 중 자본금으로 계상하는 금액을 반드시 정관에 기재하여야 하는 것은 아니다.","w":"설립 때 무액면주식의 발행가액과 그중 자본금으로 계상할 금액은 정관에 달리 정하지 않으면 발기인 전원의 동의로 정한다(상법 제291조 제3호). 정관의 절대적 기재사항이 아니다.","c":"상","v":1},"세무사2025_62-43-1":{"f":"설립에 주관적 하자가 있는 경우 주주는 설립취소의 소를 제기할 수 없다.","w":"주식회사에는 설립취소의 소가 없다. 설립의 하자는 설립무효의 소(상법 제328조)로만 다투고, 주식인수의 주관적 하자는 주식인수인 개인의 취소권 행사에 제한이 있다(제320조).","c":"중","v":1},"세무사2025_62-43-2":{"f":"회사설립의 무효는 주주ㆍ이사 또는 감사에 한하여 소만으로 이를 주장할 수 있다.","w":"설립무효의 소를 제기할 수 있는 사람은 주주ㆍ이사ㆍ감사로 한정된다(상법 제328조 제1항). 이해관계인은 제기하지 못한다.","c":"상","v":1},"세무사2025_62-43-3":{"f":"설립무효의 소를 제기한 자가 패소한 경우에 악의 또는 중대한 과실이 있는 때에는 회사에 대하여 연대하여 손해를 배상할 책임이 있다.","w":"패소한 원고는 악의 또는 중대한 과실이 있을 때에만 배상책임을 진다(상법 제328조 제2항, 제191조). 경과실로는 책임이 없다.","c":"상","v":1},"세무사2025_62-43-5":{"f":"설립무효의 판결이 인용된 경우 그 판결의 효력은 판결확정전에 생긴 회사와 사원간의 권리의무에 영향을 미치지 아니한다.","w":"설립무효판결에는 소급효가 없어서 판결 확정 전에 생긴 회사와 사원, 제3자 사이의 권리의무는 그대로 유지된다(상법 제328조 제2항, 제190조 단서).","c":"상","v":1},"세무사2025_62-80-1":{"f":"외국회사가 대한민국에서 영업을 하려면 대한민국에서의 대표자를 정하고 대한민국 내에 영업소를 설치하거나 대표자 중 1명 이상이 대한민국에 그 주소를 두어야 한다.","w":"외국회사는 영업소를 두는 대신 대표자 중 1명 이상이 국내에 주소를 두는 방법도 쓸 수 있다(상법 제614조 제1항). 영업소 설치가 반드시 필요한 것은 아니다.","c":"상","v":1},"세무사2026_63-47-3":{"f":"회사는 상행위 기타 영리를 목적으로 설립한 법인을 말한다.","w":"회사는 상행위만을 목적으로 하는 법인이 아니라 영리를 목적으로 하는 사단법인이다(상법 제169조).","c":"상","v":1},"세무사2026_63-48-2":{"f":"회사설립시 액면 이상으로 주식을 발행할 때에는 그 수와 금액은 정관으로 달리 정하지 않으면 발기인 전원의 동의로 이를 정한다.","w":"정관에 정하지 않은 액면 이상 발행의 수와 금액은 발기인 전원의 동의로 정한다(상법 제291조). 과반수가 아니다.","c":"상","v":1},"세무사2026_63-61-3":{"f":"창립총회에서는 소집통지서에 정관의 변경에 관한 뜻의 기재가 없는 경우에도 정관 변경의 결의를 할 수 있다.","w":"창립총회는 소집통지서에 적지 않았더라도 정관의 변경이나 설립폐지를 결의할 수 있다(상법 제316조 제2항 취지).","c":"중","v":1},"세무사2016_53-42-4":{"f":"감사는 자회사의 이사의 직무를 겸하지 못한다.","w":"감사가 겸직할 수 없는 것은 자회사의 이사직무이고 자회사의 감사직은 겸할 수 있다(상법 제411조).","c":"상","v":1},"세무사2017_54-63-1":{"f":"발행주식총수의 100분의 3 이상에 해당하는 주식을 가진 주주가 회사에 대하여 회계의 장부와 서류의 열람 또는 등사를 청구한 경우 회사는 그 청구가 부당함을 증명하여야 이를 거부할 수 있다.","w":"주주는 이유를 붙인 서면으로 청구하면 되고, 청구가 부당하다는 것을 회사가 증명하지 못하면 거부하지 못한다(상법 제466조 제2항). 주주가 정당함을 증명할 필요는 없다.","c":"상","v":1},"세무사2021_58-57-5":{"f":"모회사 주주와 자회사 이사의 공모로 인하여 소송의 목적인 자회사의 권리를 사해할 목적으로써 판결을 하게 한 때에는 자회사는 확정한 종국판결에 대하여 재심의 소를 제기할 수 있다.","w":"공모로 소송의 목적인 회사의 권리를 사해하는 판결이 난 경우 자회사는 재심의 소를 제기할 수 있다(상법 제406조의2 제3항이 준용하는 제406조 제1항).","c":"상","v":1},"세무사2021_58-66-3":{"f":"감사위원회는 그 결의로 위원회를 대표할 자를 선정하여야 한다.","w":"위원회의 대표는 이사회가 아니라 감사위원회가 자기 결의로 정한다(상법 제415조의2 제4항).","c":"상","v":1},"세무사2021_58-67-2":{"f":"정기총회에서 재무제표와 그 부속명세서에 대해 승인한 후 2년 내에 다른 결의가 없으면, 회사는 감사의 부정행위에 따른 책임을 제외하고 책임을 해제한 것으로 본다.","w":"재무제표 승인 후 2년 내에 다른 결의가 없으면 책임이 해제된 것으로 보지만, 부정행위로 인한 책임은 해제되지 않는다(상법 제450조).","c":"상","v":1},"세무사2022_59-68-1":{"f":"회사는 주주가 적법하게 제기한 대표소송에 참가할 수 있다.","w":"대표소송이 제기되면 회사는 참가할 수 있다(상법 제404조 제1항).","c":"상","v":1},"세무사2022_59-68-2":{"f":"발행주식의 총수의 100분의 1 이상에 해당하는 주식을 가진 주주가 회사에 대하여 이사의 책임을 추궁할 소의 제기를 청구한 후 30일 내에 회사가 소를 제기하지 않으면 주주는 대표소송을 제기할 수 있다.","w":"소 제기를 청구한 뒤 회사가 30일 내에 소를 제기하지 않아야 주주가 대표소송을 낼 수 있다(상법 제403조 제3항). 즉시 제기할 수 있는 경우는 회사에 회복할 수 없는 손해가 생길 염려가 있을 때뿐이다(제403조 제4항).","c":"상","v":1},"세무사2022_59-68-4":{"f":"대표소송을 제기한 주주는 법원의 허가를 얻어야만 소의 취하를 할 수 있다.","w":"대표소송의 소 취하, 청구의 포기ㆍ인락ㆍ화해는 법원의 허가를 받아야 한다(상법 제403조 제6항).","c":"상","v":1},"세무사2022_59-68-5":{"f":"대표소송을 제기한 주주가 패소한 때에는 악의가 있는 경우에 회사에 대하여 손해를 배상할 책임이 있다.","w":"패소한 주주는 악의가 있을 때에만 회사에 배상책임을 진다(상법 제405조 제2항 취지). 단순한 과실로는 책임이 없다.","c":"중","v":1},"세무사2022_59-72-1":{"f":"감사위원회 위원을 선임하거나 해임할 권한은 주주총회에 있고 정관 규정으로도 이사회 권한으로 할 수 없다.","w":"자산총액 2조원 이상 상장회사의 감사위원 선임ㆍ해임은 주주총회가 하며, 정관으로 이사회에 맡길 수 없다(상법 제542조의12).","c":"상","v":1},"세무사2023_60-56-5":{"f":"모회사의 주주가 다중대표소송을 제기하는 경우 자회사는 다중대표소송에 참가할 수 있다.","w":"자회사는 다중대표소송에 참가할 수 있다. 대표소송의 참가 규정이 준용된다(상법 제406조의2 제3항, 제404조 제1항).","c":"상","v":1},"세무사2023_60-63-4":{"f":"감사가 고의로 회사에 손해를 발생시킨 경우에는 회사는 정관으로 정하는 바에 따라 감사가 그 행위를 한 날이전 최근 1년간의 보수액의 6배를 초과하는 손해배상책임 금액에 대하여 면제할 수 없다.","w":"책임 한도를 보수액의 6배로 제한하는 정관 규정은 고의 또는 중대한 과실로 손해를 입힌 경우에는 적용되지 않는다(상법 제415조, 제400조 제2항 단서).","c":"상","v":1},"세무사2023_60-64-2":{"f":"이사회는 감사위원회가 결의한 사항에 대하여 다시 결의할 수 없다.","w":"이사회내 위원회의 결의는 이사회가 다시 결의할 수 있지만, 감사위원회에는 이 규정이 적용되지 않아 이사회가 다시 결의하지 못한다(상법 제415조의2 제6항, 제393조의2 제4항 후단).","c":"상","v":1},"세무사2024_61-57-1":{"f":"대표소송을 제기한 주주는 법원의 허가를 얻어 소의 취하, 청구의 포기ㆍ인락ㆍ화해를 할 수 있다.","w":"소 취하, 청구의 포기ㆍ인락ㆍ화해에는 법원의 허가가 필요하다(상법 제403조 제6항).","c":"상","v":1},"세무사2024_61-57-2":{"f":"회사는 법원의 허가없이 대표소송에 참가할 수 있다.","w":"회사의 대표소송 참가에는 법원의 허가가 필요 없다(상법 제404조 제1항).","c":"상","v":1},"세무사2024_61-57-3":{"f":"주주가 주주대표소송의 제기를 회사에 대하여 청구한 때 회사가 그 청구를 받은 날로부터 30일내에 소를 제기하지 않으면 주주는 즉시 회사를 위하여 소를 제기할 수 있다.","w":"소 제기를 청구한 뒤 회사가 30일 내에 소를 제기하지 않을 때 주주가 대표소송을 제기할 수 있다(상법 제403조 제3항). 기간은 2주가 아니라 30일이다.","c":"상","v":1},"세무사2024_61-57-5":{"f":"대표소송을 제기한 주주가 승소한 경우 그 주주는 회사에 대하여 소송비용 외에 소송으로 인하여 지출한 비용 중 상당한 금액도 청구할 수 있다.","w":"승소한 주주는 소송비용뿐 아니라 그 밖에 소송으로 지출한 비용 중 상당한 금액도 회사에 청구할 수 있다(상법 제405조 제1항).","c":"상","v":1},"세무사2025_62-61-2":{"f":"전자적 방법으로 의결권을 행사하는 회사의 감사는 주주총회에서 출석한 주주의 의결권의 과반수로써 선임할 수 있다.","w":"전자투표를 도입한 회사는 감사를 출석 주주 의결권의 과반수만으로 선임할 수 있고, 발행주식총수의 4분의 1 이상 요건이 필요하지 않다(상법 제409조 제3항).","c":"상","v":1},"세무사2026_63-75-5":{"f":"이사회에서 감사위원회 위원에 대한 해임결의를 한 경우 당해 감사위원회 위원직만 상실하고 이사직은 상실하지 않는다.","w":"감사위원 해임으로 잃는 것은 위원직뿐이고 이사직은 그대로 남는다. 이사직을 잃게 하려면 주주총회에서 이사로 해임해야 한다.","c":"중","v":1},"세무사2017_54-54-3":{"f":"주주는 동일한 주식에 관하여 상법의 규정에 따라 의결권을 행사하는 경우 전자적 방법과 서면의 방법을 병행할 수 없다.","w":"같은 주식에 관하여 서면투표와 전자투표를 함께 쓰지 못하고 둘 중 하나를 선택해야 한다(상법 제368조의4 제4항).","c":"상","v":1},"세무사2017_54-56-4":{"f":"이사인 주주가 결의취소의 소를 제기한 때에는 법원은 회사의 청구에 의하여도 담보를 제공할 것을 명할 수 없다.","w":"결의취소의 소를 제기한 주주에게 담보를 제공하게 할 수 있지만, 그 주주가 이사 또는 감사인 때에는 담보 제공을 명하지 못한다(상법 제377조 제1항 단서).","c":"상","v":1},"세무사2021_58-59-5":{"f":"명의개서를 하지 아니한 주식양수인에 대하여 주주총회 소집통지를 하지 않은 경우, 그 주주총회의 결의에는 절차상의 하자가 인정되지 않는다.","w":"명의개서를 하지 않은 양수인은 회사에 대해 주주로 주장할 수 없으므로 소집통지를 하지 않아도 절차상 하자가 아니다(상법 제337조 제1항).","c":"상","v":1},"세무사2021_58-62-3":{"f":"부당결의 취소의 소가 제기된 경우에 법원은 결의의 내용, 회사의 현황과 제반사정을 참작하여 그 취소가 부적당하다고 인정한 때에도 그 청구를 기각할 수 없다.","w":"재량기각은 결의취소의 소에 인정되는 제도(상법 제379조)이고, 부당결의 취소ㆍ변경의 소에는 준용되지 않는다(제381조).","c":"중","v":1},"세무사2022_59-61-4":{"f":"이사회는 주주제안의 내용이 법령 또는 정관을 위반하는 경우 등을 제외하고는 이를 주주총회의 목적사항으로 하여야 한다.","w":"이사회는 법령이나 정관 위반 등 대통령령으로 정한 사유가 있으면 주주제안을 총회 안건에서 제외할 수 있다(상법 제363조의2 제3항). 모든 제안을 안건으로 해야 하는 것은 아니다.","c":"상","v":1},"세무사2022_59-63-1":{"f":"기명주식을 가진 주주는 주권을 제시하지 않아도 의결권을 행사할 수 있다.","w":"의결권은 주주명부에 주주로 기재된 사람이 행사하고 주권 제시는 요건이 아니다.","c":"중","v":1},"세무사2022_59-63-2":{"f":"의결권의 대리행사의 경우에 대리인은 대리권을 증명하는 서면을 총회에 제출하여야 한다.","w":"대리인이 대리권을 증명하는 서면 또는 전자문서를 총회에 제출해야 한다(상법 제368조 제2항). 주주 본인이 제출하는 것이 아니다.","c":"상","v":1},"세무사2022_59-63-3":{"f":"주식의 신탁을 인수한 주주가 2 이상의 의결권에 대하여 불통일 행사하고자 하는 경우 회사는 이를 거부할 수 없다.","w":"주식의 신탁을 인수했거나 다른 사람을 위해 주식을 가진 경우에는 불통일행사를 회사가 거부하지 못한다(상법 제368조의2 제2항).","c":"상","v":1},"세무사2022_59-63-4":{"f":"주주는 정관의 규정에 따라 총회에 출석하지 아니하고 서면에 의하여 의결권을 행사할 수 있다.","w":"서면투표는 정관에 규정이 있어야 한다(상법 제368조의3 제1항). 이사회 결의로 정하는 것은 전자투표다(제368조의4).","c":"상","v":1},"세무사2022_59-65-3":{"f":"총회의 결의방법이 법령에 위반한 때에는 감사는 결의의 날로부터 2월내에 결의취소의 소를 제기할 수 있다.","w":"결의내용이 법령에 위반하면 결의무효확인의 소 대상이고, 결의취소의 소는 소집절차나 결의방법이 법령ㆍ정관에 위반하거나 현저히 불공정한 경우에 제기한다(상법 제376조 제1항).","c":"상","v":1},"세무사2023_60-58-4":{"f":"주주가 주식의 신탁을 인수한 경우에는 회사는 주주의 의결권의 불통일행사를 거부할 수 없다.","w":"주식의 신탁을 인수한 경우 불통일행사는 거부할 수 없다(상법 제368조의2 제2항).","c":"상","v":1},"세무사2023_60-59-1":{"f":"의결권을 대리행사하는 경우에 그 대리인은 대리권을 증명하는 서면을 주주총회에 제출하여야 한다.","w":"대리인은 대리권을 증명하는 서면 또는 전자문서를 총회에 제출해야 한다(상법 제368조 제2항).","c":"상","v":1},"세무사2023_60-59-2":{"f":"회사가 전자적 방법으로 의결권을 행사하는 경우에는 출석주주의 의결권의 과반수로써 감사를 선임할 수 있다.","w":"전자투표를 도입한 회사는 출석 주주 의결권의 과반수만으로 감사를 선임할 수 있고, 발행주식총수의 4분의 1 이상이라는 요건은 필요 없다(상법 제409조 제3항).","c":"상","v":1},"세무사2023_60-59-3":{"f":"주주총회의 의장은 정관에서 정함이 없는 때에는 총회에서 선출한다.","w":"정관에 정함이 없으면 총회에서 의장을 선출한다(상법 제366조의2 제1항). 이사회가 선임하지 않는다.","c":"상","v":1},"세무사2023_60-59-5":{"f":"주주총회는 정당한 사유가 있는 경우에 특별결의로 이사를 해임할 수 있다.","w":"이사 해임은 특별결의로 하며(상법 제385조 제1항, 제434조), 정당한 이유 없이 해임하면 이사가 손해배상을 청구할 수 있다.","c":"상","v":1},"세무사2024_61-54-2":{"f":"결의내용이 정관에 위반한 때 주주는 결의의 날로부터 2월내에 결의취소의 소를 제기할 수 있다.","w":"결의취소의 소는 결의일부터 2개월 내에 제기해야 한다(상법 제376조 제1항). 2주가 아니다.","c":"상","v":1},"세무사2024_61-54-3":{"f":"주주총회의 소집절차 또는 결의방법에 결의가 존재한다고 볼 수 없을 정도의 중대한 하자가 있는 경우에는 결의부존재확인 소의 대상이다.","w":"소집절차나 결의방법의 하자가 결의의 존재를 인정할 수 없을 정도면 결의부존재확인의 소 대상이다(상법 제380조). 결의무효확인은 결의 내용이 법령에 위반한 경우다.","c":"상","v":1},"세무사2024_61-54-4":{"f":"결의내용이 법령에 위반한 경우에는 결의무효확인 소의 대상이다.","w":"결의 내용이 법령에 위반하면 결의무효확인의 소 대상이다(상법 제380조). 결의부존재확인은 결의가 존재한다고 볼 수 없을 정도의 하자가 있을 때다.","c":"상","v":1},"세무사2024_61-54-5":{"f":"이사인 주주가 결의취소의 소를 제기한 때에는 법원은 회사의 청구에 의하여도 담보를 제공할 것을 명할 수 없다.","w":"주주가 결의취소의 소를 제기하면 회사의 청구로 담보를 제공하게 할 수 있지만, 그 주주가 이사 또는 감사이면 담보를 명하지 못한다(상법 제377조 제1항 단서).","c":"상","v":1},"세무사2024_61-56-2":{"f":"회사는 이사회의 결의로 주주가 총회에 출석하지 아니하고 전자적 방법으로 의결권을 행사할 수 있음을 정할 수 있다.","w":"전자투표를 도입하는 것은 주주총회가 아니라 이사회의 결의로 정한다(상법 제368조의4 제1항).","c":"상","v":1},"세무사2024_61-62-1":{"f":"회사의 영업에 중대한 영향을 미치는 다른 회사의 영업 전부의 양수는 주주총회의 특별결의가 있어야 한다.","w":"다른 회사의 영업 전부를 양수하는 것이 회사 영업에 중대한 영향을 미치면 주주총회 특별결의가 필요하다(상법 제374조 제1항 제3호).","c":"상","v":1},"세무사2024_61-62-2":{"f":"이사의 임무해태로 인한 회사에 대한 손해배상책임은 총주주의 동의로 면제할 수 있다.","w":"이사의 회사에 대한 책임은 총주주의 동의로 면제한다(상법 제400조 제1항). 주주총회 특별결의로는 면제하지 못한다.","c":"상","v":1},"세무사2024_61-62-3":{"f":"주식회사는 총주주의 동의에 의하여 유한책임회사로 조직을 변경할 수 있다.","w":"주식회사를 유한책임회사로 조직변경할 때는 총주주의 동의가 필요하다(상법 제287조의43). 특별결의로는 부족하다.","c":"상","v":1},"세무사2024_61-62-5":{"f":"발기인이 중과실로 회사에 대한 손해배상책임을 지는 경우 총주주의 동의로 면제할 수 있다.","w":"발기인의 회사에 대한 임무해태 책임은 총주주의 동의로 면제한다(상법 제324조, 제400조). 보통결의로는 면제하지 못한다.","c":"상","v":1},"세무사2025_62-54-4":{"f":"주주의 의결권을 대리행사 하고자 하는 자가 총회에 제출하여야 하는 대리권을 증명하는 서면은 특별한 사정이 없는 한 사본이 아닌 원본을 제출하여야 한다.","w":"대리권을 증명하는 서면은 원본이어야 하고 사본으로는 대리권 증명이 되지 않는다는 것이 판례의 취지다.","c":"중","v":1},"세무사2025_62-56-1":{"f":"결의취소의 소의 제소권자는 주주ㆍ이사 또는 감사이다.","w":"결의취소의 소는 주주ㆍ이사ㆍ감사가 제기하며 회사채권자는 포함되지 않는다(상법 제376조 제1항).","c":"상","v":1},"세무사2025_62-56-3":{"f":"결의취소의 소가 제기된 경우, 회사의 현황과 제반사정을 참작하여 그 취소가 부적당하다고 인정한 때에는 그 원인이 된 하자가 보완되지 않았더라도 법원은 그 청구를 기각할 수 있다.","w":"재량기각(상법 제379조)에서 법원은 결의 내용, 회사 현황 등 제반사정을 보고 판단하며 하자가 보완되었을 것까지 요구하지 않는다.","c":"중","v":1},"세무사2025_62-56-4":{"f":"결의무효확인을 청구하는 소가 인용된 경우, 그 판결은 판결확정전에 생긴 회사와 주주 및 제3자간의 권리의무에 영향을 미친다.","w":"결의무효확인판결은 소급효가 있어 확정 전의 권리의무에도 영향을 준다. 장래에만 효력이 있다는 단서(제190조 단서)는 준용되지 않는다(상법 제380조).","c":"상","v":1},"세무사2025_62-56-5":{"f":"부당결의의 취소, 변경의 소는 결의의 날로부터 2월내에 제기하여야 한다.","w":"부당결의 취소ㆍ변경의 소도 결의의 날부터 2개월 내에 제기해야 한다(상법 제381조 제1항).","c":"상","v":1},"세무사2026_63-49-1":{"f":"회사는 주주총회의 회의의 목적사항에 상법상 반대주주의 주식매수청구권이 인정되는 사항이 포함된 경우에는 의결권 없는 종류주식의 주주에게도 주주총회의 소집을 통지하여야 한다.","w":"의결권 없는 주주에게는 원칙적으로 소집통지를 하지 않지만, 주식매수청구권이 인정되는 안건이 있으면 통지해야 한다(상법 제363조 제7항 단서).","c":"상","v":1},"세무사2026_63-49-3":{"f":"주주총회에서는 주주총회의 연기의 결의를 할 수 있고, 이 경우 연기되어 개최되는 주주총회에 앞서 상법상의 주주총회 소집절차를 거치지 않아도 된다.","w":"총회의 연기ㆍ속행 결의가 있으면 다시 소집절차를 밟지 않고 속행회를 열 수 있다(상법 제372조).","c":"상","v":1},"세무사2026_63-49-4":{"f":"자본금 총액 10억원 미만 회사는 결의의 목적사항에 대하여 주주 전원이 서면으로 동의를 한 때에는 서면에 의한 결의가 있는 것으로 본다.","w":"소규모 회사의 서면결의는 주주 전원의 서면 동의가 있어야 한다(상법 제363조 제4항). 과반수 동의로는 부족하다.","c":"상","v":1},"세무사2026_63-49-5":{"f":"주주총회는 본점소재지 또는 이에 인접한 지에서 소집하여야 하고 정관에서 이와 다르게 정할 수 있다.","w":"총회 장소는 본점소재지 또는 인접지가 원칙이지만 정관으로 달리 정할 수 있다(상법 제364조).","c":"상","v":1},"세무사2026_63-55-5":{"f":"의결권 없는 주식을 제외한 발행주식총수의 100분의 3을 초과하는 수의 주식을 가진 주주의 의결권은 감사 선임결의에서 그 초과하는 주식에 한하여 출석한 주주의 의결권 수에 산입되지 않는다.","w":"감사 선임에서 의결권이 제한되는 것은 3%를 초과하는 주식만이고, 보유분 전부가 제외되는 것이 아니다(상법 제409조 제2항).","c":"상","v":1},"세무사2016_53-47-4":{"f":"이사회의사록의 열람 또는 등사를 청구하려는 주주는 보유 주식의 수에 제한이 없다.","w":"이사회의사록 열람ㆍ등사는 지분 요건이 없는 단독주주권이다. 회사는 이유를 붙여 거절할 수 있고, 주주는 법원의 허가를 얻어 열람할 수 있다(상법 제391조의3 제3항, 제4항).","c":"상","v":1},"세무사2016_53-48-4":{"f":"감사는 이사가 회사에 대하여 소를 제기하는 경우에 그 소에 관하여 회사를 대표한다.","w":"회사와 이사 사이의 소송에서는 대표이사가 아니라 감사가 회사를 대표한다(상법 제394조 제1항).","c":"상","v":1},"세무사2016_53-49-2":{"f":"이사는 이사회의 승인이 없으면 자기 또는 제3자의 계산으로 회사의 영업부류에 속한 거래를 할 수 없으며 이 경우 이사회의 승인은 이사 과반수의 출석과 출석이사의 과반수로써 하여야 한다.","w":"경업 승인에는 따로 정한 요건이 없어 일반 이사회 결의(이사 과반수 출석과 출석이사 과반수)로 한다(상법 제397조 제1항, 제391조 제1항). 이사 3분의 2 이상이 필요한 것은 회사 기회 유용 승인(제397조의2)과 자기거래 승인(제398조)이다.","c":"상","v":1},"세무사2016_53-50-5":{"f":"집행임원이 이사회 소집청구를 한 후 이사가 지체없이 이사회 소집 절차를 밟지 아니하면 집행임원은 법원의 허가를 받아 이사회를 소집할 수 있다.","w":"집행임원은 법원의 허가를 받아야 이사회를 소집할 수 있다(상법 제408조의7 제2항). 즉시 소집할 수 있는 것이 아니다.","c":"상","v":1},"세무사2017_54-55-5":{"f":"이사회의 결의로 이사 중에서 이사회의 소집권자를 정할 수 있다.","w":"이사회 결의로 소집권자를 정할 때는 이사 중에서 정한다(상법 제390조 제1항 단서). 감사는 이사에게 소집을 청구하고, 이사가 지체 없이 소집하지 않을 때 직접 소집할 수 있을 뿐이다(제412조의4).","c":"상","v":1},"세무사2017_54-58-1":{"f":"법원에 의한 직무대행자의 선임은 등기사항이다.","w":"이사 직무집행정지 가처분과 직무대행자 선임, 그 변경ㆍ취소는 본점 소재지에서 등기한다(상법 제407조 제3항).","c":"상","v":1},"세무사2017_54-61-5":{"f":"감사위원회의 결의에 대하여 이사회는 다시 결의할 수 없다.","w":"이사회내 위원회 결의를 이사회가 다시 결의할 수 있다는 규정은 감사위원회에 적용되지 않으므로, 이사회는 감사위원회의 결의를 다시 결의하지 못한다(상법 제415조의2 제6항).","c":"상","v":1},"세무사2017_54-62-3":{"f":"공동대표이사를 둔 경우 상대방이 공동대표이사 중 1인에 대하여 의사표시를 하면 회사에 대하여 그 효력이 생긴다.","w":"공동대표의 경우에도 제3자의 의사표시는 대표이사 1인에게만 하면 회사에 효력이 생긴다(상법 제389조 제3항, 제208조 제2항). 능동대표만 공동으로 한다.","c":"상","v":1},"세무사2017_54-64-1":{"f":"집행임원은 회사의 기회 및 자산의 유용 금지의무를 부담한다.","w":"집행임원에게도 이사의 사업기회 유용금지 규정이 준용된다(상법 제408조의9, 제397조의2).","c":"상","v":1},"세무사2017_54-64-3":{"f":"회사의 기회 및 자산의 유용 금지의 대상이 되는 사업기회를 이용하고자 하는 이사는 이사회의 승인결의에 있어서 의결권을 행사할 수 없다.","w":"해당 이사는 특별한 이해관계가 있으므로 승인결의에서 의결권을 행사하지 못한다(상법 제391조 제3항, 제368조 제3항).","c":"상","v":1},"세무사2017_54-64-4":{"f":"회사의 기회 및 자산의 유용 금지의 대상이 되는 사업기회에 대한 이사회의 승인은 이사 3분의 2 이상의 수로써 하여야 한다.","w":"사업기회 이용 승인은 이사 3분의 2 이상의 수로 한다(상법 제397조의2 제1항). 이사 전원의 동의까지 필요하지는 않다.","c":"상","v":1},"세무사2017_54-64-5":{"f":"회사의 기회 및 자산의 유용 금지 규정을 위반하여 회사에 손해를 발생시킨 이사는 회사에 대하여 손해를 배상하여야 하는데, 그 위반 행위로 인하여 제3자가 얻은 이익은 회사의 손해로 추정된다.","w":"이사나 제3자가 얻은 이익은 회사의 손해로 추정된다(상법 제397조의2 제2항).","c":"상","v":1},"세무사2017_54-65-1":{"f":"이사가 회사에 대하여 손해배상책임을 부담하는 경우 주주 전원의 동의로 그 책임을 면제할 수 있다.","w":"이사의 회사에 대한 책임은 총주주의 동의로 면제할 수 있다(상법 제400조 제1항).","c":"상","v":1},"세무사2017_54-65-2":{"f":"정기주주총회에서 재무제표를 승인한 후 2년내에 다른 결의가 없으면 회사는 이사의 책임을 해제한 것으로 본다.","w":"재무제표 승인 후 2년이 지나야 책임이 해제된 것으로 본다(상법 제450조). 1년이 아니고, 부정행위가 있으면 해제되지 않는다.","c":"상","v":1},"세무사2017_54-65-3":{"f":"회사는 이사가 고의 또는 중대한 과실로 손해를 발생시킨 경우에는 정관에 책임감면 규정이 있더라도 이사의 회사에 대한 손해배상책임을 최근 1년간의 보수액의 6배를 초과하는 금액에 대하여 면제할 수 없다.","w":"보수액 6배(사외이사는 3배)로 책임을 제한하는 정관 규정은 고의 또는 중대한 과실로 손해를 입힌 이사에게는 적용되지 않는다(상법 제400조 제2항 단서).","c":"상","v":1},"세무사2017_54-65-5":{"f":"이사가 이사회의 결의에 의하여 고의 또는 과실로 법령에 위반한 행위를 하여 회사에 손해를 배상할 책임을 지는 경우 그 이사회 결의에 참가한 이사로서 의사록에 이의를 한 기재가 없는 자는 그 결의에 찬성한 것으로 추정한다.","w":"찬성 추정을 받는 것은 결의에 참가하고도 의사록에 이의를 기재하지 않은 이사다(상법 제399조 제3항). 참가하지 않은 이사는 추정 대상이 아니다.","c":"상","v":1},"세무사2017_54-66-3":{"f":"준법지원인의 임기는 3년이며, 다만 다른 법률의 규정이 준법지원인의 임기를 3년보다 단기로 정하고 있는 경우에는 상법이 우선하여 적용된다.","w":"준법지원인의 임기는 3년이고(상법 제542조의13 제6항), 다른 법률이 임기를 이보다 짧게 정하고 있으면 상법의 3년 규정이 다른 법률보다 우선 적용된다(같은 조 제11항 단서).","c":"상","v":1},"세무사2021_58-58-3":{"f":"집중투표의 청구 서면은 총회가 종결될 때까지 본점에 비치하고 주주로 하여금 영업시간 내에 열람할 수 있게 하여야 한다.","w":"집중투표 청구 서면은 결산기 종료가 아니라 총회가 종결될 때까지 본점에 비치해 열람하게 한다(상법 제382조의2 제6항).","c":"상","v":1},"세무사2021_58-60-1":{"f":"이사회의 결의는 이사 과반수의 출석과 출석이사의 과반수로 하며, 그 비율은 정관으로 높게 정할 수 있다.","w":"이사회 결의 요건은 정관으로 높이는 것만 가능하고 낮추는 것은 불가능하다(상법 제391조 제1항 단서).","c":"상","v":1},"세무사2021_58-60-2":{"f":"이사는 이사회의 승인을 얻은 경우에도 타인에게 이사회의 출석과 의결권을 위임할 수 없다.","w":"이사는 이사회에 직접 출석해야 하고 대리 출석이나 의결권 위임은 허용되지 않는다. 이사회 승인으로 바꿀 수도 없다.","c":"상","v":1},"세무사2021_58-60-3":{"f":"이사회의 결의무효확인의 소가 인용되어 그 판결이 확정된 경우 대세적 효력이 인정되지 않는다.","w":"이사회 결의 무효확인의 소는 주주총회 결의 소송과 달리 판결의 대세효를 인정하는 규정이 없고 판례도 이를 인정하지 않는다.","c":"중","v":1},"세무사2021_58-60-5":{"f":"이사회의 결의에 관하여 특별한 이해관계가 있는 이사는 이사회의 승인이 있더라도 의결권을 행사할 수 없다.","w":"특별이해관계 있는 이사는 의결권을 행사하지 못한다(상법 제391조 제3항, 제368조 제3항). 이사회가 승인해도 마찬가지다.","c":"상","v":1},"세무사2021_58-63-1":{"f":"이사선임결의의 무효나 취소의 소가 제기된 경우, 법원은 당사자의 신청에 의하여 가처분으로써 이사의 직무집행을 정지할 수 있다.","w":"직무집행정지 가처분은 당사자의 신청이 있어야 하고 법원이 직권으로 하지 못한다(상법 제407조 제1항).","c":"상","v":1},"세무사2021_58-63-3":{"f":"법원은 본안소송이 제기되기 전이라도 급박한 사정이 있는 때에는 직무집행정지 가처분을 할 수 있다.","w":"본안소송 제기 전이라도 급박한 사정이 있으면 가처분을 할 수 있다(상법 제407조 제1항).","c":"상","v":1},"세무사2021_58-63-4":{"f":"가처분으로 선임된 직무대행자는 가처분명령에 다른 정함이 있는 경우 외에는 회사의 상무에 속하지 아니한 행위를 하지 못한다. 다만, 법원의 허가를 얻은 경우에는 그러하지 아니하다.","w":"상법 제408조 제1항은 가처분명령에 다른 정함이 있는 경우와 법원의 허가를 얻은 경우 두 가지를 예외로 둔다. 법원 허가만 예외로 적으면 가처분명령으로 상무 외 행위를 허용한 경우가 빠진다.","c":"중","v":1},"세무사2021_58-63-5":{"f":"가처분으로 선임된 직무대행자가 그 권한을 위반한 경우에도 회사는 선의의 제3자에 대하여 책임을 진다.","w":"직무대행자가 권한을 넘어 한 행위도 회사는 선의의 제3자에게 책임을 진다(상법 제408조 제2항).","c":"상","v":1},"세무사2021_58-64-1":{"f":"이사회는 대표이사의 선임에 관한 권한을 위원회에 위임할 수 없다.","w":"이사회내 위원회에 위임할 수 없는 사항에는 대표이사의 선임ㆍ해임이 포함된다(상법 제393조의2 제2항).","c":"상","v":1},"세무사2022_59-59-4":{"f":"이사는 이사회의 승인이 없으면 동종영업을 목적으로 하는 다른 회사의 이사가 될 수 없다.","w":"이사는 이사회의 승인 없이 동종영업을 하는 다른 회사의 무한책임사원이나 이사가 되지 못한다(상법 제397조 제1항).","c":"상","v":1},"세무사2022_59-66-2":{"f":"정관으로 이사가 가질 주식의 수를 정한 경우에 다른 규정이 없는 때에는 이사는 그 수의 주권을 감사에게 공탁하여야 한다.","w":"자격주는 법원이 아니라 감사에게 공탁한다(상법 제387조).","c":"상","v":1},"세무사2022_59-67-2":{"f":"이사회를 소집함에는 회일을 정하고 그 1주간전에 각 이사 및 감사에 대하여 통지를 발송하여야 한다. 그러나 그 기간은 정관으로 단축할 수 있다.","w":"소집통지 기간은 정관으로 단축할 수 있고, 이사회 결의로 정하지는 못한다(상법 제390조 제3항).","c":"상","v":1},"세무사2022_59-69-1":{"f":"대표이사의 선임은 정관으로 주주총회에서 선정하도록 정한 경우를 제외하고는 이사회의 결의에 의한다.","w":"대표이사는 원칙적으로 이사회가 선정하고, 정관으로 정한 경우에만 주주총회에서 선정한다(상법 제389조 제1항).","c":"상","v":1},"세무사2022_59-69-3":{"f":"대표이사가 정당한 이유없이 이사로서의 임기가 만료되기 전에 주주총회의 결의로 이사직에서 해임된 때에는 그 자는 회사에 대하여 해임으로 인한 손해의 배상을 청구할 수 있다.","w":"정당한 이유 없이 임기 중 해임된 이사는 회사에 손해배상을 청구할 수 있다(상법 제385조 제1항 단서).","c":"상","v":1},"세무사2022_59-69-4":{"f":"대표이사는 회사의 영업에 관하여 재판상 또는 재판 외의 모든 행위를 할 권한이 있다.","w":"대표이사의 권한에는 재판상 행위도 포함된다(상법 제389조 제3항, 제209조 제1항).","c":"상","v":1},"세무사2022_59-69-5":{"f":"회사가 이사에 대하여 소를 제기하는 경우에 감사는 그 소에 관하여 회사를 대표한다.","w":"회사가 이사를 상대로 소를 제기할 때는 대표이사가 아니라 감사가 회사를 대표한다(상법 제394조 제1항).","c":"상","v":1},"세무사2022_59-70-4":{"f":"이사가 중대한 과실로 그 임무를 게을리한 때에는 그 이사는 제3자에 대하여 연대하여 손해를 배상할 책임이 있다.","w":"이사의 제3자에 대한 책임은 고의 또는 중대한 과실이 있을 때 생긴다(상법 제401조 제1항). 경과실로는 책임이 없다.","c":"상","v":1},"세무사2022_59-71-1":{"f":"대표집행임원은 이사회의 결의에 의하여 선임한다.","w":"집행임원 설치회사에서는 이사회가 대표집행임원을 선임하고, 집행임원회의 같은 기관은 없다(상법 제408조의2 제3항).","c":"상","v":1},"세무사2023_60-55-1":{"f":"자본금 총액이 10억원 미만인 회사의 이사는 1명 또는 2명으로 할 수 있다.","w":"자본금 10억원 미만 회사는 이사를 1인이나 2인으로 둘 수 있다(상법 제383조 제1항 단서). 3명 이상은 일반 회사의 원칙이다.","c":"상","v":1},"세무사2023_60-55-2":{"f":"이사의 보수는 정관에 그 액을 정하지 아니한 때에는 주주총회의 결의로 정한다.","w":"정관에 보수액이 없으면 주주총회가 정한다(상법 제388조). 이사회가 정하지 않는다.","c":"상","v":1},"세무사2023_60-55-4":{"f":"이사회의 결의는 재임이사 과반수의 출석과 출석이사의 과반수로 하여야 한다.","w":"이사회 결의는 이사 과반수의 출석과 출석이사 과반수의 찬성으로 한다(상법 제391조 제1항). 3분의 2 출석은 요건이 아니다.","c":"상","v":1},"세무사2023_60-55-5":{"f":"주식의 포괄적 교환을 하고자 하는 회사는 주식교환계약서를 작성하여 주주총회의 승인을 얻어야 한다.","w":"주식교환계약서는 주주총회의 특별결의로 승인받는다(상법 제360조의3). 간이교환이나 소규모교환은 승인을 생략하거나 이사회 승인으로 대신한다.","c":"상","v":1},"세무사2023_60-61-5":{"f":"회사의 기회 및 자산의 유용에 관한 이사회의 승인은 이사 3분의 2 이상의 수로써 하여야 한다.","w":"사업기회 이용의 승인 요건은 이사 3분의 2 이상이다(상법 제397조의2 제1항).","c":"상","v":1},"세무사2023_60-62-2":{"f":"직무대행자가 법원의 허가 없이 상무에 속하지 아니한 행위를 하더라도 회사는 선의의 제3자에게 책임을 진다.","w":"직무대행자가 허가 없이 한 행위도 선의의 제3자에게는 회사가 책임을 진다(상법 제408조 제2항).","c":"상","v":1},"세무사2023_60-79-1":{"f":"사외이사는 3명 이상으로 하되, 이사 총수의 과반수가 되도록 하여야 한다.","w":"자산총액 2조원 이상 상장회사는 사외이사(2025.7.22 개정 뒤 명칭은 독립이사)를 3명 이상, 이사 총수의 과반수로 두어야 한다(상법 제542조의8 제1항 단서, 시행령 제34조 제2항). 그 밖의 상장회사 기준은 이사 총수의 4분의 1 이상이었다가 2025년 개정으로 3분의 1 이상이 되었다.","c":"상","v":1},"세무사2024_61-58-3":{"f":"회사가 공동대표이사를 둔 경우에는 제3자의 회사에 대한 의사표시는 공동대표이사 중 1인에 대하여 이를 하면 그 효력이 생긴다.","w":"수동대표는 단독으로 가능해서 상대방은 공동대표이사 1인에게 의사표시를 하면 된다(상법 제389조 제3항, 제208조 제2항).","c":"상","v":1},"세무사2024_61-59-3":{"f":"회사의 이사회는 집행임원과 회사 간의 소송에서 회사를 대표할 자를 선임한다.","w":"집행임원과 회사 사이의 소송에서 회사를 대표할 자는 이사회가 선임한다(상법 제408조의2 제3항 제3호). 이사회가 직접 회사를 대표하지는 않는다.","c":"상","v":1},"세무사2024_61-61-5":{"f":"이사회의 승인 없이 회사의 사업기회를 유용하여 회사에 손해를 발생시킨 이사는 이를 배상할 책임이 있으며 이로 인하여 이사 또는 제3자가 얻은 이익은 손해로 추정한다.","w":"이사나 제3자가 얻은 이익은 회사의 손해로 추정될 뿐 간주되지 않으므로 반증이 가능하다(상법 제397조의2 제2항).","c":"상","v":1},"세무사2024_61-63-1":{"f":"이사회의 결의로 이사회를 소집할 수 있는 이사를 정한 경우에는 대표이사도 소집권자에게 이사회 소집을 요구하여야 하고 요구하지 않고 이사회를 소집할 수 없다.","w":"소집권자를 정한 경우 다른 이사는 소집권자에게 소집을 요구하고, 소집권자가 정당한 이유 없이 거절한 때에야 직접 소집할 수 있다. 대표이사도 소집권자가 아니면 마찬가지다(상법 제390조 제1항 단서, 제2항).","c":"상","v":1},"세무사2024_61-63-2":{"f":"이사회 소집권이 없는 이사가 이사회 소집권 있는 이사에게 이사회 소집을 청구하였음에도 정당한 이유없이 이사회 소집을 거절하는 경우에는 그 이사는 이사회를 소집할 수 있다.","w":"소집권자가 정당한 이유 없이 거절하면 다른 이사가 직접 이사회를 소집한다(상법 제390조 제2항). 법원에 재지정을 청구하는 절차는 없다.","c":"상","v":1},"세무사2024_61-63-3":{"f":"집행임원 설치회사의 집행임원이 이사에게 적법하게 이사회 소집을 청구하였음에도 이사가 지체없이 이사회 소집절차를 밟지 않으면 집행임원은 법원의 허가를 받아 이사회를 소집할 수 있다.","w":"집행임원이 이사회를 소집하려면 법원의 허가가 필요하다(상법 제408조의7 제2항).","c":"상","v":1},"세무사2024_61-63-5":{"f":"감사는 적법하게 이사에게 이사회 소집을 청구했음에도 이사가 지체없이 이사회 소집을 하지 않는 경우에는 감사가 이사회를 소집할 수 있다.","w":"감사는 법원의 허가 없이 직접 이사회를 소집할 수 있다(상법 제412조의4 제2항). 법원 허가가 필요한 것은 집행임원이다.","c":"상","v":1},"세무사2025_62-57-5":{"f":"정관으로 이사가 가질 주식의 수를 정한 경우에 다른 규정이 없는 때에는 이사는 그 수의 주권을 감사에게 공탁하여야 한다.","w":"자격주는 법원이 아니라 감사에게 공탁한다(상법 제387조).","c":"상","v":1},"세무사2025_62-58-1":{"f":"이사회가 이사에 대하여 회사의 사업기회를 자기의 이익을 위하여 이용할 수 있도록 승인하려면 이사 3분의 2 이상의 수로 결의하여야 한다.","w":"사업기회 이용 승인은 이사 3분의 2 이상의 수가 필요하다(상법 제397조의2 제1항). 출석이사 과반수로는 부족하다.","c":"상","v":1},"세무사2025_62-58-2":{"f":"정관에 달리 정하는 경우를 제외하고, 이사가 직접 회의에 출석하지 아니하였더라도 모든 이사가 음성을 동시에 송수신하는 원격통신수단에 의하여 참석한 경우에는 그 이사는 이사회에 출석한 것으로 본다.","w":"원격 이사회는 모든 이사가 음성을 동시에 송수신하는 원격통신수단으로 결의에 참가하면 되고, 영상까지 요구하지 않는다(상법 제391조 제2항).","c":"상","v":1},"세무사2025_62-58-3":{"f":"감사는 이사회에 출석하여 의견을 진술할 수 있으나 의결권을 행사할 수 없다.","w":"감사는 이사회에 출석해 의견을 진술할 수 있을 뿐 이사가 아니므로 의결권이 없다(상법 제391조의2 제1항).","c":"상","v":1},"세무사2025_62-58-5":{"f":"이사회의 결의에 특별이해관계가 있는 이사가 의결권을 행사한 이사회 결의는 그 이사를 제외하고도 결의요건이 충족되면 유효하다.","w":"특별이해관계 이사의 의결권은 정족수에 산입되지 않는다. 그 이사를 빼고 계산해도 결의요건이 충족되면 결의는 유효하므로 언제나 무효가 되지는 않는다.","c":"중","v":1},"세무사2025_62-59-1":{"f":"회사는 회사를 대표할 이사를 주주총회에서 선정할 것을 정관으로 정할 수 있다.","w":"대표이사는 이사회가 선정하는 것이 원칙이고, 정관으로 정하면 주주총회에서 선정할 수 있다(상법 제389조 제1항).","c":"상","v":1},"세무사2025_62-59-2":{"f":"주식회사의 대표이사가 이사회의 결의를 거쳐야 할 대외적 거래행위에 관하여 이를 거치지 아니한 경우라도, 그 거래 상대방이 그와 같은 이사회 결의가 없었음을 알았거나 중대한 과실로 알지 못한 경우에는 그 거래행위는 무효이다.","w":"대법원 2021. 2. 18. 선고 2015다45451 전원합의체 판결로, 거래 상대방이 이사회 결의가 없었음을 알았거나 모른 데 중대한 과실이 있을 때에만 거래가 무효가 된다. 알 수 있었던 데 그친 경과실이면 거래는 유효하다.","c":"상","v":1},"세무사2025_62-59-3":{"f":"대표이사가 그 업무집행으로 인하여 타인에게 손해를 가한 때에는 회사의 귀책사유 유무와 관계없이 회사는 그 대표이사와 연대하여 배상할 책임이 있다.","w":"대표이사의 업무집행상 불법행위에 대해서는 회사의 귀책사유가 따로 필요하지 않고 회사가 연대책임을 진다(상법 제389조 제3항, 제210조).","c":"상","v":1},"세무사2025_62-59-5":{"f":"표현대표이사와 거래한 상대방인 제3자가 대표이사가 아닌 그 표현대표이사에게 회사를 대표할 권한이 있다고 믿었더라도, 그 믿는 데에 중대한 과실이 있으면 회사는 표현대표이사 규정에 의한 책임을 지지 않는다.","w":"표현대표이사 규정은 선의의 제3자를 보호하고, 판례는 중대한 과실이 있는 제3자를 보호하지 않는다(상법 제395조).","c":"상","v":1},"세무사2025_62-63-2":{"f":"이사의 제3자에 대한 손해배상책임은 주주 전원의 동의로 면제할 수 없다.","w":"총주주의 동의로 면제할 수 있는 것은 회사에 대한 책임이다(상법 제400조 제1항). 제3자에 대한 책임(제401조)은 면제 대상이 아니다.","c":"상","v":1},"세무사2025_62-74-5":{"f":"최근 사업연도 말 현재의 자산총액이 5천억원 이상인 상장회사는 준법지원인을 1명 이상 두어야 한다.","w":"준법지원인을 두어야 하는 상장회사는 자산총액 5천억원 이상이다(상법 제542조의13 제1항, 시행령). 1천억원 이상은 상근감사를 두는 기준이다.","c":"상","v":1},"세무사2026_63-60-2":{"f":"상법상 주식소유비율을 갖춘 주주가 회사에 대하여 집중투표에 의해 이사를 선임할 것을 청구하려면 정관에서 집중투표를 배제하지 않아야 한다.","w":"집중투표는 정관에 허용 규정이 없어도 청구할 수 있고, 정관으로 배제한 경우에만 청구하지 못한다(상법 제382조의2 제1항).","c":"상","v":1},"세무사2026_63-60-3":{"f":"회사의 사외이사가 모회사의 감사로 선임된 경우 사외이사직을 상실한다.","w":"모회사의 이사ㆍ감사ㆍ집행임원 및 피용자는 사외이사가 될 수 없고, 이에 해당하게 되면 사외이사직을 상실한다(상법 제382조 제3항).","c":"상","v":1},"세무사2026_63-60-4":{"f":"임기가 정해지지 않은 이사 乙을 정당한 이유없이 주주총회에서 해임한 경우 乙은 상법 제385조에 따라 회사에 손해배상을 청구할 수 없다.","w":"제385조의 손해배상은 임기가 정해진 이사를 정당한 이유 없이 임기 만료 전에 해임한 경우에 생긴다. 임기를 정하지 않았다면 청구할 수 없다.","c":"상","v":1},"세무사2026_63-60-5":{"f":"이사선임결의의 무효의 소가 제기된 경우 법원은 당사자의 신청에 의하여 이사의 직무집행을 정지하는 가처분을 할 수 있다.","w":"직무집행정지 가처분은 당사자의 신청이 있어야 하며 법원이 직권으로 하지 못한다(상법 제407조 제1항).","c":"상","v":1},"세무사2026_63-66-2":{"f":"이사회에서 정당한 이유없이 임기가 정해진 대표이사를 해임한 경우 해임된 대표이사는 상법 제385조의 유추적용을 주장하여 회사에게 손해배상을 청구할 수 없다.","w":"대표이사직만 이사회가 해임한 경우에는 이사 지위가 유지되므로 제385조를 유추적용할 수 없다는 것이 판례다.","c":"상","v":1},"세무사2026_63-74-2":{"f":"업무집행지시자가 고의로 이사에게 임무해태 행위를 지시하고, 이사가 중과실로 임무 해태 행위를 실행하여 회사가 아닌 제3자에게 손해를 입힌 경우 업무집행지시자와 이사가 연대하여 상법 제401조 제1항에 따라 제3자에게 손해배상책임을 부담한다.","w":"업무집행지시자는 이사로 보고(상법 제401조의2 제1항) 지시를 이행한 이사와 연대하여 책임을 진다. 업무집행지시자만 책임지는 것이 아니다.","c":"상","v":1},"세무사2026_63-78-5":{"f":"최근 사업연도 말 현재의 자산총액이 5천억원 이상인 상장회사는 준법통제에 관한 기준 및 절차를 마련하여야 한다.","w":"준법통제기준을 마련해야 하는 상장회사는 자산총액 5천억원 이상이다(상법 제542조의13 제1항). 1천억원은 상근감사 설치 기준이다.","c":"상","v":1},"세무사2016_53-54-4":{"f":"주식이 수인의 공유에 속하는 때에는 공유자는 주주의 권리를 행사할 자 1인을 정하여야 한다.","w":"공유자들이 공동으로 권리를 행사하는 것이 아니라 권리행사자 1인을 정해야 한다(상법 제333조 제2항).","c":"상","v":1},"세무사2016_53-55-3":{"f":"주식매수선택권은 이를 부여받을 자의 성명 등을 정하는 주주총회의 결의일부터 2년 이상 재임 또는 재직하여야 행사할 수 있다.","w":"행사 요건은 결의일부터 2년 이상 재임 또는 재직이다(상법 제340조의4 제1항). 1년이 아니다.","c":"상","v":1},"세무사2016_53-57-5":{"f":"회사가 주주명부의 폐쇄기간 또는 기준일을 정한 때에는 정관에 다른 정함이 없는 때에는 그 기간 또는 날의 2주간전에 이를 공고하여야 한다.","w":"폐쇄기간이나 기준일의 공고는 2주 전에 한다(상법 제354조 제4항). 1주가 아니다.","c":"상","v":1},"세무사2016_53-58-1":{"f":"회사는 정관에서 정하는 바에 따라 주권을 발행하는 대신 전자등록기관의 전자등록부에 주식을 등록할 수 있다.","w":"전자등록은 정관의 규정이 있어야 한다(상법 제356조의2 제1항).","c":"상","v":1},"세무사2016_53-69-1":{"f":"B회사는 회사의 권리를 실행함에 있어 그 목적을 달성하기 위하여 필요한 때에는 A회사 주식을 취득할 수 있으나 6월 이내에 처분하여야 한다.","w":"자회사가 모회사 주식을 예외적으로 취득한 경우 취득한 날부터 6개월 이내에 처분해야 한다(상법 제342조의2 제2항). 즉시 처분하는 것이 아니다.","c":"상","v":1},"세무사2017_54-67-1":{"f":"주식의 상환에 관한 종류주식을 발행한 회사는 상환주식의 취득의 대가로 현금 외에 유가증권이나 자산을 교부할 수 있으나 그 회사의 다른 종류주식은 교부할 수 없다.","w":"상환의 대가로 현금 외에 유가증권이나 그 밖의 자산을 줄 수 있지만 다른 종류주식은 줄 수 없다(상법 제345조 제4항).","c":"상","v":1},"세무사2017_54-69-4":{"f":"주권의 점유자는 이를 적법한 소지인으로 추정한다.","w":"주권의 점유자는 적법한 소지인으로 추정된다(상법 제336조 제2항).","c":"상","v":1},"세무사2017_54-71-2":{"f":"주식을 양수한 자는 자신의 성명과 주소를 주주명부에 기재하지 아니하면 회사에 대항하지 못한다.","w":"명의개서를 하지 않으면 대항하지 못하는 상대방은 양도인이 아니라 회사다(상법 제337조 제1항).","c":"상","v":1},"세무사2017_54-73-1":{"f":"주식매수선택권에 관한 사항을 정하는 주주총회결의일부터 2년을 재임 또는 재직한 자만 이를 행사할 수 있다.","w":"결의일부터 2년 이상 재임 또는 재직해야 행사할 수 있다(상법 제340조의4 제1항). 1년만 재직한 사람은 행사하지 못한다.","c":"상","v":1},"세무사2017_54-73-2":{"f":"주식매수선택권은 이를 양도할 수 없다.","w":"주식매수선택권은 양도할 수 없고 상속인만 행사할 수 있다(상법 제340조의4 제2항).","c":"상","v":1},"세무사2017_54-73-3":{"f":"주식매수선택권의 행사에 따라 발행할 신주 또는 양도할 자기의 주식은 회사의 발행주식총수의 100분의 10을 초과할 수 없다.","w":"주식매수선택권 부여에 따라 발행할 신주나 양도할 자기주식은 발행주식총수의 10%를 넘지 못한다(상법 제340조의2 제3항).","c":"상","v":1},"세무사2017_54-73-5":{"f":"주식매수선택권의 행사가액은 신주를 발행하는 경우에는 주식매수선택권의 부여 일을 기준으로 한 주식의 실질가액과 주식의 권면액(券面額) 중 높은 금액 이상으로 한다.","w":"신주 발행 시 행사가액은 부여일 기준 실질가액과 권면액 중 높은 금액 이상이어야 한다(상법 제340조의2 제4항 제1호).","c":"상","v":1},"세무사2017_54-74-1":{"f":"회사는 정관으로 정한 경우에는 주식의 전부를 무액면주식으로 발행할 수 있다.","w":"액면주식과 무액면주식은 섞어 발행할 수 없고 전부 어느 한쪽으로만 발행한다(상법 제329조 제1항).","c":"상","v":1},"세무사2017_54-74-3":{"f":"회사의 자본금은 액면주식을 무액면주식으로 전환함으로써 변경할 수 없다.","w":"액면주식과 무액면주식 사이의 전환은 자본금을 변경시키지 않는다(상법 제451조 제3항).","c":"상","v":1},"세무사2017_54-74-4":{"f":"회사는 정관으로 정하는 바에 따라 발행된 무액면주식을 액면주식으로 전환할 수 있다.","w":"무액면주식을 액면주식으로, 액면주식을 무액면주식으로 전환할 수 있다(상법 제329조 제4항).","c":"상","v":1},"세무사2017_54-74-5":{"f":"주권이 발행된 경우 주식의 질권자는 계속하여 주권을 점유하지 아니하면 그 질권으로써 제3자에게 대항할 수 없다.","w":"질권자는 계속해서 주권을 점유해야 질권을 제3자에게 대항할 수 있다(상법 제338조 제2항).","c":"상","v":1},"세무사2021_58-48-1":{"f":"회사는 주식을 양도하고자 하는 주주의 양도승인 청구가 있는 날부터 1개월 이내에 주주에게 그 승인여부를 서면으로 통지하여야 한다.","w":"승인 여부의 통지 기한은 청구일부터 1개월이다(상법 제335조의2 제2항). 20일은 거부 통지를 받은 주주가 지정이나 매수를 청구하는 기간이다.","c":"상","v":1},"세무사2021_58-48-2":{"f":"회사가 주주의 양도승인 청구를 거부한 경우, 거부의 통지를 받은 주주는 회사에 대하여 양도의 상대방의 지정이나 그 주식의 매수를 청구할 수 있다.","w":"거부 통지를 받은 주주는 상대방 지정 청구와 주식매수 청구 중 선택할 수 있고 지정 청구가 우선하는 것이 아니다(상법 제335조의2 제4항).","c":"상","v":1},"세무사2021_58-48-3":{"f":"주주의 양도상대방 지정청구에 대하여 청구가 있은 날부터 2주간 내에 회사가 상대방 지정의 통지를 하지 않은 경우, 주식양도에 관하여 이사회의 승인이 있는 것으로 본다.","w":"지정 통지가 2주 안에 없으면 양도를 승인한 것으로 본다(상법 제335조의3 제2항). 주주가 다시 매수를 청구하는 절차가 아니다.","c":"중","v":1},"세무사2021_58-48-5":{"f":"이사회의 승인을 얻지 아니한 주식의 양도는 주주총회의 특별결의가 있어도 회사에 대하여 효력이 없다.","w":"이사회 승인이 없는 양도는 당사자 사이에서만 유효하고 회사에는 효력이 없다. 승인은 이사회의 권한이어서 주주총회 특별결의로 대신하지 못한다(상법 제335조 제2항).","c":"중","v":1},"세무사2021_58-49-3":{"f":"회사는 성립한 날부터 2년을 경과한 후에 주주총회의 특별결의와 법원의 인가를 얻어서 주식을 액면미달의 가액으로 발행할 수 있다.","w":"액면미달 발행은 회사 성립 후 2년이 지난 뒤에 주주총회 특별결의와 법원의 인가를 받아야 한다(상법 제417조 제1항). 1년이 아니다.","c":"상","v":1},"세무사2021_58-51-5":{"f":"회사가 의결권이 제한되는 종류주식을 발행주식총수의 4분의 1을 초과하여 발행한 경우, 그 초과된 부분의 발행이 당연히 무효로 되지는 않는다.","w":"한도를 넘으면 회사는 지체 없이 한도 안으로 맞추는 필요한 조치를 해야 하고, 초과 발행이 당연 무효가 되지는 않는다(상법 제344조의3 제2항).","c":"상","v":1},"세무사2021_58-52-2":{"f":"회사가 전자등록부에 등록한 주식에 대하여는 선의취득이 인정된다.","w":"전자등록부를 선의로, 중대한 과실 없이 신뢰하고 등록에 따라 권리를 취득한 사람은 그 권리를 적법하게 취득한다(상법 제356조의2 제3항). 전자등록 주식도 선의취득이 인정된다.","c":"상","v":1},"세무사2021_58-54-1":{"f":"지배주주가 있는 회사의 소수주주는 정관의 규정이 없더라도 지배주주에게 그 보유주식의 매수를 청구할 수 있다.","w":"발행주식총수의 95% 이상을 가진 지배주주가 있으면 소수주주는 정관 규정 없이 매수를 청구할 수 있다(상법 제360조의25).","c":"상","v":1},"세무사2022_59-51-2":{"f":"회사는 주주총회의 특별결의로 액면주식을 무액면주식으로 전환하거나 무액면주식을 액면주식으로 전환할 수 있다.","w":"전환은 정관을 바꾸는 일이므로 특별결의가 필요하다(상법 제329조 제4항, 제434조).","c":"상","v":1},"세무사2022_59-51-3":{"f":"회사는 주주총회의 특별결의로 주식을 분할할 수 있으나 분할 후의 액면주식 1주의 금액은 100원 미만으로 하지 못한다.","w":"주식 분할은 주주총회 특별결의 사항이다(상법 제329조의2 제1항). 보통결의로는 하지 못한다.","c":"상","v":1},"세무사2022_59-51-4":{"f":"주식이 수인의 공유에 속하나 그 주식에 관한 주주의 권리를 행사할 자가 없는 경우 공유자에 대한 통지나 최고는 그 중 1인에 대하여 하면 된다.","w":"권리행사자가 정해지지 않았을 때 회사의 통지나 최고는 공유자 중 1인에게 하면 된다(상법 제333조 제3항).","c":"상","v":1},"세무사2022_59-51-5":{"f":"주주의 책임은 그가 가진 주식의 인수가액을 한도로 한다.","w":"주주는 주식의 인수가액을 한도로 유한책임을 진다(상법 제331조). 액면가액이 한도가 아니다.","c":"상","v":1},"세무사2022_59-52-1":{"f":"甲회사 이사회의 승인을 얻지 아니한 주식의 양도는 주식 양도인과 양수인 간에는 효력이 있다.","w":"이사회 승인이 없는 양도는 회사에 대해서만 효력이 없고 당사자 사이에서는 유효하다(판례, 상법 제335조 제2항).","c":"상","v":1},"세무사2022_59-52-2":{"f":"甲회사의 주주가 甲회사에 대하여 서면으로 양도의 승인을 청구한 경우 甲회사는 1월 이내에 주주에게 그 승인여부를 서면으로 통지하여야 한다.","w":"승인 여부는 청구일부터 1개월 이내에 서면으로 통지한다(상법 제335조의2 제2항). 2개월이 아니다.","c":"상","v":1},"세무사2022_59-52-3":{"f":"양도승인거부의 통지를 받은 주주는 통지를 받은 날부터 20일 이내에 甲회사에 대하여 양도의 상대방의 지정을 청구하거나 주식매수를 청구할 수 있다.","w":"기간은 20일이고, 상대방 지정 청구와 함께 주식매수 청구도 할 수 있다(상법 제335조의2 제4항).","c":"상","v":1},"세무사2022_59-52-5":{"f":"甲회사의 주식을 취득한 자는 甲회사에 대하여 그 주식의 종류와 수를 기재한 서면으로 그 취득의 승인을 청구할 수 있다.","w":"주식을 취득한 사람도 회사에 서면으로 취득 승인을 청구할 수 있다(상법 제335조의7 제1항).","c":"상","v":1},"세무사2022_59-53-5":{"f":"주주가 그 주식에 대하여 주권의 소지를 하지 아니하겠다는 뜻을 회사에 신고하려면 정관에 근거가 없어도 된다.","w":"주권불소지 신고는 정관에 다른 정함이 없으면 할 수 있는 주주의 권리다(상법 제358조의2 제1항). 정관에 근거가 있어야 하는 것이 아니다.","c":"상","v":1},"세무사2022_59-54-4":{"f":"이사ㆍ집행임원ㆍ감사의 선임과 해임 등 회사의 주요 경영사항에 대하여 사실상 영향력을 행사하는 자에게는 주식매수선택권을 부여할 수 없다.","w":"사실상 영향력을 행사하는 자와 그 배우자, 직계존비속에게는 주식매수선택권을 줄 수 없다(상법 제340조의2 제2항).","c":"상","v":1},"세무사2022_59-55-3":{"f":"회사는 자기주식을 취득하는 해당 영업연도의 결산기에 상법 규정에 따라 산정된 배당가능이익이 없을 우려가 있는 경우에는 자기주식을 취득할 수 없고, 이를 어긴 이사는 회사에 대하여 손해배상책임을 질 수 있다.","w":"결산기에 순자산액이 배당가능이익 산정 공제액 합계에 못 미칠 우려가 있으면 자기주식을 취득해서는 안 되고, 그런데도 취득했다면 이사는 회사에 연대하여 그 부족액을 배상할 책임을 진다(상법 제341조 제3항, 제4항).","c":"상","v":1},"세무사2022_59-57-3":{"f":"주주명부의 기준일은 주주 또는 질권자로서 권리를 행사할 날에 앞선 3월내의 날로 정하여야 하며 주주명부의 폐쇄 기간은 3월을 초과하지 못한다.","w":"기준일은 권리행사일 전 3개월 내의 날로 정하고 폐쇄기간도 3개월을 넘지 못한다(상법 제354조 제2항, 제3항). 2개월이 아니다.","c":"상","v":1},"세무사2022_59-58-5":{"f":"주식의 상환에 관한 종류주식을 발행한 회사는 그 주식 취득의 대가로 그 회사의 다른 종류주식을 교부할 수 없다.","w":"상환의 대가로 다른 종류주식은 줄 수 없다(상법 제345조 제4항).","c":"상","v":1},"세무사2022_59-64-4":{"f":"전환으로 인하여 신주식을 발행하는 경우에는 전환전의 주식의 발행가액을 신주식의 발행가액으로 한다.","w":"전환주식을 전환할 때 신주식의 발행가액은 전환 전 주식의 발행가액이다(상법 제348조). 액면가액이 기준이 아니다.","c":"상","v":1},"세무사2023_60-45-1":{"f":"주식의 분할이 이루어져도 회사의 자본금은 증가하지 않는다.","w":"주식 분할은 주식 수를 늘리고 1주의 액면금액을 그만큼 줄이는 것이어서 발행주식의 액면총액인 자본금(상법 제451조 제1항)은 변하지 않는다.","c":"상","v":1},"세무사2023_60-45-2":{"f":"주식의 분할 후의 주식 1주의 금액은 100원 미만으로 할 수 없다.","w":"분할 후 액면주식 1주의 금액은 100원 미만으로 하지 못한다(상법 제329조의2 제2항, 제329조 제3항).","c":"상","v":1},"세무사2023_60-45-3":{"f":"주식의 분할이 있으면 이로 인하여 종전의 주주가 받을 주식에 대하여는 종전의 주식을 목적으로 한 질권을 행사할 수 있다.","w":"주식의 분할로 종전 주주가 받을 주식에도 종전 주식에 대한 질권을 행사할 수 있다(상법 제339조).","c":"상","v":1},"세무사2023_60-45-4":{"f":"주식의 분할에 적당하지 아니한 수의 주식이 있는 때에 그 분할에 적당하지 아니한 부분에 대하여 발행한 신주는 거래소 시세있는 주식이면 거래소를 통하여 매각할 수 있다.","w":"단주 처리는 경매가 원칙이지만 거래소 시세가 있는 주식은 거래소를 통해 팔 수 있다(상법 제443조 제1항 단서).","c":"상","v":1},"세무사2023_60-46-1":{"f":"주식이 수인의 공유에 속하는 경우에는 주주의 권리를 행사할 자 1인을 정하여야 한다.","w":"공유자들은 주주의 권리를 행사할 사람 1인을 정해야 한다(상법 제333조 제2항).","c":"상","v":1},"세무사2023_60-48-3":{"f":"","w":"주권 발행 전에 한 양도는 회사에 대하여 효력이 없고, 회사성립 후 또는 신주 납입기일 후 6개월이 지난 때에만 주권 없이도 효력이 있다(상법 제335조 제3항). 사안의 양도 시점이 이 6개월 전이면 효력이 없다.","c":"중","v":1},"세무사2023_60-49-1":{"f":"이사회의 결의에 의하여 회사가 보유하는 자기주식을 소각하는 경우에는 자본금 감소에 관한 규정에 따르지 않아도 된다.","w":"자기주식 소각은 이사회 결의로 할 수 있고 자본금 감소 절차를 따를 필요가 없다(상법 제343조 제1항 단서).","c":"상","v":1},"세무사2023_60-49-2":{"f":"주주는 정관에 다른 정함이 있는 경우를 제외하고는 그 주식에 대하여 주권의 소지를 하지 아니하겠다는 뜻을 회사에 신고할 수 있는데, 이미 발행된 주권이 있는 경우에는 그 주권을 회사에 제출하여야 한다.","w":"이미 발행된 주권이 있어도 그 주권을 회사에 제출하면 불소지 신고를 할 수 있다(상법 제358조의2 제3항).","c":"상","v":1},"세무사2023_60-49-4":{"f":"주주가 회사에 대하여 상환을 청구할 수 있는 종류주식의 발행을 정한 정관규정은 유효하다.","w":"주주에게 상환청구권을 주는 상환주식도 발행할 수 있다(상법 제345조 제3항).","c":"상","v":1},"세무사2023_60-49-5":{"f":"회사는 정관에 정하는 바에 따라 전자문서로 주주명부를 작성할 수 있다.","w":"전자문서 주주명부는 정관에 규정이 있어야 작성할 수 있다(상법 제352조의2 제1항).","c":"상","v":1},"세무사2023_60-50-2":{"f":"甲회사는 정관에 의하여 의결권이 제한되는 종류주식을 발행하는 경우에는 그 종류주식의 발행총수가 발행주식총수의 4분의 1을 초과하지 못한다.","w":"의결권이 배제되거나 제한되는 종류주식은 발행주식총수의 4분의 1 이내여야 한다(상법 제344조의3 제2항).","c":"상","v":1},"세무사2023_60-51-4":{"f":"이사는 주주명부를 본점에 비치하여야 하고 명의개서대리인의 영업소에도 비치할 수 있다.","w":"명의개서대리인을 둔 경우 주주명부나 그 복본을 그 영업소에 둘 수 있다(상법 제396조 제1항).","c":"상","v":1},"세무사2023_60-54-5":{"f":"회사의 자본금은 무액면주식을 액면주식으로 전환함으로써 변경할 수 없고, 액면주식을 무액면주식으로 전환함으로써도 변경할 수 없다.","w":"어느 방향의 전환이든 자본금은 변하지 않는다(상법 제451조 제3항).","c":"상","v":1},"세무사2024_61-45-5":{"f":"회사가 전환주식을 전환하면 정관에 기재된 회사가 발행할 주식의 총수는 감소하지 않는다.","w":"전환은 정관을 바꾸는 일이 아니어서 정관의 발행예정주식총수는 그대로다. 전환으로 새로 발행할 주식의 수는 전환 기간 동안 발행을 유보해 둔다(상법 제346조 제4항).","c":"중","v":1},"세무사2024_61-47-1":{"f":"상환주식은 상환과 전환에 관한 것을 제외한 종류주식에 한정하여 발행할 수 있다.","w":"상환주식은 상환과 전환에 관한 것을 뺀 종류주식(이익배당·잔여재산분배·의결권에 관한 종류주식)으로만 발행할 수 있다(상법 제345조 제5항).","c":"상","v":1},"세무사2024_61-47-2":{"f":"회사가 상환주식을 발행하면 회사의 자본금이 증가한다.","w":"상환주식도 신주 발행이어서 발행 시점에는 자본금이 늘어난다. 상환할 때 이익으로 소각하면 자본금은 줄지 않는다.","c":"중","v":1},"세무사2024_61-47-4":{"f":"주주에게 상환청구권이 부여된 상환주식을 회사가 발행한 경우 그 내용을 주권에 기재할 의무가 있다.","w":"상환주식을 발행하면 상환의 뜻과 내용을 주권에 적어야 한다(상법 제356조 제6호).","c":"중","v":1},"세무사2024_61-47-5":{"f":"회사에게 상환권이 부여된 상환주식을 회사가 상환하는 경우 주식취득일로부터 2주 전에 그 주식의 주주 및 주주명부에 적힌 권리자에게 따로 통지해야 하며 이를 공고로 갈음할 수 있다.","w":"회사는 상환대상 주식의 취득일부터 2주 전에 주주와 주주명부상 권리자에게 따로 통지해야 하지만, 이 통지는 공고로 갈음할 수 있다(상법 제345조 제2항).","c":"상","v":1},"세무사2024_61-49-4":{"f":"질권의 목적인 주식이 분할된 경우 등록질권자는 분할에 의해 새로 발행되는 주식에 대한 주권의 교부를 청구할 수 있다.","w":"등록질권자는 주식 분할로 새로 발행되는 주식의 주권을 회사에 청구할 수 있다(상법 제340조 제3항, 제339조).","c":"상","v":1},"세무사2024_61-50-1":{"f":"A회사가 乙이 주식을 양수한 사실을 알고 있더라도 명의개서를 하지 않은 乙에게 주주권 행사를 인정할 의무는 없다.","w":"명의개서를 하지 않은 양수인은 회사에 대항하지 못한다(상법 제337조 제1항). 회사가 양수 사실을 알아도 마찬가지다.","c":"상","v":1},"세무사2024_61-52-2":{"f":"적법하게 주권불소지 신고를 한 甲이 A회사가 설립된 지 6개월이 지나기 전에 乙에게 주식을 양도하였다면 A회사에 대해 그 효력이 없다.","w":"주권불소지 신고로 주권이 발행되지 않은 상태에서 한 양도는 주권발행 전 양도와 같아서, 회사성립 후 6개월이 지나기 전에는 회사에 대해 효력이 없다(상법 제335조 제3항).","c":"중","v":1},"세무사2024_61-53-5":{"f":"A회사가 B회사의 주식 일부를 처분하여 40% 지분만을 갖게 된 경우에는 A회사는 매도청구권을 행사할 수 없다.","w":"지배주주의 매도청구는 발행주식총수의 95% 이상을 가진 주주만 할 수 있다(상법 제360조의24 제1항). 40%로는 요건에 못 미친다.","c":"상","v":1},"세무사2024_61-55-5":{"f":"회사는 이사의 해임 등 회사의 주요 경영사항에 대하여 사실상 영향력을 행사하는 자의 직계존비속에 대하여 주식매수선택권을 부여할 수 없다.","w":"사실상 영향력을 행사하는 자의 배우자와 직계존비속에게도 주식매수선택권을 줄 수 없다(상법 제340조의2 제2항).","c":"상","v":1},"세무사2024_61-71-1":{"f":"회사가 보유하는 자기주식을 이사회 결의에 의하여 소각하는 경우에는 채권자보호절차를 밟지 않아도 된다.","w":"자기주식의 소각은 이사회 결의로 하며 자본금 감소 절차(채권자보호절차)가 필요 없다(상법 제343조 제1항 단서).","c":"상","v":1},"세무사2025_62-44-2":{"f":"주식회사를 모집설립하는 경우 액면주식은 창립총회의 승인을 얻더라도 액면미달의 가액으로 발행할 수 없다.","w":"설립 시에는 액면미달 발행이 허용되지 않는다. 액면미달 발행은 회사 성립 후 2년이 지나 특별결의와 법원 인가를 거쳐야 가능하다(상법 제330조, 제417조).","c":"상","v":1},"세무사2025_62-45-3":{"f":"회사성립후 6월이 경과하도록 회사가 주권을 발행하지 않은 경우 주주는 주권 없이도 주식을 양도할 수 있다.","w":"회사성립 후 6개월이 지나도록 주권이 발행되지 않으면 주권 없이 한 양도도 회사에 대해 효력이 있다(상법 제335조 제3항 단서).","c":"상","v":1},"세무사2025_62-46-3":{"f":"전환으로 인하여 신주식을 발행하는 경우 회사의 자본금이 언제나 증가하는 것은 아니다.","w":"전환 전 주식의 발행가액이 신주식의 발행가액이 되므로(상법 제348조), 자본금은 전환 비율에 따라 달라진다. 신주식 수가 전환 전보다 많으면 자본금이 늘고, 같으면 그대로이며, 적으면 줄어든다.","c":"중","v":1},"세무사2025_62-47-1":{"f":"회사가 명의개서대리인을 둔 경우에 이사는 주주명부의 복본을 명의개서대리인의 영업소에 둘 수 있다.","w":"주주명부 원본은 본점에 두고 복본을 대리인 영업소에 둔다는 식의 구분은 법에 없다. 대리인을 둔 경우 주주명부나 복본을 그 영업소에 둘 수 있다(상법 제396조 제1항).","c":"중","v":1},"세무사2025_62-47-2":{"f":"회사의 주주는 영업시간 내에 주주명부의 열람을 청구할 수 있다.","w":"주주와 채권자는 영업시간 안에 주주명부의 열람이나 등사를 청구한다(상법 제396조 제2항). 영업시간과 무관하게 언제든 청구하는 것은 아니다.","c":"상","v":1},"세무사2025_62-47-3":{"f":"주주명부의 폐쇄기간은 3월을 초과하지 못한다.","w":"폐쇄기간의 한도는 3개월이다(상법 제354조 제2항).","c":"상","v":1},"세무사2025_62-47-5":{"f":"정관으로 주주명부의 폐쇄기간을 정한 때에는 회사는 그 기간의 2주간 전에 이를 공고할 필요가 없다.","w":"정관에 폐쇄기간이 정해져 있으면 별도 공고가 필요 없다(상법 제354조 제4항 단서).","c":"상","v":1},"세무사2025_62-48-1":{"f":"회사는 성립 후 지체없이 주권을 발행하여야 한다.","w":"회사는 성립 후 또는 신주 납입기일 후 지체 없이 주권을 발행해야 한다(상법 제355조 제1항). 6개월은 발행 전 양도의 효력에 관한 기간이다.","c":"상","v":1},"세무사2025_62-50-2":{"f":"주식매수선택권의 행사가액은 회사가 자기주식을 양도하는 경우에는 주식매수선택권의 부여일을 기준으로 한 주식의 실질가액 이상이어야 한다.","w":"기준 시점은 행사일이 아니라 부여일이다(상법 제340조의2 제4항 제2호).","c":"상","v":1},"세무사2025_62-52-1":{"f":"회사가 발행하는 의결권 배제ㆍ제한 종류주식은 발행주식 총수의 4분의 1을 초과하지 못한다.","w":"4분의 1 한도는 의결권이 배제되거나 제한되는 종류주식에만 적용되고 모든 종류주식에 적용되지 않는다(상법 제344조의3 제2항).","c":"상","v":1},"세무사2026_63-50-1":{"f":"A회사가 정관이 정하는 바에 따라 종전의 액면주식을 무액면주식으로 전환하는 경우 회사채권자보호절차를 거치지 않아도 된다.","w":"액면주식과 무액면주식 사이의 전환으로는 자본금이 바뀌지 않으므로(상법 제451조 제3항) 채권자보호절차가 없다. 주권 제출 공고 등 제440조, 제441조 본문, 제442조만 준용된다(상법 제329조 제5항).","c":"상","v":1},"세무사2026_63-54-4":{"f":"A회사는 타인의 명의로 A회사의 계산으로 甲과 乙로부터 A회사의 주식을 취득할 수 없다.","w":"상법 제341조 제1항은 회사가 자기의 명의와 계산으로 자기주식을 취득하도록 정한다. 타인 명의로 회사 계산에 따라 취득하는 것은 이 방법에 해당하지 않는다.","c":"상","v":1},"세무사2026_63-57-1":{"f":"주식매수선택권의 행사가액이 주식의 실질가액보다 낮은 경우 회사는 그 차액을 금전으로 지급할 수 있는데 이때 주식의 실질가액은 주식매수선택권의 행사일을 기준으로 평가한다.","w":"차액을 금전이나 자기주식으로 줄 때 주식의 실질가액은 주식매수선택권의 행사일을 기준으로 평가한다(상법 제340조의2 제1항 단서).","c":"상","v":1},"세무사2026_63-57-2":{"f":"주식매수선택권에 관한 정관규정에는 일정한 경우 이사회결의로 주식매수선택권의 부여를 취소할 수 있다는 뜻을 기재하여야 한다.","w":"취소의 주체는 대표이사가 아니라 이사회 결의다(상법 제340조의3 제1항).","c":"상","v":1},"세무사2026_63-57-3":{"f":"주식매수선택권을 행사할 수 있는 자가 사망한 경우 그 상속인은 이를 행사할 수 있다.","w":"선택권은 양도할 수 없지만 상속인은 행사할 수 있다(상법 제340조의4 제2항).","c":"상","v":1},"세무사2026_63-57-5":{"f":"주식매수선택권의 행사기간은 주식매수선택권에 관한 정관의 규정에 기재하여야 한다.","w":"정관에는 선택권의 행사기간이 기재된다(상법 제340조의3 제1항).","c":"상","v":1},"세무사2026_63-59-1":{"f":"甲이 A회사에 대하여 주식양도의 승인을 청구했다면, A회사는 甲에게 서면으로 승인 여부를 통지하여야 한다.","w":"승인 여부는 청구일부터 1개월 이내에 서면으로 통지해야 한다(상법 제335조의2 제2항). 구두 통지로는 부족하다.","c":"상","v":1},"세무사2026_63-59-2":{"f":"甲이 A회사에 대하여 사전에 양도승인 청구를 하지 않았더라도, 甲으로부터 주식을 취득한 乙은 A회사에 대하여 그 취득의 승인을 청구할 수 있다.","w":"주식을 취득한 사람은 양도인의 사전 승인 청구가 없었더라도 회사에 취득의 승인을 청구할 수 있다(상법 제335조의7 제1항).","c":"상","v":1},"세무사2026_63-59-3":{"f":"A회사로부터 승인거부의 통지를 받은 甲이 양도상대방의 지정을 청구했음에도 A회사가 지정청구를 받은 날로부터 2주간내에 상대방지정의 통지를 하지 아니하였다면, A회사가 주식양도를 승인한 것으로 본다.","w":"지정청구가 있은 날부터 2주 안에 상대방지정 통지를 하지 않으면 주식양도에 관하여 이사회의 승인이 있는 것으로 본다(상법 제335조의3 제2항). 주주가 매수를 청구한 것으로 보는 것이 아니다.","c":"상","v":1},"세무사2026_63-59-4":{"f":"A회사가 甲의 지정청구에 따라 丙을 양도상대방으로 지정하였음에도 丙이 지정통지를 받은 날로부터 10일이내에 甲에게 그 주식의 매도를 청구하지 않았다면, 주식의 양도에 관하여 이사회의 승인이 있는 것으로 본다.","w":"지정된 상대방이 10일 안에 매도청구를 하지 않으면 주식의 양도에 관하여 이사회의 승인이 있는 것으로 본다(상법 제335조의4 제2항, 제335조의3 제2항). 甲과 丙 사이에 매매계약이 성립하는 것은 아니다.","c":"상","v":1},"세무사2026_63-63-2":{"f":"주권이 분실된 경우 공시최고를 하여 제권판결을 받아야 회사에 대하여 주권의 재발행을 청구할 수 있다.","w":"주권을 잃어버린 사람은 제권판결을 받아야 재발행을 청구할 수 있고, 공시최고만으로는 청구할 수 없다(상법 제360조 제2항).","c":"상","v":1},"세무사2026_63-63-3":{"f":"회사는 신주발행의 경우 주금납입기일 후가 아니면 주권을 발행할 수 없다.","w":"신주의 주권은 납입기일 후에야 발행할 수 있고, 그 전에 발행한 주권은 무효다(상법 제355조 제2항).","c":"상","v":1},"세무사2026_63-63-4":{"f":"타인의 승낙없이 그 명의로 주식을 인수한 자는 주식인수인으로서의 책임이 있다.","w":"타인의 승낙 없이 그 명의로 주식을 인수한 사람은 주식인수인으로서 책임을 진다(상법 제332조 제1항).","c":"상","v":1},"세무사2026_63-63-5":{"f":"주식이 공유관계에 있는 경우 주주의 권리를 행사할 자를 정하지 않은 때에는 공유자 중 1인에게 통지나 최고를 하면 된다.","w":"권리행사자가 정해지지 않았으면 회사의 통지나 최고는 공유자 중 1인에게 하면 된다(상법 제333조 제3항).","c":"상","v":1},"세무사2026_63-64-2":{"f":"액면주식의 경우 주주총회의 특별결의로 주식을 분할할 수 있다.","w":"주식 분할은 주주총회 특별결의 사항이다(상법 제329조의2 제1항).","c":"상","v":1},"세무사2026_63-68-3":{"f":"무액면주식을 발행한 회사에서 주식 발행가 총액에서 자본금에 계상하는 금액을 결정하는 권한은 신주발행사항 결정 권한이 주주총회에 있는 회사에서는 주주총회가 갖는다.","w":"자본금 계상액은 신주발행사항을 결정하는 기관이 정한다. 그 권한이 이사회에 있으면 이사회, 주주총회에 있으면 주주총회가 정한다(상법 제451조 제2항).","c":"상","v":1},"세무사2026_63-69-3":{"f":"이익배당을 받을 자를 정하기 위한 기준일이 정관에 정해져 있는 때에는 회사는 그 기준일을 공고할 필요가 없다.","w":"정관에 기준일이 정해져 있으면 2주 전 공고가 필요 없다(상법 제354조 제4항 단서).","c":"상","v":1},"세무사2016_53-59-5":{"f":"신주의 인수인이 납입 또는 현물출자의 이행을 한 때에는 납입기일의 다음날로부터 주주의 권리의무가 발생한다.","w":"주주의 권리의무는 변경등기일이 아니라 납입기일의 다음 날부터 생긴다(상법 제423조 제1항).","c":"상","v":1},"세무사2016_53-60-1":{"f":"결손의 보전(補塡)을 위한 자본금의 감소는 주주총회의 보통결의에 의하여야 한다.","w":"자본금 감소는 원칙적으로 특별결의이지만 결손 보전을 위한 감소는 보통결의로 한다(상법 제438조 제2항).","c":"상","v":1},"세무사2016_53-64-4":{"f":"사채권자집회의 결의요건은 출석한 사채권자의 의결권의 3분의 2 이상이고 사채 총액의 3분의 1 이상이다.","w":"사채권자집회 결의에는 주주총회 특별결의 규정(제434조)이 준용되어, 출석 사채권자 의결권의 3분의 2 이상과 사채 총액의 3분의 1 이상의 찬성이 필요하다(상법 제495조 제1항).","c":"상","v":1},"세무사2016_53-65-2":{"f":"사채관리회사는 사채를 발행한 회사와 사채권자집회의 동의를 얻어 사임할 수 있고, 부득이한 사유가 있으면 법원의 허가를 받아 사임할 수 있다.","w":"사채관리회사는 발행회사와 사채권자집회의 동의를 받아 사임할 수 있고, 부득이한 사유가 있어 법원의 허가를 받은 경우에도 사임할 수 있다(상법 제481조).","c":"상","v":1},"세무사2017_54-68-5":{"f":"이사와 통모하여 현저하게 불공정한 발행가액으로 주식을 인수한 자는 회사에 대하여 공정한 발행가액과의 차액에 상당한 금액을 지급할 의무가 있다.","w":"통모인수인이 차액을 지급할 상대방은 회사채권자가 아니라 회사다(상법 제424조의2 제1항).","c":"상","v":1},"세무사2017_54-75-2":{"f":"각 신주인수권부사채에 부여된 신주인수권의 행사로 인하여 발행할 주식의 발행 가액의 합계액은 각 신주인수권부사채의 금액을 초과할 수 없다.","w":"신주인수권 행사로 발행할 주식의 발행가액 합계는 각 신주인수권부사채의 금액을 넘지 못한다(상법 제516조의2 제3항).","c":"상","v":1},"세무사2017_54-75-3":{"f":"신주의 발행가액의 전액을 납입한 자만 신주인수권을 행사할 수 있다.","w":"신주인수권을 행사하려면 발행가액 전액을 납입해야 하고 일부만 납입해서는 행사할 수 없다(상법 제516조의9 제1항).","c":"상","v":1},"세무사2017_54-75-4":{"f":"주주외의 자에 대한 신주인수권부사채의 발행은 정관에 규정이 있거나 주주총회 특별결의가 있고 경영상 목적을 달성하기 위하여 필요한 경우에 할 수 있다.","w":"주주 외의 자에게도 신주인수권부사채를 발행할 수 있다. 정관에 규정이 없으면 발행액·신주인수권의 내용·행사기간을 주주총회 특별결의로 정해야 하고, 경영상 목적이 필요하다는 제418조 제2항 단서가 준용된다(상법 제516조의2 제4항).","c":"상","v":1},"세무사2017_54-75-5":{"f":"회사는 신주인수권증권을 발행하는 대신 정관으로 정하는 바에 따라 전자등록기관의 전자등록부에 신주인수권을 등록할 수 있다.","w":"신주인수권증권을 발행하지 않고 전자등록부에 등록하는 방법을 정관으로 정할 수 있다(상법 제516조의7).","c":"중","v":1},"세무사2017_54-77-2":{"f":"회사가 다른 회사의 발행주식총수의 10분의 1을 초과하는 주식을 취득한 때에는 그 다른 회사에 대하여 지체없이 이를 통지하여야 한다.","w":"통지 의무는 10분의 1을 초과하여 취득할 때 생긴다(상법 제342조의3). 100분의 1이 아니다.","c":"상","v":1},"세무사2017_54-80-1":{"f":"이사회의 결의에 의하여 회사가 보유하는 자기주식을 소각하는 경우에는 자본금 감소에 관한 규정에 따르지 않아도 된다.","w":"자기주식 소각은 이사회 결의로 하며 자본금 감소 규정을 따를 필요가 없다(상법 제343조 제1항 단서).","c":"상","v":1},"세무사2021_58-68-1":{"f":"회사는 정관의 규정에 의하여 경영상 목적을 달성하기 위하여 필요한 경우에 한하여 주주 외의 자에게 신주를 배정할 수 있다.","w":"주주 외의 자에게 신주를 배정하려면 정관에 근거가 있어야 하고 경영상 목적이 필요하다(상법 제418조 제2항).","c":"상","v":1},"세무사2021_58-69-2":{"f":"사채관리회사는 사채를 발행한 회사와 사채권자집회의 동의를 얻어 사임할 수 있고, 부득이한 사유가 있으면 법원의 허가를 받아 사임할 수 있다.","w":"사채관리회사는 발행회사와 사채권자집회의 동의를 받아 사임할 수 있고, 부득이한 사유가 있어 법원의 허가를 받은 경우에도 사임할 수 있다(상법 제481조).","c":"상","v":1},"세무사2021_58-70-4":{"f":"신주발행무효의 판결이 확정된 때에는 신주는 장래에 대하여 그 효력을 잃는다.","w":"신주발행무효판결에는 소급효가 없고 장래에 대해서만 효력을 잃는다(상법 제431조 제1항).","c":"상","v":1},"세무사2021_58-71-1":{"f":"회사가 사채를 발행하기 위해서는 이사회의 결의를 거쳐야 한다.","w":"회사는 이사회의 결의로 사채를 발행한다(상법 제469조 제1항). 주주총회 승인 사항이 아니다.","c":"상","v":1},"세무사2021_58-72-1":{"f":"결손의 보전을 위하여 자본금을 감소하는 경우에는 주주총회의 보통결의가 필요하다.","w":"결손 보전을 위한 감자는 보통결의로 한다(상법 제438조 제2항).","c":"상","v":1},"세무사2021_58-72-2":{"f":"자본금의 감소를 승인하지 아니한 채권자는 자본금 감소로 인한 변경등기가 된 날부터 6개월 내에 소만으로 자본금 감소의 무효를 주장할 수 있다.","w":"감자무효의 소를 제기할 수 있는 채권자는 감자를 승인하지 않은 채권자다(상법 제445조). 승인한 채권자는 제소권이 없다.","c":"상","v":1},"세무사2021_58-72-4":{"f":"사채권자는 사채권자집회의 결의가 있어야 이의를 제기할 수 있다.","w":"사채권자가 감자에 이의를 제기하려면 사채권자집회의 결의가 필요하다(상법 제439조 제3항).","c":"상","v":1},"세무사2021_58-72-5":{"f":"결손의 보전을 위하여 자본금을 감소하는 경우에는 채권자 보호절차를 거치지 않아도 된다.","w":"결손 보전을 위한 감자는 채권자보호절차를 거치지 않는다(상법 제439조 제2항 단서).","c":"상","v":1},"세무사2022_59-73-4":{"f":"신주인수인이 납입기일에 납입을 하지 않은 경우 회사의 최고가 없더라도 그 권리를 잃는다.","w":"신주 인수인은 납입기일까지 납입하지 않으면 최고 없이 당연히 권리를 잃는다(상법 제423조 제2항). 실권예고 통지는 설립 시 모집설립에서 쓰는 절차다.","c":"상","v":1},"세무사2022_59-74-3":{"f":"특정인이 계약에 의하여 사채 총액을 인수하는 경우 이사는 사채청약서를 작성하지 아니하여도 된다.","w":"사채 총액을 계약으로 인수하는 경우에는 사채청약서가 필요 없다(상법 제475조).","c":"상","v":1},"세무사2022_59-75-1":{"f":"주주 외의 자에게 신주인수권부사채를 발행하려는 경우 정관규정 또는 주주총회 특별결의가 있어야 하고, 경영상 목적을 달성하기 위하여 필요한 경우에 한한다.","w":"정관 규정이나 특별결의가 있어도 신기술 도입, 재무구조 개선 등 경영상 목적을 달성하는 데 필요해야 한다(상법 제516조의2 제4항 후단, 제418조 제2항 단서 준용).","c":"상","v":1},"세무사2022_59-75-2":{"f":"각 신주인수권부사채에 부여된 신주인수권 행사로 인하여 발행할 주식의 발행가액의 합계액은 각 신주인수권부사채의 금액을 초과할 수 없다.","w":"신주인수권 행사로 발행할 주식의 발행가액 합계는 각 신주인수권부사채의 금액을 넘지 못한다(상법 제516조의2 제3항).","c":"상","v":1},"세무사2022_59-75-3":{"f":"신주인수권증권이 발행된 경우 신주인수권증권의 선의취득이 인정된다.","w":"신주인수권증권에는 수표의 선의취득에 관한 수표법 제21조가 준용되어 선의취득이 인정된다(상법 제516조의6 제2항).","c":"상","v":1},"세무사2022_59-75-5":{"f":"주식 양도에 관하여 이사회 승인을 얻도록 하는 정관 규정을 둔 회사가 신주인수권증권을 발행하는 경우에는 주식양도가 제한되는 사정을 채권에 기재하지 않는다.","w":"신주인수권증권을 발행할 때에는 양도제한 규정 등 제516조의4 각 호의 사항을 채권에 적지 않는다(상법 제516조의4 단서). 양도제한 규정은 신주인수권증권에 적는다(상법 제516조의5 제2항 제5호).","c":"상","v":1},"세무사2022_59-76-5":{"f":"자본금감소 무효판결이 확정된 경우 그 판결의 효력은 소급한다.","w":"감자무효판결은 소급효가 있어서 확정 전에 생긴 일에도 영향을 미친다. 소급하지 않는 것은 신주발행무효판결이다(상법 제446조, 제431조).","c":"상","v":1},"세무사2023_60-65-4":{"f":"신주의 발행으로 인한 변경등기가 있은 후에 주식인수의 청약이 취소된 때에는 이사가 이를 공동으로 인수한 것으로 본다.","w":"인수 책임은 이사와 감사가 아니라 이사가 진다(상법 제428조 제1항).","c":"상","v":1},"세무사2023_60-66-1":{"f":"회사가 성립한 날로부터 2년을 경과한 후가 아니면 액면미달의 주식발행은 허용되지 않는다.","w":"액면미달 발행은 회사 성립 후 2년이 지나야 한다(상법 제417조 제1항). 5년이 아니다.","c":"상","v":1},"세무사2023_60-66-2":{"f":"액면미달의 주식발행은 주주총회의 특별결의로 한다.","w":"액면미달 발행에는 주주총회 특별결의와 법원의 인가가 필요하다(상법 제417조 제1항).","c":"상","v":1},"세무사2023_60-66-3":{"f":"액면미달로 주식을 발행하는 경우 주식의 발행에 따른 변경등기에는 미상각액을 등기하여야 한다.","w":"액면미달 발행의 변경등기에는 미상각액을 등기해야 한다(상법 제426조).","c":"상","v":1},"세무사2023_60-66-4":{"f":"액면미달 발행에는 회사채권자에 대한 이의제출 공고와 최고 절차가 필요하지 않다.","w":"액면미달 발행에 필요한 것은 주주총회 특별결의, 법원 인가, 미상각액 등기이고 채권자 이의절차는 없다(상법 제417조).","c":"상","v":1},"세무사2023_60-69-2":{"f":"해당 종류의 사채권자 전원이 동의한 결의는 법원의 인가를 받지 않아도 효력이 있다.","w":"사채권자집회의 결의는 법원의 인가를 받아야 효력이 생기지만, 그 종류의 사채권자 전원이 동의한 결의는 인가가 필요 없다(상법 제498조 제1항 단서).","c":"상","v":1},"세무사2023_60-70-2":{"f":"신주인수권부사채의 경우 대용납입을 하는 때에는 신주인수권을 행사하면 사채권자는 사채권자로서의 지위를 상실하지만, 대용납입이 아닌 경우에는 사채권자의 지위를 유지한다.","w":"신주인수권부사채는 신주인수권을 행사해도 사채가 남는 것이 원칙이다. 사채 상환에 갈음해 그 발행가액으로 납입한 것으로 보는 대용납입(상법 제516조의2 제2항 제5호)을 한 경우에만 사채권자 지위가 사라진다.","c":"상","v":1},"세무사2023_60-70-3":{"f":"전환사채의 경우 전환권은 사채와 분리하여 양도할 수 없다.","w":"전환사채의 전환권은 사채와 함께 양도되고 따로 양도할 수 없다.","c":"상","v":1},"세무사2023_60-70-4":{"f":"신주인수권부사채의 경우 신주인수권을 행사하려는 자가 청구서 2통을 회사에 제출하고, 신주의 발행가액의 전액을 납입한 경우 납입한 때에 주주가 된다.","w":"신주인수권을 행사하면 전액을 납입한 때에 주주가 된다(상법 제516조의10). 다음 날이 아니다.","c":"상","v":1},"세무사2023_60-70-5":{"f":"전환사채의 경우 주주명부 폐쇄기간 중 전환권을 행사하여 주주로 된 자는 그 기간 중의 총회의 결의에 관하여 의결권을 행사할 수 없다.","w":"폐쇄기간 중에 전환되어 주주가 된 사람은 그 기간 중 총회 결의에서 의결권이 없다(상법 제516조 제2항, 제350조 제2항).","c":"상","v":1},"세무사2024_61-74-4":{"f":"신주발행으로 인한 변경등기가 있은 후에 아직 인수하지 아니한 주식은 이사가 인수한 것으로 본다.","w":"인수되지 않은 주식은 회사가 아니라 이사가 공동으로 인수한 것으로 본다(상법 제428조 제1항).","c":"상","v":1},"세무사2024_61-76-3":{"f":"주주의 신주인수권은 법률의 규정에 의하여 발생한다.","w":"주주는 상법 제418조 제1항에 따라 법률상 당연히 신주인수권을 가지며, 정관이나 이사회 결의로 생기는 것이 아니다.","c":"상","v":1},"세무사2024_61-77-5":{"f":"사채관리회사가 둘 이상 있을 때에는 그 권한에 속하는 행위를 공동으로 하여야 한다.","w":"사채관리회사가 둘 이상이면 그 권한에 속하는 행위는 공동으로 해야 한다(상법 제485조 제1항).","c":"상","v":1},"세무사2024_61-78-1":{"f":"각 신주인수권부사채에 부여된 신주인수권의 행사로 인하여 발행할 주식의 발행가액의 합계액은 각 신주인수권부사채의 금액을 초과할 수 없다.","w":"신주인수권 행사로 발행할 주식의 발행가액 합계는 각 신주인수권부사채의 금액을 넘지 못한다(상법 제516조의2 제3항).","c":"상","v":1},"세무사2025_62-64-5":{"f":"액면미달 발행 주식은 법원의 인가를 얻은 날로부터 1월내에 발행하여야 하고, 법원은 이 기간을 연장하여 인가할 수 있다.","w":"액면미달 주식은 법원의 인가를 얻은 날부터 1개월 안에 발행해야 하지만, 법원은 이 기간을 연장하여 인가할 수 있다(상법 제417조 제4항).","c":"상","v":1},"세무사2025_62-65-3":{"f":"회사가 전자등록기관의 전자등록부에 신주인수권을 등록한 경우에는 신주인수권증서를 발행할 필요가 없다.","w":"회사는 신주인수권증서를 발행하는 대신 정관으로 정하는 바에 따라 전자등록부에 신주인수권을 등록할 수 있다(상법 제420조의4). 등록하면 증서를 따로 발행하지 않는다.","c":"상","v":1},"세무사2025_62-66-1":{"f":"신주의 인수인은 납입 또는 현물출자의 이행을 한 때에는 납입기일의 다음 날부터 주주의 권리·의무가 있다.","w":"주주의 권리의무는 납입기일 당일이 아니라 다음 날부터 생긴다(상법 제423조 제1항).","c":"상","v":1},"세무사2025_62-66-2":{"f":"신주의 인수인은 회사의 동의 없이 인수가액 납입채무와 주식회사에 대한 채권을 상계할 수 없다.","w":"신주 인수인은 회사의 동의 없이 상계하지 못한다(상법 제421조 제2항).","c":"상","v":1},"세무사2025_62-66-4":{"f":"신주의 발행으로 인한 변경등기가 있은 후에 아직 인수하지 아니한 주식이 있거나 주식인수의 청약이 취소된 때에는 이사가 이를 공동으로 인수한 것으로 본다.","w":"인수담보책임을 지는 사람은 발기인이나 감사가 아니라 이사다(상법 제428조 제1항).","c":"상","v":1},"세무사2025_62-66-5":{"f":"신주발행의 무효는 주주·이사 또는 감사에 한하여 신주를 발행한 날로부터 6월내에 소만으로 이를 주장할 수 있다.","w":"신주발행무효의 소는 신주 발행일부터 6개월 내에 제기해야 한다(상법 제429조). 3년이 아니다.","c":"상","v":1},"세무사2025_62-67-4":{"f":"주식을 병합할 경우에는 회사는 1개월 이상의 기간을 정하여 그 뜻과 그 기간 내에 주권을 회사에 제출할 것을 공고하여야 한다.","w":"주식병합 시 주권 제출 기간은 1개월 이상으로 정한다(상법 제440조).","c":"상","v":1},"세무사2025_62-70-2":{"f":"신탁회사도 사채관리회사가 될 수 있다.","w":"은행, 신탁회사, 그 밖에 대통령령으로 정하는 자는 사채관리회사가 될 수 있다(상법 제480조의3 제1항, 상법 시행령 제26조). 신탁회사는 법이 직접 자격자로 정하고 있다.","c":"상","v":1},"세무사2025_62-70-3":{"f":"사채의 인수인은 그 사채의 사채관리회사가 될 수 없다.","w":"사채의 인수인은 그 사채의 사채관리회사가 될 수 없다(상법 제480조의3 제2항). 사채권자와 이해가 부딪히기 때문이다.","c":"상","v":1},"세무사2025_62-70-4":{"f":"회사는 사채를 발행하는 경우에 사채관리회사를 정하여 변제의 수령 등을 위탁할 수 있다.","w":"회사는 사채관리회사에 변제의 수령, 채권의 보전 등을 위탁할 수 있다(상법 제480조의2).","c":"상","v":1},"세무사2025_62-70-5":{"f":"사채관리회사는 사채를 발행한 회사와 사채권자집회의 동의를 얻어 사임할 수 있고, 부득이한 사유가 있으면 법원의 허가를 받아 사임할 수 있다.","w":"사채관리회사는 발행회사와 사채권자집회의 동의를 받아 사임할 수 있고, 부득이한 사유가 있어 법원의 허가를 받은 경우에도 사임할 수 있다(상법 제481조).","c":"상","v":1},"세무사2026_63-51-2":{"f":"신주의 발행으로 인한 변경등기가 있은 후에 주식인수의 청약이 취소된 때에는 이사가 취소된 주식을 인수한 것으로 본다.","w":"인수 의제의 주체는 회사가 아니라 이사다(상법 제428조 제1항).","c":"상","v":1},"세무사2026_63-52-5":{"f":"신주인수인은 회사의 동의가 없으면 주금납입채무와 주식회사에 대한 채권을 상계할 수 없다.","w":"신주 인수인은 회사의 동의 없이 상계하지 못한다(상법 제421조 제2항).","c":"상","v":1},"세무사2026_63-56-2":{"f":"자본금 감소에 관한 의안을 통지받은 사채권자는 사채권자집회의 결의가 있어야 회사에 대하여 이의를 제기할 수 있다.","w":"사채권자의 이의는 사채권자집회의 결의로 한다(상법 제439조 제3항).","c":"상","v":1},"세무사2026_63-56-3":{"f":"주식병합을 통한 자본금 감소의 효력은 주권제출기간이 끝난 때에 발생한다.","w":"주식병합의 효력은 주권제출기간이 끝난 때 생기고, 채권자보호절차가 끝나지 않았으면 그 절차가 끝난 때 생긴다(상법 제441조). 변경등기 시점이 아니다.","c":"상","v":1},"세무사2026_63-56-4":{"f":"감자무효의 판결이 확정된 때에는 본점의 소재지에서 등기하여야 한다.","w":"감자무효의 소에는 제192조가 준용되어, 판결이 확정되면 본점 소재지에서 등기한다(상법 제446조, 제192조). 지점 소재지 등기는 요구되지 않는다.","c":"상","v":1},"세무사2026_63-56-5":{"f":"감사는 감자무효의 소를 제기할 수 있다.","w":"감자무효의 소는 주주ㆍ이사ㆍ감사ㆍ청산인ㆍ파산관재인과 감자를 승인하지 않은 채권자가 제기할 수 있다(상법 제445조).","c":"상","v":1},"세무사2026_63-67-5":{"f":"특정인이 주식회사와 계약하여 사채총액을 인수하는 경우 이사는 상법 제474조의 사채청약서를 작성하지 아니하여도 된다.","w":"사채 총액을 계약으로 인수하는 경우에는 사채청약서가 필요 없다(상법 제475조).","c":"상","v":1},"세무사2026_63-70-2":{"f":"각 신주인수권부사채에 부여된 신주인수권의 행사로 인하여 발행할 주식의 발행가액의 합계액은 각 신주인수권부사채의 금액을 초과할 수 없다.","w":"발행가액 합계가 사채 금액과 같아야 하는 것은 아니고, 사채 금액을 넘지만 않으면 된다(상법 제516조의2 제3항).","c":"상","v":1},"세무사2026_63-70-3":{"f":"사채권자는 주주명부폐쇄기간 중에도 신주인수권을 행사할 수 있다.","w":"폐쇄기간 중에도 신주인수권을 행사할 수 있고, 이때 주주가 되어도 그 기간 중 총회에서는 의결권이 없다(상법 제516조의10, 제350조 제2항).","c":"상","v":1},"세무사2026_63-70-4":{"f":"주주 외의 자에 대하여 신주인수권부사채를 발행하는 경우 그 발행 사항은 정관에 규정이 없으면 주주총회의 특별결의로써 정한다.","w":"정관에 규정이 없으면 주주총회 특별결의로 정한다(상법 제516조의2 제4항). 이사회 결의로 정하는 것이 아니다.","c":"상","v":1},"세무사2026_63-70-5":{"f":"무권리자가 신주인수권증권을 양도한 경우 양수인은 이를 선의취득할 수 있다.","w":"신주인수권증권에는 수표법 제21조가 준용되어, 무권리자에게서 악의나 중대한 과실 없이 취득한 양수인은 선의취득한다(상법 제516조의6 제2항).","c":"상","v":1},"세무사2016_53-61-2":{"f":"회사의 자본금은 액면주식을 무액면주식으로 전환함으로써 변경할 수 없다.","w":"주식의 종류를 액면에서 무액면으로 바꿔도 자본금은 변하지 않는다(상법 제451조 제3항).","c":"상","v":1},"세무사2016_53-62-1":{"f":"자본준비금은 자본금의 결손 보전에 충당하는 경우 이를 처분할 수 있고 이익준비금도 그러하다.","w":"자본준비금과 이익준비금 모두 결손 보전에 충당할 수 있다(상법 제460조).","c":"상","v":1},"세무사2016_53-62-2":{"f":"자본금의 2분의 1이 될 때까지 매 결산기 이익배당액의 10분의 1 이상을 이익준비금으로 적립하여야 하며, 주식배당은 이에 포함되지 않는다.","w":"이익준비금 적립 기준은 금전으로 하는 이익배당액이고 주식배당은 제외한다(상법 제458조).","c":"상","v":1},"세무사2016_53-62-3":{"f":"무액면주식을 발행하는 경우 주식의 발행가액 중 자본금으로 계상하지 아니하는 금액은 자본준비금으로 계상하여야 한다.","w":"무액면주식 발행가액 중 자본금으로 계상하지 않는 금액은 자본준비금으로 계상한다(상법 제451조 제2항 후단). 이익준비금이 아니다.","c":"상","v":1},"세무사2016_53-62-5":{"f":"적립된 자본준비금 및 이익준비금의 총액이 자본금의 1.5배를 초과하는 경우에 주주총회의 결의에 따라 그 초과한 금액 범위에서 자본준비금과 이익준비금을 감액할 수 있다.","w":"준비금 감액은 이사회가 아니라 주주총회 결의로 한다(상법 제461조의2).","c":"상","v":1},"세무사2016_53-63-3":{"f":"회사는 주주총회의 결의에 의하여 이익배당총액의 2분의 1에 상당하는 금액을 초과하지 않는 범위에서 새로이 발행하는 주식으로 배당할 수 있다.","w":"주식배당은 이익배당총액의 2분의 1을 넘지 못한다(상법 제462조의2 제1항).","c":"상","v":1},"세무사2017_54-76-4":{"f":"주식배당에 의하여 회사의 자본금은 증가한다.","w":"주식배당으로 신주가 발행되면 액면주식 회사의 자본금은 발행주식의 액면총액이므로(상법 제451조 제1항) 새로 발행한 주식의 액면총액만큼 자본금이 늘어난다.","c":"상","v":1},"세무사2017_54-79-1":{"f":"이익배당금의 지급청구권은 5년간 이를 행사하지 아니하면 소멸시효가 완성된다.","w":"이익배당금 지급청구권의 소멸시효는 5년이다(상법 제464조의2 제2항).","c":"상","v":1},"세무사2017_54-79-2":{"f":"이익배당은 원칙적으로 주주총회의 결의로 정한다.","w":"재무제표를 이사회가 승인하는 경우에는 이사회 결의로 이익배당을 정할 수 있어 예외가 있다(상법 제449조의2 제1항, 제462조 제2항 단서).","c":"상","v":1},"세무사2017_54-79-4":{"f":"연 1회의 결산기를 정한 회사는 영업년도 중 1회에 한하여 이사회의 결의로 일정한 날을 정하여 그 날의 주주에 대하여 중간배당을 할 수 있음을 정관으로 정할 수 있다.","w":"중간배당은 연 1회 결산기를 정한 회사만 정관으로 정할 수 있다(상법 제462조의3 제1항).","c":"상","v":1},"세무사2017_54-79-5":{"f":"회사는 대차대조표의 순자산액으로부터 그 결산기에 적립하여야 할 이익준비금의 액을 공제하고 이익배당을 할 수 있다.","w":"배당 가능 한도를 계산할 때 순자산액에서 자본금, 법정준비금 적립액, 그 결산기에 적립할 이익준비금 등을 공제한다(상법 제462조 제1항).","c":"상","v":1},"세무사2021_58-73-5":{"f":"년 1회의 결산기를 정한 회사는 중간배당을 할 수 있음을 정관으로 정할 수 있다.","w":"중간배당은 연 1회 결산기를 정한 회사에 한한다(상법 제462조의3 제1항).","c":"상","v":1},"세무사2022_59-77-1":{"f":"무액면주식을 발행하는 회사의 자본금의 액은 설립등기사항이다.","w":"자본금의 액은 설립등기사항이다(상법 제317조 제2항).","c":"상","v":1},"세무사2022_59-78-5":{"f":"회사는 현물배당을 할 때 일정 수 미만의 주식을 보유한 주주에게 현물 대신 금전을 지급할 것을 정할 수 있다.","w":"현물배당에서 일정 수 미만 주식을 가진 주주에게 금전을 지급하도록 정할 수 있다(상법 제462조의4 제2항).","c":"상","v":1},"세무사2022_59-79-2":{"f":"주식배당의 경우에는 이익준비금을 적립하지 않아도 된다.","w":"이익준비금 적립 대상은 금전으로 하는 이익배당이고 주식배당은 제외다(상법 제458조).","c":"상","v":1},"세무사2023_60-67-1":{"f":"준비금의 자본금전입은 정관에서 주주총회 결의로 결정한다는 규정이 없는 한 이사회 결의로 정한다.","w":"준비금의 자본금 전입은 이사회가 결정하는 것이 원칙이고, 정관으로 주주총회가 정하게 할 수 있다(상법 제461조 제1항).","c":"상","v":1},"세무사2023_60-67-3":{"f":"회사채권자는 영업시간 내에 본점에서 비치하고 있는 재무제표를 열람할 수 있다.","w":"주주와 회사채권자는 영업시간 내에 재무제표를 열람할 수 있고 법원의 허가가 필요 없다(상법 제448조 제2항).","c":"상","v":1},"세무사2023_60-67-4":{"f":"법정준비금은 자본금의 결손 보전에 충당할 수 있다.","w":"자본준비금과 이익준비금은 결손 보전에 충당할 수 있다(상법 제460조).","c":"상","v":1},"세무사2023_60-67-5":{"f":"정기주주총회에서 재무제표 등을 승인한 후 2년내에 다른 결의가 없더라도 이사에게 부정행위가 있으면 회사는 이사와 감사의 책임을 해제한 것으로 보지 않는다.","w":"2년 경과 후 책임 해제로 보는 효과는 부정행위에는 미치지 않는다(상법 제450조).","c":"상","v":1},"세무사2023_60-68-3":{"f":"회사가 각 주주가 가진 주식의 수에 따라 이익배당을 하는 경우 배당금 지급청구권의 소멸시효는 5년이다.","w":"이익배당금 지급청구권의 소멸시효는 5년이다(상법 제464조의2 제2항). 10년이 아니다.","c":"상","v":1},"세무사2024_61-44-1":{"f":"무액면주식을 발행하는 회사를 설립하는 경우 설립시 발행되는 주식의 발행가액 중 자본금으로 계상하는 금액은 발기인 전원의 동의로 정한다.","w":"정관에 정하지 않으면 발기인 전원의 동의로 정한다(상법 제291조 제3호). 과반수가 아니다.","c":"상","v":1},"세무사2024_61-44-3":{"f":"액면주식을 발행한 회사가 액면주식을 무액면주식으로 전환하더라도 그 회사의 자본금은 변하지 않는다.","w":"전환으로 자본금이 변하지 않는다(상법 제451조 제3항).","c":"상","v":1},"세무사2024_61-44-4":{"f":"무액면주식을 발행하여 온 회사는 기존의 무액면주식을 존속시키면서 새로 액면주식을 발행할 수 없다.","w":"한 회사는 액면주식과 무액면주식을 함께 발행하지 못한다(상법 제329조 제1항).","c":"상","v":1},"세무사2024_61-44-5":{"f":"액면주식을 발행하는 회사는 기발행된 액면주식의 1주 액면금액을 변경하지 않은 채 1주 액면금액을 감액하여 신주를 발행할 수 없다.","w":"액면주식의 금액은 균일해야 하므로 신주만 다른 액면으로 발행하지 못한다(상법 제329조 제2항).","c":"상","v":1},"세무사2024_61-64-2":{"f":"신설합병의 경우 소멸되는 회사의 법정준비금은 새로 설립되는 회사가 승계할 수 있다.","w":"합병으로 소멸하는 회사의 이익준비금이나 그 밖의 법정준비금은 존속회사나 신설회사가 승계할 수 있다(상법 제459조 제2항).","c":"상","v":1},"세무사2024_61-73-5":{"f":"주식배당을 받은 주주는 주주총회가 종결한 때부터 신주의 주주가 된다.","w":"주식으로 배당을 받은 주주는 주식배당 결의가 있는 주주총회가 종결한 때부터 신주의 주주가 된다(상법 제462조의2 제4항). 1개월을 기다리지 않는다.","c":"상","v":1},"세무사2026_63-65-1":{"f":"주식배당의 경우에는 이익준비금을 적립하지 않아도 된다.","w":"이익준비금 적립 대상은 금전 배당액이고 주식배당은 제외된다(상법 제458조).","c":"상","v":1},"세무사2026_63-65-2":{"f":"년 1회의 결산기를 정한 회사는 중간배당을 할 수 있음을 정관으로 정할 수 있다.","w":"중간배당은 연 1회 결산기를 정한 회사에 한한다(상법 제462조의3 제1항).","c":"상","v":1},"세무사2026_63-65-3":{"f":"주식배당의 경우 주주는 주식배당 결의가 있는 주주총회가 종결한 때에 신주의 주주가 된다.","w":"주식으로 배당을 받은 주주는 주권 교부와 상관없이 주식배당 결의가 있는 주주총회가 종결한 때부터 신주의 주주가 된다(상법 제462조의2 제4항).","c":"상","v":1},"세무사2026_63-65-5":{"f":"현물배당은 주주총회의 보통결의로 정하되, 재무제표를 이사회가 승인하는 경우에는 이사회의 결의로 정한다.","w":"현물배당은 정관에 근거를 두고(상법 제462조의4 제1항) 일반 이익배당처럼 주주총회 보통결의로 정한다. 재무제표를 이사회가 승인하는 회사는 이사회 결의로 정한다(상법 제462조 제2항).","c":"상","v":1},"세무사2016_53-66-1":{"f":"영업의 전부를 양수하려는 회사가 영업을 양도하는 회사의 발행주식총수의 100분의 90 이상을 소유하고 있는 경우 양도하는 회사의 이사회 승인으로 영업을 양도할 수 있다.","w":"간이영업양도는 양수 회사가 양도 회사 발행주식총수의 90% 이상을 가진 경우다(상법 제374조의3). 양도 회사가 양수 회사 지분을 가진 경우가 아니다.","c":"상","v":1},"세무사2016_53-66-2":{"f":"영업양도에 반대하는 주주가 주식매수를 청구한 경우 청구를 받은 회사는 매수청구기간이 종료하는 날부터 2개월 이내에 그 주식을 매수하여야 한다.","w":"회사는 매수청구기간이 끝나는 날부터 2개월 안에 주식을 매수해야 한다(상법 제374조의2 제2항). 20일은 주주가 매수를 청구할 수 있는 기간이다.","c":"상","v":1},"세무사2016_53-66-3":{"f":"영업을 양도하려는 회사의 총주주의 동의가 있는 경우, 그 회사의 주주총회의 승인은 이사회의 승인으로 갈음할 수 있으며 이 경우 주주총회의 승인 없이 영업양도를 한다는 뜻을 공고하거나 주주에게 통지할 필요가 없다.","w":"총주주의 동의가 있으면 이사회 승인으로 갈음하고 공고나 통지도 하지 않는다(상법 제374조의3 제2항 단서). 공고·통지는 상대방이 90% 이상을 소유해서 이사회 승인으로 갈음하는 경우에 한다.","c":"상","v":1},"세무사2016_53-66-4":{"f":"주주총회의 승인을 받지 아니하고 영업양도를 한다는 뜻의 공고가 있은 날부터 2주 이내에 회사에 대하여 서면으로 영업양도에 반대하는 의사를 통지한 주주는 주식의 매수를 청구할 수 있다.","w":"반대 통지 기간은 공고일부터 2주다(상법 제374조의3 제3항). 20일이 아니다.","c":"상","v":1},"세무사2016_53-67-1":{"f":"주식의 포괄적 교환은 주식교환계약서에서 정한 주식교환을 할 날에 효력이 발생한다.","w":"설립등기로 효력이 생기는 것은 포괄적 이전이고, 포괄적 교환은 계약서에 정한 교환일에 효력이 생긴다(상법 제360조의2).","c":"상","v":1},"세무사2016_53-70-2":{"f":"유한회사는 정관의 규정이 있으면 총사원의 반수 이상이며 총사원의 의결권의 4분의 3 이상을 가지는 자의 동의로 주식회사로 조직을 변경할 수 있다.","w":"정관에 정하면 총사원의 일치 대신 총사원의 반수 이상이며 의결권 4분의 3 이상으로 변경할 수 있다(상법 제607조 제1항 단서). 3분의 2가 아니다.","c":"상","v":1},"세무사2016_53-71-1":{"f":"완전모회사가 되는 회사가 주식교환을 위하여 발행하는 신주의 총수가 그 회사의 발행주식총수의 100분의 10을 초과하지 않아야 한다.","w":"소규모 주식교환의 요건은 신주 총수가 발행주식총수의 10%를 넘지 않는 것이다(상법 제360조의10 제1항). 5%가 아니다.","c":"상","v":1},"세무사2016_53-71-3":{"f":"완전모회사가 되는 회사는 주식교환계약서를 작성한 날부터 2주내에 완전자회사가 되는 회사의 상호와 본점, 주식교환을 할 날 및 주주총회의 승인을 얻지 않고 주식교환을 한다는 뜻을 공고하거나 주주에게 통지하여야 한다.","w":"소규모 주식교환의 공고ㆍ통지 기한은 계약서 작성일부터 2주다(상법 제360조의10 제4항). 3주가 아니다.","c":"상","v":1},"세무사2016_53-71-4":{"f":"완전모회사가 되는 회사의 발행주식총수의 100분의 20 이상에 해당하는 주식을 가지는 주주가 법정기간 내에 회사에 대하여 서면으로 소규모 주식교환에 반대하는 의사를 통지한 경우에는 소규모 주식교환을 할 수 없다.","w":"소규모 주식교환을 막으려면 완전모회사가 되는 회사 발행주식총수의 20% 이상을 가진 주주가 반대해야 한다(상법 제360조의10 제5항). 10%는 소규모 주식교환이 되는 신주 비율이다.","c":"상","v":1},"세무사2016_53-71-5":{"f":"소규모 주식교환에 반대하는 주주는 주식의 매수를 청구할 수 없다.","w":"소규모 주식교환에서는 반대 주주의 주식매수청구권이 인정되지 않는다(상법 제360조의10 제7항).","c":"상","v":1},"세무사2016_53-73-5":{"f":"주식회사와 유한회사가 합병하여 존속회사 또는 신설회사가 주식회사가 되는 경우에는 법원의 인가를 얻어야 합병의 효력이 있다.","w":"법원의 인가가 필요한 경우는 합병 후 회사가 주식회사일 때다(상법 제600조 제1항). 유한회사가 되는 경우에는 인가가 아니라 사채 상환 완료 등이 요건이다.","c":"중","v":1},"세무사2017_54-50-1":{"f":"사채의 상환을 완료하지 아니한 주식회사는 주주총회의 총주주 일치로도 유한회사로 조직을 변경할 수 없다.","w":"사채 상환이 끝나지 않은 주식회사는 유한회사로 조직변경을 하지 못한다(상법 제604조 제1항 단서).","c":"상","v":1},"세무사2017_54-50-2":{"f":"합자회사는 유한책임사원 전원이 퇴사한 경우에는 무한책임사원 전원의 동의로 합명회사로 조직을 변경할 수 있다.","w":"무한책임사원 과반수가 아니라 전원의 동의가 있어야 한다(상법 제286조 제2항).","c":"상","v":1},"세무사2017_54-50-4":{"f":"유한회사의 주식회사로의 조직변경은 법원의 인가를 받지 아니하면 효력이 없다.","w":"유한회사가 주식회사로 조직변경하려면 법원의 인가가 필요하다(상법 제607조 제3항).","c":"상","v":1},"세무사2017_54-50-5":{"f":"합명회사는 총사원의 동의로 일부 사원을 유한책임사원으로 하거나 유한 책임사원을 새로 가입시켜서 합자회사로 조직을 변경할 수 있다.","w":"합명회사의 합자회사 조직변경에는 총사원의 동의가 필요하다(상법 제242조 제1항). 과반수로는 부족하다.","c":"상","v":1},"세무사2017_54-51-4":{"f":"회사의 합병의 무효는 합병을 승인하지 아니한 회사채권자만 소로써 이를 주장할 수 있다.","w":"합병무효의 소를 제기할 수 있는 채권자는 합병을 승인하지 않은 채권자다(상법 제529조 제1항). 승인한 채권자는 제기하지 못한다.","c":"상","v":1},"세무사2017_54-70-5":{"f":"주식교환무효의 판결은 판결확정전에 생긴 회사와 사원 및 제3자간의 권리의무에 영향을 미치지 아니한다.","w":"주식교환무효의 소에는 신주발행무효판결의 장래효에 관한 제431조가 준용되어, 판결은 확정 전에 생긴 권리의무에 영향을 주지 않는다(상법 제360조의14 제4항).","c":"상","v":1},"세무사2021_58-53-4":{"f":"주식교환을 하고자 하는 회사는 주식교환계약서를 작성하여 주주총회의 승인을 얻어야 하고 채권자 보호절차는 필요하지 않다.","w":"주식교환은 회사 재산이 바뀌지 않아서 채권자보호절차가 없다(상법 제360조의3).","c":"상","v":1},"세무사2021_58-80-1":{"f":"의결권이 배제되는 주식의 주주도 분할합병을 승인하는 주주총회에서 의결권이 있다.","w":"분할·분할합병 승인결의에서는 제344조의3 제1항에 따라 의결권이 배제되는 주주도 의결권이 있다(상법 제530조의3 제3항).","c":"상","v":1},"세무사2022_59-45-1":{"f":"합명회사와 주식회사가 합병하는 경우 합명회사를 존속하는 회사로 할 수 없다.","w":"합병하는 회사의 일방이 주식회사, 유한회사 또는 유한책임회사이면 존속회사나 신설회사는 주식회사, 유한회사 또는 유한책임회사여야 한다(상법 제174조 제2항). 합명회사는 존속회사가 될 수 없다.","c":"상","v":1},"세무사2022_59-45-2":{"f":"합명회사와 합자회사가 합병하는 경우 합병승인의 결의는 총사원의 동의로 한다.","w":"합명회사와 합자회사의 합병은 총사원의 동의가 필요하다(상법 제230조, 제269조). 특별결의 방식이 아니다.","c":"상","v":1},"세무사2022_59-45-3":{"f":"해산 후의 회사가 존립중의 회사와 합병하는 경우 그 존립중의 회사를 존속회사로 하여야 한다.","w":"해산후의 회사는 존립중의 회사를 존속회사로 하는 경우에만 합병할 수 있다(상법 제174조 제3항).","c":"상","v":1},"세무사2022_59-45-4":{"f":"주식회사를 존속회사로 정하여 주식회사와 유한회사가 합병하는 경우 법원의 인가가 필요하다.","w":"합병 후 존속회사나 신설회사가 주식회사이면 법원의 인가를 받아야 효력이 있다(상법 제600조 제1항).","c":"상","v":1},"세무사2022_59-46-4":{"f":"분할회사의 주주에게 분할합병의 대가로 제공하는 재산이 분할승계회사의 모회사의 주식을 포함할 경우 분할승계회사는 그 모회사의 주식을 취득할 수 있다.","w":"분할합병 대가에 분할승계회사의 모회사 주식이 들어가면 분할승계회사는 그 지급을 위해 모회사 주식을 취득할 수 있다(상법 제530조의6 제4항). 분할합병 뒤에도 남아 있으면 6개월 안에 처분해야 한다(같은 조 제5항).","c":"상","v":1},"세무사2022_59-60-1":{"f":"주주총회 및 종류주주총회에서 주식이전계획서가 승인된 경우에도, 주식이전으로 인하여 주식이전에 관련되는 각 회사의 주주의 부담이 가중되는 때에는 그 주주의 동의가 필요하다.","w":"주식이전으로 주주의 부담이 가중되면 주주총회 승인과 종류주주총회 결의 외에 그 주주 전원의 동의가 있어야 한다(상법 제360조의16 제4항).","c":"상","v":1},"세무사2022_59-60-3":{"f":"주식이전의 경우 자회사는 모회사의 주식을 취득할 수 있으나 그 주식을 취득한 날로부터 6월 이내에 모회사의 주식을 처분하여야 한다.","w":"주식의 포괄적 이전으로 모회사 주식을 취득한 자회사는 취득한 날부터 6개월 안에 처분해야 한다(상법 제342조의2 제2항). 3개월이 아니다.","c":"상","v":1},"세무사2022_59-60-4":{"f":"주식이전은 이로 인하여 설립한 완전모회사가 그 본점소재지에서 회사의 설립등기를 행함으로써 그 효력이 발생한다.","w":"주식이전은 완전모회사가 본점소재지에서 설립등기를 함으로써 효력이 생긴다(상법 제360조의21). 지점소재지 등기는 효력 요건이 아니다.","c":"상","v":1},"세무사2022_59-60-5":{"f":"주식이전을 무효로 하는 판결이 확정된 때에는 완전모회사가 된 회사는 주식이전을 위하여 발행한 주식의 주주에 대하여 그가 소유하였던 완전자회사가 된 회사의 주식을 이전하여야 한다.","w":"주식이전무효판결이 확정되면 완전모회사가 된 회사는 주식이전으로 발행한 주식의 주주에게 그가 가졌던 완전자회사 주식을 이전해야 한다(상법 제360조의23 제3항).","c":"상","v":1},"세무사2023_60-72-4":{"f":"분할회사의 채무 중에서 단순분할신설회사가 승계할 책임을 일정한 범위 내로 제한하는 것은 허용된다.","w":"분할회사는 주주총회 특별결의로 단순분할신설회사가 분할계획서에 승계하기로 정한 채무에 대해서만 책임을 지도록 정할 수 있다(상법 제530조의9 제2항). 이 경우 채권자보호절차를 거친다(같은 조 제4항, 제527조의5).","c":"상","v":1},"세무사2024_61-51-3":{"f":"B회사가 C회사의 주주에게 A회사의 주식을 교환대가로 지급하고 교환절차를 완료하면 C회사는 A회사의 자회사가 된다.","w":"교환이 끝나면 B회사가 C회사 주식 전부를 가진다. 다른 회사의 발행주식 50%를 넘는 주식을 자회사가 가지고 있으면 그 회사는 모회사의 자회사로 보므로(상법 제342조의2 제3항), A회사의 자회사인 B회사가 전부를 가진 C회사는 A회사의 자회사가 된다.","c":"중","v":1},"세무사2024_61-69-1":{"f":"유한책임사원 전원이 퇴사한 경우 합자회사는 남아 있는 무한책임사원 전원의 동의로 합명회사로 변경하여 계속할 수 있다.","w":"무한책임사원 과반수가 아니라 전원의 동의가 필요하다(상법 제286조 제2항).","c":"상","v":1},"세무사2024_61-69-2":{"f":"합자회사의 유한책임사원이 전부 퇴사하여 무한책임사원 1인만 남은 경우, 유한책임사원을 새로 가입시켜 합자회사로 계속할 수 있다.","w":"유한책임사원 전원이 퇴사하면 남은 무한책임사원은 전원의 동의로 유한책임사원을 새로 가입시켜 회사를 계속할 수 있다(상법 제285조 제2항). 무한책임사원을 새로 들여서는 합자회사가 되지 않는다.","c":"상","v":1},"세무사2024_61-69-3":{"f":"주식회사는 총주주의 일치에 의한 총회의 결의로 유한회사로 조직변경을 할 수 있다.","w":"주식회사의 유한회사 조직변경은 특별결의가 아니라 총주주의 일치가 필요하다(상법 제604조 제1항).","c":"상","v":1},"세무사2024_61-69-4":{"f":"조직변경을 한 경우에는 본점소재지에서 2주간 내에 변경전의 회사는 해산등기를, 변경후의 회사는 설립등기를 하여야 한다.","w":"조직변경 등기는 본점 소재지에서 2주 안에 변경 전 회사의 해산등기와 변경 후 회사의 설립등기를 한다(상법 제243조, 제286조 제3항, 제606조). 지점 소재지 등기는 하지 않는다.","c":"중","v":1},"세무사2024_61-80-4":{"f":"합병무효의 소의 제소기간은 합병등기가 있은 날부터 6월 이내이다.","w":"합병무효의 소는 합병등기가 있은 날부터 6개월 안에 제기해야 한다(상법 제529조 제2항). 3개월이 아니다.","c":"상","v":1},"세무사2025_62-72-5":{"f":"합병무효의 소는 합병등기가 있은 날로부터 6월 이내에 제기하여야 한다.","w":"합병무효의 소의 제소기간은 6개월이다(상법 제529조 제2항).","c":"상","v":1},"세무사2025_62-73-5":{"f":"간이분할합병 또는 소규모분할합병이 아닌 경우, 회사가 분할합병을 하는 때에는 분할합병계약서를 작성하여 주주총회의 승인을 얻어야 한다.","w":"일반 분할합병은 주주총회 특별결의가 필요하고 이사회 승인만으로는 부족하다(상법 제530조의3 제1항, 제2항).","c":"상","v":1},"세무사2026_63-73-2":{"f":"해산후의 회사는 존립중의 회사를 존속하는 회사로 하거나 새로 회사를 설립하는 경우에 한하여 분할 또는 분할합병할 수 있다.","w":"해산후의 회사는 존립중의 회사를 존속회사로 하거나 새로 회사를 설립하는 경우에 분할ㆍ분할합병이 가능하다(상법 제530조의2 제4항). 신설하는 경우만 가능한 것은 아니다.","c":"상","v":1},"세무사2026_63-76-2":{"f":"소규모합병이란 소멸회사의 주주에게 교부하기 위해 존속회사가 발행하는 신주의 총수가 발행주식총수의 10%를 초과하지 않는 합병을 말한다.","w":"신주 비율 10% 이하는 소규모합병의 요건이다(상법 제527조의3). 간이합병은 소멸회사의 총주주 동의가 있거나 존속회사가 소멸회사 지분 90% 이상을 가진 경우다(제527조의2).","c":"상","v":1},"세무사2026_63-76-3":{"f":"존속회사가 소멸회사의 주주에게 합병대가의 전부를 금전이나 그 밖의 재산으로 제공할 수 있다.","w":"합병대가는 주식에 한하지 않고 금전이나 그 밖의 재산으로 전부 제공할 수 있다(상법 제523조 제4호).","c":"상","v":1},"세무사2026_63-76-4":{"f":"합병에 따라 존속회사의 정관을 변경해야 할 경우 이를 기재한 합병계약서에 대한 주주총회 승인 결의 이외에 정관변경을 위한 별도의 주주총회 결의가 필요하지 않다.","w":"존속회사가 합병으로 정관을 변경하기로 정하면 그 규정을 합병계약서에 적고(상법 제523조 제7호), 합병계약서를 특별결의로 승인하면 정관변경 결의도 함께 이루어진 것으로 본다. 따로 결의할 필요가 없다.","c":"중","v":1},"세무사2026_63-76-5":{"f":"소규모합병의 경우 합병에 반대하는 존속회사의 주주에게는 주식매수청구권이 인정되지 않는다.","w":"소규모합병에서는 존속회사 주주의 반대와 주식매수청구권이 인정되지 않는다(상법 제527조의3 제5항).","c":"상","v":1},"세무사2016_53-74-2":{"f":"자본금 총액이 20억원인 유한회사를 설립하는 경우에도 공증인의 인증은 정관의 효력발생 요건이다.","w":"유한회사 정관은 자본금 규모와 관계없이 공증인의 인증을 받아야 효력이 생긴다(상법 제543조 제3항).","c":"상","v":1},"세무사2016_53-75-2":{"f":"지배인의 선임과 해임은 무한책임사원 과반수의 결의에 의한다.","w":"합자회사에서 지배인의 선임과 해임은 업무집행사원이 있어도 무한책임사원 과반수의 결의로 한다(상법 제274조).","c":"상","v":1},"세무사2016_53-76-3":{"f":"설립의 무효는 사원 및 업무집행자에 한하여 회사성립의 날로부터 2년내에 소만으로 이를 주장할 수 있다.","w":"유한책임회사 설립무효의 소에는 제184조가 준용되면서 \"사원\"을 \"사원 및 업무집행자\"로 읽으므로, 사원과 업무집행자만 제기할 수 있다(상법 제287조의6). 이사ㆍ감사는 유한책임회사의 기관이 아니다.","c":"상","v":1},"세무사2016_53-77-5":{"f":"합명회사의 사원은 무한ㆍ연대책임을 지지만 회사가 주장할 수 있는 항변으로 합명회사의 채권자에게 대항할 수 있다.","w":"사원은 회사의 항변을 원용해 채권자에게 대항할 수 있다(상법 제214조 제1항).","c":"상","v":1},"세무사2016_53-78-1":{"f":"합명회사의 사원은 다른 사원의 동의가 없으면 동종영업을 목적으로 하는 주식회사의 이사가 될 수 없다.","w":"합명회사의 사원은 다른 사원의 동의 없이 동종영업을 목적으로 하는 다른 회사의 무한책임사원이나 이사가 되지 못한다(상법 제198조 제1항).","c":"상","v":1},"세무사2016_53-78-2":{"f":"합자회사의 유한책임사원은 다른 사원 전원의 동의가 없어도 주식회사의 이사가 될 수 있다.","w":"유한책임사원에게는 경업금지 의무가 없다(상법 제275조).","c":"상","v":1},"세무사2016_53-78-3":{"f":"합자회사의 유한책임사원은 무한책임사원 전원의 동의가 없으면 그 지분의 전부 또는 일부를 타인에게 양도하지 못한다.","w":"유한책임사원의 지분 양도에는 무한책임사원 전원의 동의가 필요하다(상법 제276조). 다른 사원 전원이 아니다.","c":"상","v":1},"세무사2016_53-78-5":{"f":"유한책임회사의 사원은 지분 비율과 관계없이 회사에 대하여 업무집행자의 책임을 추궁하는 소의 제기를 청구할 수 있다.","w":"유한책임회사의 사원은 지분 요건 없이 회사에 업무집행자의 책임을 추궁하는 소의 제기를 청구할 수 있다(상법 제287조의22 제1항).","c":"상","v":1},"세무사2016_53-80-3":{"f":"유한책임회사의 업무집행자는 사원이 아닌 자로도 정할 수 있다.","w":"유한책임회사는 정관으로 사원이 아닌 사람을 업무집행자로 정할 수 있다(상법 제287조의12).","c":"상","v":1},"세무사2017_54-41-2":{"f":"회사는 정관으로 사원이 아닌 자를 업무집행자로 정할 수 있다.","w":"사원이 아닌 사람도 정관으로 업무집행자로 정할 수 있다(상법 제287조의12).","c":"상","v":1},"세무사2017_54-41-3":{"f":"사원은 신용이나 노무를 출자의 목적으로 할 수 없다.","w":"유한책임회사 사원은 금전이나 그 밖의 재산으로만 출자한다(상법 제287조의4 제1항).","c":"상","v":1},"세무사2017_54-41-4":{"f":"사원은 설립등기를 하는 때까지 금전이나 그 밖의 재산의 출자를 전부 이행하여야 한다.","w":"출자 이행 시한은 정관 작성 전이 아니라 설립등기를 하는 때까지다(상법 제287조의4 제2항).","c":"상","v":1},"세무사2017_54-41-5":{"f":"퇴사한 사원의 성명이 유한책임회사의 상호 중에 사용된 경우 그 사원은 유한책임회사에 대하여 그 사용의 폐지를 청구할 수 있다.","w":"유한책임회사의 내부관계에는 합명회사 규정이 준용되므로, 퇴사한 사원은 자기 성명이 상호에 쓰이는 것의 폐지를 청구할 수 있다(상법 제287조의18, 제226조).","c":"상","v":1},"세무사2017_54-43-3":{"f":"사원의 지분에 관하여 지시식 증권을 발행할 수 없다.","w":"유한회사의 지분에 관해서는 지시식이나 무기명식 증권을 발행하지 못한다(상법 제555조).","c":"상","v":1},"세무사2017_54-44-1":{"f":"유한책임사원이 금치산의 선고를 받은 경우에도 퇴사되지 않는다.","w":"유한책임사원은 금치산이나 성년후견 선고를 받아도 퇴사하지 않는다(상법 제284조).","c":"상","v":1},"세무사2017_54-44-2":{"f":"유한책임사원은 다른 사원의 동의없이도 자기 또는 제3자의 계산으로 회사의 영업부류에 속하는 거래를 할 수 있다.","w":"유한책임사원에게는 경업금지와 자기거래 제한이 없다(상법 제275조).","c":"상","v":1},"세무사2017_54-44-3":{"f":"유한책임사원은 회사의 업무집행이나 대표행위를 할 수 없다.","w":"유한책임사원은 업무집행과 대표를 할 수 없다(상법 제278조).","c":"상","v":1},"세무사2017_54-44-4":{"f":"유한책임사원은 신용 또는 노무를 출자의 목적으로 할 수 없다.","w":"유한책임사원의 출자는 금전이나 그 밖의 재산으로 한정된다(상법 제272조).","c":"상","v":1},"세무사2017_54-53-1":{"f":"사원이 1인으로 되어 해산하게 된 경우 해산된 회사의 재산처분방법은 정관 또는 총사원의 동의로 이를 정할 수 없다.","w":"사원이 1인으로 되어 해산한 회사에는 정관이나 총사원의 동의로 재산처분방법을 정하는 임의청산 규정이 적용되지 않는다(상법 제247조 제2항, 제227조 제3호). 법정청산을 해야 한다.","c":"상","v":1},"세무사2021_58-75-1":{"f":"자본금의 최저한도는 없다.","w":"2011년 개정으로 유한회사의 최저자본금 규정이 없어졌다.","c":"상","v":1},"세무사2021_58-75-2":{"f":"사원 총수에 제한이 없다.","w":"2011년 개정으로 유한회사의 사원 수 50인 제한이 폐지되었다.","c":"상","v":1},"세무사2021_58-75-3":{"f":"사원이 그 지분의 전부를 양도하려는 경우, 정관에 제한 규정이 없으면 사원총회의 승인 없이 양도할 수 있다.","w":"지분은 원칙적으로 자유롭게 양도할 수 있고 정관으로 제한할 수 있다(상법 제556조).","c":"상","v":1},"세무사2021_58-75-4":{"f":"사원이 1인으로 된 때에도 해산사유가 되지 않는다.","w":"유한회사는 사원이 1인이 되어도 해산사유가 아니다(상법 제609조).","c":"상","v":1},"세무사2021_58-76-3":{"f":"회사성립 후에 가입한 사원은 그 가입 전에 생긴 회사 채무에 대하여도 책임이 있다.","w":"새로 가입한 사원도 가입 전에 생긴 회사 채무에 같은 책임을 진다(상법 제213조).","c":"상","v":1},"세무사2021_58-78-2":{"f":"B는 업무집행이나 대표행위를 할 수 없다.","w":"유한책임사원은 업무집행과 대표를 할 수 없다(상법 제278조).","c":"상","v":1},"세무사2021_58-79-3":{"f":"유한책임회사의 내부관계에 관하여는 정관이나 상법에 다른 규정이 없으면 합명회사에 관한 규정을 준용한다.","w":"유한책임회사의 내부관계는 합명회사 규정을 준용한다(상법 제287조의18).","c":"상","v":1},"세무사2022_59-47-4":{"f":"사원은 그 보유지분의 일부에 대해서도 다른 사원 전원의 동의가 없으면 타인에게 양도할 수 없다.","w":"합명회사에서는 지분의 전부든 일부든 다른 사원 전원의 동의가 있어야 양도할 수 있다(상법 제197조).","c":"상","v":1},"세무사2022_59-48-3":{"f":"지배인의 선임과 해임은 업무집행사원이 있는 경우에도 무한책임사원 과반수의 결의에 의하여야 한다.","w":"지배인의 선임과 해임은 무한책임사원 과반수의 결의로 한다(상법 제274조). 유한책임사원은 결의에 참여하지 않는다.","c":"상","v":1},"세무사2022_59-49-1":{"f":"사원은 신용이나 노무를 출자의 목적으로 할 수 없다.","w":"유한책임회사에서는 노무뿐 아니라 신용도 출자할 수 없다(상법 제287조의4 제1항).","c":"상","v":1},"세무사2023_60-73-3":{"f":"정관으로 사원의 1인 또는 수인을 업무집행사원으로 정한 때에는 그 사원이 회사의 업무를 집행할 권리와 의무를 가진다.","w":"업무집행사원은 정관으로 정한다(상법 제201조 제1항). 총사원 과반수의 동의로 정하는 것이 아니다.","c":"상","v":1},"세무사2023_60-74-2":{"f":"유한책임회사는 그 지분의 전부 또는 일부를 양수할 수 없다.","w":"유한책임회사는 자기 지분을 양수하지 못한다(상법 제287조의9).","c":"상","v":1},"세무사2023_60-75-2":{"f":"유한책임사원이 타인에게 자기를 무한책임사원이라고 오인시키는 행위를 한 때에는 오인으로 인하여 회사와 거래를 한 자에 대하여 무한책임사원과 동일한 책임이 있다.","w":"오인시킨 유한책임사원은 상대방에 대해 무한책임사원과 같은 책임을 진다(상법 제281조 제1항). 유한책임 한도로 제한되지 않는다.","c":"상","v":1},"세무사2023_60-75-3":{"f":"유한책임사원은 다른 사원의 동의없이 동종영업을 목적으로 하는 다른 회사의 무한책임사원 또는 이사가 될 수 있다.","w":"유한책임사원에게는 경업금지 의무가 없다(상법 제275조).","c":"상","v":1},"세무사2023_60-75-4":{"f":"유한책임사원은 무한책임사원 전원의 동의가 없으면 그 지분의 전부 또는 일부를 타인에게 양도할 수 없다.","w":"지분 양도에는 총사원이 아니라 무한책임사원 전원의 동의가 필요하다(상법 제276조).","c":"상","v":1},"세무사2023_60-75-5":{"f":"유한책임사원은 성년후견개시 심판을 받은 경우에도 퇴사하지 않는다.","w":"유한책임사원은 성년후견 개시로 퇴사하지 않는다(상법 제284조).","c":"상","v":1},"세무사2023_60-76-2":{"f":"사원의 지분은 질권의 목적으로 할 수 있으나, 증권이 없으므로 주식과 같은 약식질은 인정되지 않는다.","w":"유한회사 지분은 질권의 목적이 되지만, 지분 입질에는 지분이전의 대항요건(사원명부 기재)이 준용된다(상법 제559조). 지분에 관한 증권도 발행할 수 없어서 증권 교부로 하는 약식질은 없다.","c":"상","v":1},"세무사2023_60-76-3":{"f":"정관으로 사원의 지분의 양도를 제한할 수 있다.","w":"유한회사의 지분은 자유롭게 양도할 수 있으나 정관으로 제한할 수 있다(상법 제556조).","c":"상","v":1},"세무사2023_60-76-4":{"f":"이사가 수인인 경우에 정관에 다른 정함이 없으면 회사의 업무집행은 이사의 과반수의 결의에 의한다.","w":"유한회사 이사가 여러 명이면 정관에 다른 정함이 없는 한 이사 과반수의 결의로 업무집행을 정한다(상법 제564조 제1항). 과반수 출석 요건은 없다.","c":"상","v":1},"세무사2023_60-76-5":{"f":"정관변경의 특별결의는 총사원의 반수 이상이며 총사원의 의결권의 4분의 3 이상을 가지는 자의 동의로 한다.","w":"유한회사 정관변경은 총사원의 반수 이상이며 총사원 의결권의 4분의 3 이상이 필요하다(상법 제585조 제1항).","c":"상","v":1},"세무사2024_61-66-2":{"f":"지분의 이전은 취득자의 성명, 주소와 그 출자좌수를 사원명부에 기재해야 회사와 제3자에게 대항할 수 있다.","w":"유한회사는 등기가 아니라 사원명부 기재가 대항요건이다(상법 제557조).","c":"상","v":1},"세무사2024_61-66-3":{"f":"회사가 이사에 대해 소를 제기하는 경우에는 사원총회가 그 소에 관하여 회사를 대표할 자를 선정하여야 한다.","w":"유한회사와 이사 사이의 소에서는 사원총회가 회사를 대표할 자를 선정한다(상법 제563조). 감사가 법원에 지정을 신청하는 절차는 없다.","c":"상","v":1},"세무사2024_61-66-4":{"f":"이사는 매결산기에 대차대조표와 손익계산서 등을 작성하여 정기총회 회일로부터 4주간 전에 감사에게 제출해야 한다.","w":"감사가 있으면 이사는 정기총회 회일부터 4주 전에 대차대조표, 손익계산서 등을 감사에게 제출해야 한다(상법 제579조 제2항). 2주가 아니다.","c":"상","v":1},"세무사2024_61-66-5":{"f":"사원총회 결의의 목적사항에 대해서 총사원이 서면으로 동의한 때에는 서면에 의한 결의가 있는 것으로 본다.","w":"동의는 서면으로 해야 하고 구두는 안 되며, 추정이 아니라 결의가 있는 것으로 본다(상법 제577조 제2항).","c":"상","v":1},"세무사2024_61-67-2":{"f":"사원이 채권자를 해할 것을 알고 회사를 설립한 때에는 채권자는 회사와 사원을 상대로 하여 회사의 설립취소소송을 제기할 수 있다.","w":"사해설립취소의 소는 그 사원과 회사를 함께 상대로 제기한다(상법 제185조). 회사만 상대로 할 수 없다.","c":"상","v":1},"세무사2024_61-68-1":{"f":"유한책임사원은 신용을 출자의 목적으로 할 수 없다.","w":"유한책임사원은 신용이나 노무로 출자하지 못하고 금전과 재산으로만 출자한다(상법 제272조).","c":"상","v":1},"세무사2024_61-68-2":{"f":"무한책임사원은 정관에 다른 정함이 없으면 각자 회사의 업무를 집행할 권리와 의무가 있다.","w":"정관에 정함이 있어야 하는 것이 아니고, 정함이 없으면 각 무한책임사원이 업무를 집행한다(상법 제273조, 제200조).","c":"상","v":1},"세무사2024_61-68-3":{"f":"유한책임사원은 무한책임사원의 동의를 얻지 않아도 자기 또는 제3자의 계산으로 회사의 동종영업에 속하는 거래를 할 수 있다.","w":"유한책임사원에게는 경업금지 규정이 적용되지 않는다(상법 제275조).","c":"상","v":1},"세무사2024_61-68-5":{"f":"유한책임사원의 사망으로 그 지분을 수인의 상속인이 상속하는 경우 그 사원의 권리 행사는 상속인 중 1인을 정하여 하여야 한다.","w":"상속인이 여럿이면 사원의 권리를 행사할 사람 1인을 정해야 한다(상법 제283조 제2항).","c":"상","v":1},"세무사2025_62-75-1":{"f":"회사의 정관에는 사원의 성명ㆍ주민등록번호 및 주소를 반드시 기재하여야 하며, 회사를 대표할 사원을 정한 때에도 그 외의 사원의 주소를 기재하여야 한다.","w":"정관에는 모든 사원의 성명, 주민등록번호, 주소가 절대적으로 기재되어야 한다(상법 제179조 제3호).","c":"상","v":1},"세무사2025_62-76-1":{"f":"사원 1인만으로도 유한책임회사의 설립이 가능하다.","w":"유한책임회사는 사원 1인으로도 설립할 수 있다.","c":"상","v":1},"세무사2025_62-76-2":{"f":"유한책임회사는 정기사원총회를 소집하여야 하는 것은 아니다.","w":"유한책임회사에는 사원총회 같은 기관이 없어서 정기총회를 열 의무가 없다.","c":"상","v":1},"세무사2025_62-76-3":{"f":"유한책임회사는 정관으로 사원 또는 사원이 아닌 자 중 1인 이상을 업무집행자로 정하여야 한다.","w":"업무집행자는 사원 중에서만 정하는 것이 아니고 사원이 아닌 사람도 가능하다(상법 제287조의12).","c":"상","v":1},"세무사2025_62-76-5":{"f":"유한책임회사에 새로운 사원의 가입은 정관을 변경한 후 해당 사원이 출자를 이행하지 아니한 경우에는 출자를 이행한 때에 사원이 된다.","w":"사원 가입은 정관을 변경한 때에 효력이 생기지만, 그때까지 출자를 이행하지 않았으면 납입이나 이행을 마친 때에 사원이 된다(상법 제287조의23 제2항).","c":"상","v":1},"세무사2025_62-77-3":{"f":"이익의 배당은 정관에 다른 정함이 있는 경우 외에는 각 사원의 출자가액에 비례하여 배당하여야 한다.","w":"합자회사의 내부관계에는 합명회사 규정을 거쳐 민법의 조합 규정이 준용되므로, 정관에 정함이 없으면 손익은 각 사원의 출자가액에 비례해 나눈다(상법 제269조, 제195조, 민법 제711조 제1항).","c":"상","v":1},"세무사2025_62-78-1":{"f":"유한회사는 주식회사의 모집설립에 해당하는 방법으로는 설립할 수 없다.","w":"유한회사는 사원을 모집하는 방식이 아니라 정관 작성 후 사원이 출자를 이행하는 방식으로 설립한다(상법 제543조 이하).","c":"상","v":1},"세무사2026_63-41-4":{"f":"회사의 설립의 무효는 그 사원에 한하여 회사성립의 날로부터 2년내에 소만으로 이를 주장할 수 있다.","w":"설립무효는 소로써만 주장할 수 있고 제소기간은 2년이다(상법 제184조 제1항). 3년이 아니다.","c":"상","v":1},"세무사2026_63-42-1":{"f":"유한책임사원은 회사의 업무집행이나 대표행위를 할 수 없다.","w":"유한책임사원은 업무집행과 대표를 할 수 없다(상법 제278조).","c":"상","v":1},"세무사2026_63-43-2":{"f":"사원은 신용이나 노무를 출자의 목적으로 할 수 없다.","w":"유한책임회사 사원은 금전이나 그 밖의 재산으로만 출자한다(상법 제287조의4 제1항).","c":"상","v":1},"세무사2026_63-43-3":{"f":"회사는 총사원의 동의로 주식회사로 조직을 변경할 수 있다.","w":"유한책임회사는 주식회사로만 조직변경할 수 있고 유한회사로는 변경할 수 없다(상법 제287조의43).","c":"상","v":1},"세무사2026_63-43-4":{"f":"회사는 그 지분의 전부 또는 일부를 양수할 수 없다.","w":"유한책임회사는 자기 지분을 양수하지 못한다(상법 제287조의9).","c":"상","v":1},"세무사2026_63-43-5":{"f":"업무집행자는 다른 사원 전원의 승인을 얻으면 자기의 계산으로 회사와 거래할 수 있다.","w":"업무집행자는 다른 사원 과반수의 결의가 있으면 자기 또는 제3자의 계산으로 회사와 거래할 수 있다(상법 제287조의11). 전원이 승인했다면 당연히 거래할 수 있다.","c":"상","v":1},"세무사2026_63-44-4":{"f":"회사는 정관으로 사원의 지분양도를 제한할 수 있다.","w":"유한회사는 정관으로 지분양도를 제한할 수 있다(상법 제556조).","c":"상","v":1},"세무사2026_63-45-4":{"f":"유한책임회사에서의 정관변경은 정관에 다른 정함이 없으면 총사원의 동의로 가능하다.","w":"유한책임회사의 정관변경은 정관에 다른 규정이 없으면 총사원의 동의가 필요하다(상법 제287조의16). 과반수 동의가 아니다.","c":"상","v":1},"세무사2017_54-52-2":{"f":"회사가 합병과 파산 외의 사유로 해산하는 경우에는 본점소재지에서 2주일 내에 해산등기를 하여야 한다.","w":"해산등기는 합병과 파산의 경우를 빼고 해산사유가 있은 날부터 2주일 안에 본점 소재지에서 한다(상법 제228조). 파산으로 해산한 때에는 이 해산등기를 하지 않는다.","c":"상","v":1},"세무사2021_58-74-3":{"f":"청산인의 임기에는 제한이 없다.","w":"청산인의 임기를 3년으로 제한하는 규정이 상법에 없다.","c":"중","v":1},"세무사2024_61-72-2":{"f":"합명회사가 총사원의 동의로 해산하는 경우에도 청산절차를 거쳐 소멸한다.","w":"합명회사는 해산 후 청산을 거쳐 소멸하고, 총사원 동의로 재산처분방법을 정하는 임의청산도 청산의 한 방식이다(상법 제247조).","c":"상","v":1},"세무사2026_63-77-3":{"f":"법원이 선임하지 아니한 청산인을 해임하는 경우에는 주주총회의 보통결의를 요한다.","w":"법원이 선임하지 않은 청산인은 주주총회 보통결의로 해임한다(상법 제539조 제1항).","c":"상","v":1},"세무사2016_53-72":{"w":"감자무효의 소에는 제190조 본문만 준용되고 단서는 준용되지 않는다(제446조). 그래서 감자무효 판결에는 소급효가 있다.\n설립무효(제328조 제2항), 합병무효(제530조 제2항·제240조), 분할무효(제530조의11 제1항·제240조), 주식이전무효(제360조의23 제4항)는 제190조 단서까지 준용되어 판결 확정 전에 생긴 회사·사원·제3자 사이의 권리의무에 영향을 미치지 않는다.","c":"상","v":1},"세무사2022_59-41":{"w":"제171조 1항: 회사의 주소는 본점소재지에 있는 것으로 한다. 지점소재지가 아니므로 ②가 옳지 않다.\n① 제169조 법인. ③ 제173조: 회사는 다른 회사의 무한책임사원이 되지 못한다. ④ 법인이므로 권리의무의 주체. ⑤ 관청의 허가·인가를 요하는 사항은 서류가 도달한 날부터 등기기간을 기산한다.","c":"상","v":1},"세무사2022_59-50":{"w":"변태설립사항(제290조)은 발기인의 특별이익, 현물출자, 성립 후 양수할 재산(재산인수), 설립비용과 발기인 보수 네 가지다.\n②는 1호, ③은 2호, ④는 3호, ⑤는 4호에 해당한다.\n①은 사후설립(제375조)이다. 성립 후 2년 내 자본금의 5% 이상 대가로 성립 전부터 존재하는 재산을 취득하는 계약으로, 주주총회 특별결의 사항이고 변태설립사항이 아니다.","c":"상","v":1},"세무사2023_60-80":{"w":"제기권자가 주주·이사·감사로 한정된 소는 결의취소의 소(제376조)이므로 채권자는 제기할 수 없다.\n위법배당 반환청구(제462조 3항), 합병무효(제529조 1항), 분할합병무효(제530조의11), 감자무효(제445조)는 채권자가 제기할 수 있다.","c":"상","v":1},"세무사2025_62-41":{"w":"틀린 진술은 첫째 하나다.\n첫째 X: 회사는 상행위나 그 밖의 영리를 목적으로 하여 설립한 법인이다(제169조). 상행위만을 목적으로 하는 것으로 한정되지 않는다.\n둘째 O: 회사는 본점소재지에서 설립등기를 함으로써 성립한다(제172조).\n셋째 O: 회사는 다른 회사의 무한책임사원이 되지 못할 뿐 유한책임사원은 될 수 있다(제173조).\n넷째 O: 정당한 사유 없이 설립 후 1년 내에 영업을 개시하지 않으면 법원은 직권으로도 해산을 명할 수 있다(제176조 제1항 제2호).\n옳지 않은 것은 1개이므로 2번이다.","c":"상","v":1},"세무사2026_63-53":{"w":"상대적 기재사항은 정관에 적어야 효력이 생기는 사항이다. ① 발기인의 보수액은 제290조 제4호, ② 의결권 제한 종류주식은 제344조의3, ③ 명의개서대리인 설치는 제337조 제2항, ④ 신주인수권의 전자등록은 제420조의4에 따라 정관에 정해야 한다.\n⑤ 감사의 수는 법률상 정관에 적어야 효력이 생기는 사항이 아니다. 5번이다.","c":"상","v":1},"세무사2016_53-51":{"w":"ㄱ O: 대표소송은 본점소재지 지방법원의 전속관할이다(제403조 7항, 제186조).\nㄴ O: 비상장회사는 발행주식총수의 1% 이상 주주가 이사의 책임을 추궁할 소 제기를 회사에 청구할 수 있다(제403조 1항).\nㄷ X: 제소 후 발행주식을 전혀 보유하지 않게 되면 원고적격을 잃는다. 1% 미만이 된 경우에만 제소의 효력에 영향이 없다(제403조 5항).\nㄹ X: 회사는 대표소송에 참가할 수 있다(제404조 1항).","c":"상","v":1},"세무사2021_58-55":{"w":"비상장회사 소수주주권의 비율: 주주제안권 3%(제363조의2), 회계장부열람권 3%(제466조), 이사·감사 해임청구권 3%(제385조 2항, 제415조), 임시총회 소집청구권 3%(제366조).\n이사의 위법행위 유지청구권은 1%(제402조)로 다르다.","c":"상","v":1},"세무사2022_59-80":{"w":"회계장부열람권은 발행주식총수의 3% 이상이 요건이다(제466조 1항). 1%로 쓴 ①이 옳지 않다.\n나머지는 모두 3%: 주주총회소집청구(제366조), 이사해임청구(제385조 2항), 감사해임청구(제415조), 청산인해임청구(제539조 2항).","c":"상","v":1},"세무사2023_60-52":{"w":"A는 甲회사 주식 2%를 가진 주주다.\nㄱ X: 유지청구는 乙회사의 주주권이다. 甲의 주주 A는 모회사 주주로서 乙 이사에 대해 다중대표소송만 할 수 있다.\nㄴ O: 재무제표 열람은 주주 누구나 가능하다(제448조 2항).\nㄷ O: 다중대표소송은 모회사 발행주식총수의 1%(비상장) 이상이면 되므로 2%로 가능하다(제406조의2).\nㄹ X: 임시총회 소집청구는 3%(제366조).\nㅁ X: 주주제안권은 3%(제363조의2).","c":"상","v":1},"세무사2024_61-48":{"w":"집중투표청구권은 의결권 없는 주식을 제외한 발행주식총수의 3% 이상을 기준으로 한다(제382조의2 1항).\n발기인 책임 대표소송(제324조·제403조), 청산인 해임(제539조 2항), 해산판결(제520조 1항), 주주총회 소집청구(제366조)는 모두 단순히 발행주식총수가 기준이다.","c":"상","v":1},"세무사2025_62-53":{"w":"ㄱ 유지청구권 1%(제402조), ㄴ 회계장부열람청구권 3%(제466조), ㄷ 집중투표청구권 3%(제382조의2), ㄹ 해산판결청구권 10%(제520조).\n비율이 같은 것은 ㄴ과 ㄷ이다.","c":"상","v":1},"세무사2026_63-62":{"w":"대표소송은 회사가 이사 등에게 갖는 권리를 주주가 회사를 위하여 행사하는 제도다.\n⑤는 제3자가 제401조에 따라 이사에게 갖는 손해배상청구권으로 회사의 권리가 아니므로 대표소송 대상이 아니다.\n① 발기인(제324조), ② 집행임원(제408조의9), ③ 불공정한 가액으로 주식을 인수한 자(제424조의2 제2항), ④ 감사(제415조)에 대한 청구에는 제403조가 준용된다.","c":"상","v":1},"세무사2016_53-45":{"w":"주주총회 결의내용이 법령에 위반하면 결의무효확인의 소 대상이다(제380조). 취소의 소 대상이 아니다.\n결의취소의 소(제376조)는 소집절차·결의방법이 법령·정관에 위반하거나 현저히 불공정한 경우, 결의내용이 정관에 위반한 경우에 한다. ②~⑤가 이에 해당한다.","c":"상","v":1},"세무사2017_54-57":{"w":"검사인 선임(제367조)은 보통결의사항이다.\n주식매수선택권 부여(제340조의2), 사후설립(제375조), 정관변경(제433조), 회사 계속(제519조)은 특별결의사항이다.","c":"상","v":1},"세무사2021_58-56":{"w":"재무제표 승인(제449조 1항)은 보통결의사항이다.\n회사 계속(제519조), 주식매수선택권(제340조의2), 임의해산(제518조), 휴면회사의 계속(제520조의2 3항)은 특별결의사항이다.","c":"상","v":1},"세무사2022_59-62":{"w":"ㄱ X: 중간배당은 이사회 결의사항이다(제462조의3 1항).\nㄴ O: 정관에 정하지 않은 이사 보수는 주주총회 결의로 정한다(제388조).\nㄷ O: 주식의 포괄적 교환은 주주총회 특별결의로 승인한다(제360조의3).\nㄹ O: 자본금 감소는 주주총회 결의 사항이다(제438조).","c":"상","v":1},"세무사2023_60-57":{"w":"ㄱ O: 상장회사에서 6개월 전부터 계속하여 1.5% 이상 보유한 주주는 이사회에 임시총회 소집을 청구할 수 있다(제542조의6 1항).\nㄴ O: 감사는 서면으로 이사회에 임시총회 소집을 청구할 수 있다(제412조의3).\nㄷ X: 청구 주주가 직접 소집하려면 법원의 허가를 받아야 한다(제366조 2항).\nㄹ X: 전자문서 통지는 각 주주의 동의를 받아야 한다(제363조 1항). 주주 과반수 동의가 아니다.","c":"상","v":1},"세무사2025_62-62":{"w":"감사는 임시총회의 소집을 청구할 수 있다(제412조의3). ④가 옳지 않다.\n① 제363조 1항: 서면 통지가 3년간 계속 도달하지 않으면 통지하지 않을 수 있다. ② 제363조 2항. ③ 자본금 10억원 미만 회사는 총회일 10일 전 통지가 가능하고 전자문서는 각 주주 동의가 필요하다. ⑤ 제363조 4항: 소규모회사는 주주 전원 동의로 소집절차를 생략할 수 있다.","c":"상","v":1},"세무사2026_63-58":{"w":"옳지 않은 것은 ㄱ, ㄷ, ㄹ이다.\nㄱ X: 이사가 회사에 대하여 소를 제기하면 감사가 그 소에 관하여 회사를 대표한다(제394조 제1항).\nㄴ O: 정관상 이사 정원을 채운 상태에서 추가로 한 선임결의는 결의내용이 정관에 위반하여 취소의 소 대상이다(제376조 제1항).\nㄷ X: 주주가 이사 또는 감사인 때에는 담보 제공을 명하지 못한다(제377조 제1항 단서).\nㄹ X: 다른 주주에 대한 소집통지 누락을 이유로 통지를 받은 주주도 결의취소의 소를 제기할 수 있다(판례).\nㅁ O: 결의한 사항이 등기된 경우 취소판결이 확정되면 본점소재지에서 등기한다(제378조).\n2번이다.","c":"상","v":1},"세무사2016_53-52":{"w":"제400조의 책임 감면에 대한 진술은 모두 옳다.\nㄱ: 총주주의 동의로 면제할 수 있다(제400조 1항).\nㄴ: 정관으로 최근 1년 보수액의 6배(사외이사는 3배)를 초과하는 금액을 면제할 수 있다(제400조 2항).\nㄷ: 사외이사는 3배(제400조 2항).\nㄹ: 고의 또는 중대한 과실로 손해를 발생시킨 경우에는 면제가 허용되지 않는다(제400조 2항 단서).","c":"상","v":1},"세무사2017_54-59":{"w":"④ 감사는 회사 및 자회사의 이사·지배인 등의 직무를 겸할 수 없다(제411조). 乙은 甲의 자회사이므로 乙의 지배인도 겸할 수 없다.\n① 甲이 2015.5.1 성립했으므로 7.1은 성립 후 6개월 내이고, 이때 주권발행 전 양도는 회사에 효력이 없다(제335조 3항). ② 제382조의4. ③ 제397조 1항. ⑤ 삼각합병에서 존속회사의 모회사 주식 취득이 허용된다(제523조의2).","c":"상","v":1},"세무사2017_54-60":{"w":"이사와 그 배우자 등이 자기 또는 제3자의 계산으로 회사와 거래하려면 미리 이사회에서 이사 3분의 2 이상의 수로 승인을 받아야 한다(제398조). 1번이다.\n② 경업은 이사회 승인이 필요하지만 가중 정족수가 없다(제397조 제1항). ③ 지배인 선임(제393조 제1항)과 ⑤ 이사회 내 위원회 설치(제393조의2 제1항)는 일반 이사회 결의사항이다. ④ 영업 전부의 임대는 주주총회 특별결의 사항이다(제374조 제1항 제2호).","c":"상","v":1},"세무사2017_54-72":{"w":"감사의 보수는 정관에 정하지 않으면 주주총회 결의로 정한다(제415조·제388조). 이미 주주총회의 권한이다.\n정관으로 주주총회로 돌릴 수 있는 사항: 대표이사 선정(제389조 1항 단서), 신주발행(제416조 단서), 준비금의 자본전입(제461조 1항 단서), 전환사채 발행(제513조 2항).","c":"상","v":1},"세무사2021_58-61":{"w":"이사가 이사회 승인 없이 제3자의 계산으로 경업거래를 한 경우이다.\nㄱ O: 경업금지 위반 거래도 거래 자체는 유효하고 상대방의 선의·악의를 묻지 않는다.\nㄴ O: 주주총회는 언제든지 특별결의로 이사를 해임할 수 있고(제385조 제1항) 경업금지 위반은 해임의 정당한 이유가 된다.\nㄷ O: 법령 위반으로 회사에 손해를 입혔으므로 손해배상을 청구할 수 있다(제399조).\nㄹ X: 자기의 계산으로 한 거래일 때만 회사의 계산으로 한 것으로 볼 수 있다. 제3자의 계산으로 한 거래는 이사에게 이득의 양도를 청구한다(제397조 제2항).\nㄱ, ㄴ, ㄷ이므로 1번이다.","c":"상","v":1},"세무사2021_58-65":{"w":"이사가 가질 주식의 수를 정관으로 정한 경우 그 수의 주권은 감사에게 공탁한다(제387조). 이사회에 공탁한다는 ⑤가 옳지 않다.\n① 자본금 10억원 이상이면 이사 3명 이상. ② 제383조 2항·3항. ③ 제385조 1항 본문, 특별결의. ④ 제385조 1항 단서.","c":"상","v":1},"세무사2023_60-60":{"w":"이사회가 위원회에 위임할 수 없는 사항(제393조의2 2항): 주주총회 승인 사항의 제안, 대표이사 선임·해임, 위원회 설치와 위원 선임·해임, 정관에서 정한 이사회 권한 사항.\n⑤ 지점의 설치·이전·폐지는 이 제외 사항에 없으므로 위임할 수 있다.","c":"상","v":1},"세무사2025_62-60":{"w":"⑤ 이사회 승인 없이 할 수 없는 것은 동종영업을 목적으로 하는 다른 회사의 무한책임사원 또는 이사가 되는 것이다(제397조 1항). 동종영업이 아닌 회사의 무한책임사원은 제한이 없다.\n① 제397조 1항. ② 제397조의2 1항. ③ 제398조. ④ 제397조의2 2항.","c":"상","v":1},"세무사2026_63-79":{"w":"법정준비금의 자본금 전입은 이사회 결의로 하지만 정관으로 주주총회에서 결정하기로 정할 수 있다고 명시돼 있다(제461조 제1항 단서). 4번이다.\n지배인 선임·지점 설치(제393조 제1항), 주주총회 소집(제362조), 이사와 회사 간 거래 승인(제398조)은 이사회 결의사항으로만 규정돼 있고 정관으로 주주총회에 넘길 수 있다는 명문 규정이 없다.","c":"상","v":1},"세무사2016_53-53":{"w":"양도승인 거부 통지를 받은 주주는 통지받은 날부터 20일 이내에 회사에 주식매수를 청구할 수 있고(제335조의2 4항), 회사는 청구를 받은 날부터 2개월 이내에 그 주식을 매수해야 한다(제335조의6, 제374조의2 준용).","c":"중","v":1},"세무사2016_53-56":{"w":"제341조의2의 특정목적 자기주식 취득은 합병·영업 전부 양수, 권리 실행, 단주 처리, 주식매수청구권 행사의 네 경우로, 배당가능이익이 없어도 가능하다.\n주식을 소각하기 위한 취득은 이에 없고, 배당가능이익 범위 내에서 제341조에 따라 해야 한다.","c":"상","v":1},"세무사2021_58-47":{"w":"제341조의2: 합병 또는 다른 회사의 영업 전부의 양수, 권리 실행, 단주 처리, 주식매수청구권 행사의 경우 취득이 허용된다.\nㄱ O, ㄷ O, ㄹ O. ㄴ은 영업 일부의 양수여서 해당하지 않는다.","c":"상","v":1},"세무사2021_58-50":{"w":"주식매수선택권을 줄 수 없는 자(제340조의2 2항)는 의결권 없는 주식을 뺀 발행주식총수의 10% 이상 주주, 이사·감사의 선임·해임 등 회사 경영을 사실상 지배하는 자, 이들의 배우자와 직계존비속이다.\nA(95%)는 10% 이상 주주, B는 A의 배우자, C·D는 A의 직계비속이므로 불가하다. E는 A의 자매로 위 범위에 들지 않는 이사이므로 부여할 수 있다.","c":"중","v":1},"세무사2023_60-47":{"w":"ㄱ X: 의결권 없는 주식을 뺀 발행주식총수의 10% 이상 주주에게는 부여할 수 없다(제340조의2 2항).\nㄴ O: 신주 또는 양도할 자기주식은 발행주식총수의 10%를 초과할 수 없다(제340조의2 3항).\nㄷ X: 주식매수선택권은 양도할 수 없다(제340조의4 1항). 상속만 가능하다.\nㄹ O: 주주총회 결의 후 부여받는 자와 계약을 체결하고 계약서를 작성한다(제340조의3 3항).","c":"상","v":1},"세무사2024_61-46":{"w":"④ 불소지 신고가 있어도 무효 처리되지 않은 채 남은 주권은 유효하다. 이를 절취한 자로부터 선의로 양수하면 선의취득(수표법 제21조 준용)이 성립한다.\n① 상속은 포괄승계라 선의취득이 아니다. ② 회사 성립 전 발행 주권은 무효(제355조 2항). ③ 제권판결이 있으면 그 주권은 무효다. ⑤ 위조 주권은 권리가 화체되지 않아 선의취득이 불가능하다.","c":"중","v":1},"세무사2025_62-49":{"w":"② 주주는 정관에 다른 정함이 없으면 주권 발행 전후를 가리지 않고 주권불소지 신고를 할 수 있다(제358조의2 제1항). 이미 발행된 주권이 있으면 회사에 제출한다. ②가 옳지 않다.\n① 같은 조 제1항. ③ 회사가 불발행 뜻을 주주명부에 기재하고 통지하면 주권을 발행할 수 없다(같은 조 제2항). ④ 제출된 주권은 무효로 하거나 명의개서대리인에게 임치한다(같은 조 제3항). ⑤ 주주는 언제든지 주권의 발행 또는 반환을 청구할 수 있다(같은 조 제4항).","c":"상","v":1},"세무사2025_62-51":{"w":"① 이사회 결의로 이익배당을 할 수 있다고 정관에 정한 회사는 취득가액 총액 한도 등을 이사회 결의로 정한다(제341조 2항). 주주총회 결의가 필요하다는 ①이 옳지 않다.\n② 제341조 1항 1호의 균등 취득 방식. ③ 취득내역서 6개월 비치. ④ 제341조 3항·4항에 따른 이사의 면책. ⑤ 양도신청 절차.","c":"중","v":1},"세무사2026_63-72":{"w":"주권 기재사항은 제356조에 있다.\nㄱ O: 회사 성립연월일. ㄹ O: 주식양도에 이사회 승인을 요하는 때에는 그 규정. ㅁ O: 액면주식의 1주 금액.\nㄴ X: 본점·지점 소재지는 기재사항이 아니다. ㄷ X: 존립기간·해산사유도 아니다.","c":"상","v":1},"세무사2026_63-80":{"w":"자회사가 모회사 주식을 취득할 수 있는 경우(제342조의2 1항): 주식의 포괄적 교환·이전, 합병, 다른 회사 영업 전부의 양수, 권리 실행에 필요한 때.\n영업 일부의 양수로는 취득할 수 없다.","c":"상","v":1},"세무사2023_60-78":{"w":"결손 보전을 위한 자본금 감소다.\n① 결손 보전 감자는 보통결의로 한다(제438조 2항). ② 주식매수청구권은 인정되지 않는다. ③ 결손 보전을 위한 감자는 채권자 보호절차를 요하지 않는다(제439조 2항 단서). ④ 명목상 감소이므로 회사재산은 줄지 않는다. ⑤ 효력은 감자 절차(주식병합 등)가 끝나는 때 생긴다.","c":"상","v":1},"세무사2025_62-69":{"w":"③ 제476조 제1항: 사채 모집이 끝나면 이사는 지체 없이 인수인에게 각 사채의 전액 또는 제1회 납입을 시켜야 한다.\n① 제469조 제1항: 사채는 이사회 결의로 발행한다.\n② 제474조: 사채청약서는 이사가 작성한다.\n④ 제478조 제1항: 채권은 사채 전액의 납입이 완료된 후가 아니면 발행하지 못한다.\n⑤ 제479조 제1항: 기명사채의 이전은 취득자의 성명과 주소를 사채원부에 기재하고 그 성명을 채권에 기재해야 회사 기타의 제3자에게 대항할 수 있다.","c":"상","v":1},"세무사2024_61-79":{"w":"배당한도(제462조 1항)는 순자산액에서 자본금, 자본준비금·이익준비금 합계, 그 결산기에 적립할 이익준비금, 미실현이익(시행령상 평가이익 중 미실현손실과 상계되지 않은 금액)을 뺀 값이다.\nㄱ·ㄴ·ㅁ은 공제 항목이다. 임의준비금(ㄷ)은 공제하지 않고, 미실현손실과 상계된 금액(ㄹ)도 공제 대상이 아니다.","c":"중","v":1},"세무사2025_62-68":{"w":"ㄱ O: 이사는 영업보고서를 작성해 이사회 승인을 얻는다(제447조의2).\nㄴ X: 감사보고서 제출기한은 재무제표를 받은 날부터 4주 내이다(제447조의4 1항).\nㄷ O: 주주와 회사채권자는 영업시간 내 언제든지 열람할 수 있다(제448조 2항).\nㄹ X: 정기총회에서 승인을 구하는 것은 재무제표이고, 영업보고서는 내용을 보고만 한다(제449조 2항).","c":"중","v":1},"세무사2017_54-78":{"w":"이사의 해임은 주주총회 결의사항이지만 반대주주의 주식매수청구권 대상이 아니다.\n영업 전부 양도, 경영위임, 손익공통계약, 다른 회사 영업 양수는 제374조 1항에 따라 매수청구권이 인정된다.","c":"상","v":1},"세무사2022_59-56":{"w":"ㄱ O: 간이영업양도·양수는 반대주주의 매수청구가 인정된다(제374조의3 2항).\nㄴ O: 소규모합병은 존속회사 주주만 제외되고 소멸회사 주주는 매수청구를 할 수 있다.\nㄷ X: 회사 계속 결의는 대상이 아니다.\nㄹ X: 영업 전부 임대만 대상이고 일부 임대는 아니다(제374조 1항 2호).\nㅁ O: 손익공통계약은 대상이다(제374조 1항 2호).","c":"중","v":1},"세무사2025_62-55":{"w":"영업양수에서 매수청구권이 인정되는 것은 회사의 영업에 중대한 영향을 미치는 다른 회사의 영업 전부 또는 일부의 양수이다(제374조 제1항 제3호, 제374조의2). 전부를 양수하는 경우에 한한다는 ⑤가 옳지 않다.\n① 주주총회 전에 서면으로 반대 의사를 통지해야 한다(제374조의2 제1항). ② 의결권이 없거나 제한되는 주주도 포함된다(같은 항). ③ 매수청구기간이 끝나는 날부터 2개월 이내에 매수한다(같은 조 제2항). ④ 그날부터 30일 이내에 협의가 안 되면 회사 또는 주주가 법원에 매수가액 결정을 청구할 수 있다(같은 조 제4항).","c":"상","v":1},"세무사2021_58-77":{"w":"ㄱ O: 소규모합병도 채권자 보호절차를 거친다(제527조의5).\nㄴ O: 존속회사 반대주주는 주식매수청구권을 행사할 수 없다(제527조의3 5항).\nㄷ X: 존속회사 발행주식총수의 20% 이상 주주가 반대 통지를 하면 소규모합병을 할 수 없다. 10%가 아니다(제527조의3 4항).","c":"상","v":1},"세무사2023_60-71":{"w":"상법상 조직변경: 합명↔합자(제242조, 제286조), 유한회사↔주식회사(제604조), 유한책임회사↔주식회사(제287조의43).\nㄴ 합자→합명, ㄹ 유한→주식, ㅁ 주식→유한책임이 인정된다. 합명→유한책임(ㄱ), 유한책임→유한회사(ㄷ)는 규정이 없다.","c":"중","v":1},"세무사2024_61-60":{"w":"매수청구권이 있는 경우는 주식의 포괄적 교환(ㄱ, 제360조의5 제1항), 간이주식교환의 완전자회사 주주(ㄷ, 제360조의5 제2항·제360조의9), 간이합병의 소멸회사 주주(ㄹ, 제522조의3 제2항)이다.\n소규모합병의 존속회사 주주(ㄴ, 제527조의3 제5항)와 소규모주식교환의 완전모회사 주주(ㅁ, 제360조의10 제7항)에게는 매수청구권이 없다. ㄱ, ㄷ, ㄹ이므로 2번이다.","c":"상","v":1},"세무사2016_53-68":{"w":"유한회사 사원의 소수사원권으로는 회사 이사 책임추궁 청구·대표소송, 이사의 위법행위 유지청구, 청산인 해임, 검사인 선임청구 등이 있다.\n집중투표청구권은 주식회사에만 있고 유한회사에는 없다.","c":"중","v":1},"세무사2024_61-70":{"w":"ㄱ X: 유한책임회사는 지분을 양수하거나 질권의 목적으로 받지 못한다(제287조의9).\nㄴ O: 지분 전부 양도에는 다른 사원의 동의가 필요하다(제287조의8 1항).\nㄷ O: 업무집행자가 둘 이상이면 각자 업무집행 권리·의무가 있다(제287조의12).\nㄹ O: 자기거래는 다른 사원 과반수 결의가 있어야 한다(제287조의11).\nㅁ X: 정관 변경은 총사원 동의가 필요하다(제287조의16).","c":"중","v":1},"세무사2025_62-79":{"w":"합명회사의 사원과 합자회사의 무한책임사원은 신용·노무를 출자로 할 수 있다(제195조·제222조).\n합자회사의 유한책임사원(제272조), 유한책임회사 사원(제287조의4), 주주, 유한회사 사원은 재산출자만 가능하다.","c":"상","v":1},"세무사2026_63-46":{"w":"ㄱ X: 유한회사에서 이사의 책임을 추궁할 소의 제기를 청구하려면 자본금 총액의 100분의 3 이상에 해당하는 출자좌수가 필요하다(제565조 제1항).\nㄴ O: 업무집행자가 둘 이상이면 정관 또는 총사원의 동의로 회사를 대표할 업무집행자를 정할 수 있다(제287조의19 제2항).\nㄷ O: 합자회사 유한책임사원이 사망하면 상속인이 그 지분을 승계하여 사원이 된다(제283조 제1항).\nㄹ O: 합명회사 사원은 회사가 주장할 수 있는 항변으로 채권자에게 대항할 수 있다(제214조 제1항).\nㄴ, ㄷ, ㄹ이므로 4번이다.","c":"상","v":1},"세무사2017_54-45":{"w":"주주가 1인이 되는 것은 주식회사의 해산사유가 아니다. 합명·합자회사는 사원이 1인이 되면 해산사유지만 주식회사는 1인 주주도 허용된다.\n파산, 법원의 해산판결·해산명령, 존립기간 만료 등 정관 정한 사유 발생은 해산사유다(제517조).","c":"상","v":1},"세무사2025_62-71":{"w":"주식회사의 해산사유(제517조): 존립기간 만료 등 정관 정한 사유, 합병, 파산, 법원의 해산명령·해산판결, 주주총회 결의.\nㄱ·ㄷ·ㄹ은 해당하고, 주주가 1인이 된 것(ㄴ)은 해산사유가 아니다.","c":"상","v":1},"세무사2016_53-66-5":{"w":"영업양도 등에 반대하는 주주는 의결권이 없거나 제한되는 주주를 포함하여 주식매수청구권을 가진다(상법 제374조의2 제1항). 이 때문에 무의결권 주주에게도 소집통지를 해야 한다(제363조 제7항 단서).","c":"상","v":1},"세무사2016_53-41-3":{"w":"정관에 적은 발기인의 특별이익(제290조 제1호)과 설립비용·발기인 보수(제4호)는 공증인의 조사·보고로 검사인 조사를 갈음할 수 있다(상법 제299조의2). 현물출자·재산인수는 공인된 감정인의 감정으로 갈음한다.","c":"상","v":1},"세무사2016_53-43-1":{"w":"상법 제306조는 납입금의 보관자 또는 납입장소를 변경할 때 법원의 허가를 얻도록 한다. 발기인이 마음대로 바꾸어 가장납입을 하는 것을 막기 위한 규정이다.","c":"상","v":1},"세무사2016_53-43-2":{"w":"상법 제634조(납입책임면탈의 죄)가 타인 또는 가설인 명의로 주식·출자를 인수한 자를 1년 이하의 징역 또는 300만원 이하의 벌금에 처한다.","c":"상","v":1},"세무사2016_53-43-3":{"w":"상법 제318조 제2항에 따라 납입금 보관 은행 등은 증명한 보관금액에 대하여 납입이 부실하거나 반환에 제한이 있다는 이유로 회사에 대항하지 못한다. 보관증명을 믿은 회사를 보호하는 규정이다.","c":"상","v":1},"세무사2016_53-43-4":{"w":"자본금 총액 10억원 미만 회사를 발기설립할 때에는 납입금보관증명서를 금융기관의 잔고증명서로 대체할 수 있다(상법 제318조 제3항). 모집설립에는 이 특례가 없다.","c":"상","v":1},"세무사2016_53-44-1":{"w":"액면주식을 발행하는 경우 1주의 금액은 상법 제289조 제1항 제4호의 절대적 기재사항이다. 무액면주식만 발행하면 적을 필요가 없다.","c":"상","v":1},"세무사2016_53-44-2":{"w":"회사가 부담할 설립비용과 발기인 보수액은 변태설립사항으로 정관에 적어야 효력이 있다(상법 제290조 제4호).","c":"상","v":1},"세무사2016_53-44-3":{"w":"상법 제435조 제1항에 따라 정관변경이 어느 종류주식 주주에게 손해를 미치면 주주총회 결의와 별도로 그 종류주주총회 결의가 필요하다. 결의 요건은 출석 의결권 3분의 2 이상이면서 그 종류 발행주식총수 3분의 1 이상이다(같은 조 제2항).","c":"상","v":1},"세무사2016_53-44-4":{"w":"정관은 원칙적으로 공증인의 인증을 받아야 효력이 생기지만 자본금 10억원 미만 회사를 발기설립하는 경우에는 각 발기인이 기명날인 또는 서명하면 효력이 생긴다(상법 제292조 단서).","c":"상","v":1},"세무사2016_53-46-1":{"w":"이사는 3명 이상이어야 하지만 자본금 총액 10억원 미만 회사는 1명 또는 2명으로 할 수 있다(상법 제383조 제1항 단서).","c":"상","v":1},"세무사2016_53-46-2":{"w":"자본금 총액 10억원 미만 회사는 감사를 선임하지 않을 수 있다(상법 제409조 제4항). 이때 감사의 권한은 주주총회가 행사한다(같은 조 제6항).","c":"상","v":1},"세무사2016_53-46-4":{"w":"자본금 총액 10억원 미만 회사는 주주총회일 2주 전 대신 10일 전에 서면 또는 동의를 받은 전자문서로 소집통지를 발송할 수 있다(상법 제363조 제3항).","c":"상","v":1},"세무사2016_53-46-5":{"w":"자본금 총액 10억원 미만 회사는 주주 전원이 동의하면 소집절차 없이 총회를 열 수 있고 서면결의로 총회 결의를 갈음할 수도 있다(상법 제363조 제4항). 서면결의는 총회 결의와 같은 효력이 있다(제5항).","c":"상","v":1},"세무사2016_53-79-1":{"w":"주식회사 설립무효의 소에는 제190조 본문이 준용되어 원고승소 판결은 제3자에게도 효력이 미친다(상법 제328조 제2항). 다만 판결 전에 생긴 회사와 사원·제3자 사이의 권리의무에는 영향이 없다(제190조 단서).","c":"상","v":1},"세무사2016_53-79-3":{"w":"재량기각을 정한 제189조는 결의취소의 소에만 준용되고(상법 제379조) 결의무효확인·부존재확인의 소에 관한 제380조는 이를 준용하지 않는다. 그래서 무효확인 청구는 재량으로 기각할 수 없다.","c":"상","v":1},"세무사2016_53-79-4":{"w":"상법 제376조 제1항에 따라 결의취소의 소는 주주·이사 또는 감사가 결의한 날부터 2개월 안에 제기해야 한다.","c":"상","v":1},"세무사2016_53-79-5":{"w":"설립무효의 소에는 제191조가 준용되어(상법 제328조 제2항) 패소한 원고에게 악의 또는 중대한 과실이 있으면 회사에 연대하여 손해를 배상한다.","c":"상","v":1},"세무사2017_54-42-1":{"w":"상법 제169조가 회사를 상행위나 그 밖의 영리를 목적으로 하여 설립한 법인으로 정의한다. 2011년 개정으로 사단성 요건이 정의에서 빠졌다.","c":"상","v":1},"세무사2017_54-42-3":{"w":"상법 제171조는 회사의 주소를 본점 소재지에 있는 것으로 정한다.","c":"상","v":1},"세무사2017_54-42-4":{"w":"상법 제172조에 따라 회사는 본점 소재지에서 설립등기를 함으로써 성립한다.","c":"상","v":1},"세무사2017_54-42-5":{"w":"상법 제173조는 회사가 다른 회사의 무한책임사원이 되지 못한다고 정한다. 유한책임사원이 되는 것은 막지 않는다.","c":"상","v":1},"세무사2017_54-46-2":{"w":"발기설립에서 발기인은 출자이행 후 지체 없이 의결권의 과반수로 이사와 감사를 선임한다(상법 제296조 제1항). 의결권은 인수주식 1주에 1개다(같은 조 제2항).","c":"상","v":1},"세무사2017_54-46-3":{"w":"상법 제309조는 창립총회 결의를 출석한 주식인수인 의결권의 3분의 2 이상이면서 인수된 주식 총수의 과반수에 해당하는 다수로 하도록 정한다.","c":"상","v":1},"세무사2017_54-46-4":{"w":"모집설립에서 발기인은 납입과 현물출자 이행이 끝나면 지체 없이 창립총회를 소집하고(상법 제308조 제1항) 창립총회에서 이사와 감사를 선임한다(제312조).","c":"상","v":1},"세무사2017_54-46-5":{"w":"상법 제307조 제1항에 따라 주식인수인이 납입하지 않으면 발기인은 기일을 정하여 그때까지 납입하지 않으면 권리를 잃는다는 뜻을 기일 2주 전에 통지해야 한다. 기일 안에 납입하지 않으면 실권하고 발기인은 다시 주주를 모집할 수 있다(제2항).","c":"상","v":1},"세무사2017_54-47-1":{"w":"상법 제321조 제1항은 회사성립 후 인수되지 않은 주식이나 청약이 취소된 주식을 발기인이 공동으로 인수한 것으로 본다(인수담보책임). 무과실책임이다.","c":"상","v":1},"세무사2017_54-47-2":{"w":"상법 제327조의 유사발기인 책임이다. 주식청약서 등에 성명과 설립 찬조의 뜻을 적도록 승낙한 자는 발기인과 같은 책임을 진다.","c":"상","v":1},"세무사2017_54-47-3":{"w":"상법 제322조 제1항에 따라 설립에 관한 임무를 게을리한 발기인은 회사에 연대하여 손해를 배상한다. 회사에 대한 책임은 경과실로도 생긴다.","c":"상","v":1},"세무사2017_54-47-5":{"w":"상법 제322조 제2항에 따라 발기인이 악의 또는 중대한 과실로 임무를 게을리하면 제3자에게도 연대하여 손해를 배상한다.","c":"상","v":1},"세무사2017_54-48-3":{"w":"현물출자를 하는 자의 성명과 목적재산의 종류·수량·가격, 부여할 주식의 종류와 수는 변태설립사항으로 정관에 적어야 효력이 있다(상법 제290조 제2호).","c":"상","v":1},"세무사2017_54-49-1":{"w":"발기설립에서 발기인이 설립시 발행주식 총수를 인수하면 지체 없이 각 주식의 인수가액 전액을 납입해야 한다(상법 제295조 제1항). 분할납입은 허용되지 않는다.","c":"상","v":1},"세무사2017_54-49-3":{"w":"유한책임회사 정관에는 자본금의 액을 적어야 한다(상법 제287조의3 제3호).","c":"상","v":1},"세무사2017_54-49-4":{"w":"상법 제571조 제2항은 유한회사 사원총회 소집통지를 총회일 1주 전에 서면 또는 동의를 받은 전자문서로 발송하도록 정한다. 주식회사의 2주보다 짧다.","c":"상","v":1},"세무사2017_54-49-5":{"w":"상법 제170조는 회사를 합명회사, 합자회사, 유한책임회사, 주식회사, 유한회사의 5종으로 정한다.","c":"상","v":1},"세무사2021_58-41-1":{"w":"상법 제169조가 회사를 상행위나 그 밖의 영리를 목적으로 하여 설립한 법인으로 정의한다.","c":"상","v":1},"세무사2021_58-41-2":{"w":"합병 당사회사 한쪽이 주식회사·유한회사·유한책임회사이면 존속회사나 신설회사는 이 세 종류 가운데 하나여야 한다(상법 제174조 제2항). 주식회사 주주의 유한책임을 지키기 위해 합명회사로는 설립할 수 없다.","c":"중","v":1},"세무사2021_58-41-3":{"w":"상법 제173조에 따라 회사는 다른 회사의 무한책임사원이 될 수 없다.","c":"상","v":1},"세무사2021_58-41-5":{"w":"상법 제176조 제1항 제1호에 따라 설립목적이 불법한 회사에 대하여 법원은 이해관계인이나 검사의 청구 또는 직권으로 해산을 명할 수 있다.","c":"상","v":1},"세무사2021_58-42-5":{"w":"이사와 감사 전원이 발기인이었던 자 등이어서 제298조 제1항의 조사·보고를 할 수 없으면 이사는 공증인에게 조사·보고를 하게 해야 한다(상법 제298조 제3항).","c":"상","v":1},"세무사2021_58-43-2":{"w":"상법 제319조는 주식인수로 인한 권리(권리주)의 양도를 회사에 대하여 효력이 없다고 정한다.","c":"상","v":1},"세무사2021_58-43-3":{"w":"상법 제320조 제1항에 따라 회사성립 후에는 주식청약서 요건 흠결을 이유로 인수의 무효를 주장하거나 사기·강박·착오를 이유로 취소하지 못한다.","c":"상","v":1},"세무사2021_58-43-4":{"w":"모집설립에서 설립시 발행주식 총수가 인수되면 발기인은 지체 없이 주식인수인에게 인수가액 전액을 납입시켜야 한다(상법 제305조 제1항).","c":"상","v":1},"세무사2021_58-43-5":{"w":"상법 제304조 제2항은 주식인수인에 대한 통지·최고가 보통 도달할 시기에 도달한 것으로 본다고 정한다.","c":"상","v":1},"세무사2021_58-44-1":{"w":"상법 제309조가 창립총회 결의 요건을 출석 주식인수인 의결권의 3분의 2 이상이면서 인수된 주식 총수의 과반수로 정한다.","c":"상","v":1},"세무사2021_58-44-2":{"w":"창립총회에는 주주총회의 의결권 대리행사 규정(제368조 제2항)이 준용되어(상법 제308조 제2항) 주식인수인은 대리인을 통해 의결권을 행사할 수 있다.","c":"상","v":1},"세무사2021_58-44-4":{"w":"상법 제311조 제1항에 따라 발기인은 회사 창립에 관한 사항을 서면으로 창립총회에 보고해야 한다.","c":"상","v":1},"세무사2021_58-44-5":{"w":"상법 제316조 제1항에 따라 창립총회는 정관변경이나 설립폐지를 결의할 수 있고 소집통지서에 그 뜻이 없어도 할 수 있다(제2항).","c":"상","v":1},"세무사2021_58-45-4":{"w":"정관에 따라 전자적 방법으로 공고하는 경우 회사 인터넷 홈페이지에 게재하는 방법으로 해야 한다(상법 제289조 제3항 단서, 상법 시행령 제6조 제1항).","c":"상","v":1},"세무사2021_58-46-1":{"w":"상법 제321조 제2항에 따라 회사성립 후 납입이 끝나지 않은 주식이 있으면 발기인은 연대하여 납입해야 한다(납입담보책임).","c":"상","v":1},"세무사2021_58-46-3":{"w":"상법 제326조 제2항은 회사가 성립하지 못한 경우 설립에 관하여 지급한 비용을 발기인이 부담하도록 정한다. 발기인은 그 설립행위에 연대책임도 진다(제1항).","c":"상","v":1},"세무사2021_58-46-4":{"w":"이사·감사가 설립경과 조사·보고 임무(제313조 제1항)를 게을리하여 회사나 제3자에게 손해를 입히고 발기인도 책임을 지면 그 이사·감사는 발기인과 연대하여 배상한다(상법 제323조).","c":"상","v":1},"세무사2021_58-46-5":{"w":"상법 제325조에 따라 법원이 선임한 검사인이 악의 또는 중대한 과실로 임무를 게을리하면 회사 또는 제3자에게 손해를 배상한다.","c":"상","v":1},"세무사2022_59-42-3":{"w":"회사는 법인이므로 성질상 자연인에게만 인정되는 생명권·친권 등은 갖지 못하지만 재산권과 명예권·상호권·신용권 같은 인격권은 누린다.","c":"중","v":1},"세무사2022_59-43-1":{"w":"합명회사 정관에는 사원의 출자의 목적과 가격 또는 평가표준을 적어야 하고(상법 제179조 제4호) 합자회사는 이를 준용한다(제270조). 유한책임회사는 사원의 출자 목적과 가액을 적는다(제287조의3 제2호).","c":"상","v":1},"세무사2022_59-44-1":{"w":"상법 제184조 제1항에 따라 합명회사 설립무효는 사원만, 설립취소는 취소권 있는 자만 회사성립일부터 2년 안에 소로만 주장할 수 있다.","c":"상","v":1},"세무사2022_59-44-2":{"w":"합자회사에는 합명회사 규정이 준용되므로(상법 제269조) 설립무효의 소는 제184조 제1항에 따라 회사성립일부터 2년 안에 제기해야 한다.","c":"상","v":1},"세무사2022_59-44-3":{"w":"상법 제328조 제1항은 주식회사 설립무효의 소의 제소권자를 주주·이사 또는 감사로 정한다.","c":"상","v":1},"세무사2022_59-44-5":{"w":"상법 제552조 제1항에 따라 유한회사 설립무효는 사원, 이사와 감사가 소로써 주장할 수 있다.","c":"상","v":1},"세무사2023_60-41-2":{"w":"상법 제287조의15는 법인이 업무집행자인 경우의 특칙을 두어 법인도 유한책임회사 업무집행자가 될 수 있음을 전제한다. 이때 법인은 직무수행자를 선임해 다른 사원에게 통지해야 한다.","c":"상","v":1},"세무사2023_60-42-1":{"w":"상법 제172조에 따라 회사는 본점 소재지에서 설립등기를 함으로써 성립한다.","c":"상","v":1},"세무사2023_60-42-2":{"w":"본점 소재지는 주식회사 정관의 절대적 기재사항이다(상법 제289조 제1항 제6호). 합명회사도 같다(제179조 제5호).","c":"상","v":1},"세무사2023_60-42-3":{"w":"주식회사 설립등기 사항에 지점의 소재지가 들어간다(상법 제317조 제2항 제3호의4). 2024년 개정 뒤에도 지점 소재지는 본점 소재지 등기부에 등기한다.","c":"상","v":1},"세무사2023_60-42-5":{"w":"설립무효의 소는 회사 종류와 상관없이 회사성립일부터 2년 안에 제기해야 한다(상법 제184조 제1항, 제269조, 제287조의6, 제328조 제1항, 제552조 제1항).","c":"상","v":1},"세무사2023_60-43-4":{"w":"발기설립에서 발기인은 납입을 맡을 은행 등 금융기관과 납입장소를 지정해야 한다(상법 제295조 제1항 후단).","c":"상","v":1},"세무사2023_60-44-5":{"w":"모집설립에서 현물출자 이행 등에 관한 검사인 조사를 감정인 감정으로 갈음하면 감정인은 감정결과를 창립총회에 보고해야 한다(상법 제310조 제2항·제3항, 제299조의2).","c":"상","v":1},"세무사2023_60-77-1":{"w":"신주발행은 원칙적으로 이사회가 결정하지만 상법 제416조 단서가 정관으로 주주총회에서 결정하도록 정할 수 있게 하므로 성립 후 정관변경으로 권한을 주주총회로 옮길 수 있다.","c":"상","v":1},"세무사2023_60-77-2":{"w":"정관변경은 주주총회 결의로 하고(상법 제433조 제1항) 그 결의는 출석 의결권 3분의 2 이상이면서 발행주식총수 3분의 1 이상인 특별결의로 한다(제434조).","c":"상","v":1},"세무사2023_60-77-3":{"w":"상법 제435조 제1항에 따라 종류주식을 발행한 회사의 정관변경이 어느 종류주주에게 손해를 미치면 그 종류주주총회 결의도 있어야 한다.","c":"상","v":1},"세무사2023_60-77-5":{"w":"주식회사 등기사항이 변경되면 본점 소재지에서 2주 안에 변경등기를 해야 한다(상법 제317조 제4항, 제183조).","c":"상","v":1},"세무사2024_61-41-5":{"w":"정당한 사유 없이 설립 후 1년 안에 영업을 시작하지 않거나 1년 이상 영업을 쉬면 법원은 이해관계인이나 검사의 청구 또는 직권으로 해산을 명할 수 있다(상법 제176조 제1항 제2호).","c":"상","v":1},"세무사2024_61-42-3":{"w":"상법 제326조 제2항은 회사가 성립하지 못한 경우 설립에 관하여 지급한 비용을 발기인이 부담하도록 정한다.","c":"상","v":1},"세무사2024_61-43-2":{"w":"회사 공고는 관보나 일간신문에 하는 것이 원칙이지만 정관으로 정하면 전자적 방법으로도 할 수 있다(상법 제289조 제3항 단서).","c":"상","v":1},"세무사2024_61-43-3":{"w":"자본금 10억원 미만 회사를 발기설립하는 경우에는 공증인 인증 없이 각 발기인의 기명날인 또는 서명으로 정관의 효력이 생긴다(상법 제292조 단서).","c":"상","v":1},"세무사2024_61-43-4":{"w":"상법 제296조 제1항에 따라 발기설립에서 납입과 현물출자 이행이 끝나면 발기인은 지체 없이 의결권의 과반수로 이사와 감사를 선임해야 한다.","c":"상","v":1},"세무사2024_61-43-5":{"w":"발기설립에서 이사와 감사는 취임 후 지체 없이 설립에 관한 모든 사항이 법령이나 정관에 위반되는지 조사하여 발기인에게 보고해야 한다(상법 제298조 제1항). 모집설립에서는 창립총회에 보고한다(제313조).","c":"상","v":1},"세무사2024_61-75-1":{"w":"상법 제433조 제2항은 정관변경 의안의 요령을 제363조에 따른 소집통지에 적도록 정한다.","c":"상","v":1},"세무사2024_61-75-3":{"w":"상법 제435조 제1항에 따라 정관변경이 어느 종류주식 주주에게 손해를 미치면 그 종류주주총회 결의가 따로 있어야 한다.","c":"상","v":1},"세무사2024_61-75-4":{"w":"등기사항이 바뀌면 본점 소재지에서 2주 안에 변경등기를 해야 한다(상법 제317조 제4항, 제183조).","c":"상","v":1},"세무사2024_61-75-5":{"w":"회사가 발행할 주식의 총수(수권주식수)는 정관의 절대적 기재사항이므로(상법 제289조 제1항 제3호) 이를 늘리거나 줄이려면 정관을 변경해야 한다.","c":"상","v":1},"세무사2025_62-42-1":{"w":"상법 제288조는 주식회사를 설립할 때 발기인이 정관을 작성하도록 정한다.","c":"상","v":1},"세무사2025_62-42-2":{"w":"회사가 공고를 하는 방법은 상법 제289조 제1항 제7호의 절대적 기재사항이다.","c":"상","v":1},"세무사2025_62-42-4":{"w":"정관에서 전자적 방법으로 공고하도록 정하면 회사 인터넷 홈페이지 주소를 등기해야 한다(상법 시행령 제6조 제2항).","c":"상","v":1},"세무사2025_62-42-5":{"w":"상법 제316조 제1항은 창립총회가 정관변경이나 설립폐지를 결의할 수 있다고 정하고 제2항은 소집통지서에 그 뜻이 없어도 결의할 수 있다고 정한다.","c":"상","v":1},"세무사2025_62-43-4":{"w":"주식회사 설립무효는 회사성립일부터 2년 안에 소로만 주장할 수 있으므로(상법 제328조 제1항) 2년이 지나면 제소권자라도 소를 제기할 수 없다.","c":"상","v":1},"세무사2025_62-80-2":{"w":"외국회사가 대한민국에 영업소를 설치하면 설치일부터 3주 안에 영업소 소재지에서 목적·상호·대표자 등을 등기해야 한다(상법 제614조 제2항).","c":"상","v":1},"세무사2025_62-80-3":{"w":"상법 제619조 제1항 제1호에 따라 영업소 설치목적이 불법하면 법원은 이해관계인 또는 검사의 청구로 영업소 폐쇄를 명할 수 있다.","c":"상","v":1},"세무사2025_62-80-4":{"w":"상법 제621조는 다른 법률에 특별한 규정이 없으면 외국회사를 대한민국에서 성립한 같은 종류 또는 가장 비슷한 회사로 본다.","c":"상","v":1},"세무사2025_62-80-5":{"w":"상법 제617조(유사외국회사)는 외국에서 설립되었더라도 대한민국에 본점을 두거나 대한민국 영업을 주목적으로 하는 회사에 국내 회사와 같은 규정을 적용한다. 국내법 회피를 막기 위한 규정이다.","c":"상","v":1},"세무사2026_63-47-1":{"w":"상법 제173조에 따라 회사는 다른 회사의 무한책임사원이 될 수 없다.","c":"상","v":1},"세무사2026_63-47-2":{"w":"합병 당사회사 한쪽이 유한책임회사이면 존속회사나 신설회사는 주식회사·유한회사·유한책임회사 가운데 하나여야 하므로(상법 제174조 제2항) 유한책임회사로 설립할 수 있다.","c":"상","v":1},"세무사2026_63-47-4":{"w":"상법 제176조 제1항 제2호는 정당한 사유 없이 설립 후 1년 안에 영업을 개시하지 않은 경우를 해산명령 사유로 정하고 법원은 청구 또는 직권으로 명할 수 있다.","c":"상","v":1},"세무사2026_63-47-5":{"w":"상법 제175조 제1항에 따라 신설합병에서는 각 회사가 선임한 설립위원이 공동으로 정관 작성 등 설립행위를 한다. 주식회사의 설립위원 선임은 특별결의로 한다(같은 조 제2항, 제434조).","c":"상","v":1},"세무사2026_63-48-1":{"w":"상법 제289조 제3항 단서에 따라 정관으로 정하면 공고를 전자적 방법으로 할 수 있다.","c":"상","v":1},"세무사2026_63-48-3":{"w":"상법 제293조는 각 발기인이 서면으로 주식을 인수하도록 정한다.","c":"상","v":1},"세무사2026_63-48-4":{"w":"발기설립에서 발기인이 설립시 발행주식 총수를 인수하면 지체 없이 인수가액 전액을 납입해야 한다(상법 제295조 제1항).","c":"상","v":1},"세무사2026_63-48-5":{"w":"상법 제296조 제2항에 따라 발기설립에서 이사·감사를 선임할 때 발기인의 의결권은 인수주식 1주에 1개다.","c":"상","v":1},"세무사2026_63-61-1":{"w":"정관변경은 주주총회 결의로 하고(상법 제433조 제1항) 결의 요건은 출석 의결권 3분의 2 이상과 발행주식총수 3분의 1 이상이다(제434조).","c":"상","v":1},"세무사2026_63-61-2":{"w":"상법 제435조 제1항이 정관변경이 어느 종류주주에게 손해를 미치는 경우 그 종류주주총회 결의를 요구한다.","c":"상","v":1},"세무사2026_63-61-4":{"w":"액면주식 1주의 금액은 정관의 절대적 기재사항이므로(상법 제289조 제1항 제4호) 500원에서 1천원으로 바꾸려면 정관을 변경해야 한다. 이때 주식 병합 절차도 함께 밟는다.","c":"상","v":1},"세무사2026_63-61-5":{"w":"상법 제433조 제2항은 정관변경 의안의 요령을 소집통지에 적도록 정한다.","c":"상","v":1},"세무사2016_53-54-1":{"w":"상법 제329조 제1항 본문에 따라 정관으로 정하면 주식 전부를 무액면주식으로 발행할 수 있다. 이때 액면주식은 함께 발행할 수 없다(같은 항 단서).","c":"상","v":1},"세무사2016_53-54-2":{"w":"상법 제331조는 주주의 책임을 그가 가진 주식의 인수가액을 한도로 정한다(주주 유한책임).","c":"상","v":1},"세무사2016_53-54-3":{"w":"상법 제329조 제3항이 액면주식 1주의 금액을 100원 이상으로 정한다.","c":"상","v":1},"세무사2016_53-54-5":{"w":"주식분할은 제434조의 주주총회 결의, 곧 특별결의로 한다(상법 제329조의2 제1항). 분할 후 1주의 금액도 100원 이상이어야 한다(제2항).","c":"상","v":1},"세무사2016_53-55-1":{"w":"상법 제340조의2 제1항은 정관에 근거를 두고 주주총회 특별결의로 설립·경영·기술혁신 등에 기여한 이사·집행임원·감사·피용자에게 주식매수선택권을 부여할 수 있게 한다.","c":"상","v":1},"세무사2016_53-55-2":{"w":"상법 제340조의2 제3항에 따라 주식매수선택권 행사로 발행할 신주나 양도할 자기주식은 발행주식총수의 100분의 10을 넘지 못한다.","c":"상","v":1},"세무사2016_53-55-4":{"w":"상법 제340조의4 제2항 본문은 주식매수선택권 양도를 금지하고 단서는 행사할 수 있는 자가 사망하면 상속인이 행사할 수 있게 한다.","c":"상","v":1},"세무사2016_53-55-5":{"w":"의결권 없는 주식을 뺀 발행주식총수의 100분의 10 이상을 가진 주주에게는 주식매수선택권을 부여할 수 없다(상법 제340조의2 제2항 제1호).","c":"상","v":1},"세무사2016_53-57-1":{"w":"상법 제352조의2 제1항에 따라 회사는 정관으로 정하면 전자문서로 주주명부(전자주주명부)를 작성할 수 있다. 전자주주명부에는 전자우편주소도 적는다(제2항).","c":"상","v":1},"세무사2016_53-57-2":{"w":"상법 제353조 제1항은 주주 또는 질권자에 대한 통지·최고를 주주명부에 적힌 주소나 그가 회사에 통지한 주소로 하면 된다고 정한다.","c":"상","v":1},"세무사2016_53-57-3":{"w":"상법 제354조 제2항이 주주명부 폐쇄기간을 3개월 이내로 제한한다.","c":"상","v":1},"세무사2016_53-57-4":{"w":"상법 제354조 제3항에 따라 기준일은 권리를 행사할 날에 앞선 3개월 안의 날로 정해야 한다.","c":"상","v":1},"세무사2016_53-58-2":{"w":"상법 제516조의7은 신주인수권증권 발행 대신 정관으로 정하는 바에 따라 전자등록부에 신주인수권을 등록할 수 있게 한다. 등록 효력은 주식 전자등록 규정(제356조의2 제2항~제4항)을 준용한다.","c":"상","v":1},"세무사2016_53-58-3":{"w":"상법 제356조의2 제3항 전단은 전자등록부에 주식을 등록한 자를 그 주식에 대한 권리를 적법하게 보유한 것으로 추정한다.","c":"상","v":1},"세무사2016_53-58-4":{"w":"상법 제356조의2 제3항 후단에 따라 전자등록부를 선의이고 중대한 과실 없이 믿고 등록에 따라 권리를 취득한 자는 그 권리를 적법하게 취득한다(선의취득).","c":"상","v":1},"세무사2016_53-58-5":{"w":"상법 제356조의2 제2항은 전자등록 주식의 양도나 입질을 전자등록부에 등록해야 효력이 생기도록 정한다. 등록이 효력요건이다.","c":"상","v":1},"세무사2016_53-69-2":{"w":"자회사는 모회사 주식을 취득할 수 없지만 회사의 합병이나 다른 회사의 영업 전부 양수로 인한 때에는 예외로 취득할 수 있다(상법 제342조의2 제1항 제1호). 모회사와 자회사가 함께 50%를 넘게 가진 회사도 자회사로 보므로(같은 조 제3항) 손자회사에도 이 예외가 적용된다. 취득한 주식은 6개월 안에 처분해야 한다(제2항).","c":"중","v":1},"세무사2016_53-69-3":{"w":"흡수합병에서 소멸회사 주주에게 존속회사의 모회사 주식을 합병대가로 주는 경우 존속회사는 제342조의2에도 불구하고 그 지급을 위해 모회사 주식을 취득할 수 있다(상법 제523조의2 제1항). 합병 후에도 남은 주식은 효력발생일부터 6개월 안에 처분해야 한다(제2항).","c":"상","v":1},"세무사2016_53-69-4":{"w":"흡수합병의 존속회사는 소멸회사 주주에게 합병대가의 전부 또는 일부로 금전이나 그 밖의 재산을 줄 수 있고(상법 제523조 제4호) 모회사 주식도 대가가 될 수 있다(제523조의2 제1항).","c":"상","v":1},"세무사2016_53-69-5":{"w":"흡수분할합병에서 분할승계회사는 분할회사 주주에게 대가로 모회사 주식을 줄 수 있고 그 지급을 위해 모회사 주식을 취득할 수 있다(상법 제530조의6 제1항 제4호·제4항). 분할합병 후에도 남은 주식은 6개월 안에 처분한다(제5항).","c":"상","v":1},"세무사2017_54-67-2":{"w":"상법 제346조 제2항은 정관에 일정한 사유가 생기면 회사가 주주의 인수주식을 다른 종류주식으로 전환할 수 있다고 정할 수 있게 한다(회사전환주식). 이때 전환의 사유·조건·기간과 발행할 주식의 수·내용을 정관에 정한다.","c":"상","v":1},"세무사2017_54-67-3":{"w":"상법 제344조 제1항은 이익배당·잔여재산분배·의결권 행사·상환·전환 등에 관하여 내용이 다른 종류주식의 발행을 허용한다.","c":"상","v":1},"세무사2017_54-67-4":{"w":"상법 제344조 제3항에 따라 종류주식을 발행한 회사는 정관에 정함이 없어도 신주인수, 주식의 병합·분할·소각, 합병·분할로 인한 주식배정에서 종류에 따라 특수하게 정할 수 있다.","c":"상","v":1},"세무사2017_54-67-5":{"w":"상법 제348조는 전환으로 신주식을 발행할 때 전환 전 주식의 발행가액을 신주식의 발행가액으로 한다. 자본충실을 지키기 위한 규정이다.","c":"상","v":1},"세무사2017_54-69-1":{"w":"상법 제336조 제1항에 따라 주권이 발행된 주식은 주권을 교부해야 양도된다. 주권의 점유자는 적법한 소지인으로 추정된다(제2항).","c":"상","v":1},"세무사2017_54-69-2":{"w":"상법 제342조에 따라 자기주식을 처분할 때 처분할 주식의 종류와 수, 처분가액과 납입기일, 상대방과 처분방법 가운데 정관에 규정이 없는 것은 이사회가 결정한다.","c":"상","v":1},"세무사2017_54-69-3":{"w":"주권발행 전 주식양도는 회사성립 후 6개월이 지나면 회사에 대하여도 효력이 있다(상법 제335조 제3항 단서). 판례는 이때 주권이 없으므로 지명채권 양도의 일반원칙에 따라 당사자의 의사표시만으로 양도의 효력이 생긴다고 본다.","c":"상","v":1},"세무사2017_54-69-5":{"w":"상법 제335조 제1항 단서에 따라 정관으로 주식 양도에 이사회 승인을 받도록 정할 수 있다. 이 규정은 등기해야 한다(제317조 제2항 제3호의2).","c":"상","v":1},"세무사2017_54-71-1":{"w":"상법 제353조 제1항이 주주에 대한 통지·최고를 주주명부의 주소나 주주가 회사에 통지한 주소로 하면 된다고 정한다.","c":"상","v":1},"세무사2017_54-71-3":{"w":"상법 제337조 제2항 전단은 정관이 정하는 바에 따라 명의개서대리인을 둘 수 있게 한다. 대리인이 주주명부 복본에 적으면 명의개서가 있는 것으로 본다(같은 항 후단).","c":"상","v":1},"세무사2017_54-71-4":{"w":"각 주식의 취득연월일은 상법 제352조 제1항 제3호의 주주명부 기재사항이다.","c":"상","v":1},"세무사2017_54-71-5":{"w":"상법 제354조 제1항은 의결권 행사자 등을 정하기 위해 주주명부 기재변경을 정지할 수 있게 하고 제2항은 그 기간을 3개월 이내로 제한한다.","c":"상","v":1},"세무사2017_54-73-4":{"w":"주식매수선택권 부여를 결의할 때에는 부여받을 자 각각에 대하여 행사로 발행하거나 양도할 주식의 종류와 수를 정해야 한다(상법 제340조의3 제2항 제2호).","c":"상","v":1},"세무사2017_54-74-2":{"w":"상법 제329조 제3항이 액면주식 1주의 금액을 100원 이상으로 정한다.","c":"상","v":1},"세무사2021_58-48-4":{"w":"이사회 승인 없이 주식을 취득한 자는 회사에 그 주식의 종류와 수를 적은 서면으로 취득의 승인을 청구할 수 있다(상법 제335조의7 제1항). 승인 없는 양도도 당사자 사이에서는 유효하다는 전제에서 나온 제도다.","c":"상","v":1},"세무사2021_58-49-1":{"w":"상법 제329조 제1항 단서는 무액면주식을 발행하는 경우 액면주식을 발행할 수 없다고 정한다.","c":"상","v":1},"세무사2021_58-49-2":{"w":"상법 제329조의2 제1항에 따라 주식분할은 제434조의 특별결의로 한다. 주식의 수와 1주의 금액이 정관 기재사항이어서 정관변경과 같은 결의가 필요하다.","c":"상","v":1},"세무사2021_58-49-4":{"w":"상법 제332조 제2항은 타인의 승낙을 얻어 그 명의로 주식을 인수한 자에게 그 타인과 연대하여 납입할 책임을 지운다.","c":"상","v":1},"세무사2021_58-49-5":{"w":"상법 제333조 제1항에 따라 여러 사람이 공동으로 주식을 인수하면 연대하여 납입할 책임이 있다.","c":"상","v":1},"세무사2021_58-51-1":{"w":"상법 제344조 제2항은 종류주식을 발행할 때 정관으로 각 종류주식의 내용과 수를 정하도록 한다.","c":"상","v":1},"세무사2021_58-51-2":{"w":"상법 제435조 제2항이 종류주주총회 결의 요건을 출석한 그 종류 주주 의결권의 3분의 2 이상과 그 종류 발행주식총수의 3분의 1 이상으로 정한다.","c":"상","v":1},"세무사2021_58-51-3":{"w":"상법 제345조 제4항은 상환주식 취득 대가로 현금 외에 다른 종류주식을 뺀 유가증권이나 그 밖의 자산을 교부할 수 있게 하고 그 장부가액이 배당가능이익을 넘지 못하게 한다.","c":"상","v":1},"세무사2021_58-51-4":{"w":"상법 제348조에 따라 전환으로 신주식을 발행할 때에는 전환 전 주식의 발행가액을 신주식의 발행가액으로 한다.","c":"상","v":1},"세무사2021_58-52-1":{"w":"상법 제355조 제2항은 회사 성립 후 또는 신주 납입기일 후가 아니면 주권을 발행하지 못하게 한다. 이를 어긴 주권은 무효다(제3항).","c":"상","v":1},"세무사2021_58-52-3":{"w":"상법 제358조의2 제1항에 따라 정관에 다른 정함이 없으면 주주는 주권을 소지하지 않겠다는 뜻을 회사에 신고할 수 있다.","c":"상","v":1},"세무사2021_58-52-4":{"w":"상법 제360조 제1항은 주권을 공시최고 절차로 무효로 할 수 있다고 정한다.","c":"상","v":1},"세무사2021_58-52-5":{"w":"상법 제360조 제2항에 따라 주권을 상실한 자는 제권판결을 얻어야 회사에 주권 재발행을 청구할 수 있다.","c":"상","v":1},"세무사2021_58-54-2":{"w":"지배주주 여부를 가리는 100분의 95 이상 보유 산정에서는 모회사와 자회사가 보유한 주식을 합산한다(상법 제360조의24 제2항 전단).","c":"상","v":1},"세무사2021_58-54-3":{"w":"상법 제360조의24 제3항은 지배주주가 매도청구를 할 때 미리 주주총회 승인을 받도록 정한다.","c":"상","v":1},"세무사2021_58-54-4":{"w":"상법 제360조의24 제6항에 따라 매도청구를 받은 소수주주는 청구를 받은 날부터 2개월 안에 지배주주에게 주식을 매도해야 한다.","c":"상","v":1},"세무사2021_58-54-5":{"w":"상법 제360조의26 제1항은 지배주주가 매매가액을 소수주주에게 지급한 때 주식이 이전된 것으로 본다. 수령을 거부하면 공탁한 날에 이전된다(제2항).","c":"상","v":1},"세무사2022_59-51-1":{"w":"상법 제329조 제1항 본문에 따라 정관으로 정하면 주식 전부를 무액면주식으로 발행할 수 있다.","c":"상","v":1},"세무사2022_59-52-4":{"w":"상법 제335조의3에 따라 이사회는 상대방 지정 청구가 있은 날부터 2주 안에 주주와 지정된 상대방에게 통지해야 하고 이 기간 안에 통지하지 않으면 양도를 승인한 것으로 본다(제2항).","c":"상","v":1},"세무사2022_59-53-1":{"w":"주권 점유자는 적법한 소지인으로 추정되고(상법 제336조 제2항) 이 규정은 신주인수권증서(제420조의3 제2항)와 신주인수권증권(제516조의6 제2항)에 준용된다.","c":"상","v":1},"세무사2022_59-53-2":{"w":"상법 제338조 제2항에 따라 약식질권자는 주권을 계속 점유해야 질권으로 제3자에게 대항할 수 있다.","c":"상","v":1},"세무사2022_59-53-3":{"w":"상법 제339조(질권의 물상대위)에 따라 주식의 소각·병합·분할·전환으로 종전 주주가 받을 금전이나 주식에도 질권을 행사할 수 있다.","c":"상","v":1},"세무사2022_59-53-4":{"w":"주식 양도에 이사회 승인을 얻도록 정한 규정은 상법 제356조 제6호의2의 주권 기재사항이다.","c":"상","v":1},"세무사2022_59-54-1":{"w":"상법 제340조의2 제1항은 정관에 따라 주주총회 특별결의로 기술혁신 등에 기여하거나 기여할 수 있는 피용자에게 주식매수선택권을 부여할 수 있게 한다.","c":"상","v":1},"세무사2022_59-54-2":{"w":"상법 제340조의4 제2항은 주식매수선택권 양도를 막되 행사할 수 있는 자가 사망하면 상속인이 행사할 수 있게 한다.","c":"상","v":1},"세무사2022_59-54-3":{"w":"상법 제340조의2 제1항 단서에 따라 행사일 기준 실질가액이 행사가액보다 높으면 회사는 그 차액을 금전으로 주거나 차액만큼 자기주식을 양도할 수 있다(차액정산형).","c":"상","v":1},"세무사2022_59-54-5":{"w":"상법 제340조의2 제3항이 주식매수선택권으로 발행할 신주나 양도할 자기주식을 발행주식총수의 100분의 10 이내로 제한한다.","c":"상","v":1},"세무사2022_59-55-1":{"w":"상법 제341조 제1항 제1호에 따라 거래소 시세가 있는 주식은 거래소에서 취득하는 방법으로 회사 명의와 계산으로 자기주식을 취득할 수 있다.","c":"상","v":1},"세무사2022_59-55-2":{"w":"상법 제341조 제1항 단서는 자기주식 취득가액 총액이 직전 결산기 대차대조표상 순자산액에서 제462조 제1항 각 호의 금액을 뺀 금액, 곧 배당가능이익을 넘지 못하게 한다.","c":"상","v":1},"세무사2022_59-55-4":{"w":"상법 제341조의3 본문은 회사가 발행주식총수의 20분의 1을 넘는 자기주식을 질권 목적으로 받지 못하게 한다.","c":"상","v":1},"세무사2022_59-55-5":{"w":"상법 제343조 제1항 단서에 따라 이사회 결의로 회사가 보유한 자기주식을 소각하는 경우에는 자본금 감소 절차를 따르지 않아도 된다.","c":"상","v":1},"세무사2022_59-57-1":{"w":"상법 제352조의2 제1항은 정관에 따라 전자주주명부를 작성할 수 있게 하고 제2항은 전자주주명부에 전자우편주소를 적도록 한다.","c":"상","v":1},"세무사2022_59-57-2":{"w":"통지·최고는 주주명부의 주소나 회사에 통지한 주소로 하면 되고(상법 제353조 제1항) 보통 도달할 시기에 도달한 것으로 본다(제2항, 제304조 제2항 준용).","c":"상","v":1},"세무사2022_59-57-4":{"w":"상법 제396조 제1항에 따라 주주명부는 본점에 비치하되 명의개서대리인을 두면 주주명부나 그 복본을 명의개서대리인의 영업소에 비치할 수 있다.","c":"상","v":1},"세무사2022_59-57-5":{"w":"상법 제337조 제2항 후단은 명의개서대리인이 취득자의 성명과 주소를 주주명부 복본에 적으면 명의개서가 있는 것으로 본다. 따라서 취득자는 회사에 대항할 수 있다.","c":"상","v":1},"세무사2022_59-58-1":{"w":"상법 제344조 제3항이 종류주식 발행 회사에 정관에 정함이 없어도 신주인수, 주식의 병합·분할·소각, 합병·분할로 인한 주식배정에서 종류별로 특수하게 정할 수 있게 한다.","c":"상","v":1},"세무사2022_59-58-2":{"w":"상법 제344조 제1항은 이익배당이나 잔여재산분배에 관하여 내용이 다른 종류주식의 발행을 허용한다.","c":"상","v":1},"세무사2022_59-58-3":{"w":"상법 제344조의3 제2항에 따라 의결권 배제·제한 종류주식은 발행주식총수의 4분의 1을 넘지 못하고 넘게 발행되면 회사는 지체 없이 필요한 조치를 해야 한다.","c":"상","v":1},"세무사2022_59-58-4":{"w":"상법 제345조는 회사가 이익으로 소각할 수 있는 종류주식(제1항)과 주주가 상환을 청구할 수 있는 종류주식(제3항)을 정관에 따라 발행할 수 있게 한다.","c":"상","v":1},"세무사2022_59-64-1":{"w":"상법 제346조 제1항에 따라 정관으로 정하면 주주는 인수한 주식을 다른 종류주식으로 전환해 달라고 청구할 수 있다(주주전환주식).","c":"상","v":1},"세무사2022_59-64-2":{"w":"상법 제346조 제2항은 정관에 일정한 사유가 생기면 회사가 주주의 인수주식을 다른 종류주식으로 전환할 수 있다고 정할 수 있게 한다.","c":"상","v":1},"세무사2022_59-64-3":{"w":"상법 제346조 제4항은 새로 발행할 주식 수를 전환청구기간이나 전환기간 동안 발행하지 않고 유보하도록 정한다.","c":"상","v":1},"세무사2022_59-64-5":{"w":"상법 제350조 제1항에 따라 주주가 전환을 청구하면 청구한 때에 전환의 효력이 생긴다. 회사가 전환하는 경우에는 주권제출기간이 끝난 때다.","c":"상","v":1},"세무사2023_60-45-5":{"w":"상법 제344조 제3항은 종류주식 발행 회사가 정관에 정함이 없어도 주식 분할로 인한 주식배정에 관하여 종류별로 특수하게 정할 수 있게 한다.","c":"상","v":1},"세무사2023_60-46-2":{"w":"상법 제338조 제2항에 따라 주식 질권자는 주권을 계속 점유해야 제3자에게 대항할 수 있다.","c":"상","v":1},"세무사2023_60-46-3":{"w":"상법 제332조 제2항은 타인의 승낙을 얻어 그 명의로 주식을 인수한 자를 그 타인과 연대하여 납입할 책임을 지게 한다.","c":"상","v":1},"세무사2023_60-46-4":{"w":"상법 제337조 제2항 전단에 따라 회사는 정관에 따라 명의개서대리인을 둘 수 있다.","c":"상","v":1},"세무사2023_60-46-5":{"w":"자기주식 질취는 발행주식총수의 20분의 1이 한도지만 합병·영업 전부 양수 또는 회사의 권리 실행에 필요한 경우(제341조의2 제1호·제2호)에는 한도를 넘어 질권 목적으로 받을 수 있다(상법 제341조의3 단서).","c":"상","v":1},"세무사2023_60-48-1":{"w":"회사 성립 전 주식인수로 인한 권리(권리주)의 양도는 회사에 대하여 효력이 없다(상법 제319조).","c":"중","v":1},"세무사2023_60-48-2":{"w":"주권은 회사 성립 후 또는 신주 납입기일 후가 아니면 발행하지 못하고 이를 어긴 주권은 무효다(상법 제355조 제2항·제3항). 사례의 회사 성립 전에 발행한 주권이 여기에 해당한다.","c":"중","v":1},"세무사2023_60-48-4":{"w":"주권이 발행되면 그 뒤의 주식 양도는 주권을 교부해야 효력이 생긴다(상법 제336조 제1항).","c":"중","v":1},"세무사2023_60-48-5":{"w":"상법 제337조 제1항에 따라 주식 취득자는 자신의 성명과 주소를 주주명부에 적지 않으면 회사에 대항하지 못한다.","c":"상","v":1},"세무사2023_60-49-3":{"w":"주식 양도에 이사회 승인을 얻도록 정한 규정은 주권에 적어야 한다(상법 제356조 제6호의2). 등기사항이기도 하다(제317조 제2항 제3호의2).","c":"상","v":1},"세무사2023_60-50-1":{"w":"상법 제342조의3은 회사가 다른 회사 발행주식총수의 10분의 1을 넘게 취득하면 그 다른 회사에 지체 없이 통지하도록 정한다.","c":"상","v":1},"세무사2023_60-50-3":{"w":"甲회사는 95% 이상을 자기 계산으로 보유한 지배주주이므로 丙회사의 소수주주인 乙회사는 언제든지 甲회사에 보유주식 매수를 청구할 수 있다(상법 제360조의24 제1항, 제360조의25 제1항).","c":"상","v":1},"세무사2023_60-50-4":{"w":"상법 제360조의14 제1항은 주식교환 무효를 각 회사의 주주·이사·감사·감사위원·청산인이 주식교환의 날부터 6개월 안에 소로만 주장하도록 정한다.","c":"상","v":1},"세무사2023_60-50-5":{"w":"납입기일 전에 발행한 주권은 무효지만(상법 제355조 제2항·제3항 본문) 발행한 자에 대한 손해배상 청구에는 영향이 없다(같은 항 단서).","c":"상","v":1},"세무사2023_60-51-1":{"w":"상법 제353조 제1항은 통지·최고를 주주명부의 주소나 통지받은 주소로 하면 되게 하고 제2항은 제304조 제2항을 준용하여 보통 도달할 시기에 도달한 것으로 본다.","c":"상","v":1},"세무사2023_60-51-2":{"w":"상법 제354조 제2항이 주주명부 폐쇄기간을 3개월 이내로 제한한다.","c":"상","v":1},"세무사2023_60-51-3":{"w":"폐쇄기간이나 기준일은 2주 전에 공고해야 하지만 정관으로 그 기간이나 날을 지정한 때에는 공고하지 않아도 된다(상법 제354조 제4항).","c":"상","v":1},"세무사2023_60-51-5":{"w":"주권 점유자는 적법한 소지인으로 추정되므로(상법 제336조 제2항) 주권을 제시하고 명의개서를 청구한 양수인은 자기가 실질적 권리자임을 따로 증명할 필요가 없다. 회사가 거부하려면 무권리를 증명해야 한다.","c":"상","v":1},"세무사2023_60-54-1":{"w":"상법 제345조 제1항에 따라 정관으로 정하면 회사의 이익으로 소각할 수 있는 종류주식(회사상환주식)을 발행할 수 있다.","c":"상","v":1},"세무사2023_60-54-2":{"w":"상법 제350조 제1항에 따라 주주가 전환을 청구하는 전환주식은 청구한 때 전환의 효력이 생긴다.","c":"상","v":1},"세무사2023_60-54-3":{"w":"상법 제421조 제1항은 이사가 신주 인수인에게 배정한 주수에 따라 납입기일에 인수가액 전액을 납입시키도록 정한다.","c":"상","v":1},"세무사2023_60-54-4":{"w":"무액면주식의 자본금은 발행가액의 2분의 1 이상에서 이사회 등이 정하고 자본금으로 계상하지 않은 금액은 자본준비금으로 계상한다(상법 제451조 제2항).","c":"상","v":1},"세무사2024_61-45-1":{"w":"상법 제346조 제2항이 정관에 일정한 사유가 생기면 회사가 주주의 인수주식을 다른 종류주식으로 전환할 수 있다고 정할 수 있게 한다.","c":"상","v":1},"세무사2024_61-45-2":{"w":"회사전환주식은 이사회가 전환할 주식과 2주 이상의 주권제출기간 등을 통지하고(상법 제346조 제3항) 그 주권제출기간이 끝난 때 전환의 효력이 생긴다(제350조 제1항).","c":"상","v":1},"세무사2024_61-45-3":{"w":"상법 제350조 제2항은 주주명부 폐쇄기간 중 전환된 주식의 주주가 그 기간 중 총회 결의에서 의결권을 행사할 수 없다고 정한다.","c":"상","v":1},"세무사2024_61-45-4":{"w":"상법 제347조 제4호는 전환주식 발행 시 주식청약서나 신주인수권증서에 전환청구기간 또는 전환의 기간을 적도록 정한다.","c":"상","v":1},"세무사2024_61-47-3":{"w":"상환 대가로 현금 외에 유가증권이나 그 밖의 자산을 줄 수 있고 제외되는 것은 다른 종류주식뿐이다(상법 제345조 제4항). 모회사가 보유한 자회사 주식도 교부할 수 있고 장부가액은 배당가능이익을 넘지 못한다.","c":"상","v":1},"세무사2024_61-49-1":{"w":"회사 성립 후나 신주 납입기일 후 6개월이 지나면 주권 없이도 주식을 양도할 수 있다(상법 제335조 제3항 단서). 같은 이치로 주권 없는 주식에도 권리질의 방법으로 질권을 설정할 수 있다고 본다.","c":"중","v":1},"세무사2024_61-49-2":{"w":"상법 제339조에 따라 주식의 전환으로 종전 주주가 받을 주식에도 종전 주식에 대한 질권을 행사할 수 있다. 약식질과 등록질 모두에 적용된다.","c":"상","v":1},"세무사2024_61-49-3":{"w":"상법 제340조 제1항에 따라 등록질권자는 회사로부터 이익배당·잔여재산분배 또는 제339조의 금전을 받아 다른 채권자보다 먼저 자기 채권의 변제에 충당할 수 있다.","c":"상","v":1},"세무사2024_61-49-5":{"w":"상법 제338조 제2항은 질권자가 주권을 계속 점유하지 않으면 질권으로 제3자에게 대항하지 못하게 한다.","c":"상","v":1},"세무사2024_61-50-2":{"w":"주권 점유자는 적법한 소지인으로 추정되므로(상법 제336조 제2항) 주권을 제시하며 명의개서를 청구한 乙은 권리를 따로 증명하지 않아도 된다.","c":"상","v":1},"세무사2024_61-50-3":{"w":"주권 점유자는 적법한 소지인으로 추정되므로(상법 제336조 제2항) 주권을 제시한 양수인은 양도인의 협력 없이 단독으로 명의개서를 청구할 수 있다.","c":"상","v":1},"세무사2024_61-50-4":{"w":"회사가 정당한 이유 없이 명의개서를 거부하면 양수인은 회사를 상대로 명의개서 이행을 구하는 소를 낼 수 있다. 판례는 부당거절의 경우 명의개서 없이도 회사에 주주권을 주장할 수 있다고 본다.","c":"상","v":1},"세무사2024_61-50-5":{"w":"명의개서 전에는 양수인이 회사에 대항하지 못하므로(상법 제337조 제1항) 회사는 주주명부상 주주인 甲을 주주로 다루면 면책된다. 양도 사실을 모른 회사가 甲에게 한 주식배당은 효력이 있다.","c":"상","v":1},"세무사2024_61-52-1":{"w":"주권발행 전 주식양도는 회사에 효력이 없다(상법 제335조 제3항 본문). 회사 성립 후 6개월이 지나야 회사에 효력이 생긴다(같은 항 단서).","c":"상","v":1},"세무사2024_61-52-3":{"w":"회사 성립 후 6개월이 지나도록 주권이 발행되지 않았으면 주권 없이 한 주식양도도 회사에 효력이 있다(상법 제335조 제3항 단서). 이때 양도는 당사자의 의사표시만으로 이루어진다.","c":"상","v":1},"세무사2024_61-52-4":{"w":"적법한 소지인 추정은 주권 점유에서 나오는데(상법 제336조 제2항) 주권 없이 의사표시로 양수한 乙에게는 점유할 주권이 없으므로 추정을 받지 못한다. 乙이 자신의 권리를 증명해야 한다.","c":"상","v":1},"세무사2024_61-52-5":{"w":"판례는 성립 후 6개월 전에 한 주권발행 전 주식양도라도 그 뒤 주권이 발행되지 않은 채 6개월이 지나면 하자가 치유되어 회사에 효력이 있다고 본다(상법 제335조 제3항 단서).","c":"상","v":1},"세무사2024_61-53-1":{"w":"상법 제360조의24 제3항에 따라 지배주주가 매도청구를 하려면 미리 대상회사(C회사) 주주총회의 승인을 받아야 한다.","c":"상","v":1},"세무사2024_61-53-2":{"w":"지배주주가 매도청구를 하면 소수주주는 2개월 안에 매도해야 하고(상법 제360조의24 제6항) 매매가액 수령과 동시에 주권을 지배주주에게 교부해야 한다(같은 조 제5항 제1호).","c":"상","v":1},"세무사2024_61-53-3":{"w":"상법 제360조의26 제1항은 지배주주가 매매가액을 소수주주에게 지급한 때 주식이 이전된 것으로 본다.","c":"상","v":1},"세무사2024_61-53-4":{"w":"상법 제360조의24 제1항은 지배주주의 매도청구 요건으로 회사의 경영상 목적을 달성하기 위하여 필요한 경우를 요구한다.","c":"상","v":1},"세무사2024_61-55-1":{"w":"상법 제340조의2 제3항은 주식매수선택권 행사로 발행할 신주나 양도할 자기주식이 발행주식총수의 100분의 10을 넘지 못하게 한다.","c":"상","v":1},"세무사2024_61-55-2":{"w":"상법 제340조의3 제3항에 따라 회사는 주주총회 결의로 주식매수선택권을 부여받은 자와 계약을 체결하고 상당한 기간 안에 계약서를 작성해야 한다.","c":"상","v":1},"세무사2024_61-55-3":{"w":"상법 제340조의4 제2항 단서는 주식매수선택권을 행사할 수 있는 자가 사망하면 상속인이 행사할 수 있게 한다.","c":"상","v":1},"세무사2024_61-55-4":{"w":"상법 제340조의4 제1항에 따라 주식매수선택권은 부여 결의일부터 2년 이상 재임하거나 재직해야 행사할 수 있다.","c":"상","v":1},"세무사2024_61-71-2":{"w":"상법 제343조 제1항 본문은 주식을 자본금 감소에 관한 규정에 따라서만 소각할 수 있다고 정한다. 이사회 결의로 자기주식을 소각하는 경우는 예외다(같은 항 단서).","c":"상","v":1},"세무사2024_61-71-3":{"w":"상법 제329조의2 제1항에 따라 주식분할은 제434조의 특별결의로 한다.","c":"상","v":1},"세무사2024_61-71-4":{"w":"액면주식 1주의 금액은 정관 기재사항이므로(상법 제289조 제1항 제4호) 액면주식을 분할하면 1주의 금액이 바뀌어 정관을 변경해야 한다. 분할 결의가 특별결의(제329조의2 제1항)인 것도 이 때문이다.","c":"상","v":1},"세무사2024_61-71-5":{"w":"상법 제329조의2 제2항은 분할 후 액면주식 1주의 금액을 제329조 제3항의 100원 미만으로 하지 못하게 한다.","c":"상","v":1},"세무사2025_62-44-1":{"w":"상법 제329조 제1항 본문은 정관으로 정하면 주식 전부를 무액면주식으로 발행할 수 있게 한다.","c":"상","v":1},"세무사2025_62-44-3":{"w":"상법 제329조의2 제2항에 따라 특별결의로 주식을 분할하더라도 분할 후 액면주식 1주의 금액은 100원 이상이어야 한다.","c":"상","v":1},"세무사2025_62-44-4":{"w":"상법 제333조 제1항에 따라 여러 사람이 공동으로 주식을 인수하면 연대하여 납입해야 한다.","c":"상","v":1},"세무사2025_62-44-5":{"w":"상법 제329조 제4항은 정관으로 정하면 액면주식과 무액면주식을 서로 전환할 수 있게 한다. 이 전환으로 자본금은 바뀌지 않는다(제451조 제3항).","c":"상","v":1},"세무사2025_62-45-1":{"w":"상법 제319조에 따라 주식인수로 인한 권리(권리주)의 양도는 회사에 대하여 효력이 없다.","c":"상","v":1},"세무사2025_62-45-2":{"w":"상법 제335조의7 제1항에 따라 이사회 승인 없이 주식을 취득한 양수인도 주식의 종류와 수를 적은 서면으로 회사에 취득 승인을 청구할 수 있다.","c":"상","v":1},"세무사2025_62-45-4":{"w":"판례는 회사 성립 후 6개월 전에 한 주권발행 전 양도라도 그 뒤 주권이 발행되지 않은 채 6개월이 지나면 하자가 치유되어 회사에 효력이 있다고 본다(상법 제335조 제3항 단서).","c":"상","v":1},"세무사2025_62-45-5":{"w":"판례는 주주 사이의 양도제한 약정이 양도를 전면 금지하지 않고 사회질서에 반하지 않으면 당사자 사이에서 유효하다고 본다. 다만 회사에 대한 효력은 없다.","c":"상","v":1},"세무사2025_62-46-1":{"w":"상법 제346조 제4항은 전환으로 새로 발행할 주식 수를 전환청구기간 동안 발행하지 않고 유보하도록 정한다.","c":"상","v":1},"세무사2025_62-46-2":{"w":"상법 제349조 제1항은 전환을 청구하는 자가 청구서 2통에 주권을 첨부해 회사에 내도록 정한다.","c":"상","v":1},"세무사2025_62-46-4":{"w":"상법 제350조 제1항에 따라 주주가 전환을 청구한 경우 그 청구한 때에 전환의 효력이 생긴다.","c":"상","v":1},"세무사2025_62-46-5":{"w":"상법 제350조 제2항은 주주명부 폐쇄기간 중 전환된 주식의 주주가 그 기간 중 총회 결의에서 의결권을 행사할 수 없다고 정한다.","c":"상","v":1},"세무사2025_62-47-4":{"w":"주주와 회사채권자는 전자주주명부 기록사항의 열람·복사를 청구할 수 있고 이때 회사는 다른 주주의 전자우편주소를 대상에서 빼야 한다(상법 시행령 제11조 제2항).","c":"상","v":1},"세무사2025_62-48-2":{"w":"주권은 대표이사가 기명날인 또는 서명해야 하므로(상법 제356조) 대표권 없는 전무이사가 권한 없이 자기 명의로 발행한 주권은 무효다.","c":"상","v":1},"세무사2025_62-48-3":{"w":"주권 발행은 대표이사의 업무집행이어서 주주총회나 이사회 결의가 필요 없다. 판례는 주주 이름과 발행연월일처럼 본질적이지 않은 기재가 빠져도 주권이 무효가 되지 않는다고 본다.","c":"중","v":1},"세무사2025_62-48-4":{"w":"상법 제356조의2 제2항에 따라 전자등록부에 등록된 주식의 양도나 입질은 전자등록부에 등록해야 효력이 생긴다.","c":"상","v":1},"세무사2025_62-48-5":{"w":"상법 제356조 제6호의2는 주식 양도에 이사회 승인을 얻도록 정한 규정을 주권 기재사항으로 정한다.","c":"상","v":1},"세무사2025_62-50-1":{"w":"발행주식총수(의결권 없는 주식 제외)의 100분의 10 이상을 가진 주주와 그 배우자·직계존비속에게는 주식매수선택권을 부여할 수 없다(상법 제340조의2 제2항 제1호·제3호).","c":"상","v":1},"세무사2025_62-50-3":{"w":"상법 제340조의3 제1항 제5호에 따라 일정한 경우 이사회 결의로 부여를 취소할 수 있다는 뜻은 정관에 적어야 한다.","c":"상","v":1},"세무사2025_62-50-4":{"w":"상법 제340조의4 제2항 본문이 주식매수선택권의 양도를 금지한다.","c":"상","v":1},"세무사2025_62-50-5":{"w":"상법 제340조의4 제1항에 따라 주식매수선택권은 부여 결의일부터 2년 이상 재임·재직해야 행사할 수 있다.","c":"상","v":1},"세무사2025_62-52-2":{"w":"상법 제344조 제3항이 종류주식 발행 회사가 정관에 정함이 없어도 신주인수, 주식의 병합·분할·소각, 합병·분할로 인한 배정에서 종류별로 특수하게 정할 수 있게 한다.","c":"상","v":1},"세무사2025_62-52-3":{"w":"주식청약서에는 제289조 제1항과 제290조의 사항 외에 제291조의 사항(종류주식의 종류와 수 등)을 적어야 한다(상법 제302조 제2항 제2호·제5호). 정관의 종류주식 규정도 여기에 들어간다.","c":"중","v":1},"세무사2025_62-52-4":{"w":"상법 제344조의3 제2항 전단은 의결권 없는 종류주식과 의결권이 제한되는 종류주식의 총수가 발행주식총수의 4분의 1을 넘지 못하게 한다.","c":"상","v":1},"세무사2025_62-52-5":{"w":"상환주식은 회사의 이익으로 소각하므로(상법 제345조 제1항) 상환해도 자본금은 줄지 않는다. 이 경우 자본금이 발행주식 액면총액과 일치하지 않게 된다.","c":"상","v":1},"세무사2026_63-50-2":{"w":"상법 제344조 제1항에 따라 회사는 정관으로 이익배당·잔여재산분배·의결권·상환·전환 등에 관하여 내용이 다른 종류주식의 발행을 정할 수 있다.","c":"상","v":1},"세무사2026_63-50-3":{"w":"상법 제467조 제1항에 따라 업무집행에 부정행위나 법령·정관 위반의 중대한 사실을 의심할 사유가 있으면 발행주식총수 100분의 3 이상을 가진 주주가 법원에 검사인 선임을 청구할 수 있다.","c":"상","v":1},"세무사2026_63-50-4":{"w":"상법 제338조 제2항에 따라 질권자는 주권을 계속 점유하지 않으면 질권으로 제3자에게 대항하지 못한다.","c":"상","v":1},"세무사2026_63-50-5":{"w":"주권불소지 신고로 제출된 주권은 회사가 무효로 하거나 명의개서대리인에게 임치한다(상법 제358조의2 제3항). 무효가 된 주권은 유가증권이 아니어서 선의취득의 대상이 되지 않는다.","c":"상","v":1},"세무사2026_63-54-1":{"w":"주주 사이의 양도제한 약정은 당사자 사이의 채권적 효력만 있어 회사에 그 효력을 주장할 수 없다. 판례는 양도를 전면 금지하는 약정은 당사자 사이에서도 무효로 본다.","c":"상","v":1},"세무사2026_63-54-2":{"w":"신주발행에도 권리주 양도 제한(상법 제319조)이 준용되므로(제425조 제1항) 납입기일까지 신주인수로 인한 권리의 양도는 회사에 효력이 없다.","c":"상","v":1},"세무사2026_63-54-3":{"w":"상법 제335조 제3항 단서에 따라 회사 성립 후 6개월이 지나도 주권이 발행되지 않으면 주권 없이 한 주식양도도 회사에 효력이 있다.","c":"상","v":1},"세무사2026_63-54-5":{"w":"주권 교부로 주식을 양수한 丙은 적법한 소지인으로 추정되므로(상법 제336조) 양도인의 협력 없이 주권을 제시해 단독으로 명의개서를 청구할 수 있다.","c":"상","v":1},"세무사2026_63-57-4":{"w":"상법 제350조 제2항에 따라 주주명부 폐쇄기간 중 전환된 주식의 주주는 그 기간 중 총회 결의에서 의결권을 행사할 수 없고 주식매수선택권에 관한 결의도 마찬가지다.","c":"상","v":1},"세무사2026_63-59-5":{"w":"지정된 상대방의 매도청구에서 매도가액은 협의로 정하고(상법 제335조의5 제1항) 청구를 받은 날부터 30일 안에 협의가 안 되면 제374조의2 제4항을 준용해 법원에 가액 결정을 청구할 수 있다(제335조의5 제2항).","c":"상","v":1},"세무사2026_63-63-1":{"w":"상법 제356조의2 제3항 전단은 전자등록부에 주식을 등록한 자를 적법한 권리 보유자로 추정한다.","c":"상","v":1},"세무사2026_63-64-1":{"w":"상환주식은 회사의 이익으로 소각하므로(상법 제345조 제1항) 자본금감소 절차를 밟지 않는다.","c":"상","v":1},"세무사2026_63-64-3":{"w":"상법 제339조는 주식의 병합으로 종전 주주가 받을 금전이나 주식에 대하여도 종전 주식에 대한 질권을 행사할 수 있게 한다. 약식질권자도 포함된다.","c":"상","v":1},"세무사2026_63-64-4":{"w":"상법 제340조 제1항에 따라 등록질권자는 회사로부터 이익배당 금전을 받아 다른 채권자보다 먼저 변제에 충당할 수 있다.","c":"상","v":1},"세무사2026_63-64-5":{"w":"상법 제337조 제1항은 주식 이전을 취득자의 성명과 주소를 주주명부에 적지 않으면 회사에 대항하지 못한다고 정한다.","c":"상","v":1},"세무사2026_63-68-1":{"w":"주주평등의 원칙에 따라 주주는 회사와의 법률관계에서 가진 주식 수에 비례하여 평등하게 취급받는다. 판례는 특정 주주에게만 손실보전 등을 약정하면 이 원칙에 어긋나 무효로 본다.","c":"상","v":1},"세무사2026_63-68-2":{"w":"상법 제333조 제1항은 공동으로 주식을 인수한 자에게 연대 납입책임을 지운다.","c":"상","v":1},"세무사2026_63-68-4":{"w":"상법 제345조 제4항 본문은 상환주식 취득 대가로 현금 외에 다른 종류주식을 뺀 유가증권이나 그 밖의 자산을 교부할 수 있게 한다.","c":"상","v":1},"세무사2026_63-68-5":{"w":"주권불소지 신고는 정관에 다른 정함이 있으면 할 수 없다(상법 제358조의2 제1항).","c":"상","v":1},"세무사2026_63-69-1":{"w":"상법 제352조의2 제2항은 전자주주명부에 제352조 제1항의 기재사항 외에 전자우편주소를 적도록 한다.","c":"상","v":1},"세무사2026_63-69-2":{"w":"상법 제353조 제1항은 주주 또는 질권자에 대한 통지·최고를 주주명부의 주소나 그가 회사에 통지한 주소로 하면 된다고 정한다.","c":"상","v":1},"세무사2026_63-69-4":{"w":"상법 제352조 제2항은 전환주식을 발행하면 제347조의 사항(전환할 수 있다는 뜻, 전환조건, 발행할 주식의 내용, 전환청구기간 또는 전환기간)도 주주명부에 적도록 한다.","c":"상","v":1},"세무사2026_63-69-5":{"w":"상법 제354조 제1항·제2항에 따라 회사는 권리를 행사할 자를 정하기 위해 3개월을 넘지 않는 기간 동안 주주명부 기재변경을 정지할 수 있다.","c":"상","v":1},"세무사2017_54-54-1":{"w":"상법 제368조 제2항 전단은 주주가 대리인으로 하여금 의결권을 행사하게 할 수 있다고 정한다. 대리인은 대리권을 증명하는 서면을 총회에 내야 한다(같은 항 후단).","c":"상","v":1},"세무사2017_54-54-2":{"w":"상법 제368조의4 제1항에 따라 회사는 정관이 아니라 이사회 결의로 전자투표를 채택할 수 있다.","c":"상","v":1},"세무사2017_54-54-4":{"w":"서면투표는 정관에 근거가 있어야 하고(상법 제368조의3 제1항) 회사는 소집통지서에 서면투표에 필요한 서면과 참고자료를 첨부해야 한다(제2항).","c":"상","v":1},"세무사2017_54-54-5":{"w":"상법 제368조의2 제1항 후단은 의결권을 불통일행사하려는 주주가 총회일 3일 전에 회사에 서면 또는 전자문서로 그 뜻과 이유를 통지하도록 정한다.","c":"상","v":1},"세무사2017_54-56-2":{"w":"소집절차나 결의방법이 법령·정관에 위반하거나 현저하게 불공정한 경우는 결의취소 사유이고 주주·이사·감사가 결의한 날부터 2개월 안에 소를 제기할 수 있다(상법 제376조 제1항).","c":"상","v":1},"세무사2017_54-56-3":{"w":"결의취소 판결에는 제190조 본문만 준용되고 소급효를 막는 단서는 준용되지 않으므로(상법 제376조 제2항) 취소판결은 대세효와 함께 소급효를 가진다.","c":"상","v":1},"세무사2017_54-56-5":{"w":"결의 내용이 법령에 위반하면 결의무효확인의 소 사유다(상법 제380조). 내용이 정관에 위반하면 취소 사유다(제376조 제1항).","c":"상","v":1},"세무사2021_58-59-1":{"w":"상법 제362조는 총회 소집을 이 법에 다른 규정이 있는 경우 외에는 이사회가 결정하도록 정한다. 소수주주 소집청구(제366조)나 감사의 소집청구(제412조의3)가 다른 규정이다.","c":"상","v":1},"세무사2021_58-59-2":{"w":"상법 제364조는 정관에 다른 정함이 없으면 총회를 본점 소재지 또는 인접한 곳에서 소집하도록 정한다.","c":"상","v":1},"세무사2021_58-59-3":{"w":"상법 제363조 제1항 단서에 따라 소집통지가 주주명부상 주소에 계속 3년간 도달하지 않으면 그 주주에게는 통지하지 않아도 된다.","c":"상","v":1},"세무사2021_58-59-4":{"w":"상법 제365조 제1항은 정기총회를 매년 1회 일정한 시기에 소집하게 하고 제2항은 연 2회 이상 결산기를 정한 회사가 매기에 총회를 소집하도록 한다.","c":"상","v":1},"세무사2021_58-62-1":{"w":"상법 제381조 제1항이 부당결의 취소·변경의 소를 정한다. 특별이해관계로 의결권을 행사하지 못한 주주가 결의가 현저하게 부당하고 의결권을 행사했으면 막을 수 있었던 경우 제기한다.","c":"상","v":1},"세무사2021_58-62-2":{"w":"부당결의 취소의 소에는 상법 제376조 제1항이 준용되어(제381조 제2항) 결의한 날부터 2개월 안에 제기해야 한다.","c":"상","v":1},"세무사2021_58-62-4":{"w":"부당결의 취소의 소에는 제376조 제2항이 준용되고 이를 통해 제190조 본문만 준용되므로(상법 제381조 제2항) 원고승소 판결은 대세효와 소급효를 가진다.","c":"상","v":1},"세무사2021_58-62-5":{"w":"부당결의 취소의 소에는 제376조 제2항을 거쳐 제191조가 준용되어(상법 제381조 제2항) 패소한 원고에게 악의 또는 중과실이 있으면 회사에 연대하여 손해를 배상한다.","c":"상","v":1},"세무사2022_59-61-1":{"w":"주주제안권은 의결권 없는 주식을 뺀 발행주식총수의 100분의 3 이상을 가진 주주만 행사하는 소수주주권이다(상법 제363조의2 제1항). 상장회사는 6개월 보유 시 1%(대규모 상장회사 0.5%)로 낮춘다(제542조의6 제2항).","c":"상","v":1},"세무사2022_59-61-2":{"w":"상법 제363조의2 제1항·제2항은 주주제안을 이사에게 서면 또는 전자문서로 하도록 정한다.","c":"상","v":1},"세무사2022_59-61-3":{"w":"상법 제363조의2 제1항에 따라 주주제안은 총회일(정기총회는 직전 연도 정기총회일에 해당하는 날)의 6주 전에 해야 한다.","c":"상","v":1},"세무사2022_59-61-5":{"w":"상법 제363조의2 제3항 후단은 주주제안을 한 자가 청구하면 총회에서 그 의안을 설명할 기회를 주도록 정한다.","c":"상","v":1},"세무사2022_59-63-5":{"w":"상법 제368조의4 제1항에 따라 회사는 이사회 결의로 전자투표를 허용할 수 있다.","c":"상","v":1},"세무사2022_59-65-1":{"w":"결의방법의 법령 위반은 결의취소 사유이고 감사도 결의한 날부터 2개월 안에 취소의 소를 낼 수 있다(상법 제376조 제1항).","c":"상","v":1},"세무사2022_59-65-2":{"w":"상법 제376조 제1항은 결의취소의 소 제소권자를 주주·이사·감사로 정한다.","c":"상","v":1},"세무사2022_59-65-4":{"w":"결의취소의 소에서 주주가 원고이면 법원은 회사의 청구로 담보제공을 명할 수 있다(상법 제377조 제1항 본문). 원고 주주가 이사나 감사이면 그렇지 않다(같은 항 단서).","c":"상","v":1},"세무사2022_59-65-5":{"w":"상법 제379조는 결의취소의 소에서 결의 내용과 회사 현황 등 사정을 참작해 취소가 부적당하면 법원이 청구를 기각할 수 있게 한다(재량기각).","c":"상","v":1},"세무사2023_60-58-1":{"w":"상법 제369조 제2항은 회사가 가진 자기주식에 의결권이 없다고 정한다.","c":"상","v":1},"세무사2023_60-58-2":{"w":"상법 제369조 제3항에 따라 회사가 다른 회사 발행주식총수의 10분의 1을 넘게 가지면 그 다른 회사가 가진 회사 주식에는 의결권이 없다(상호주).","c":"상","v":1},"세무사2023_60-58-3":{"w":"상법 제371조 제1항은 제369조 제2항의 자기주식처럼 의결권 없는 주식의 수를 발행주식총수에 넣지 않도록 정한다.","c":"상","v":1},"세무사2023_60-58-5":{"w":"상법 제368조 제3항은 총회 결의에 특별한 이해관계가 있는 자의 의결권 행사를 막는다.","c":"상","v":1},"세무사2023_60-59-4":{"w":"상법 제368조의4 제1항에 따라 회사는 이사회 결의로 주주가 총회에 나오지 않고 전자적 방법으로 의결권을 행사하게 할 수 있다.","c":"상","v":1},"세무사2024_61-54-1":{"w":"결의취소 판결에는 제190조 본문만 준용되고 단서는 준용되지 않으므로(상법 제376조 제2항) 판결은 결의 시점으로 소급하여 효력이 있다.","c":"상","v":1},"세무사2024_61-56-1":{"w":"상법 제368조 제2항 후단은 의결권 대리인이 대리권을 증명하는 서면을 총회에 제출하도록 정한다. 판례는 원본을 요구한다.","c":"상","v":1},"세무사2024_61-56-3":{"w":"상법 제368조의2 제2항에 따라 회사는 불통일행사를 거부할 수 있지만 주주가 주식의 신탁을 인수했거나 타인을 위하여 주식을 가진 경우에는 거부하지 못한다.","c":"상","v":1},"세무사2024_61-56-4":{"w":"상법 제368조의4 제4항은 같은 주식에 관하여 전자투표와 서면투표 가운데 하나만 선택하도록 정한다.","c":"상","v":1},"세무사2024_61-56-5":{"w":"상법 제368조의2 제1항 후단이 불통일행사 통지를 총회일 3일 전에 서면 또는 전자문서로 하도록 정한다.","c":"상","v":1},"세무사2024_61-62-4":{"w":"분할합병신설회사의 창립총회에는 신설합병 창립총회 규정(제527조)이 준용되고(상법 제530조의11 제1항) 제527조 제3항이 제309조를 준용하므로 결의는 출석 주식인수인 의결권 3분의 2 이상이면서 인수주식 총수의 과반수로 한다.","c":"상","v":1},"세무사2025_62-54-1":{"w":"상법 제368조 제3항은 총회 결의에 특별한 이해관계가 있는 자의 의결권 행사를 막는다.","c":"상","v":1},"세무사2025_62-54-2":{"w":"상법 제368조의2 제1항 후단은 불통일행사하려는 주주가 총회일 3일 전에 서면 또는 전자문서로 그 뜻과 이유를 통지하도록 정한다.","c":"상","v":1},"세무사2025_62-54-3":{"w":"상법 제368조의4 제1항에 따라 전자투표는 이사회 결의로 채택할 수 있다.","c":"상","v":1},"세무사2025_62-54-5":{"w":"상법 제368조의3 제1항에 따라 정관이 정하면 주주는 총회에 나오지 않고 서면으로 의결권을 행사할 수 있다.","c":"상","v":1},"세무사2025_62-56-2":{"w":"상법 제376조 제1항은 결의취소의 소를 결의한 날부터 2개월 안에 제기하도록 정한다.","c":"상","v":1},"세무사2026_63-49-2":{"w":"판례는 이미 통지한 총회 소집을 철회하거나 연기할 때에도 소집과 같이 이사회 결의를 거쳐 대표이사가 소집 때와 같은 방법으로 통지해야 한다고 본다.","c":"상","v":1},"세무사2026_63-55-1":{"w":"회사가 보유한 자기주식은 의결권이 없어(상법 제369조 제2항) 결의할 때 발행주식총수에 넣지 않는다(제371조 제1항).","c":"상","v":1},"세무사2026_63-55-2":{"w":"의결권 없는 종류주식(상법 제344조의3 제1항)의 수는 총회 결의에서 발행주식총수에 넣지 않는다(제371조 제1항).","c":"상","v":1},"세무사2026_63-55-3":{"w":"특별이해관계인(상법 제368조 제3항)이 행사할 수 없는 의결권 수는 출석한 주주의 의결권 수에 넣지 않는다(제371조 제2항).","c":"상","v":1},"세무사2026_63-55-4":{"w":"3% 초과분 의결권 제한(상법 제409조 제2항)은 비상장회사 감사의 선임에만 적용되고 해임에는 적용되지 않는다. 따라서 비상장회사 감사 해임결의에서는 보유주식 전부가 출석 의결권 수에 들어간다(제371조 제2항 참조).","c":"상","v":1},"세무사2016_53-47-1":{"w":"이사회는 각 이사가 소집하되 소집권자를 정할 수 있고 그 이사가 정당한 이유 없이 소집을 거절하면 다른 이사가 소집할 수 있다(상법 제390조 제1항·제2항).","c":"상","v":1},"세무사2016_53-47-2":{"w":"상법 제391조 제1항은 이사회 결의를 이사 과반수 출석과 출석이사 과반수로 하되 정관으로 그 비율을 높일 수 있게 한다. 낮추는 것은 허용되지 않는다.","c":"상","v":1},"세무사2016_53-47-3":{"w":"상법 제391조의2 제2항은 감사가 이사의 법령·정관 위반 행위나 그 염려를 인정하면 이사회에 보고하도록 정한다.","c":"상","v":1},"세무사2016_53-47-5":{"w":"상법 제393조 제4항은 이사가 3개월에 1회 이상 업무 집행상황을 이사회에 보고하도록 정한다.","c":"상","v":1},"세무사2016_53-48-1":{"w":"공동대표이사도 수동대표는 각자 할 수 있어 제3자의 의사표시는 그중 1명에게 하면 효력이 생긴다(상법 제389조 제3항, 제208조 제2항).","c":"상","v":1},"세무사2016_53-48-2":{"w":"대표이사는 이사 중에서 선정하므로(상법 제389조 제1항) 대표이사직을 잃어도 이사 지위는 그대로 남는다. 반대로 이사 자격을 잃으면 대표이사 자격도 잃는다.","c":"상","v":1},"세무사2016_53-48-3":{"w":"대표이사에게 준용되는 제209조 제1항(상법 제389조 제3항)에 따라 대표이사는 회사의 영업에 관한 재판상·재판외의 모든 행위를 할 권한이 있다.","c":"상","v":1},"세무사2016_53-48-5":{"w":"상법 제389조 제3항이 준용하는 제210조에 따라 대표이사가 업무집행으로 타인에게 손해를 입히면 회사는 대표이사와 연대하여 배상한다.","c":"상","v":1},"세무사2016_53-49-1":{"w":"상법 제397조의2 제1항은 이사가 이사회 승인 없이 직무 수행 중 알게 되거나 회사 정보를 이용한 사업기회로서 회사의 이익이 될 수 있는 것을 자기 또는 제3자의 이익을 위해 이용하지 못하게 한다. 승인은 이사 3분의 2 이상의 수로 한다.","c":"상","v":1},"세무사2016_53-49-3":{"w":"상법 제382조의4는 이사가 재임 중뿐 아니라 퇴임 후에도 직무상 알게 된 회사의 영업상 비밀을 누설하지 못하게 한다.","c":"상","v":1},"세무사2016_53-49-4":{"w":"상법 제398조에 따라 이사 등이 자기 또는 제3자의 계산으로 회사와 거래하려면 미리 이사회에서 중요사실을 밝히고 승인을 받아야 한다. 승인은 이사 3분의 2 이상의 수로 하고 거래 내용과 절차가 공정해야 한다.","c":"상","v":1},"세무사2016_53-49-5":{"w":"상법 제397조의2 제2항은 사업기회 유용 금지를 위반해 회사에 손해를 입힌 이사와 승인한 이사에게 연대배상책임을 지우고 이사나 제3자가 얻은 이익을 손해로 추정한다.","c":"상","v":1},"세무사2016_53-50-1":{"w":"상법 제408조의2 제1항 후단은 집행임원을 둔 회사는 대표이사를 두지 못한다고 정한다.","c":"상","v":1},"세무사2016_53-50-2":{"w":"상법 제408조의2 제3항 제1호에 따라 집행임원 설치회사의 이사회는 집행임원과 대표집행임원을 선임·해임한다.","c":"상","v":1},"세무사2016_53-50-3":{"w":"상법 제408조의3 제1항은 정관에 다른 규정이 없으면 집행임원의 임기를 2년을 넘지 못하게 한다.","c":"상","v":1},"세무사2016_53-50-4":{"w":"상법 제408조의2 제4항 후단은 집행임원 설치회사에서 정관에 규정이 없으면 이사회 결의로 이사회 의장을 선임하도록 정한다.","c":"상","v":1},"세무사2017_54-55-1":{"w":"상법 제393조 제3항은 이사가 대표이사에게 다른 이사나 피용자의 업무에 관하여 이사회에 보고하도록 요구할 수 있게 한다.","c":"상","v":1},"세무사2017_54-55-2":{"w":"상법 제391조 제1항은 이사회 결의를 이사 과반수 출석과 출석이사 과반수로 하되 정관으로 비율을 높일 수 있게 한다.","c":"상","v":1},"세무사2017_54-55-3":{"w":"상법 제391조 제2항에 따라 정관에 다른 정함이 없으면 이사회는 음성을 동시에 송수신하는 원격통신수단으로 결의에 참가하게 할 수 있고 그 이사는 출석한 것으로 본다.","c":"상","v":1},"세무사2017_54-55-4":{"w":"상법 제393조 제4항이 이사에게 3개월에 1회 이상 업무 집행상황을 이사회에 보고하게 한다.","c":"상","v":1},"세무사2017_54-58-2":{"w":"상법 제408조 제1항은 직무대행자가 가처분명령에 다른 정함이 없으면 회사의 상무에 속하지 않는 행위를 하지 못하되 법원 허가를 얻으면 할 수 있다고 정한다.","c":"상","v":1},"세무사2017_54-58-3":{"w":"판례는 정기총회 소집 자체는 상무에 속하더라도 그 안건에 이사회 구성을 바꾸는 등 경영·지배에 영향을 줄 수 있는 것이 들어 있으면 그 범위에서 상무에 속하지 않는다고 본다(상법 제408조 제1항).","c":"상","v":1},"세무사2017_54-58-4":{"w":"상법 제407조 제2항은 법원이 당사자의 신청으로 직무집행정지 가처분을 변경하거나 취소할 수 있게 한다.","c":"상","v":1},"세무사2017_54-58-5":{"w":"상법 제407조 제1항에 따라 이사선임결의 무효·취소의 소나 이사해임의 소가 제기되면 법원은 당사자 신청으로 직무집행정지나 직무대행자 선임 가처분을 할 수 있다.","c":"상","v":1},"세무사2017_54-61-1":{"w":"자산총액 2조원 이상 상장회사는 후보추천위원회를 설치해야 한다(상법 제542조의8 제4항, 시행령 제34조). 2025.7.22 개정(2026.7.23 시행) 뒤 법문의 이름은 독립이사 후보추천위원회이고 독립이사가 위원 과반수여야 한다.","c":"중","v":1},"세무사2017_54-61-2":{"w":"상법 제415조의2 제2항은 감사위원회를 3명 이상의 이사로 구성하고 사외이사가 위원의 3분의 2 이상이 되도록 정한다.","c":"상","v":1},"세무사2017_54-61-3":{"w":"자산총액 2조원 이상 상장회사는 감사위원회 설치가 의무이고(상법 제542조의11 제1항) 이 회사의 감사위원 선임·해임 권한은 이사회가 아니라 주주총회에 있다(제542조의12 제1항).","c":"상","v":1},"세무사2017_54-61-4":{"w":"상법 제393조의2 제2항 제2호는 대표이사의 선임·해임을 위원회에 위임할 수 없는 사항으로 정한다.","c":"상","v":1},"세무사2017_54-62-1":{"w":"대표이사는 이사회 결의로 선정하되 정관으로 주주총회에서 선정하게 할 수 있고(상법 제389조 제1항) 여러 대표이사가 공동으로 대표하도록 정할 수도 있다(제2항).","c":"상","v":1},"세무사2017_54-62-2":{"w":"상법 제395조(표현대표이사)에 따라 사장·부사장·전무·상무 등 대표권이 있는 것으로 인정될 명칭을 쓴 이사의 행위에 대하여 회사는 대표권이 없더라도 선의의 제3자에게 책임을 진다. 판례는 제3자에게 중과실이 없을 것도 요구한다.","c":"상","v":1},"세무사2017_54-62-4":{"w":"상법 제394조 제1항에 따라 회사가 이사(대표이사 포함)와 소송을 할 때에는 감사가 회사를 대표한다.","c":"상","v":1},"세무사2017_54-62-5":{"w":"대표이사에게는 제210조가 준용되어(상법 제389조 제3항) 대표이사가 업무집행으로 타인에게 손해를 입히면 회사가 대표이사와 연대하여 배상한다.","c":"상","v":1},"세무사2017_54-64-2":{"w":"정관으로 이사의 회사에 대한 책임을 최근 1년 보수의 6배(사외·독립이사 3배)를 넘는 부분에서 면제할 수 있지만 고의·중과실이나 경업(제397조)·사업기회 유용(제397조의2)·자기거래(제398조)에는 적용되지 않는다(상법 제400조 제2항 단서).","c":"상","v":1},"세무사2017_54-65-4":{"w":"상법 제401조의2 제1항 제1호에 따라 회사에 대한 영향력을 이용해 이사에게 업무집행을 지시한 자는 그 업무에 관한 회사·제3자에 대한 책임(제399조, 제401조)과 대표소송(제403조)에서 이사로 본다.","c":"상","v":1},"세무사2017_54-66-1":{"w":"준법지원인을 두어야 하는 상장회사는 최근 사업연도 말 자산총액 5천억원 이상인 회사이고 다른 법률에 따라 내부통제기준과 준법감시인을 두어야 하는 회사는 빠진다(상법 제542조의13 제1항·제2항, 시행령 제39조).","c":"상","v":1},"세무사2017_54-66-2":{"w":"상법 제542조의13 제4항은 준법지원인을 임면하려면 이사회 결의를 거치도록 정한다.","c":"상","v":1},"세무사2017_54-66-4":{"w":"상법 제542조의13 제8항은 준법지원인이 재임 중은 물론 퇴임 후에도 직무상 알게 된 영업상 비밀을 누설하지 못하게 한다.","c":"상","v":1},"세무사2017_54-66-5":{"w":"준법지원인은 상근이고 임기는 3년이며(상법 제542조의13 제6항) 회사는 준법지원인이 직무를 독립적으로 수행할 수 있게 해야 한다(제9항).","c":"상","v":1},"세무사2021_58-58-1":{"w":"상법 제382조의2 제1항은 의결권 없는 주식을 뺀 발행주식총수의 100분의 3 이상을 가진 주주가 정관에 달리 정함이 없으면 집중투표를 청구할 수 있게 한다.","c":"상","v":1},"세무사2021_58-58-2":{"w":"상법 제382조의2 제2항은 집중투표 청구를 총회일 7일 전까지 서면 또는 전자문서로 하도록 정한다. 상장회사 특례는 6주 전이다(제542조의7 제1항).","c":"상","v":1},"세무사2021_58-58-4":{"w":"상법 제382조의2 제3항에 따라 집중투표에서 각 주주는 1주마다 선임할 이사 수만큼 의결권을 가지고 이를 후보자 1명이나 여러 명에게 몰아서 투표할 수 있다.","c":"상","v":1},"세무사2021_58-58-5":{"w":"상법 제382조의2 제4항은 집중투표에서 최다 득표자부터 차례로 이사에 선임되도록 정한다.","c":"상","v":1},"세무사2021_58-60-4":{"w":"상법 제391조 제2항에 따라 정관에 다른 정함이 없으면 이사 전부가 출석하지 않고 원격통신수단으로 결의에 참가하는 것도 허용할 수 있다. 이 경우 직접 출석한 것으로 본다.","c":"상","v":1},"세무사2021_58-64-2":{"w":"상법 제393조의2 제3항은 이사회내 위원회를 2인 이상의 이사로 구성하도록 정한다. 감사위원회는 3명 이상이다(제415조의2 제2항).","c":"상","v":1},"세무사2021_58-64-3":{"w":"상법 제393조의2 제4항 전단은 위원회가 결의한 사항을 각 이사에게 통지하도록 정한다.","c":"상","v":1},"세무사2021_58-64-4":{"w":"상법 제393조의2 제4항 후단에 따라 이사회는 위원회의 결의사항을 다시 결의할 수 있다. 감사위원회 결의는 이사회가 다시 결의할 수 없다(제415조의2 제6항).","c":"상","v":1},"세무사2021_58-64-5":{"w":"상법 제393조의2 제1항은 이사회가 정관이 정한 바에 따라 위원회를 설치할 수 있게 한다.","c":"상","v":1},"세무사2022_59-59-1":{"w":"회사와 이사의 관계에는 민법 위임 규정이 준용되므로(상법 제382조 제2항) 이사는 민법 제681조의 선량한 관리자의 주의의무를 진다.","c":"상","v":1},"세무사2022_59-59-2":{"w":"상법 제382조의3 제1항은 이사가 법령과 정관에 따라 회사를 위하여 직무를 충실하게 수행하도록 정한다. 2025.7.22 개정으로 충실의무의 상대방에 주주가 더해졌고 총주주의 이익을 보호하고 공평하게 대우할 의무도 생겼다(같은 조 제2항).","c":"상","v":1},"세무사2022_59-59-3":{"w":"상법 제382조의4는 이사가 재임 중뿐 아니라 퇴임 후에도 직무상 알게 된 영업상 비밀을 누설하지 못하게 한다.","c":"상","v":1},"세무사2022_59-59-5":{"w":"상법 제396조 제1항은 이사가 정관과 주주총회 의사록을 본점과 지점에, 주주명부와 사채원부를 본점에 비치하도록 정한다.","c":"상","v":1},"세무사2022_59-66-1":{"w":"상법 제382조 제2항은 회사와 이사의 관계에 민법의 위임에 관한 규정을 준용한다.","c":"상","v":1},"세무사2022_59-66-3":{"w":"상법 제383조 제1항 본문은 이사를 3명 이상으로 하고 자본금 10억원 미만 회사만 1명 또는 2명으로 할 수 있게 한다.","c":"상","v":1},"세무사2022_59-66-4":{"w":"상법 제383조 제2항은 이사 임기가 3년을 넘지 못하게만 정하므로 3년 이내인 2년으로 정할 수 있다.","c":"상","v":1},"세무사2022_59-66-5":{"w":"상법 제386조 제1항에 따라 법률이나 정관의 이사 원수를 채우지 못하면 임기만료나 사임으로 퇴임한 이사는 새 이사가 취임할 때까지 이사의 권리의무가 있다.","c":"상","v":1},"세무사2022_59-67-1":{"w":"상법 제390조 제1항은 이사회를 각 이사가 소집하되 이사회 결의로 소집할 이사를 정할 수 있게 한다.","c":"상","v":1},"세무사2022_59-67-3":{"w":"상법 제391조 제1항이 이사회 결의를 이사 과반수 출석과 출석이사 과반수로 하되 정관으로 비율을 높일 수 있게 한다.","c":"상","v":1},"세무사2022_59-67-4":{"w":"상법 제391조의2 제2항은 감사가 이사의 법령·정관 위반 행위나 그 염려를 인정하면 이사회에 보고하도록 정한다.","c":"상","v":1},"세무사2022_59-67-5":{"w":"상법 제393조 제1항은 중요한 자산의 처분·양도, 대규모 재산 차입, 지배인 선임·해임과 지점의 설치·이전·폐지 등 회사 업무집행을 이사회 결의로 하도록 정한다.","c":"상","v":1},"세무사2022_59-69-2":{"w":"대표이사 결원에는 제386조가 준용되어(상법 제389조 제3항) 법원은 이사·감사 등 이해관계인의 청구로 일시 대표이사의 직무를 행할 자를 선임할 수 있다(제386조 제2항).","c":"상","v":1},"세무사2022_59-70-1":{"w":"상법 제399조 제1항은 이사가 고의 또는 과실로 법령·정관에 위반한 행위를 하거나 임무를 게을리하면 회사에 연대하여 손해를 배상하도록 정한다.","c":"상","v":1},"세무사2022_59-70-2":{"w":"상법 제399조 제2항은 책임 원인이 된 행위가 이사회 결의에 의한 것이면 찬성한 이사도 연대책임을 지게 한다. 이의를 적지 않은 출석이사는 찬성한 것으로 추정한다(제3항).","c":"상","v":1},"세무사2022_59-70-3":{"w":"상법 제401조의2 제1항 제2호에 따라 이사의 이름으로 직접 업무를 집행한 자는 그 업무에 관하여 이사로 보아 제399조의 책임을 지고 책임 있는 이사와 연대한다(제2항).","c":"상","v":1},"세무사2022_59-70-5":{"w":"상법 제401조의2 제1항 제3호(표현이사)에 따라 이사가 아니면서 명예회장 등 업무집행권이 있어 보이는 명칭으로 업무를 집행한 자는 이사로 보아 제399조의 책임을 진다.","c":"상","v":1},"세무사2022_59-71-2":{"w":"상법 제408조의2 제3항 제3호는 집행임원과 회사 사이의 소송에서 회사를 대표할 자의 선임을 이사회 권한으로 정한다.","c":"상","v":1},"세무사2022_59-71-3":{"w":"집행임원 임기는 원칙적으로 2년 이내이고(상법 제408조의3 제1항) 정관으로 임기 중 최종 결산기에 관한 정기총회 종결 후 가장 먼저 소집되는 이사회 종결 시까지로 정할 수 있다(제2항).","c":"상","v":1},"세무사2022_59-71-4":{"w":"집행임원에게는 대표소송(제403조)이 준용되므로(상법 제408조의9) 소수주주는 임무를 게을리한 집행임원의 책임(제408조의8 제1항)을 대표소송으로 추궁할 수 있다.","c":"상","v":1},"세무사2022_59-71-5":{"w":"상법 제408조의2 제1항 후단에 따라 집행임원 설치회사는 대표이사를 두지 못한다.","c":"상","v":1},"세무사2023_60-55-3":{"w":"상법 제393조 제1항은 지배인의 선임·해임을 이사회 결의사항으로 정한다.","c":"상","v":1},"세무사2023_60-61-1":{"w":"상법 제397조 제1항은 이사가 이사회 승인 없이 자기나 제3자의 계산으로 회사 영업부류에 속한 거래를 하거나 동종영업 회사의 무한책임사원이나 이사가 되지 못하게 한다.","c":"상","v":1},"세무사2023_60-61-2":{"w":"상법 제397조 제2항에 따라 경업금지 위반 거래가 이사 자신의 계산이면 회사는 이사회 결의로 회사의 계산으로 한 것으로 볼 수 있다(개입권). 제3자 계산이면 이익 양도를 청구한다.","c":"상","v":1},"세무사2023_60-61-3":{"w":"상법 제397조의2 제1항 제1호는 직무 수행 중 알게 되거나 회사 정보를 이용한 사업기회를 이사회 승인 없이 자기나 제3자의 이익을 위해 이용하지 못하게 한다.","c":"상","v":1},"세무사2023_60-61-4":{"w":"상법 제398조 제2호에 따라 이사의 배우자와 직계존비속도 자기거래 규제 대상이어서 미리 이사회에 중요사실을 밝히고 승인을 받아야 한다.","c":"상","v":1},"세무사2023_60-62-1":{"w":"상법 제407조 제1항에 따라 이사해임의 소가 제기되면 법원은 신청에 따라 직무대행자를 선임할 수 있고 급박한 사정이 있으면 본안소송 제기 전에도 할 수 있다.","c":"상","v":1},"세무사2023_60-62-3":{"w":"상법 제408조의3 제1항은 정관에 다른 규정이 없으면 집행임원 임기를 2년 이내로 정하므로 정관에 규정이 있으면 2년을 넘길 수 있다.","c":"상","v":1},"세무사2023_60-62-4":{"w":"상법 제408조의6 제1항이 집행임원에게 3개월에 1회 이상 업무 집행상황을 이사회에 보고하게 한다.","c":"상","v":1},"세무사2023_60-62-5":{"w":"상법 제408조의6 제3항은 이사가 대표집행임원에게 다른 집행임원이나 피용자의 업무에 관하여 이사회에 보고하도록 요구할 수 있게 한다.","c":"상","v":1},"세무사2023_60-79-2":{"w":"자산총액 2조원 이상 상장회사는 후보추천위원회(상법 제542조의8 제4항)와 감사위원회(제542조의11 제1항)를 설치해야 한다. 2025.7.22 개정(2026.7.23 시행)으로 법문의 위원회 이름은 독립이사 후보추천위원회가 되었다.","c":"중","v":1},"세무사2023_60-79-3":{"w":"후보추천위원회는 독립이사가 총위원의 과반수가 되도록 구성한다(상법 제542조의8 제4항 후단). 독립이사는 사외이사 가운데 독립적 기능을 하는 이사이므로(같은 조 제1항) 사외이사가 과반수라는 내용도 충족된다.","c":"중","v":1},"세무사2023_60-79-4":{"w":"자산 2조원 이상 상장회사에서는 제393조의2에도 불구하고 감사위원 선임·해임 권한이 주주총회에 있다(상법 제542조의12 제1항).","c":"상","v":1},"세무사2023_60-79-5":{"w":"감사위원은 이사 중에서 선임되므로 이사로서 경업금지(상법 제397조)와 사업기회 유용금지(제397조의2) 의무를 그대로 진다.","c":"상","v":1},"세무사2024_61-58-1":{"w":"상법 제389조 제1항 단서에 따라 정관으로 주주총회에서 대표이사를 선정하게 할 수 있다.","c":"상","v":1},"세무사2024_61-58-2":{"w":"상법 제386조 제1항은 정관의 이사 원수를 채우지 못하면 임기만료로 퇴임한 이사가 새 이사 취임 때까지 이사의 권리의무를 가진다고 정한다.","c":"상","v":1},"세무사2024_61-58-4":{"w":"상법 제389조 제3항이 준용하는 제210조에 따라 회사는 대표이사의 업무집행상 불법행위에 대표이사와 연대하여 배상한다.","c":"상","v":1},"세무사2024_61-58-5":{"w":"상법 제394조 제1항에 따라 회사와 이사(대표이사 포함) 사이의 소송에서는 감사가 회사를 대표한다.","c":"상","v":1},"세무사2024_61-59-1":{"w":"상법 제408조의8 제3항에 따라 집행임원이 회사나 제3자에게 배상책임을 지고 다른 집행임원·이사·감사도 책임이 있으면 연대하여 배상한다.","c":"상","v":1},"세무사2024_61-59-2":{"w":"상법 제408조의2 제4항 전단은 집행임원 설치회사가 이사회 회의를 주관할 이사회 의장을 두도록 정한다.","c":"상","v":1},"세무사2024_61-59-4":{"w":"상법 제408조의5 제1항에 따라 집행임원이 2명 이상이면 이사회 결의로 대표집행임원을 선임해야 하고 1명이면 그가 대표집행임원이 된다.","c":"상","v":1},"세무사2024_61-59-5":{"w":"집행임원에게는 업무집행지시자 책임 규정(제401조의2)이 준용되므로(상법 제408조의9) 영향력을 이용해 집행임원에게 업무를 지시한 자는 그 업무에 관하여 집행임원으로 보아 회사에 손해배상책임을 진다.","c":"중","v":1},"세무사2024_61-61-1":{"w":"자본금 10억원 미만으로 이사가 1~2명인 회사에서는 이사회가 없어 제397조의2 제1항의 이사회를 주주총회로 본다(상법 제383조 제4항). 따라서 사업기회 이용 승인은 주주총회가 한다.","c":"상","v":1},"세무사2024_61-61-2":{"w":"상법 제408조의9가 집행임원에게 제397조의2를 준용하므로 집행임원도 이사회 승인 없이 회사의 사업기회를 자기나 제3자를 위해 이용하지 못한다.","c":"상","v":1},"세무사2024_61-61-3":{"w":"이사회 결의에도 특별이해관계인 의결권 제한(제368조 제3항)이 준용되므로(상법 제391조 제3항) 사업기회를 이용하려는 이사는 그 승인 결의에서 의결권을 행사하지 못한다.","c":"상","v":1},"세무사2024_61-61-4":{"w":"상법 제397조의2 제1항 후단은 사업기회 이용 승인을 이사 3분의 2 이상의 수로 하도록 정한다.","c":"상","v":1},"세무사2024_61-63-4":{"w":"상법 제390조 제3항은 이사회 소집 시 회일 1주 전에 각 이사와 감사에게 통지를 발송하되 정관으로 그 기간을 단축할 수 있게 한다.","c":"상","v":1},"세무사2025_62-57-1":{"w":"상법 제382조 제2항은 회사와 이사의 관계에 민법의 위임 규정을 준용한다.","c":"상","v":1},"세무사2025_62-57-2":{"w":"상법 제382조의3 제1항은 이사가 법령과 정관에 따라 회사를 위하여 직무를 충실하게 수행하도록 정한다. 2025.7.22 개정으로 충실의무 대상에 주주가 더해졌다.","c":"상","v":1},"세무사2025_62-57-3":{"w":"상법 제383조 제1항 단서는 자본금 총액 10억원 미만 회사가 이사를 1명 또는 2명으로 할 수 있게 한다.","c":"상","v":1},"세무사2025_62-57-4":{"w":"상법 제385조 제1항에 따라 이사는 언제든지 주주총회 특별결의로 해임할 수 있다. 정당한 이유 없이 임기 전에 해임하면 회사가 손해를 배상한다(같은 항 단서).","c":"상","v":1},"세무사2025_62-58-4":{"w":"상법 제390조 제4항은 이사와 감사 전원이 동의하면 소집절차 없이 언제든지 이사회를 열 수 있게 한다.","c":"상","v":1},"세무사2025_62-59-4":{"w":"판례는 대표권 범위 안의 행위는 대표이사가 자기나 제3자의 이익을 꾀하려고 권한을 남용했더라도 회사의 행위로 유효하되 상대방이 그 진의를 알았거나 알 수 있었으면 회사에 무효라고 본다(민법 제107조 제1항 단서 유추).","c":"상","v":1},"세무사2025_62-63-1":{"w":"상법 제399조 제1항에 따라 이사가 고의 또는 과실로 법령·정관에 위반한 행위를 하거나 임무를 게을리하면 회사에 연대하여 배상한다. 회사에 대한 책임은 경과실로도 생긴다.","c":"상","v":1},"세무사2025_62-63-3":{"w":"상법 제401조 제1항은 이사가 고의 또는 중대한 과실로 임무를 게을리하면 제3자에게도 연대하여 배상하도록 정한다.","c":"상","v":1},"세무사2025_62-63-4":{"w":"상법 제403조 제1항에 따라 발행주식총수 100분의 1 이상을 가진 주주는 회사에 이사의 책임을 추궁할 소의 제기를 청구할 수 있다.","c":"상","v":1},"세무사2025_62-63-5":{"w":"상법 제406조의2 제1항은 모회사 발행주식총수 100분의 1 이상을 가진 주주가 자회사에 자회사 이사의 책임 추궁 소 제기를 청구할 수 있게 한다(다중대표소송).","c":"상","v":1},"세무사2025_62-74-1":{"w":"상장회사 특례는 상장 주권을 발행한 주식회사에 적용하되 집합투자를 수행하기 위한 기구로서 대통령령으로 정하는 주식회사는 제외한다(상법 제542조의2 제1항 단서).","c":"상","v":1},"세무사2025_62-74-2":{"w":"비상장회사는 발행주식총수의 100분의 10이 한도지만 상장회사는 제340조의2 제3항에도 불구하고 100분의 20 범위에서 대통령령으로 정하는 한도까지 부여할 수 있다(상법 제542조의3 제2항).","c":"상","v":1},"세무사2025_62-74-4":{"w":"자산총액 2조원 이상 상장회사는 3명 이상이면서 이사 총수의 과반수가 되도록 해야 한다(상법 제542조의8 제1항 단서, 시행령 제34조 제2항). 2025.7.22 개정(2026.7.23 시행) 뒤 법문은 사외이사 대신 독립이사라는 말을 쓴다.","c":"중","v":1},"세무사2026_63-60-1":{"w":"대법원 전원합의체 판례는 이사 지위가 주주총회 선임결의와 피선임자의 승낙만으로 생기고 대표이사와 따로 임용계약을 맺을 필요가 없다고 본다(상법 제382조 제1항).","c":"상","v":1},"세무사2026_63-66-1":{"w":"상법 제408조의5 제1항에 따라 집행임원이 2명 이상이면 이사회가 대표집행임원을 선임하고 1명이면 그가 대표집행임원이 되므로 집행임원 설치회사에는 언제나 대표집행임원이 있다.","c":"상","v":1},"세무사2026_63-66-3":{"w":"공동대표는 상법 제389조 제2항에 따라 따로 정한 때에만 생기므로 정하지 않으면 각 대표이사가 단독으로 회사를 대표한다.","c":"상","v":1},"세무사2026_63-66-4":{"w":"공동대표이사도 수동대표는 각자 할 수 있다(상법 제389조 제3항, 제208조 제2항). 그래서 제3자의 의사표시는 1명에게 하면 효력이 생긴다.","c":"상","v":1},"세무사2026_63-66-5":{"w":"대표이사 결원에는 제386조가 준용되어(상법 제389조 제3항) 사임으로 퇴임한 대표이사는 새 대표이사나 일시대표이사가 취임할 때까지 대표이사의 권리의무가 있다.","c":"상","v":1},"세무사2026_63-74-1":{"w":"업무집행지시자는 제399조와 제406조의2를 적용할 때 이사로 보므로(상법 제401조의2 제1항) 모회사 발행주식총수 100분의 1 이상을 가진 주주는 그를 상대로 다중대표소송을 제기할 수 있다(제406조의2 제1항).","c":"상","v":1},"세무사2026_63-74-3":{"w":"상법 제401조의2 제1항은 업무집행지시자를 제399조·제401조·제403조·제406조의2를 적용할 때만 이사로 보므로 경업금지(제397조)는 적용되지 않는다.","c":"상","v":1},"세무사2026_63-74-4":{"w":"상법 제401조의2 제1항이 업무집행지시자에게 적용하는 조문은 제399조·제401조·제403조·제406조의2뿐이고 총주주 동의 면제(제400조)는 들어 있지 않다.","c":"상","v":1},"세무사2026_63-74-5":{"w":"상법 제401조의2 제1항 제1호는 회사에 대한 영향력을 이용해 이사에게 업무집행을 지시한 자라고만 정하므로 자연인뿐 아니라 법인인 지배회사도 포함된다고 보는 것이 통설이다.","c":"중","v":1},"세무사2026_63-78-1":{"w":"상법 제542조의9 제1항은 상장회사가 주요주주와 그 특수관계인, 이사·집행임원·감사를 상대방으로 하거나 그를 위하여 신용공여를 하지 못하게 한다. 복리후생 목적 대여 등은 예외다(제2항).","c":"상","v":1},"세무사2026_63-78-2":{"w":"자산 2조원 이상 상장회사에서는 제393조의2에도 불구하고 감사위원 선임·해임 권한이 주주총회에 있다(상법 제542조의12 제1항, 제542조의11 제1항).","c":"상","v":1},"세무사2026_63-78-3":{"w":"자산 2조원 이상 상장회사는 3명 이상이면서 이사 총수의 과반수가 되도록 해야 한다(상법 제542조의8 제1항 단서). 2025.7.22 개정(2026.7.23 시행) 뒤 법문은 이들을 독립이사라 부른다.","c":"중","v":1},"세무사2026_63-78-4":{"w":"자산총액 1천억원 이상 상장회사는 상근감사를 1명 이상 두어야 하고 감사위원회를 설치하면 두지 않아도 된다(상법 제542조의10 제1항, 시행령 제36조 제1항).","c":"상","v":1},"세무사2016_53-42-1":{"w":"상법 제409조 제1항은 감사를 주주총회에서 선임하도록 정한다.","c":"상","v":1},"세무사2016_53-42-2":{"w":"상법 제412조 제2항은 감사가 언제든지 이사에게 영업에 관한 보고를 요구하거나 회사의 업무와 재산상태를 조사할 수 있게 한다.","c":"상","v":1},"세무사2016_53-42-3":{"w":"상법 제409조의2는 감사가 주주총회에서 감사의 해임에 관하여 의견을 진술할 수 있다고 정한다.","c":"상","v":1},"세무사2016_53-42-5":{"w":"상법 제412조 제3항은 감사가 회사의 비용으로 전문가의 도움을 구할 수 있게 한다.","c":"상","v":1},"세무사2017_54-63-2":{"w":"상법 제467조 제1항에 따라 업무집행에 부정행위나 법령·정관 위반의 중대한 사실을 의심할 사유가 있으면 발행주식총수 100분의 3 이상을 가진 주주가 법원에 검사인 선임을 청구할 수 있다.","c":"상","v":1},"세무사2017_54-63-3":{"w":"정관과 주주총회 의사록은 본점과 지점에, 주주명부와 사채원부는 본점에 비치되고(상법 제396조 제1항) 주주와 회사채권자는 영업시간 안에 언제든지 열람·등사를 청구할 수 있다(제2항).","c":"상","v":1},"세무사2017_54-63-4":{"w":"상법 제391조의3 제3항에 따라 주주는 영업시간 안에 이사회 의사록의 열람·등사를 청구할 수 있다. 회사는 이유를 붙여 거절할 수 있고 주주는 법원 허가를 얻어 열람한다(제4항).","c":"상","v":1},"세무사2017_54-63-5":{"w":"상법 제448조 제2항은 주주와 회사채권자가 영업시간 안에 언제든지 비치된 재무제표·영업보고서·감사보고서를 열람하고 회사가 정한 비용을 내고 등본·초본을 받을 수 있게 한다.","c":"상","v":1},"세무사2021_58-57-1":{"w":"상법 제406조의2 제1항이 모회사 발행주식총수 100분의 1 이상을 가진 주주에게 자회사 이사의 책임 추궁 소 제기 청구권을 준다.","c":"상","v":1},"세무사2021_58-57-2":{"w":"다중대표소송에는 제403조 제6항이 준용되어(상법 제406조의2 제3항) 당사자는 법원 허가 없이 소 취하, 청구의 포기·인락·화해를 할 수 없다.","c":"상","v":1},"세무사2021_58-57-3":{"w":"다중대표소송에는 제405조가 준용되어(상법 제406조의2 제3항) 패소한 주주는 악의인 경우 외에는 회사에 손해배상책임을 지지 않는다(제405조 제2항).","c":"상","v":1},"세무사2021_58-57-4":{"w":"상법 제406조의2 제4항에 따라 청구 후 모회사의 자회사 지분이 100분의 50 이하로 줄어도 제소의 효력에는 영향이 없다. 지분을 전혀 갖지 않게 된 경우만 예외다.","c":"상","v":1},"세무사2021_58-66-1":{"w":"상법 제415조의2 제1항 후단은 감사위원회를 설치한 회사는 감사를 둘 수 없다고 정한다.","c":"상","v":1},"세무사2021_58-66-2":{"w":"상법 제415조의2 제2항은 감사위원회를 3명 이상의 이사로 구성하고 사외이사가 위원의 3분의 2 이상이 되도록 정한다.","c":"상","v":1},"세무사2021_58-66-4":{"w":"상법 제415조의2 제3항은 감사위원 해임에 관한 이사회 결의를 이사 총수의 3분의 2 이상으로 하도록 정한다.","c":"상","v":1},"세무사2021_58-66-5":{"w":"상법 제415조의2 제5항은 감사위원회가 회사 비용으로 전문가의 조력을 구할 수 있게 한다.","c":"상","v":1},"세무사2021_58-67-1":{"w":"상법 제409조 제4항에 따라 자본금 총액 10억원 미만 회사는 감사를 선임하지 않을 수 있다.","c":"상","v":1},"세무사2021_58-67-3":{"w":"상법 제412조의5 제1항은 모회사 감사가 직무 수행에 필요하면 자회사에 영업 보고를 요구할 수 있게 한다.","c":"상","v":1},"세무사2021_58-67-4":{"w":"상법 제411조는 감사가 회사와 자회사의 이사·지배인 그 밖의 사용인의 직무를 겸하지 못하게 한다.","c":"상","v":1},"세무사2021_58-67-5":{"w":"상법 제412조 제2항이 감사에게 언제든지 이사에게 영업 보고를 요구하고 업무와 재산상태를 조사할 권한을 준다.","c":"상","v":1},"세무사2022_59-68-3":{"w":"상법 제403조 제5항은 대표소송을 제기한 주주의 보유주식이 제소 후 발행주식총수의 100분의 1 미만으로 줄어도 제소의 효력에 영향이 없다고 정한다. 다만 주식을 전혀 보유하지 않게 되면 예외다.","c":"상","v":1},"세무사2022_59-72-3":{"w":"감사위원 선임 시 의결권 없는 주식을 뺀 발행주식총수의 100분의 3을 넘는 주식을 가진 주주는 초과분 의결권을 행사하지 못한다(상법 제542조의12 제4항). 2025.7.22 개정으로 정관에서 더 낮은 비율을 정할 수 있고 최대주주는 특수관계인 주식을 합산한다.","c":"상","v":1},"세무사2022_59-72-4":{"w":"상법 제542조의12 제6항은 상장회사의 감사나 감사위원회가 제447조의4 제1항(총회 6주 전 제출)에도 불구하고 감사보고서를 총회일 1주 전까지 이사에게 제출할 수 있게 한다.","c":"상","v":1},"세무사2022_59-72-5":{"w":"상법 제542조의12 제8항에 따라 전자투표를 허용한 회사는 제368조 제1항에도 불구하고 출석 주주 의결권 과반수로 감사위원을 선임할 수 있다(발행주식총수 4분의 1 요건 면제).","c":"상","v":1},"세무사2023_60-56-1":{"w":"상장회사에서는 6개월 전부터 계속 발행주식총수 1만분의 50 이상을 가진 주주가 다중대표소송을 위한 청구를 할 수 있다(상법 제542조의6 제7항).","c":"상","v":1},"세무사2023_60-56-2":{"w":"상법 제406조의2 제2항에 따라 자회사가 청구를 받은 날부터 30일 안에 소를 제기하지 않으면 청구한 주주는 즉시 자회사를 위하여 소를 제기할 수 있다.","c":"상","v":1},"세무사2023_60-56-3":{"w":"다중대표소송에는 제403조 제5항이 준용되어(상법 제406조의2 제3항) 제소 후 보유주식이 100분의 1 미만으로 줄어도 제소의 효력에 영향이 없다.","c":"상","v":1},"세무사2023_60-56-4":{"w":"다중대표소송에는 제404조 제2항이 준용되어(상법 제406조의2 제3항) 소를 제기한 주주는 지체 없이 자회사에 소송고지를 해야 한다.","c":"상","v":1},"세무사2023_60-63-1":{"w":"상법 제409조 제4항이 자본금 총액 10억원 미만 회사에 감사를 선임하지 않을 수 있게 한다.","c":"상","v":1},"세무사2023_60-63-2":{"w":"상법 제411조는 감사가 자회사의 이사·지배인 그 밖의 사용인을 겸하지 못하게 한다.","c":"상","v":1},"세무사2023_60-63-3":{"w":"상법 제413조는 감사가 이사가 총회에 제출할 의안과 서류를 조사하여 법령·정관 위반이나 현저하게 부당한 사항이 있는지 총회에 의견을 진술하도록 정한다.","c":"상","v":1},"세무사2023_60-63-5":{"w":"상법 제410조가 감사의 임기를 취임 후 3년 내의 최종 결산기에 관한 정기총회 종결 시까지로 정한다.","c":"상","v":1},"세무사2023_60-64-1":{"w":"상법 제415조의2 제2항은 감사위원회를 3명 이상의 이사로 구성하고 사외이사가 위원의 3분의 2 이상이 되게 한다.","c":"상","v":1},"세무사2023_60-64-3":{"w":"감사위원회에는 감사에 관한 제391조의2 제2항이 준용되어(상법 제415조의2 제7항) 이사의 정관 위반 행위나 그 염려를 인정하면 이사회에 보고해야 한다.","c":"상","v":1},"세무사2023_60-64-4":{"w":"상법 제415조의2 제3항이 감사위원 해임 이사회 결의를 이사 총수의 3분의 2 이상으로 하도록 정한다.","c":"상","v":1},"세무사2023_60-64-5":{"w":"상법 제415조의2 제4항은 감사위원회가 그 결의로 위원회를 대표할 자를 선정하도록 정한다.","c":"상","v":1},"세무사2024_61-57-4":{"w":"상법 제405조 제2항에 따라 대표소송에서 패소한 주주는 악의인 경우 외에는 회사에 손해를 배상할 책임이 없다.","c":"상","v":1},"세무사2025_62-61-1":{"w":"상법 제409조 제1항이 감사를 주주총회에서 선임하도록 정한다.","c":"상","v":1},"세무사2025_62-61-3":{"w":"상법 제409조의2는 감사가 총회에서 감사 해임에 관하여 의견을 진술할 수 있게 한다.","c":"상","v":1},"세무사2025_62-61-4":{"w":"상법 제410조에 따라 감사 임기는 취임 후 3년 내의 최종 결산기에 관한 정기총회 종결 시까지다.","c":"상","v":1},"세무사2025_62-61-5":{"w":"감사 해임에는 이사 해임 규정(제385조)이 준용되어(상법 제415조) 임기를 정한 감사를 정당한 이유 없이 임기 전에 해임하면 감사는 손해배상을 청구할 수 있다.","c":"상","v":1},"세무사2026_63-75-1":{"w":"상법 제411조는 감사가 자회사의 이사 등을 겸하지 못하게 할 뿐 모회사 이사가 자회사 감사가 되는 것은 막지 않는다. 자회사 감사가 감사하는 대상은 자회사 이사이므로 자기감사 문제가 생기지 않는다.","c":"상","v":1},"세무사2026_63-75-2":{"w":"상법 제402조는 이사의 법령·정관 위반 행위로 회사에 회복할 수 없는 손해가 생길 염려가 있으면 감사 또는 발행주식총수 100분의 1 이상을 가진 주주가 행위의 유지를 청구할 수 있게 한다.","c":"상","v":1},"세무사2026_63-75-3":{"w":"상법 제409조 제3항에 따라 전자투표를 허용한 회사는 제368조 제1항의 발행주식총수 4분의 1 요건 없이 출석 의결권 과반수로 감사를 선임할 수 있다.","c":"상","v":1},"세무사2026_63-75-4":{"w":"상법 제415조의2 제2항은 감사위원회를 3명 이상의 이사로 구성하도록 정한다.","c":"상","v":1},"세무사2016_53-59-1":{"w":"액면미달발행은 성립 후 2년이 지난 회사가 주주총회 특별결의와 법원 인가를 얻어 할 수 있고(상법 제417조 제1항) 그 결의에서 주식의 최저발행가액을 정해야 한다(제2항).","c":"상","v":1},"세무사2016_53-59-2":{"w":"상법 제420조의3 제1항은 신주인수권증서가 발행되면 신주인수권 양도를 증서 교부로만 하도록 정한다.","c":"상","v":1},"세무사2016_53-59-3":{"w":"상법 제424조의2 제1항에 따라 이사와 통모해 현저하게 불공정한 발행가액으로 주식을 인수한 자는 공정한 발행가액과의 차액을 회사에 지급해야 한다. 이 책임은 대표소송으로도 추궁할 수 있다(제2항).","c":"상","v":1},"세무사2016_53-59-4":{"w":"상법 제421조 제2항은 신주 인수인이 회사의 동의 없이 납입채무와 회사에 대한 채권을 상계하지 못하게 하므로 회사가 동의하면 상계할 수 있다.","c":"상","v":1},"세무사2016_53-60-2":{"w":"자본금 감소에는 채권자보호절차(제232조)가 준용되지만 결손 보전을 위한 감자는 회사 재산이 밖으로 나가지 않아 예외로 한다(상법 제439조 제2항 단서).","c":"상","v":1},"세무사2016_53-60-3":{"w":"상법 제439조 제3항 전단은 자본금 감소에 사채권자가 이의를 제기하려면 사채권자집회 결의가 있어야 한다고 정한다. 법원은 이해관계인 청구로 이의기간을 늘릴 수 있다(같은 항 후단).","c":"상","v":1},"세무사2016_53-60-4":{"w":"상법 제440조에 따라 주식을 병합할 때 회사는 1개월 이상의 기간을 정해 그 뜻과 기간 안에 주권을 제출하라는 것을 공고하고 주주명부의 주주와 질권자에게 각각 통지해야 한다.","c":"상","v":1},"세무사2016_53-60-5":{"w":"상법 제445조는 감자무효를 주주·이사·감사·청산인·파산관재인 또는 감자를 승인하지 않은 채권자가 변경등기일부터 6개월 안에 소로만 주장하도록 정한다.","c":"상","v":1},"세무사2016_53-64-1":{"w":"상법 제491조 제1항은 사채권자집회를 사채를 발행한 회사 또는 사채관리회사가 소집하도록 정한다.","c":"상","v":1},"세무사2016_53-64-2":{"w":"사채 총액 10분의 1 이상을 가진 사채권자는 집회 소집을 청구할 수 있지만(상법 제491조 제2항) 무기명식 채권을 가진 자는 채권을 공탁해야 이 권리를 행사할 수 있다(제4항).","c":"상","v":1},"세무사2016_53-64-3":{"w":"상법 제492조 제1항은 각 사채권자가 해당 종류 사채 금액의 합계액(상환받은 액 제외)에 따라 의결권을 가진다고 정한다.","c":"상","v":1},"세무사2016_53-64-5":{"w":"상법 제496조는 사채권자집회 소집자가 결의한 날부터 1주 안에 법원에 결의 인가를 청구하도록 정한다. 결의는 인가를 받아야 효력이 생긴다(제498조 제1항).","c":"상","v":1},"세무사2016_53-65-1":{"w":"상법 제469조 제1항에 따라 회사는 이사회 결의로 사채를 발행할 수 있다. 정관에 따라 대표이사에게 1년 이내 기간의 발행을 위임할 수도 있다(제4항).","c":"상","v":1},"세무사2016_53-65-3":{"w":"상법 제516조의2 제3항은 각 신주인수권부사채에 붙은 신주인수권 행사로 발행할 주식의 발행가액 합계가 각 사채의 금액을 넘지 못하게 한다.","c":"상","v":1},"세무사2016_53-65-4":{"w":"상법 제516조의6 제1항은 신주인수권증권이 발행되면 신주인수권 양도를 증권 교부로만 하도록 정한다.","c":"상","v":1},"세무사2016_53-65-5":{"w":"상법 제513조의2 제1항 본문에 따라 전환사채 인수권을 가진 주주는 가진 주식 수에 따라 전환사채를 배정받을 권리가 있다.","c":"상","v":1},"세무사2017_54-68-1":{"w":"상법 제418조 제1항은 주주가 가진 주식 수에 따라 신주를 배정받을 권리가 있다고 정한다. 정관에 따라 신기술 도입 등 경영상 목적이 있으면 제3자에게 배정할 수 있다(제2항).","c":"상","v":1},"세무사2017_54-68-2":{"w":"상법 제417조 제1항은 성립 후 2년이 지난 회사가 특별결의와 법원 인가를 얻어 액면미달 발행을 할 수 있게 하고 제4항은 인가일부터 1개월 안에 발행하되 법원이 이 기간을 연장할 수 있게 한다.","c":"상","v":1},"세무사2017_54-68-3":{"w":"상법 제420조의4는 신주인수권증서 발행 대신 정관에 따라 전자등록부에 신주인수권을 등록할 수 있게 한다.","c":"상","v":1},"세무사2017_54-68-4":{"w":"상법 제424조는 회사가 법령·정관에 위반하거나 현저하게 불공정한 방법으로 주식을 발행해 주주가 불이익을 받을 염려가 있으면 주주가 발행 유지를 청구할 수 있게 한다.","c":"상","v":1},"세무사2017_54-75-1":{"w":"상법 제516조의6 제1항에 따라 신주인수권증권이 발행된 경우 신주인수권 양도는 증권 교부로만 한다.","c":"상","v":1},"세무사2017_54-77-1":{"w":"회사가 발행할 주식의 총수는 정관의 절대적 기재사항이다(상법 제289조 제1항 제3호).","c":"상","v":1},"세무사2017_54-77-3":{"w":"상계 금지는 주식 납입에만 있고(상법 제421조 제2항) 사채에는 그런 규정이 없어 사채 납입은 상계로 할 수 있다.","c":"상","v":1},"세무사2017_54-77-4":{"w":"상법 제491조 제1항에 따라 사채를 발행한 회사 또는 사채관리회사가 사채권자집회를 소집한다.","c":"상","v":1},"세무사2017_54-77-5":{"w":"상법 제329조의2 제1항은 주식분할을 제434조의 특별결의로 하도록 정한다.","c":"상","v":1},"세무사2017_54-80-2":{"w":"상법 제440조가 주식병합 시 1개월 이상의 주권제출기간 공고와 주주명부상 주주·질권자에 대한 개별 통지를 요구한다.","c":"상","v":1},"세무사2017_54-80-3":{"w":"상법 제441조에 따라 주식병합은 주권제출기간이 끝난 때 효력이 생기고 채권자보호절차(제232조)가 끝나지 않았으면 그 절차가 끝난 때 효력이 생긴다.","c":"상","v":1},"세무사2017_54-80-4":{"w":"상법 제439조 제3항 전단에 따라 자본금 감소에 사채권자가 이의를 하려면 사채권자집회 결의가 있어야 한다.","c":"상","v":1},"세무사2017_54-80-5":{"w":"상법 제445조는 감자무효의 제소권자를 주주·이사·감사·청산인·파산관재인·감자 불승인 채권자로 하고 제소기간을 변경등기일부터 6개월로 정한다.","c":"상","v":1},"세무사2021_58-68-2":{"w":"상법 제418조 제1항 본문은 주주가 가진 주식 수에 따라 신주를 배정받을 권리가 있다고 정한다.","c":"상","v":1},"세무사2021_58-68-3":{"w":"상법 제421조 제2항은 회사 동의 없는 상계만 금지하므로 회사가 동의하면 납입채무와 회사에 대한 채권을 상계할 수 있다.","c":"상","v":1},"세무사2021_58-68-4":{"w":"상법 제420조의3 제1항이 신주인수권증서가 발행된 경우 신주인수권 양도를 증서 교부로만 하도록 정한다.","c":"상","v":1},"세무사2021_58-68-5":{"w":"신주인수권증서에는 주권의 점유 추정 규정(제336조 제2항)이 준용되어(상법 제420조의3 제2항) 점유자는 적법한 소지인으로 추정된다.","c":"상","v":1},"세무사2021_58-69-1":{"w":"상법 제480조의3 제2항은 사채 인수인이 그 사채의 사채관리회사가 될 수 없다고 정한다. 이해가 충돌하기 때문이다.","c":"상","v":1},"세무사2021_58-69-3":{"w":"상법 제484조 제2항에 따라 사채관리회사는 사채에 관한 채권을 변제받으면 지체 없이 공고하고 알고 있는 사채권자에게 통지해야 한다.","c":"상","v":1},"세무사2021_58-69-4":{"w":"상법 제485조 제1항은 사채관리회사가 둘 이상이면 권한에 속하는 행위를 공동으로 하도록 정한다.","c":"상","v":1},"세무사2021_58-69-5":{"w":"상법 제507조 제1항은 사채관리회사의 보수와 비용을 발행회사와의 계약에 약정이 없으면 법원 허가를 받아 발행회사가 부담하게 할 수 있다고 정한다.","c":"상","v":1},"세무사2021_58-70-1":{"w":"상법 제424조의2 제1항에 따라 이사와 통모해 현저하게 불공정한 발행가액으로 인수한 자는 공정한 가액과의 차액을 회사에 지급해야 한다.","c":"상","v":1},"세무사2021_58-70-2":{"w":"상법 제427조는 신주발행 변경등기일부터 1년이 지나면 인수인이 주식청약서나 신주인수권증서의 요건 흠결을 이유로 인수 무효를 주장하지 못하게 한다.","c":"상","v":1},"세무사2021_58-70-3":{"w":"상법 제429조는 신주발행 무효를 주주·이사·감사가 신주를 발행한 날부터 6개월 안에 소로만 주장하도록 정한다.","c":"상","v":1},"세무사2021_58-70-5":{"w":"상법 제432조 제1항은 신주발행 무효판결이 확정되면 회사가 신주의 주주에게 납입한 금액을 반환하도록 정한다.","c":"상","v":1},"세무사2021_58-71-2":{"w":"상법 제469조 제2항 제2호는 주식이나 그 밖의 유가증권으로 교환 또는 상환할 수 있는 사채를 회사가 발행할 수 있는 사채에 넣는다(교환사채·상환사채).","c":"상","v":1},"세무사2021_58-71-3":{"w":"상법 제476조 제1항은 사채 모집이 끝나면 이사가 지체 없이 인수인에게 사채 전액 또는 제1회 납입을 시키도록 정한다. 주식과 달리 분할납입이 허용된다.","c":"상","v":1},"세무사2021_58-71-4":{"w":"상법 제478조 제1항은 사채 전액 납입이 끝나기 전에는 채권을 발행하지 못하게 한다.","c":"상","v":1},"세무사2021_58-71-5":{"w":"사채권자는 기명식과 무기명식 사이의 전환을 청구할 수 있지만 채권을 기명식 또는 무기명식에 한하기로 정했으면 그렇지 않다(상법 제480조 단서).","c":"상","v":1},"세무사2021_58-72-3":{"w":"감자무효의 소에는 제190조 본문만 준용되고 단서는 준용되지 않아(상법 제446조) 판결은 대세효와 소급효를 가진다.","c":"상","v":1},"세무사2022_59-73-1":{"w":"상법 제417조 제1항은 성립 후 2년이 지난 회사가 주주총회 특별결의와 법원 인가로 액면미달 발행을 할 수 있게 한다.","c":"상","v":1},"세무사2022_59-73-2":{"w":"상법 제420조 제4호에 따라 액면미달 발행을 한 경우 이사는 주식청약서에 그 발행조건과 미상각액을 적어야 한다.","c":"상","v":1},"세무사2022_59-73-3":{"w":"전자등록한 신주인수권에는 제356조의2 제2항~제4항이 준용되어(상법 제420조의4 후단) 등록한 자는 등록된 신주인수권을 적법하게 보유한 것으로 추정된다.","c":"상","v":1},"세무사2022_59-73-5":{"w":"상법 제428조 제1항은 신주발행 변경등기 후 인수되지 않았거나 청약이 취소된 주식을 이사가 공동으로 인수한 것으로 본다(이사의 인수담보책임).","c":"상","v":1},"세무사2022_59-74-1":{"w":"상법 제474조 제2항 제2호는 이사가 작성하는 사채청약서에 자본금과 준비금의 총액을 적도록 정한다.","c":"상","v":1},"세무사2022_59-74-2":{"w":"상법 제479조 제1항은 기명사채 이전을 취득자의 성명과 주소를 사채원부에 적고 성명을 채권에 적지 않으면 회사와 그 밖의 제3자에게 대항하지 못하게 한다.","c":"상","v":1},"세무사2022_59-74-4":{"w":"상법 제486조 제1항에 따라 이권 있는 무기명사채를 상환할 때 이권이 빠져 있으면 그 이권에 상당하는 금액을 상환액에서 공제한다.","c":"상","v":1},"세무사2022_59-74-5":{"w":"상법 제487조 제1항은 사채 상환청구권의 소멸시효를 10년으로 정한다. 이자청구권은 5년이다(제3항).","c":"상","v":1},"세무사2022_59-75-4":{"w":"상법 제516조의8 제1항은 신주인수권부사채를 발행하면 각 사채의 금액과 납입금액 등을 등기하도록 정한다.","c":"상","v":1},"세무사2022_59-76-1":{"w":"상법 제445조는 자본금 감소를 승인하지 않은 채권자를 감자무효의 소 제소권자에 넣는다.","c":"상","v":1},"세무사2022_59-76-2":{"w":"감자무효의 소는 회사법상 형성의 소로서 판결 효력이 회사를 중심으로 생기므로 회사를 피고로 한다는 것이 판례·통설이다.","c":"중","v":1},"세무사2022_59-76-3":{"w":"감자무효의 소는 감자 변경등기일부터 6개월 안에 제기하므로(상법 제445조) 감자의 효력이 생기기 전, 곧 주식병합의 주권제출기간이 끝나기 전(제441조)에는 소를 제기할 수 없다.","c":"중","v":1},"세무사2022_59-76-4":{"w":"감자무효 판결에는 제190조 본문이 준용되어(상법 제446조) 제3자에게도 효력이 미친다. 그래서 소를 제기하지 않은 사람도 감자의 무효를 주장할 수 있다.","c":"상","v":1},"세무사2023_60-65-1":{"w":"상법 제420조의4가 신주인수권증서 대신 정관에 따라 신주인수권을 전자등록할 수 있게 한다.","c":"상","v":1},"세무사2023_60-65-2":{"w":"상법 제420조의3 제1항에 따라 신주인수권증서가 발행되면 신주인수권은 증서 교부로만 양도한다.","c":"상","v":1},"세무사2023_60-65-3":{"w":"상법 제423조 제1항은 신주 인수인이 납입이나 현물출자 이행을 하면 납입기일 다음 날부터 주주의 권리의무를 가진다고 정한다.","c":"상","v":1},"세무사2023_60-65-5":{"w":"상법 제429조는 신주발행 무효를 주주·이사·감사가 신주를 발행한 날부터 6개월 안에 소로만 주장하도록 정한다.","c":"상","v":1},"세무사2023_60-66-5":{"w":"상법 제417조 제4항은 액면미달 주식을 법원 인가일부터 1개월 안에 발행하되 법원이 그 기간을 연장해 인가할 수 있게 한다.","c":"상","v":1},"세무사2023_60-69-1":{"w":"상법 제509조는 여러 종류의 사채를 발행한 경우 사채권자집회를 종류별로 소집하도록 정한다.","c":"상","v":1},"세무사2023_60-69-3":{"w":"상법 제498조 제2항은 사채권자집회 결의가 그 종류의 사채를 가진 모든 사채권자에게 효력이 있다고 정한다.","c":"상","v":1},"세무사2023_60-69-4":{"w":"상법 제492조 제1항에 따라 각 사채권자는 해당 종류 사채 금액의 합계액(상환받은 액 제외)에 따라 의결권을 가진다.","c":"상","v":1},"세무사2023_60-69-5":{"w":"상법 제495조 제3항은 사채권자집회에 출석하지 않은 사채권자가 서면으로 의결권을 행사할 수 있게 한다.","c":"상","v":1},"세무사2023_60-70-1":{"w":"주주 외의 자에게 발행하는 경우 전환사채는 상법 제513조 제3항, 신주인수권부사채는 제516조의2 제4항에 따라 발행할 사채의 액 등 주요 사항을 정관에 규정이 없으면 특별결의로 정해야 한다.","c":"상","v":1},"세무사2024_61-74-1":{"w":"상법 제424조는 법령·정관 위반이나 현저하게 불공정한 방법의 주식발행으로 불이익을 받을 염려가 있는 주주에게 신주발행 유지청구권을 준다.","c":"상","v":1},"세무사2024_61-74-2":{"w":"상법 제424조의2 제1항이 이사와 통모해 현저하게 불공정한 발행가액으로 인수한 자에게 공정한 가액과의 차액 지급의무를 지운다.","c":"상","v":1},"세무사2024_61-74-3":{"w":"상법 제427조에 따라 변경등기일부터 1년이 지나면 신주 인수인은 주식청약서 요건 흠결을 이유로 인수 무효를 주장하지 못한다.","c":"상","v":1},"세무사2024_61-74-5":{"w":"상법 제432조 제1항에 따라 신주발행 무효판결이 확정되면 회사는 신주의 주주에게 납입한 금액을 돌려줘야 한다. 신주는 장래에 대하여만 효력을 잃는다(제431조 제1항).","c":"상","v":1},"세무사2024_61-76-1":{"w":"주주는 가진 주식 수에 따라 신주를 배정받을 권리, 곧 신주인수권을 가진다(상법 제418조 제1항). 그래서 다른 사람보다 먼저 신주를 인수할 수 있다.","c":"상","v":1},"세무사2024_61-76-2":{"w":"상법 제418조 제2항은 정관에 따라 주주 외의 자에게 신주를 배정하되 신기술 도입·재무구조 개선 등 경영상 목적 달성에 필요한 경우로 한정한다.","c":"상","v":1},"세무사2024_61-76-4":{"w":"신주인수권의 양도에 관한 사항은 정관이나 이사회가 정하고(상법 제416조 제5호) 이를 정한 경우 주주는 신주인수권증서로 양도할 수 있다(제420조의3). 판례는 정함이 없어도 회사가 승낙한 양도는 회사에 효력이 있다고 본다.","c":"상","v":1},"세무사2024_61-76-5":{"w":"상법 제420조의4에 따라 회사는 신주인수권증서 대신 정관에 따라 신주인수권을 전자등록부에 등록할 수 있다.","c":"상","v":1},"세무사2024_61-77-1":{"w":"상법 제480조의2는 회사가 사채를 발행할 때 사채관리회사를 정해 변제 수령, 채권 보전 등 사채 관리를 위탁할 수 있게 한다.","c":"상","v":1},"세무사2024_61-77-2":{"w":"상법 제480조의3 제2항은 사채 인수인이 그 사채의 사채관리회사가 될 수 없다고 정한다.","c":"상","v":1},"세무사2024_61-77-3":{"w":"상법 제481조 전단은 사채관리회사가 발행회사와 사채권자집회의 동의를 받아 사임할 수 있게 한다. 부득이한 사유로 법원 허가를 받아도 된다(후단).","c":"상","v":1},"세무사2024_61-77-4":{"w":"상법 제482조는 사채관리회사가 적임이 아니거나 정당한 사유가 있으면 법원이 발행회사나 사채권자집회의 청구로 해임할 수 있게 한다.","c":"상","v":1},"세무사2024_61-78-2":{"w":"상법 제516조의2 제4항은 주주 외의 자에게 신주인수권부사채를 발행할 때 사채 액, 신주인수권의 내용, 행사기간을 정관에 규정이 없으면 특별결의로 정하도록 한다.","c":"상","v":1},"세무사2024_61-78-3":{"w":"상법 제516조의6 제1항에 따라 신주인수권증권이 발행되면 신주인수권은 증권 교부로만 양도한다.","c":"상","v":1},"세무사2024_61-78-4":{"w":"신주인수권을 행사하려면 청구서와 함께 발행가액 전액을 납입해야 하고(상법 제516조의9 제1항) 그 납입을 한 때 주주가 된다(제516조의10).","c":"상","v":1},"세무사2024_61-78-5":{"w":"신주인수권부사채 등기에는 전환사채 등기 규정(제514조의2 제1항)이 준용되어(상법 제516조의8 제2항) 사채 납입이 완료된 날부터 2주 안에 본점 소재지에서 등기한다.","c":"상","v":1},"세무사2025_62-64-1":{"w":"상법 제417조 제1항이 성립 후 2년이 지난 회사에 주주총회 특별결의와 법원 인가로 액면미달 발행을 허용한다.","c":"상","v":1},"세무사2025_62-64-2":{"w":"상법 제417조 제2항은 액면미달 발행 결의에서 최저발행가액을 정하도록 한다.","c":"상","v":1},"세무사2025_62-64-3":{"w":"상법 제417조 제3항 전단에 따라 법원은 회사 현황과 사정을 참작해 최저발행가액을 변경해 인가할 수 있다.","c":"상","v":1},"세무사2025_62-64-4":{"w":"상법 제417조 제3항 후단은 법원이 회사 재산상태 등을 조사하게 하려고 검사인을 선임할 수 있게 한다.","c":"상","v":1},"세무사2025_62-65-1":{"w":"상법 제418조 제1항이 주주에게 가진 주식 수에 따라 신주를 배정받을 권리를 준다. 제3자 배정은 정관과 경영상 목적이 있어야 하는 예외다(제2항).","c":"상","v":1},"세무사2025_62-65-2":{"w":"상법 제420조의3 제1항에 따라 신주인수권증서가 발행되면 신주인수권은 증서 교부로만 양도한다.","c":"상","v":1},"세무사2025_62-65-4":{"w":"상법 제420조의5 제1항 전단은 신주인수권증서를 발행한 경우 그 증서로 주식 청약을 하도록 정한다.","c":"상","v":1},"세무사2025_62-65-5":{"w":"상법 제420조의5 제2항에 따라 증서를 잃은 자는 주식청약서로 청약할 수 있다. 다만 증서에 의한 청약이 있으면 그 청약은 효력을 잃는다.","c":"상","v":1},"세무사2025_62-66-3":{"w":"상법 제424조에 따라 정관 위반의 주식발행으로 불이익을 받을 염려가 있는 주주는 회사에 발행 유지를 청구할 수 있다.","c":"상","v":1},"세무사2025_62-67-1":{"w":"상법 제439조 제1항은 자본금 감소 결의에서 감소의 방법을 정하도록 한다.","c":"상","v":1},"세무사2025_62-67-2":{"w":"상법 제439조 제3항 전단에 따라 사채권자가 감자에 이의를 하려면 사채권자집회 결의가 있어야 한다.","c":"상","v":1},"세무사2025_62-67-3":{"w":"상법 제439조 제3항 후단은 법원이 이해관계인 청구로 사채권자를 위해 이의기간을 연장할 수 있게 한다.","c":"상","v":1},"세무사2025_62-67-5":{"w":"상법 제445조가 감자무효를 주주·이사·감사·청산인·파산관재인·감자 불승인 채권자가 변경등기일부터 6개월 안에 소로만 주장하도록 정한다.","c":"상","v":1},"세무사2025_62-70-1":{"w":"상법 제482조는 사채관리회사가 적임이 아니거나 그 밖에 정당한 사유가 있으면 법원이 발행회사 또는 사채권자집회의 청구로 해임할 수 있게 한다.","c":"상","v":1},"세무사2026_63-51-1":{"w":"상법 제418조 제1항은 주주가 가진 주식 수에 따라 신주를 배정받을 권리가 있다고 정한다.","c":"상","v":1},"세무사2026_63-51-3":{"w":"상법 제418조 제3항 본문에 따라 회사는 배정기준일을 정해 그날 주주명부의 주주가 신주인수권을 가진다는 뜻을 2주 전에 공고해야 한다. 그날이 주주명부 폐쇄기간 중이면 그 기간 초일의 2주 전에 공고한다(단서).","c":"상","v":1},"세무사2026_63-51-4":{"w":"상법 제418조 제2항은 정관에 정하는 바에 따라 신기술 도입·재무구조 개선 등 경영상 목적 달성에 필요한 경우 주주 외의 자에게 신주를 배정할 수 있게 한다.","c":"상","v":1},"세무사2026_63-51-5":{"w":"상법 제419조 제1항은 신주인수권자에게 인수권 있는 주식의 종류와 수, 기일까지 청약하지 않으면 실권한다는 뜻을 통지하도록 정한다. 통지는 그 기일 2주 전에 한다(제2항).","c":"상","v":1},"세무사2026_63-52-1":{"w":"신주인수권증서에는 주권 점유의 추정 규정(제336조 제2항)이 준용되어(상법 제420조의3 제2항) 점유자는 적법한 소지인으로 추정된다.","c":"상","v":1},"세무사2026_63-52-2":{"w":"상법 제420조의3 제1항이 신주인수권증서가 발행된 경우 신주인수권을 증서 교부로만 양도하도록 정한다.","c":"상","v":1},"세무사2026_63-52-3":{"w":"상법 제420조의4에 따라 정관으로 정하면 신주인수권증서 대신 신주인수권을 전자등록할 수 있다.","c":"상","v":1},"세무사2026_63-52-4":{"w":"상법 제421조 제1항이 이사에게 신주 인수인으로 하여금 납입기일에 인수가액 전액을 납입시킬 의무를 지운다.","c":"상","v":1},"세무사2026_63-56-1":{"w":"자본금 감소는 원칙적으로 특별결의로 하지만 결손 보전을 위한 감자는 제368조 제1항의 보통결의(출석 의결권 과반수와 발행주식총수 4분의 1 이상)로 한다(상법 제438조 제2항).","c":"상","v":1},"세무사2026_63-67-1":{"w":"상법 제469조 제1항에 따라 주식회사는 이사회 결의로 사채를 발행할 수 있다.","c":"상","v":1},"세무사2026_63-67-2":{"w":"채권은 사채 전액 납입 후에 발행하고(상법 제478조 제1항) 회사는 그 채권을 발행하는 대신 정관에 따라 전자등록부에 채권(債權)을 등록할 수 있다(제3항).","c":"상","v":1},"세무사2026_63-67-3":{"w":"상법 제480조의2는 사채 발행 시 사채관리회사를 정해 변제 수령, 채권 보전 등 관리를 위탁할 수 있게 한다.","c":"상","v":1},"세무사2026_63-67-4":{"w":"상법 제476조 제1항은 사채 모집이 끝나면 이사가 지체 없이 인수인에게 각 사채의 전액 또는 제1회 납입을 시키도록 정한다.","c":"상","v":1},"세무사2026_63-70-1":{"w":"상법 제516조의10 전단은 신주인수권을 행사한 자가 발행가액 전액을 납입한 때 주주가 된다고 정한다.","c":"상","v":1},"세무사2016_53-61-1":{"w":"상법 제317조 제2항 제2호가 자본금의 액을 주식회사 설립등기 사항으로 정한다.","c":"상","v":1},"세무사2016_53-61-3":{"w":"상법 제451조 제2항은 무액면주식의 자본금을 발행가액의 2분의 1 이상으로서 이사회(제416조 단서의 경우 주주총회)가 자본금으로 계상하기로 한 금액의 총액으로 정한다.","c":"상","v":1},"세무사2016_53-61-4":{"w":"상법 제451조 제1항은 회사의 자본금을 이 법에서 달리 규정한 경우 외에는 발행주식의 액면총액으로 정한다.","c":"상","v":1},"세무사2016_53-61-5":{"w":"상법 제428조 제1항은 신주발행 변경등기 후 인수되지 않았거나 청약이 취소된 주식을 이사가 공동으로 인수한 것으로 본다.","c":"상","v":1},"세무사2016_53-62-4":{"w":"상법 제461조 제2항 전단에 따라 준비금을 자본금에 전입하면 주주에게 가진 주식 수에 따라 신주를 발행해야 한다(무상증자).","c":"상","v":1},"세무사2016_53-63-1":{"w":"상법 제462조 제2항에 따라 이익배당은 주주총회 결의로 정하되 제449조의2 제1항에 따라 재무제표를 이사회가 승인하는 경우에는 이사회 결의로 정한다.","c":"상","v":1},"세무사2016_53-63-2":{"w":"상법 제462조 제3항은 배당가능이익을 넘은 위법배당에 대하여 회사채권자가 배당한 이익을 회사에 반환하라고 청구할 수 있게 한다.","c":"상","v":1},"세무사2016_53-63-4":{"w":"상법 제462조의2 제2항은 주식배당을 주식의 권면액으로 하고 종류주식을 발행했으면 같은 종류의 주식으로 할 수 있게 한다.","c":"상","v":1},"세무사2016_53-63-5":{"w":"상법 제462조의3 제1항에 따라 연 1회 결산기를 정한 회사는 정관으로 정하면 영업연도 중 1회 이사회 결의로 중간배당을 할 수 있다.","c":"상","v":1},"세무사2017_54-76-1":{"w":"상법 제462조의2 제1항 단서는 주식배당이 이익배당총액의 2분의 1을 넘지 못하게 한다.","c":"상","v":1},"세무사2017_54-76-2":{"w":"상법 제462조의2 제2항 전단은 주식배당을 주식의 권면액으로 하도록 정한다.","c":"상","v":1},"세무사2017_54-76-3":{"w":"상법 제462조의2 제4항에 따라 주식배당을 받은 주주는 주식배당 결의를 한 주주총회가 종결한 때부터 신주의 주주가 된다.","c":"상","v":1},"세무사2017_54-76-5":{"w":"상법 제462조의2 제2항 후단은 종류주식을 발행한 회사가 각각 같은 종류의 주식으로 주식배당을 할 수 있게 한다.","c":"상","v":1},"세무사2017_54-79-3":{"w":"상법 제462조의4 제1항은 회사가 정관으로 금전 외의 재산으로 배당할 수 있음을 정할 수 있게 한다(현물배당).","c":"상","v":1},"세무사2021_58-73-1":{"w":"상법 제462조의4 제1항이 정관으로 정하면 금전 외의 재산으로 배당할 수 있게 한다.","c":"상","v":1},"세무사2021_58-73-2":{"w":"상법 제462조 제3항에 따라 배당가능이익을 넘어 배당하면 회사채권자가 배당한 이익을 회사에 반환하라고 청구할 수 있다.","c":"상","v":1},"세무사2021_58-73-3":{"w":"상법 제462조 제2항은 이익배당을 주주총회 결의로 정하되 이사회가 재무제표를 승인하는 경우(제449조의2 제1항)에는 이사회 결의로 정하게 한다.","c":"상","v":1},"세무사2021_58-73-4":{"w":"상법 제464조는 이익배당을 각 주주가 가진 주식 수에 따라 하도록 정하고 이익배당에 관한 종류주식(제344조 제1항)은 예외로 둔다.","c":"상","v":1},"세무사2022_59-77-2":{"w":"상법 제460조는 자본준비금과 이익준비금을 자본금의 결손 보전에 충당하는 경우 외에는 처분하지 못하게 하므로 결손 보전에 쓸 수 있다.","c":"상","v":1},"세무사2022_59-77-3":{"w":"상법 제461조의2는 자본준비금과 이익준비금 총액이 자본금의 1.5배를 넘으면 주주총회 결의로 넘는 금액 범위에서 감액할 수 있게 한다.","c":"상","v":1},"세무사2022_59-77-4":{"w":"상법 제461조 제1항 본문은 이사회 결의로 준비금을 자본금에 전입하게 하고 단서는 정관으로 주주총회가 결정하도록 정할 수 있게 한다.","c":"상","v":1},"세무사2022_59-77-5":{"w":"이사회 결의로 준비금을 전입하면 회사는 배정기준일을 정해 2주 전에 공고하고 그날 주주명부의 주주가 신주의 주주가 된다(상법 제461조 제3항). 주주총회 결의로 하면 결의한 때 주주가 된다(제4항).","c":"상","v":1},"세무사2022_59-78-1":{"w":"상법 제462조의3 제1항은 연 1회 결산 회사가 영업연도 중 1회 중간배당을 할 수 있게 한다. 2011년 개정으로 중간배당을 금전으로 한정하던 문구가 빠져 정관 근거가 있으면 현물배당(제462조의4)도 할 수 있다고 본다.","c":"중","v":1},"세무사2022_59-78-2":{"w":"상법 제462조의4 제1항에 따라 현물배당은 정관으로 금전 외의 재산으로 배당할 수 있음을 정해야 할 수 있다.","c":"상","v":1},"세무사2022_59-78-3":{"w":"현물배당도 이익배당이므로 주주총회 결의로 정하되 정관에 따라 이사회가 재무제표를 승인하는 회사는 이사회 결의로 정한다(상법 제462조 제2항, 제462조의4).","c":"상","v":1},"세무사2022_59-78-4":{"w":"상법 제462조의4 제2항 제1호에 따라 현물배당을 결정한 회사는 주주가 현물 대신 금전 지급을 청구할 수 있게 하면서 그 금액과 청구기간을 정할 수 있다.","c":"상","v":1},"세무사2022_59-79-1":{"w":"상법 제462조의2 제1항 본문은 주주총회 결의로 이익배당을 새로 발행하는 주식으로 할 수 있게 한다.","c":"상","v":1},"세무사2022_59-79-3":{"w":"상법 제462조의2 제4항은 주식배당을 받은 주주가 결의한 주주총회가 종결한 때부터 신주의 주주가 된다고 정한다.","c":"상","v":1},"세무사2022_59-79-4":{"w":"상법 제462조의2 제2항 후단은 종류주식을 발행한 회사가 같은 종류의 주식으로 주식배당을 할 수 있게 한다.","c":"상","v":1},"세무사2022_59-79-5":{"w":"상법 제462조의2 제6항 전단은 등록질권자(제340조 제1항)의 권리가 주식배당으로 주주가 받을 주식에 미친다고 정한다.","c":"상","v":1},"세무사2023_60-67-2":{"w":"상법 제458조는 자본금의 2분의 1이 될 때까지 매 결산기 이익배당액의 10분의 1 이상을 이익준비금으로 적립하게 하고 주식배당은 예외로 둔다. 주식배당은 회사 재산이 나가지 않기 때문이다.","c":"상","v":1},"세무사2023_60-68-1":{"w":"상법 제462조의3 제1항은 연 1회 결산기를 정한 회사만 영업연도 중 1회 중간배당을 할 수 있게 한다.","c":"상","v":1},"세무사2023_60-68-2":{"w":"상법 제462조의2 제1항 단서가 주식배당을 이익배당총액의 2분의 1 이내로 제한한다.","c":"상","v":1},"세무사2023_60-68-4":{"w":"상법 제462조 제3항에 따라 배당가능이익 없이 한 위법배당에 대하여 회사채권자는 배당한 이익을 회사에 반환하라고 청구할 수 있다.","c":"상","v":1},"세무사2023_60-68-5":{"w":"상법 제462조의4 제1항에 따라 회사는 정관으로 금전 외의 재산으로 배당할 수 있음을 정할 수 있다.","c":"상","v":1},"세무사2024_61-44-2":{"w":"무액면주식의 자본금은 발행가액의 2분의 1 이상에서 이사회가 계상하기로 한 금액이므로(상법 제451조 제2항) 발행가액 전액을 자본금으로 계상해도 된다.","c":"상","v":1},"세무사2024_61-64-1":{"w":"준비금을 자본금에 전입하면 주주에게 가진 주식 수에 따라 신주를 발행하므로(상법 제461조 제2항) 액면주식 회사에서는 전입액을 1주의 액면금액으로 나눈 수만큼 신주가 발행된다.","c":"상","v":1},"세무사2024_61-64-3":{"w":"상법 제461조 제4항은 정관에 따라 주주총회가 전입을 결의한 경우 주주가 결의한 때부터 신주의 주주가 된다고 정한다.","c":"상","v":1},"세무사2024_61-64-4":{"w":"상법 제458조는 주식배당을 빼고 자본금의 2분의 1이 될 때까지 매 결산기 이익배당액의 10분의 1 이상을 이익준비금으로 적립하도록 정한다.","c":"상","v":1},"세무사2024_61-64-5":{"w":"상법 제460조는 법정준비금을 결손 보전에만 쓰게 할 뿐 쓰는 순서를 정하지 않는다. 2011년 개정으로 이익준비금을 먼저 쓰도록 한 규정이 없어졌다.","c":"상","v":1},"세무사2024_61-73-1":{"w":"상법 제462조의2 제1항 본문은 주주총회 결의로 이익배당을 새로 발행하는 주식으로 할 수 있게 한다.","c":"상","v":1},"세무사2024_61-73-2":{"w":"상법 제462조의2 제5항은 주식배당 결의가 있으면 이사가 지체 없이 배당받을 주주와 주주명부상 질권자에게 받을 주식의 종류와 수를 통지하도록 정한다.","c":"상","v":1},"세무사2024_61-73-3":{"w":"상법 제462조의2 제1항 단서가 주식배당을 이익배당총액의 2분의 1 이내로 제한한다.","c":"상","v":1},"세무사2024_61-73-4":{"w":"상법 제462조의2 제2항 전단은 주식배당을 주식의 권면액으로 하도록 정한다.","c":"상","v":1},"세무사2026_63-65-4":{"w":"상법 제464조의2 제2항은 배당금 지급청구권의 소멸시효를 5년으로 정한다.","c":"상","v":1},"세무사2016_53-67-2":{"w":"상법 제360조의21에 따라 주식이전은 설립한 완전모회사가 본점 소재지에서 설립등기를 함으로써 효력이 생긴다. 주식교환은 교환하는 날에 효력이 생긴다.","c":"상","v":1},"세무사2016_53-67-3":{"w":"주식교환(상법 제360조의2)과 주식이전(제360조의15)은 모두 주식회사가 완전모회사가 되는 제도로서 주식회사에서만 인정된다.","c":"상","v":1},"세무사2016_53-67-4":{"w":"주식교환에는 간이주식교환(상법 제360조의9)과 소규모 주식교환(제360조의10)이 있지만 주식이전에는 이런 특례 규정이 없다. 완전모회사가 새로 설립되기 때문이다.","c":"상","v":1},"세무사2016_53-67-5":{"w":"상법 제360조의23 제1항은 주식이전 무효를 각 회사의 주주·이사·감사·감사위원·청산인이 주식이전의 날부터 6개월 안에 소로만 주장하도록 정한다.","c":"상","v":1},"세무사2016_53-70-1":{"w":"상법 제244조는 합명회사 사원으로서 조직변경으로 유한책임사원이 된 자가 본점 등기 전에 생긴 회사채무에 대하여 등기 후 2년 안에는 무한책임사원의 책임을 면하지 못하게 한다.","c":"상","v":1},"세무사2016_53-70-3":{"w":"상법 제604조 제1항은 주식회사가 총주주 일치의 총회 결의로 유한회사로 조직변경할 수 있게 하되 사채 상환을 끝내지 않았으면 할 수 없게 한다(단서).","c":"상","v":1},"세무사2016_53-70-4":{"w":"상법 제605조 제1항은 주식회사가 유한회사로 조직변경할 때 순재산액이 자본금 총액에 모자라면 결의 당시의 이사와 주주가 연대하여 부족액을 지급하도록 정한다.","c":"상","v":1},"세무사2016_53-70-5":{"w":"상법 제607조 제2항은 유한회사가 주식회사로 조직변경할 때 발행하는 주식의 발행가액 총액이 회사에 현존하는 순재산액을 넘지 못하게 한다.","c":"상","v":1},"세무사2016_53-71-2":{"w":"소규모 주식교환은 완전자회사 주주에게 줄 금전 등의 가액이 완전모회사 최종 대차대조표상 순자산액의 100분의 5를 넘으면 할 수 없다(상법 제360조의10 제1항 단서).","c":"상","v":1},"세무사2016_53-73-1":{"w":"상법 제523조 제4호에 따라 흡수합병의 존속회사는 소멸회사 주주에게 합병대가의 전부 또는 일부로 금전이나 그 밖의 재산을 줄 수 있다(교부금합병).","c":"상","v":1},"세무사2016_53-73-2":{"w":"간이영업양도(상법 제374조의3)에는 채권자보호절차가 없다. 간이합병(제527조의2)은 주주총회 승인만 이사회 승인으로 갈음할 뿐 채권자보호절차(제527조의5)는 그대로 거쳐야 한다.","c":"상","v":1},"세무사2016_53-73-3":{"w":"판례는 합병비율이 현저하게 불공정하면 불이익을 입은 주주 등이 합병무효의 소(상법 제529조)로 무효를 구할 수 있다고 본다.","c":"상","v":1},"세무사2016_53-73-4":{"w":"상법 제174조 제2항에 따라 합병 당사회사 한쪽이 유한책임회사이면 존속회사나 신설회사는 주식회사·유한회사·유한책임회사여야 한다.","c":"상","v":1},"세무사2017_54-50-3":{"w":"상법 제287조의43 제2항은 유한책임회사가 총사원의 동의로 주식회사로 조직을 변경할 수 있게 한다.","c":"상","v":1},"세무사2017_54-51-1":{"w":"상법 제174조 제3항은 해산한 회사가 존립 중인 회사를 존속회사로 하는 경우에만 합병할 수 있게 한다.","c":"상","v":1},"세무사2017_54-51-2":{"w":"주식회사 합병의 채권자보호절차를 정한 상법 제527조의5 제1항은 합병결의일부터 2주 안에 1개월 이상의 기간을 정해 이의 제출을 공고하고 알고 있는 채권자에게 따로 최고하도록 정한다.","c":"상","v":1},"세무사2017_54-51-5":{"w":"상법 제174조 제2항이 합병 당사회사 한쪽이나 양쪽이 주식회사·유한회사·유한책임회사이면 존속회사나 신설회사도 이 세 종류 가운데 하나여야 한다고 정한다.","c":"상","v":1},"세무사2017_54-70-1":{"w":"상법 제360조의2 제2항에 따라 완전자회사가 되는 회사 주주의 주식은 주식을 교환하는 날에 완전모회사가 되는 회사로 이전한다.","c":"상","v":1},"세무사2017_54-70-2":{"w":"상법 제360조의2 제1항은 회사가 주식교환으로 다른 회사 발행주식 총수를 소유하는 완전모회사가 될 수 있게 한다.","c":"상","v":1},"세무사2017_54-70-3":{"w":"상법 제360조의3 제3항 제6호는 주식교환을 할 날을 주식교환계약서 기재사항으로 정한다.","c":"상","v":1},"세무사2017_54-70-4":{"w":"상법 제360조의9 제1항에 따라 완전자회사가 되는 회사의 총주주가 동의하면 그 회사의 주주총회 승인을 이사회 승인으로 갈음할 수 있다(간이주식교환).","c":"상","v":1},"세무사2021_58-53-1":{"w":"상법 제360조의14 제1항이 주식교환 무효를 각 회사의 주주·이사·감사·감사위원·청산인이 교환의 날부터 6개월 안에 소로만 주장하도록 정한다.","c":"상","v":1},"세무사2021_58-53-2":{"w":"상법 제360조의9 제1항은 완전모회사가 되는 회사가 완전자회사가 되는 회사 발행주식총수의 100분의 90 이상을 가진 경우 자회사 쪽 주주총회 승인을 이사회 승인으로 갈음할 수 있게 한다.","c":"상","v":1},"세무사2021_58-53-3":{"w":"상법 제360조의14 제3항은 주식교환 무효판결이 확정되면 완전모회사가 교환 때 발행한 신주나 이전한 자기주식의 주주에게 그가 가졌던 완전자회사 주식을 이전하도록 정한다.","c":"상","v":1},"세무사2021_58-53-5":{"w":"상법 제360조의13은 완전모회사가 되는 회사의 이사·감사로서 교환 전에 취임한 자가 계약서에 다른 정함이 없으면 교환 후 최초 결산기에 관한 정기총회가 끝날 때 퇴임하도록 정한다.","c":"상","v":1},"세무사2021_58-80-2":{"w":"분할합병에는 합병 등기 규정(제528조)이 준용되므로(상법 제530조의11 제1항) 설립되는 회사는 설립등기를, 소멸하는 회사는 해산등기를 한다.","c":"상","v":1},"세무사2021_58-80-3":{"w":"분할합병에는 합병의 채권자보호절차(제527조의5)가 준용되어(상법 제530조의11 제2항) 분할회사와 분할승계회사가 각각 이 절차를 거친다.","c":"상","v":1},"세무사2021_58-80-4":{"w":"분할·분할합병에는 신설합병 창립총회 규정(제527조)이 준용되고 그 설립위원은 대표이사로 한다(상법 제530조의11 제1항 단서). 그래서 신설분할합병의 창립총회는 대표이사가 소집한다.","c":"중","v":1},"세무사2021_58-80-5":{"w":"상법 제530조의3 제6항은 분할·분할합병으로 관련 회사 주주의 부담이 가중되면 주주총회 승인과 종류주주총회 결의 외에 그 주주 전원의 동의를 요구한다.","c":"상","v":1},"세무사2022_59-45-5":{"w":"상법 제175조 제1항에 따라 신설합병에서는 각 회사가 선임한 설립위원이 공동으로 정관 작성 등 설립행위를 한다.","c":"상","v":1},"세무사2022_59-46-1":{"w":"상법 제530조의3 제1항·제2항은 분할합병을 할 때 분할합병계약서를 작성해 주주총회 특별결의로 승인을 받도록 정한다. 의결권 배제 주주도 이 결의에서는 의결권이 있다(제3항).","c":"상","v":1},"세무사2022_59-46-2":{"w":"상법 제530조의10은 단순분할신설회사가 분할회사의 권리의무를 분할계획서에서 정한 바에 따라 승계한다고 정한다.","c":"상","v":1},"세무사2022_59-46-3":{"w":"상법 제530조의12는 분할회사가 분할로 설립되는 회사의 주식 총수를 취득하는 물적분할에 분할 규정을 준용하여 이 방식을 인정한다.","c":"상","v":1},"세무사2022_59-46-5":{"w":"상법 제530조의9 제3항은 분할합병에서 분할회사가 특별결의로 분할승계회사나 분할합병신설회사가 분할합병계약서에 승계하기로 정한 채무만 책임지도록 정할 수 있게 한다.","c":"상","v":1},"세무사2022_59-60-2":{"w":"상법 제360조의18은 주식이전으로 설립하는 완전모회사의 자본금을 이전의 날 완전자회사 순자산액에서 그 주주에게 줄 금전 등의 가액을 뺀 금액 이내로 제한한다.","c":"상","v":1},"세무사2023_60-72-1":{"w":"분할로 설립되는 회사에는 설립 규정이 준용되지만 분할회사의 출자만으로 설립되는 경우에는 현물출자 검사인 조사·보고(제299조)를 적용하지 않는다(상법 제530조의4 단서).","c":"상","v":1},"세무사2023_60-72-2":{"w":"상법 제530조의2 제4항은 해산 후의 회사가 존립 중의 회사를 존속회사로 하거나 새로 회사를 설립하는 경우에만 분할 또는 분할합병할 수 있게 한다.","c":"상","v":1},"세무사2023_60-72-3":{"w":"흡수분할합병의 분할합병계약서에는 분할회사 주주에게 줄 대가(상법 제530조의6 제1항 제4호)를 적고 그 대가에 분할승계회사의 모회사 주식을 포함할 수 있다(제530조의6 제4항).","c":"상","v":1},"세무사2023_60-72-5":{"w":"상법 제530조의10은 단순분할신설회사·분할승계회사·분할합병신설회사가 분할계획서나 분할합병계약서에서 정한 바에 따라 분할회사의 권리의무를 승계한다고 정한다.","c":"상","v":1},"세무사2024_61-51-1":{"w":"주식교환 대가로 완전모회사가 되는 회사의 모회사 주식을 줄 수 있으므로(상법 제360조의3 제3항 제4호·제6항) 교환이 끝나면 C회사 주주는 그 모회사인 A회사의 주주가 된다.","c":"중","v":1},"세무사2024_61-51-2":{"w":"상법 제360조의3 제1항·제2항에 따라 주식교환을 하려는 각 회사는 주식교환계약서를 작성해 주주총회 특별결의로 승인을 받아야 한다. 간이·소규모 교환은 예외다.","c":"상","v":1},"세무사2024_61-51-4":{"w":"완전모회사의 자본금은 신주를 발행할 때 증가하므로 자기주식만 이전하여 교환대가를 지급하면 자본금은 늘지 않는다(상법 제360조의7 참조).","c":"중","v":1},"세무사2024_61-51-5":{"w":"상법 제360조의2 제2항에 따라 완전자회사가 되는 회사 주주의 주식은 주식을 교환하는 날에 완전모회사가 되는 회사로 이전하므로 그날 교환의 효력이 생긴다.","c":"상","v":1},"세무사2024_61-69-5":{"w":"상법 제607조 제2항은 유한회사가 주식회사로 조직변경할 때 발행하는 주식의 발행가액 총액이 현존 순재산액을 넘지 못하게 한다.","c":"상","v":1},"세무사2024_61-80-1":{"w":"상법 제174조 제1항은 회사가 종류와 관계없이 합병할 수 있게 하고 제2항은 한쪽이 주식회사이면 존속·신설회사를 물적회사로 하도록만 제한한다.","c":"상","v":1},"세무사2024_61-80-2":{"w":"상법 제600조 제1항은 유한회사가 주식회사와 합병하여 존속·신설회사가 주식회사가 되면 법원 인가가 없으면 합병의 효력이 없다고 정한다.","c":"상","v":1},"세무사2024_61-80-3":{"w":"상법 제175조 제1항에 따라 신설합병에서는 각 회사가 선임한 설립위원이 공동으로 설립에 관한 행위를 한다.","c":"상","v":1},"세무사2024_61-80-5":{"w":"합병무효의 소에는 제190조 단서까지 준용되어(상법 제240조, 제530조 제2항) 판결 전에 생긴 권리의무에는 영향이 없다. 무효판결은 장래에 대하여만 효력이 있다.","c":"상","v":1},"세무사2025_62-72-1":{"w":"상법 제522조 제1항은 합병계약서를 작성해 주주총회 승인을 얻도록 정하고 그 결의는 특별결의다(제3항). 간이합병(제527조의2)과 소규모합병(제527조의3)은 예외다.","c":"상","v":1},"세무사2025_62-72-2":{"w":"상법 제525조 제1항은 존속회사나 신설회사가 주식회사이고 합병할 회사 한쪽이나 양쪽이 합명회사·합자회사이면 총사원의 동의를 얻어 합병계약서를 작성하도록 정한다.","c":"상","v":1},"세무사2025_62-72-3":{"w":"상법 제527조의2 제1항에 따라 소멸회사의 총주주가 동의하면 소멸회사의 주주총회 승인을 이사회 승인으로 갈음할 수 있다(간이합병).","c":"상","v":1},"세무사2025_62-72-4":{"w":"상법 제527조의4 제1항은 존속회사의 이사·감사로서 합병 전에 취임한 자가 계약서에 다른 정함이 없으면 합병 후 최초 결산기의 정기총회가 끝날 때 퇴임하도록 정한다.","c":"상","v":1},"세무사2025_62-73-1":{"w":"상법 제530조의2 제3항은 회사가 분할로 하나 또는 여러 회사를 설립하면서 동시에 분할합병할 수 있게 한다.","c":"상","v":1},"세무사2025_62-73-2":{"w":"상법 제530조의2 제2항은 회사가 분할에 의하여 하나 또는 여러 존립 중의 회사와 합병(분할합병)할 수 있게 한다.","c":"상","v":1},"세무사2025_62-73-3":{"w":"상법 제530조의10은 분할합병신설회사가 분할합병계약서에서 정한 바에 따라 분할회사의 권리의무를 승계한다고 정한다.","c":"상","v":1},"세무사2025_62-73-4":{"w":"상법 제530조의2 제4항은 해산 후의 회사가 존립 중의 회사를 존속회사로 하거나 새로 회사를 설립하는 경우에만 분할·분할합병할 수 있게 한다.","c":"상","v":1},"세무사2026_63-73-1":{"w":"상법 제530조의10에 따라 단순분할신설회사는 분할계획서에서 정한 바에 따라 분할회사의 권리의무를 승계한다.","c":"상","v":1},"세무사2026_63-73-3":{"w":"분할계획서는 주주총회 특별결의로 승인받고(상법 제530조의3 제1항·제2항) 이 결의에서는 제344조의3 제1항에 따라 의결권이 배제된 주주도 의결권이 있다(같은 조 제3항).","c":"상","v":1},"세무사2026_63-73-4":{"w":"상법 제530조의13은 분할이나 분할합병을 할 때 단순분할신설회사·분할합병신설회사·분할승계회사가 분할회사의 자기주식에 신주를 배정하지 못하게 하고 분할회사가 자기주식을 그 회사들에 이전하지도 못하게 한다. 의결권 없던 자기주식이 신설회사의 의결권 있는 주식으로 바뀌어 지배주주의 지배력만 커지는 것을 막으려는 규정이다.","c":"상","v":1},"세무사2026_63-73-5":{"w":"상법 제530조의4 단서는 분할회사의 출자만으로 회사가 설립되는 경우 현물출자 검사인 조사(제299조)를 적용하지 않는다고 정한다.","c":"상","v":1},"세무사2026_63-76-1":{"w":"상법 제525조 제1항은 존속회사가 주식회사이고 합병할 회사가 합명회사이면 그 총사원의 동의를 얻어 합병계약서를 작성하도록 정한다.","c":"상","v":1},"세무사2017_54-52-1":{"w":"상법 제245조는 해산한 합명회사가 청산의 목적 범위 안에서 존속하는 것으로 본다.","c":"상","v":1},"세무사2017_54-52-3":{"w":"상법 제176조 제1항 제3호에 따라 업무집행 사원이 법령·정관에 위반해 회사의 존속을 허용할 수 없는 행위를 하면 법원은 청구나 직권으로 해산을 명할 수 있다.","c":"상","v":1},"세무사2017_54-52-4":{"w":"상법 제252조는 사원이 1인이 되거나(제227조 제3호) 법원의 명령·판결로(제6호) 해산한 경우 법원이 사원 그 밖의 이해관계인이나 검사의 청구 또는 직권으로 청산인을 선임하도록 정한다.","c":"상","v":1},"세무사2017_54-52-5":{"w":"상법 제263조 제1항은 청산인이 임무를 마치면 지체 없이 계산서를 작성해 각 사원에게 교부하고 승인을 얻도록 정한다. 1개월 안에 이의가 없으면 승인한 것으로 본다(제2항).","c":"상","v":1},"세무사2021_58-74-1":{"w":"상법 제540조 제1항은 청산사무가 끝나면 청산인이 지체 없이 결산보고서를 작성해 주주총회 승인을 얻도록 정한다.","c":"상","v":1},"세무사2021_58-74-2":{"w":"상법 제534조 제5항은 청산인이 대차대조표와 사무보고서를 정기총회에 제출해 승인을 요구하도록 정한다.","c":"상","v":1},"세무사2021_58-74-4":{"w":"상법 제539조 제1항은 법원이 선임한 청산인이 아니면 언제든지 주주총회 결의로 해임할 수 있게 한다.","c":"상","v":1},"세무사2021_58-74-5":{"w":"상법 제537조 제1항은 청산에서 제외된 채권자가 아직 분배되지 않은 잔여재산에 대해서만 변제를 청구할 수 있다고 정한다.","c":"상","v":1},"세무사2024_61-72-1":{"w":"상법 제285조 제1항에 따라 합자회사는 무한책임사원 전원 또는 유한책임사원 전원이 퇴사하면 해산한다. 남은 사원 전원의 동의로 새 사원을 가입시켜 계속할 수 있다(제2항).","c":"상","v":1},"세무사2024_61-72-3":{"w":"유한회사 해산사유를 정한 상법 제609조 제1항 제1호는 제227조 제3호(사원이 1인으로 된 때)를 빼고 준용하므로 1인 유한회사도 해산하지 않는다.","c":"상","v":1},"세무사2024_61-72-4":{"w":"사원이 1인이 되어 해산한 경우(상법 제227조 제3호) 법원은 이해관계인이나 검사의 청구 또는 직권으로 청산인을 선임한다(제252조).","c":"상","v":1},"세무사2024_61-72-5":{"w":"상법 제251조 제1항은 합명회사가 해산하면 총사원 과반수의 결의로 청산인을 선임하도록 정한다. 선임하지 않으면 업무집행사원이 청산인이 된다(제2항).","c":"상","v":1},"세무사2026_63-77-1":{"w":"상법 제518조는 해산 결의를 제434조의 특별결의로 하도록 정한다.","c":"상","v":1},"세무사2026_63-77-2":{"w":"상법 제521조는 회사가 해산하면 파산의 경우 외에는 이사가 지체 없이 주주에게 통지하도록 정한다.","c":"상","v":1},"세무사2026_63-77-4":{"w":"상법 제533조 제1항은 청산인이 취임 후 지체 없이 재산상태를 조사해 재산목록과 대차대조표를 작성하고 주주총회 승인을 얻도록 정한다.","c":"상","v":1},"세무사2026_63-77-5":{"w":"상법 제535조 제2항은 청산인이 알고 있는 채권자에게 각각 채권 신고를 최고해야 하고 그 채권자가 신고하지 않아도 청산에서 제외하지 못한다고 정한다.","c":"상","v":1},"세무사2016_53-74-1":{"w":"상법 제563조는 유한회사가 이사에게 또는 이사가 회사에 소를 제기할 때 사원총회가 그 소에 관해 회사를 대표할 자를 선정하도록 정한다.","c":"상","v":1},"세무사2016_53-74-3":{"w":"상법 제571조 제1항은 유한회사 사원총회를 이사가 소집하되 임시총회는 감사도 소집할 수 있게 한다.","c":"상","v":1},"세무사2016_53-74-4":{"w":"상법 제547조에 따라 정관으로 이사를 정하지 않았으면 회사 성립 전에 사원총회를 열어 선임해야 하고 이 총회는 각 사원이 소집할 수 있다.","c":"상","v":1},"세무사2016_53-74-5":{"w":"상법 제577조 제1항은 총사원이 동의하면 사원총회 결의 대신 서면결의를 할 수 있게 한다.","c":"상","v":1},"세무사2016_53-75-1":{"w":"상법 제278조는 유한책임사원이 회사의 업무집행이나 대표행위를 하지 못하게 한다.","c":"상","v":1},"세무사2016_53-75-3":{"w":"상법 제276조는 유한책임사원이 무한책임사원 전원의 동의만 있으면 지분을 양도할 수 있고 양도로 정관을 변경해야 할 때에도 같다고 정한다.","c":"상","v":1},"세무사2016_53-75-4":{"w":"유한책임사원이 무한책임사원이 되면 신입사원 책임 규정(제213조)이 준용되어(상법 제282조) 변경 전에 생긴 회사채무에도 다른 무한책임사원과 같은 책임을 진다.","c":"상","v":1},"세무사2016_53-75-5":{"w":"무한책임사원이 유한책임사원이 되면 퇴사원 책임 규정(제225조 제2항)이 준용되어(상법 제282조) 변경등기 전에 생긴 회사채무에 대하여 등기 후 2년 동안 무한책임을 진다.","c":"상","v":1},"세무사2016_53-76-1":{"w":"유한책임회사 설립의 무효·취소에는 합명회사 규정(제184조)이 준용되어(상법 제287조의6) 취소는 취소권자만 회사성립일부터 2년 안에 소로 주장할 수 있다.","c":"상","v":1},"세무사2016_53-76-2":{"w":"유한책임회사에는 제185조가 준용되어(상법 제287조의6) 사원이 채권자를 해할 것을 알고 회사를 설립하면 채권자는 그 사원과 회사를 상대로 설립취소의 소를 낼 수 있다.","c":"상","v":1},"세무사2016_53-76-4":{"w":"상법 제287조의6이 준용하는 제189조에 따라 심리 중 하자가 보완되고 설립을 무효·취소하는 것이 부적당하면 법원은 청구를 기각할 수 있다.","c":"상","v":1},"세무사2016_53-76-5":{"w":"유한책임회사 설립취소 판결에는 제190조가 단서까지 준용되어(상법 제287조의6) 판결 확정 전에 생긴 회사·사원·제3자 사이의 권리의무에는 영향이 없다.","c":"상","v":1},"세무사2016_53-77-1":{"w":"상법 제213조는 합명회사 성립 후 가입한 사원도 가입 전에 생긴 회사채무에 대하여 다른 사원과 같은 책임을 지게 한다.","c":"상","v":1},"세무사2016_53-77-2":{"w":"상법 제279조 제1항은 합자회사 유한책임사원이 출자가액에서 이미 이행한 부분을 뺀 가액을 한도로 회사채무를 변제할 책임을 진다고 정한다.","c":"상","v":1},"세무사2016_53-77-3":{"w":"상법 제287조의4 제1항은 유한책임회사 사원이 신용이나 노무를 출자 목적으로 하지 못하게 한다.","c":"상","v":1},"세무사2016_53-77-4":{"w":"상법 제556조는 유한회사 사원이 지분 전부나 일부를 양도하거나 상속할 수 있게 하고 정관으로만 양도를 제한할 수 있게 한다.","c":"상","v":1},"세무사2016_53-78-4":{"w":"상법 제287조의9 제1항은 유한책임회사가 자기 지분을 양수하지 못하게 하고 제2항은 지분을 취득하면 취득한 때 소멸하게 한다.","c":"상","v":1},"세무사2016_53-80-1":{"w":"최저자본금 제도는 주식회사(5천만원)는 2009년 개정으로, 유한회사(1천만원)는 2011년 개정으로 없어져 지금은 둘 다 제한이 없다.","c":"상","v":1},"세무사2016_53-80-2":{"w":"상법 제173조는 회사가 다른 회사의 무한책임사원이 되는 것만 금지하므로 유한책임사원이 되는 것은 허용된다.","c":"상","v":1},"세무사2016_53-80-4":{"w":"상법 제287조의2는 1명 이상의 사원이 정관을 작성해 유한책임회사를 설립하도록 정하므로 1인 설립이 가능하다.","c":"상","v":1},"세무사2016_53-80-5":{"w":"상법 제195조는 합명회사 내부관계에 정관이나 이 법에 다른 규정이 없으면 민법의 조합 규정을 준용한다.","c":"상","v":1},"세무사2017_54-41-1":{"w":"상법 제287조의7은 유한책임회사 사원의 책임을 이 법에 다른 규정이 있는 경우 외에는 출자금액을 한도로 정한다.","c":"상","v":1},"세무사2017_54-43-1":{"w":"상법 제554조는 유한회사 각 사원이 출자좌수에 따라 지분을 가진다고 정한다.","c":"상","v":1},"세무사2017_54-43-2":{"w":"상법 제562조 제2항은 유한회사 이사가 여러 명이면 정관에 다른 정함이 없는 한 사원총회에서 대표이사를 선정하도록 정한다.","c":"상","v":1},"세무사2017_54-43-4":{"w":"상법 제559조 제1항은 유한회사 사원의 지분을 질권의 목적으로 할 수 있게 한다.","c":"상","v":1},"세무사2017_54-43-5":{"w":"상법 제551조 제1항은 회사 성립 후 출자 납입이나 현물출자 이행이 끝나지 않았음이 발견되면 성립 당시 사원·이사·감사가 연대하여 그 금액이나 가액을 지급하도록 정한다.","c":"상","v":1},"세무사2017_54-44-5":{"w":"상법 제283조 제1항은 합자회사 유한책임사원이 사망하면 상속인이 지분을 승계해 사원이 된다고 정한다. 무한책임사원의 사망은 퇴사 원인이다(제218조 제3호).","c":"상","v":1},"세무사2017_54-53-2":{"w":"상법 제203조는 합명회사 지배인 선임·해임을 정관에 다른 정함이 없으면 업무집행사원이 있어도 총사원 과반수의 결의로 하도록 정한다.","c":"상","v":1},"세무사2017_54-53-4":{"w":"상법 제201조 제2항은 업무집행사원 여러 명 가운데 한 사람의 행위에 다른 업무집행사원이 이의하면 곧 중지하고 업무집행사원 과반수 결의에 따르도록 정한다.","c":"상","v":1},"세무사2017_54-53-5":{"w":"상법 제204조는 합명회사 정관 변경에 총사원의 동의를 요구한다.","c":"상","v":1},"세무사2021_58-75-5":{"w":"상법 제564조 제3항은 유한회사 이사의 자기거래에 감사가 있으면 감사의 승인을, 감사가 없으면 사원총회의 승인을 요구한다.","c":"상","v":1},"세무사2021_58-76-1":{"w":"상법 제197조는 합명회사 사원이 다른 사원 전원의 동의 없이 지분 전부나 일부를 양도하지 못하게 한다.","c":"상","v":1},"세무사2021_58-76-2":{"w":"상법 제219조 제1항은 정관으로 지분 상속을 정한 경우 상속인이 상속 개시를 안 날부터 3개월 안에 승계 또는 포기의 통지를 발송하도록 정한다. 통지 없이 3개월이 지나면 포기한 것으로 본다(제2항).","c":"상","v":1},"세무사2021_58-76-4":{"w":"상법 제207조는 정관이나 총사원의 동의로 회사를 대표할 업무집행사원을 정하면 그 사원이 회사를 대표하게 한다.","c":"상","v":1},"세무사2021_58-76-5":{"w":"상법 제212조 제1항은 회사 재산으로 회사채무를 다 갚을 수 없으면 각 사원이 연대하여 변제할 책임을 지게 한다.","c":"상","v":1},"세무사2021_58-78-1":{"w":"상법 제272조는 합자회사 유한책임사원이 신용 또는 노무를 출자 목적으로 하지 못하게 한다.","c":"상","v":1},"세무사2021_58-78-3":{"w":"무한책임사원 A의 지분양도에는 제197조가 준용되어(상법 제269조) 다른 사원 전원의 동의가 필요하고 유한책임사원 B의 지분양도는 무한책임사원 전원(A)의 동의로 족하다(제276조).","c":"상","v":1},"세무사2021_58-78-4":{"w":"사원의 책임은 정관 기재사항(상법 제270조)이므로 총사원의 동의로 정관을 변경해 무한책임사원과 유한책임사원의 지위를 바꿀 수 있다. 바뀐 뒤의 책임은 제282조가 정한다.","c":"상","v":1},"세무사2021_58-78-5":{"w":"상법 제283조 제1항에 따라 유한책임사원이 사망하면 상속인이 지분을 승계해 사원이 된다.","c":"상","v":1},"세무사2021_58-79-1":{"w":"상법 제287조의9 제1항은 유한책임회사가 자기 지분의 전부나 일부를 양수하지 못하게 한다.","c":"상","v":1},"세무사2021_58-79-2":{"w":"상법 제287조의12 제1항은 유한책임회사가 정관으로 사원 또는 사원이 아닌 자를 업무집행자로 정하도록 한다.","c":"상","v":1},"세무사2021_58-79-4":{"w":"유한책임회사 자본금 감소에는 채권자보호절차(제232조)가 준용되지만 감소 후 자본금이 순자산액 이상이면 예외다(상법 제287조의36 제2항).","c":"상","v":1},"세무사2021_58-79-5":{"w":"유한책임회사 조직변경에는 제607조가 준용되어(상법 제287조의44) 주식회사로의 조직변경은 법원 인가를 받아야 효력이 있다(제607조 제3항).","c":"상","v":1},"세무사2022_59-47-1":{"w":"상법 제178조는 합명회사 설립 시 2인 이상의 사원이 공동으로 정관을 작성하도록 정한다.","c":"상","v":1},"세무사2022_59-47-2":{"w":"상법 제179조는 합명회사 정관에 목적·상호·사원의 성명 등 절대적 기재사항을 적고 총사원이 기명날인 또는 서명하도록 정한다.","c":"상","v":1},"세무사2022_59-47-3":{"w":"상법 제185조는 사원이 채권자를 해할 것을 알고 회사를 설립하면 채권자가 그 사원과 회사를 상대로 설립취소의 소를 낼 수 있게 한다.","c":"상","v":1},"세무사2022_59-47-5":{"w":"상법 제199조는 합명회사 사원이 다른 사원 과반수의 결의가 있어야 자기 또는 제3자의 계산으로 회사와 거래할 수 있게 한다.","c":"상","v":1},"세무사2022_59-48-1":{"w":"상법 제268조는 합자회사를 무한책임사원과 유한책임사원으로 조직하도록 정하므로 두 종류 사원이 적어도 1명씩, 모두 2인 이상이어야 한다.","c":"상","v":1},"세무사2022_59-48-2":{"w":"상법 제273조는 합자회사 무한책임사원이 정관에 다른 규정이 없으면 각자 회사의 업무를 집행할 권리와 의무가 있다고 정한다.","c":"상","v":1},"세무사2022_59-48-4":{"w":"상법 제276조는 유한책임사원이 지분의 전부나 일부를 양도할 때 무한책임사원 전원의 동의를 요구한다.","c":"상","v":1},"세무사2022_59-48-5":{"w":"상법 제284조는 유한책임사원이 성년후견개시 심판을 받아도 퇴사하지 않는다고 정한다. 유한책임사원은 업무집행을 하지 않아 개인적 능력이 중요하지 않기 때문이다.","c":"상","v":1},"세무사2022_59-49-2":{"w":"상법 제287조의12 제2항 전단은 업무집행자를 1명 또는 둘 이상 정한 경우 각자가 회사의 업무를 집행할 권리와 의무가 있다고 정한다.","c":"상","v":1},"세무사2022_59-49-3":{"w":"상법 제287조의16은 정관에 다른 규정이 없으면 유한책임회사 정관 변경에 총사원의 동의를 요구한다.","c":"상","v":1},"세무사2022_59-49-4":{"w":"상법 제287조의19 제2항은 업무집행자가 둘 이상이면 정관 또는 총사원의 동의로 회사를 대표할 업무집행자를 정할 수 있게 한다.","c":"상","v":1},"세무사2022_59-49-5":{"w":"상법 제287조의28 제1항은 퇴사 사원이 지분 환급을 금전으로 받을 수 있다고 정한다. 정관으로 달리 정할 수 있다(제3항).","c":"상","v":1},"세무사2023_60-73-1":{"w":"상법 제178조는 합명회사 설립에 2인 이상의 사원이 공동으로 정관을 작성하도록 정한다.","c":"상","v":1},"세무사2023_60-73-2":{"w":"상법 제197조는 합명회사 사원이 다른 사원 전원의 동의 없이 지분을 양도하지 못하게 한다.","c":"상","v":1},"세무사2023_60-73-4":{"w":"상법 제198조 제1항은 합명회사 사원이 다른 사원의 동의 없이 회사 영업부류에 속한 거래를 하거나 동종영업 회사의 무한책임사원·이사가 되지 못하게 한다.","c":"상","v":1},"세무사2023_60-73-5":{"w":"상법 제212조 제1항은 회사 재산으로 채무를 다 갚을 수 없으면 각 사원이 연대하여 변제하도록 정한다.","c":"상","v":1},"세무사2023_60-74-1":{"w":"상법 제287조의23 제1항은 유한책임회사가 정관 변경으로 새 사원을 가입시킬 수 있게 한다. 가입은 정관을 변경한 때 효력이 생긴다(제2항).","c":"상","v":1},"세무사2023_60-74-3":{"w":"상법 제287조의36 제1항은 유한책임회사가 정관 변경의 방법으로 자본금을 감소할 수 있게 한다.","c":"상","v":1},"세무사2023_60-74-4":{"w":"상법 제287조의20은 유한책임회사를 대표하는 업무집행자가 업무집행으로 타인에게 손해를 입히면 회사가 연대하여 배상하도록 정한다.","c":"상","v":1},"세무사2023_60-74-5":{"w":"상법 제287조의11은 업무집행자가 다른 사원 과반수의 결의가 있어야 자기 또는 제3자의 계산으로 회사와 거래할 수 있게 한다.","c":"상","v":1},"세무사2023_60-75-1":{"w":"상법 제278조는 합자회사 유한책임사원이 업무집행이나 대표행위를 하지 못하게 한다.","c":"상","v":1},"세무사2023_60-76-1":{"w":"상법 제555조는 유한회사가 사원의 지분에 관하여 지시식 또는 무기명식 증권을 발행하지 못하게 한다. 유한회사 지분은 유통성을 제한하기 때문이다.","c":"상","v":1},"세무사2024_61-66-1":{"w":"유한회사 감사에는 주식회사 감사의 제412조가 준용되어(상법 제569조) 감사는 언제든지 업무와 재산상태를 조사하고 이사에게 영업 보고를 요구할 수 있다.","c":"상","v":1},"세무사2024_61-67-1":{"w":"상법 제184조 제1항은 합명회사 설립무효를 사원에 한하여 회사성립일부터 2년 안에 소로만 주장하게 한다.","c":"상","v":1},"세무사2024_61-67-3":{"w":"상법 제180조 제1호 단서에 따라 합명회사 설립등기에는 사원의 성명·주민등록번호·주소가 들어가지만 대표사원을 정했으면 나머지 사원의 주소는 뺀다.","c":"상","v":1},"세무사2024_61-67-4":{"w":"상법 제208조 제1항은 정관 또는 총사원의 동의로 여러 사원이 공동으로 회사를 대표하도록 정할 수 있게 한다.","c":"상","v":1},"세무사2024_61-67-5":{"w":"상법 제188조는 같은 회사에 관한 여러 설립무효·취소의 소가 제기되면 법원이 병합심리하도록 정한다. 판결이 서로 어긋나는 것을 막기 위해서다.","c":"상","v":1},"세무사2024_61-68-4":{"w":"상법 제274조는 합자회사 지배인의 선임과 해임을 업무집행사원이 있어도 무한책임사원 과반수의 결의로 하도록 정한다.","c":"상","v":1},"세무사2025_62-75-2":{"w":"상법 제184조 제1항에 따라 합명회사 설립무효는 사원에 한하여 회사성립일부터 2년 안에 소로만 주장할 수 있다.","c":"상","v":1},"세무사2025_62-75-3":{"w":"상법 제185조는 사원이 채권자를 해할 것을 알고 회사를 설립하면 채권자가 그 사원과 회사를 상대로 설립취소를 청구할 수 있게 한다.","c":"상","v":1},"세무사2025_62-75-4":{"w":"상법 제197조에 따라 합명회사 사원은 다른 사원 전원의 동의 없이 지분 전부나 일부를 양도하지 못한다.","c":"상","v":1},"세무사2025_62-75-5":{"w":"상법 제207조 전단은 정관으로 업무집행사원을 정하지 않으면 각 사원이 회사를 대표한다고 정한다.","c":"상","v":1},"세무사2025_62-76-4":{"w":"상법 제287조의11에 따라 업무집행자는 다른 사원 과반수의 결의가 있는 경우에만 자기 또는 제3자의 계산으로 회사와 거래할 수 있다.","c":"상","v":1},"세무사2025_62-77-1":{"w":"상법 제273조는 무한책임사원이 정관에 다른 규정이 없으면 각자 업무를 집행할 권리와 의무를 가진다고 정한다.","c":"상","v":1},"세무사2025_62-77-2":{"w":"상법 제274조는 합자회사 지배인의 선임·해임을 업무집행사원이 있는 경우에도 무한책임사원 과반수의 결의로 하도록 정한다.","c":"상","v":1},"세무사2025_62-77-4":{"w":"상법 제276조는 유한책임사원 지분양도에 무한책임사원 전원의 동의만 요구하고 다른 유한책임사원의 동의는 요구하지 않는다.","c":"상","v":1},"세무사2025_62-77-5":{"w":"상법 제281조 제1항은 유한책임사원이 자기를 무한책임사원으로 오인시키는 행위를 하면 오인하여 회사와 거래한 자에게 무한책임사원과 같은 책임을 지게 한다.","c":"상","v":1},"세무사2025_62-78-2":{"w":"상법 제546조는 유한회사 출자 1좌의 금액을 100원 이상으로 균일하게 하도록 정한다.","c":"상","v":1},"세무사2025_62-78-3":{"w":"상법 제548조 제1항은 유한회사 이사가 사원으로 하여금 출자 전액을 납입하거나 현물출자 재산 전부를 급여하게 하도록 정한다.","c":"상","v":1},"세무사2025_62-78-4":{"w":"상법 제555조는 유한회사가 사원의 지분에 관하여 지시식 또는 무기명식 증권을 발행하지 못하게 한다.","c":"상","v":1},"세무사2025_62-78-5":{"w":"상법 제573조는 총사원이 동의하면 소집절차 없이 유한회사 사원총회를 열 수 있게 한다.","c":"상","v":1},"세무사2026_63-41-1":{"w":"상법 제181조는 회사가 지점을 설치하면 본점 소재지에서 2주 안에 지점 소재지와 설치 연월일을 등기하도록 정한다. 2024.9.20 개정(2025.1.31 시행)으로 지점 소재지 등기가 없어지고 본점 소재지에서만 등기한다.","c":"상","v":1},"세무사2026_63-41-2":{"w":"상법 제182조 제1항은 본점을 이전하면 종전 소재지 또는 새 소재지에서 2주 안에 새 소재지와 이전 연월일을 등기하도록 정한다(2024.9.20 개정, 2025.1.31 시행).","c":"상","v":1},"세무사2026_63-41-3":{"w":"상법 제183조의2는 사원의 업무집행정지나 직무대행자 선임 가처분과 그 변경·취소를 본점이 있는 곳의 등기소에서 등기하도록 정한다.","c":"상","v":1},"세무사2026_63-41-5":{"w":"상법 제179조 제4호는 사원의 출자의 목적과 그 가격 또는 평가의 표준을 합명회사 정관의 절대적 기재사항으로 정한다.","c":"상","v":1},"세무사2026_63-42-2":{"w":"상법 제274조에 따라 합자회사 지배인 선임·해임은 업무집행사원이 있어도 무한책임사원 과반수의 결의로 한다.","c":"상","v":1},"세무사2026_63-42-3":{"w":"상법 제279조 제1항은 유한책임사원이 출자가액에서 이미 이행한 부분을 뺀 가액을 한도로 회사채무를 변제하도록 정한다.","c":"상","v":1},"세무사2026_63-42-4":{"w":"상법 제285조 제2항에 따라 무한책임사원 전원이 퇴사하면 남은 유한책임사원 전원의 동의로 새 무한책임사원을 가입시켜 회사를 계속할 수 있다.","c":"상","v":1},"세무사2026_63-42-5":{"w":"상법 제284조는 유한책임사원이 성년후견개시 심판을 받아도 퇴사하지 않는다고 정한다.","c":"상","v":1},"세무사2026_63-43-1":{"w":"상법 제287조의3은 유한책임회사 정관에 기재사항을 적고 각 사원이 기명날인하거나 서명하도록 정한다.","c":"상","v":1},"세무사2026_63-44-1":{"w":"상법 제575조는 유한회사 사원이 출자 1좌마다 1개의 의결권을 갖되 정관으로 의결권 수를 달리 정할 수 있게 한다.","c":"상","v":1},"세무사2026_63-44-2":{"w":"상법 제554조는 유한회사 각 사원이 출자좌수에 따라 지분을 가진다고 정한다.","c":"상","v":1},"세무사2026_63-44-3":{"w":"상법 제547조 제1항은 정관으로 이사를 정하지 않았으면 회사 성립 전에 사원총회를 열어 이사를 선임하도록 정한다.","c":"상","v":1},"세무사2026_63-44-5":{"w":"상법 제557조는 지분 이전을 취득자의 성명·주소와 출자좌수를 사원명부에 적지 않으면 회사와 제3자에게 대항하지 못하게 한다. 사원명부에 적으면 양쪽에 대항할 수 있다.","c":"상","v":1},"세무사2026_63-45-1":{"w":"상법 제561조는 유한회사에 1인 또는 수인의 이사를 두도록 정한다. 이사회는 없다.","c":"상","v":1},"세무사2026_63-45-2":{"w":"상법 제180조 제2호는 사원의 출자의 목적, 재산출자의 경우 그 가격과 이행한 부분을 합명회사 설립등기 사항으로 정한다.","c":"상","v":1},"세무사2026_63-45-3":{"w":"상법 제292조 본문은 정관이 공증인의 인증을 받아야 효력이 생긴다고 정하고 자본금 10억원 미만 회사의 발기설립만 예외로 둔다(같은 조 단서).","c":"상","v":1},"세무사2026_63-45-5":{"w":"상법 제287조는 합자회사 청산인을 무한책임사원 과반수의 의결로 선임하고 선임하지 않으면 업무집행사원이 청산인이 되도록 정한다.","c":"상","v":1},"세무사2017_54-56-1":{"old":1,"ow":"출제 당시 정답 O. 2024 개정(2025.1.31 시행)으로 지점 소재지 등기가 없어져, 결의부존재 확인 판결이 확정되면 본점 소재지에서만 등기하므로 틀린 문장이다(상법 제380조, 제378조)."},"세무사2021_58-63-2":{"old":1,"ow":"출제 당시 정답 O. 2024 개정(2025.1.31 시행)으로 직무집행정지 가처분의 등기는 본점 소재지에서만 하므로 틀린 문장이다(상법 제407조 제3항)."},"세무사2017_54-51-3":{"old":1,"ow":"출제 당시 정답 O. 2024 개정(2025.1.31 시행)으로 지점 소재지 등기가 폐지되어 합병 등기는 본점 소재지에서 2주일 안에만 하므로 틀린 문장이다(상법 제233조, 제528조 제1항)."},"세무사2017_54-53-3":{"old":1,"ow":"출제 당시 정답 O. 2024 개정(2025.1.31 시행)으로 업무집행사원 권한상실선고 판결이 확정되면 본점 소재지에서만 등기하므로 틀린 문장이다(상법 제205조 제2항)."},"세무사2025_62-74-3":{"old":1,"ow":"출제 당시 정답 O. 2025.9.9 개정(2026.9.10 시행)으로 자산 2조원 이상 상장회사는 정관으로 집중투표를 배제할 수 없어 「정관에서 달리 정하는 경우를 제외하고」라는 단서가 맞지 않으므로 틀린 문장이다(상법 제542조의7 제2항·제3항)."},"세무사2022_59-72-2":{"old":1,"ow":"출제 당시 정답 O. 2025.9.9 개정(2026.9.10 시행)으로 자산 2조원 이상 상장회사는 감사위원 중 2명(정관으로 3명 이상 가능)을 다른 이사와 분리하여 선임해야 하므로 분리선임 인원이 1명이라는 내용은 지금 법과 맞지 않는다(상법 제542조의12 제2항 단서)."}};
